window.QUIZ_DATA = {"subjects": [{"id": "AET", "code": "AET102", "name": "Art Appreciation (đề tiếng Anh)", "note": "Đề gốc không kèm đáp án. Mỗi câu được giải độc lập 2 lần; câu nào lệch nhau hoặc lệch đáp án bình luận FUOverflow thì được phân xử lại (có xem ảnh gốc, tra cứu). Câu đánh dấu ⚠️ là câu vẫn còn chưa chắc chắn.", "sets": [{"id": "de1", "name": "Đề 1", "questions": [{"id": "AET-de1-1", "question": "In Marvel's 2016 superhero movie Doctor Strange, for example, the part of the Ancient One is played by Tilda Swinton. In the film, the Ancient One is a .... sorcerer, and so it may not be surprising that the actress playing her is white", "options": [{"key": "A", "text": "Tibetan"}, {"key": "B", "text": "Asian"}, {"key": "C", "text": "Celtic"}, {"key": "D", "text": "Greek"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong phim 2016, Ancient One được viết lại thành một pháp sư người Celt (Celtic), nên việc chọn Tilda Swinton (người da trắng) 'không có gì ngạc nhiên' như câu văn nói. 'Tibetan' là nguồn gốc của nhân vật trong truyện tranh gốc, không phải trong phim.", "key_fact": "Trong phim Doctor Strange (2016), Ancient One là pháp sư người Celt; trong truyện tranh gốc là người Tây Tạng.", "topic": "Nghệ thuật và văn hóa", "note": "", "comment_answer": null}, {"id": "AET-de1-2", "question": "In 1932, who published novel The Good Earth, the sprawling story of a Chinese farmer, his new wife and their family in early twentieth-century revolutionary China?", "options": [{"key": "A", "text": "Pearl S. Buck"}, {"key": "B", "text": "Anna May Wong"}, {"key": "C", "text": "Sidney Franklin"}, {"key": "D", "text": "J.K. Rowling"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "The Good Earth (1931–1932) là tiểu thuyết của Pearl S. Buck, đoạt giải Pulitzer. Anna May Wong là nữ diễn viên gốc Hoa bị từ chối vai chính trong bản phim, còn Sidney Franklin là đạo diễn phim chuyển thể.", "key_fact": "Pearl S. Buck là tác giả tiểu thuyết The Good Earth.", "topic": "Nghệ thuật và văn hóa", "note": "", "comment_answer": null}, {"id": "AET-de1-3", "question": "Why did the art critic Alexander Benois describe the Black Square as 'aloof', 'arrogant', and 'ostentatious'?", "options": [{"key": "A", "text": "Because the painting is just a black square."}, {"key": "B", "text": "Because it is the most representative painting of Suprematism."}, {"key": "C", "text": "Because of its placement in the exhibition hall."}, {"key": "D", "text": "Because Black Square is significant for the innovation in Russian art."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Benois chỉ trích Black Square vì Malevich treo nó ở 'góc đẹp' (góc đỏ) trên cao của phòng triển lãm — vị trí truyền thống dành cho tranh thánh (icon) trong nhà người Nga. Việc bức tranh chỉ là hình vuông đen hay thuộc Suprematism không phải lý do ông gọi nó là 'kiêu ngạo, phô trương'.", "key_fact": "Black Square bị chê vì được treo ở góc dành cho tranh thánh.", "topic": "Phê bình nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-4", "question": "According to Bicknell, what is the respectful attitude that performers and audiences should have when playing or listening to blues music?", "options": [{"key": "A", "text": "Focus on musical technique."}, {"key": "B", "text": "Focus on the performer's emotions."}, {"key": "C", "text": "Focus on the song's significance to the audience"}, {"key": "D", "text": "Focus on the history of blues music."}], "answer": ["C"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Không tìm được nguồn trực tiếp về Bicknell; theo lập luận trong giáo trình (Hick, chương nghệ thuật và đạo đức/chiếm dụng văn hóa), thái độ tôn trọng là chú ý đến ý nghĩa của bài hát đối với cộng đồng người nghe gốc. Kỹ thuật (A) và lịch sử thể loại (D) không phải trọng tâm của 'sự tôn trọng'.", "key_fact": "Bicknell: tôn trọng blues = chú trọng ý nghĩa bài hát với người nghe.", "topic": "Âm nhạc và văn hóa", "note": "", "comment_answer": null}, {"id": "AET-de1-5", "question": "Which theory does Berys Gaut challenge in his essay 'Interpreting the Arts: The Patchwork Theory'?", "options": [{"key": "A", "text": "Global theory of interpretation"}, {"key": "B", "text": "Intentionalist theory"}, {"key": "C", "text": "Anti-intentionalist theory"}, {"key": "D", "text": "Hypothetical intentionalist theory"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong 'Interpreting the Arts: The Patchwork Theory', Gaut phản đối các 'lý thuyết toàn cục' (global theory) cho rằng một nguyên tắc duy nhất chi phối mọi diễn giải. Ông đề xuất lý thuyết 'chắp vá', nơi nhiều yếu tố khác nhau cùng góp phần, nên không chỉ nhắm vào riêng thuyết ý định hay phản ý định.", "key_fact": "Gaut phản bác lý thuyết diễn giải toàn cục bằng thuyết chắp vá.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-6", "question": "Who introduced the technique of Pointillism, replacing brush strokes with countless dots of colour?", "options": [{"key": "A", "text": "George Seurat"}, {"key": "B", "text": "Monet"}, {"key": "C", "text": "Manet"}, {"key": "D", "text": "Picasso"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Georges Seurat là người khởi xướng kỹ thuật Pointillism (điểm họa), dùng vô số chấm màu thay cho nét cọ. Monet và Manet thuộc Ấn tượng, Picasso gắn với Lập thể.", "key_fact": "Seurat là cha đẻ của trường phái điểm họa.", "topic": "Các trường phái hội họa", "note": "", "comment_answer": null}, {"id": "AET-de1-7", "question": "..., a painting style characterized by its visible brush strokes, its emphasis on light and its attempts to portray movement.", "options": [{"key": "A", "text": "Pop art"}, {"key": "B", "text": "Cubism"}, {"key": "C", "text": "Abstractionism"}, {"key": "D", "text": "Impressionism"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trường phái Ấn tượng có nét cọ lộ rõ, chú trọng ánh sáng và nỗ lực thể hiện chuyển động. Lập thể phân mảnh hình khối, Pop art dùng hình ảnh đại chúng.", "key_fact": "Ấn tượng: nét cọ lộ rõ, ánh sáng, chuyển động.", "topic": "Các trường phái hội họa", "note": "", "comment_answer": null}, {"id": "AET-de1-8", "question": "Who was the first to mention the term “Aesthetic” in the history?", "options": [{"key": "A", "text": "I . Kant"}, {"key": "B", "text": "A. Baumgarten"}, {"key": "C", "text": "Hegel"}, {"key": "D", "text": "Hume"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Alexander Baumgarten là người đầu tiên dùng thuật ngữ 'Aesthetica' (1735/1750). Kant, Hegel, Hume đều phát triển mỹ học sau đó nhưng không đặt ra thuật ngữ.", "key_fact": "Baumgarten là người đặt ra thuật ngữ 'mỹ học'.", "topic": "Lịch sử mỹ học", "note": "", "comment_answer": null}, {"id": "AET-de1-9", "question": "According to George Dickie, what factor constitutes a work of art?", "options": [{"key": "A", "text": "Aesthetics"}, {"key": "B", "text": "Ideas"}, {"key": "C", "text": "The recognition by the art world."}, {"key": "D", "text": "The material value of the artwork."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo thuyết thể chế của George Dickie, một vật trở thành tác phẩm nghệ thuật khi được giới nghệ thuật (artworld) trao vị thế ứng viên để thưởng thức. Tính thẩm mỹ hay giá trị vật chất không phải điều kiện quyết định.", "key_fact": "Dickie: nghệ thuật được xác lập bởi sự công nhận của giới nghệ thuật.", "topic": "Định nghĩa nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-10", "question": "In 1981, ... re-photographed a number of the images in First and Last, including Evans's Alabama Tenant Farmer Wife - a portrait of Allie Mae Burroughs - titling her 're-photograph' of Evans's iconic image After Walker Evans: 4.", "options": [{"key": "A", "text": "Walker Evans"}, {"key": "B", "text": "James Agee"}, {"key": "C", "text": "Sherrie Levine"}, {"key": "D", "text": "Michael Mandiberg"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Năm 1981 Sherrie Levine chụp lại các ảnh của Walker Evans và đặt tên 'After Walker Evans: 4'. Walker Evans là tác giả ảnh gốc, James Agee là nhà văn cộng tác với Evans, còn Mandiberg làm lại vào năm 2001.", "key_fact": "Sherrie Levine – 'After Walker Evans' (1981).", "topic": "Tính nguyên bản và sao chép", "note": "", "comment_answer": null}, {"id": "AET-de1-11", "question": "Which book is authored by Clive Bell?", "options": [{"key": "A", "text": "The Role of Theory in Aesthetics"}, {"key": "B", "text": "The Principles of Art"}, {"key": "C", "text": "Art"}, {"key": "D", "text": "Institutional Theory of Art"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Clive Bell viết cuốn 'Art' (1914), nêu khái niệm 'hình thức có ý nghĩa'. 'The Principles of Art' là của Collingwood, 'The Role of Theory in Aesthetics' là của Morris Weitz.", "key_fact": "Clive Bell là tác giả cuốn 'Art' (1914).", "topic": "Định nghĩa nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-12", "question": "Collingwood's view seems to avoid the perplexities of ....objects: there is not a type with multiple tokens, and some strange relation between them. Rather, each printing of a book, copy of a film or print of a photograph is simply something that offers the same access to the work itself.", "options": [{"key": "A", "text": "Romantic"}, {"key": "B", "text": "Abstract"}, {"key": "C", "text": "Popular"}, {"key": "D", "text": "Mini"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quan điểm của Collingwood (tác phẩm tồn tại trong tâm trí nghệ sĩ) tránh được những rắc rối của 'đối tượng trừu tượng' (abstract objects) như quan hệ type–token. Các phương án khác không liên quan đến vấn đề bản thể của tác phẩm có nhiều bản.", "key_fact": "Collingwood né được bài toán type–token của đối tượng trừu tượng.", "topic": "Bản thể học tác phẩm nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-13", "question": "In 2006, Lucasfilm announced that, in creating the 1997 Special Edition, it had to permanently alter the original negatives for the ... version of Star Wars.", "options": [{"key": "A", "text": "1977"}, {"key": "B", "text": "1978"}, {"key": "C", "text": "1979"}, {"key": "D", "text": "1980"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Star Wars gốc ra mắt năm 1977, và Lucasfilm thừa nhận đã sửa vĩnh viễn âm bản gốc của bản này khi làm Special Edition 1997. Các năm khác không phải năm phát hành phim gốc.", "key_fact": "Âm bản Star Wars 1977 bị sửa vĩnh viễn cho bản Special Edition.", "topic": "Tính nguyên bản và sao chép", "note": "", "comment_answer": null}, {"id": "AET-de1-14", "question": "Who stated: \"An artwork is something created with the purpose of providing others with the satisfaction of aesthetic pleasure\"?", "options": [{"key": "A", "text": "Monroe Beardsley"}, {"key": "B", "text": "Oswald Hanfling"}, {"key": "C", "text": "George Schlesinger"}, {"key": "D", "text": "Richard Lind"}], "answer": ["C"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Định nghĩa chức năng 'tác phẩm là thứ được tạo ra nhằm mang lại cho người khác sự thỏa mãn khoái cảm thẩm mỹ' gắn với George Schlesinger ('Aesthetic Experience and the Definition of Art', BJA 1979). Beardsley diễn đạt bằng 'năng lực thỏa mãn mối quan tâm thẩm mỹ', không phải câu này. (Nguồn: https://doi.org/10.1093/bjaesthetics/19.2.167)", "key_fact": "Schlesinger (1979): art = tạo ra để đem lại khoái cảm thẩm mỹ cho người khác.", "topic": "Định nghĩa nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-15", "question": "In the eighteenth century, however, the practice of landscape design turned to the '.....' style, an idealized version of wild nature, with properties looking on the one hand natural and accidentally placed, and, on the other hand, polished.", "options": [{"key": "A", "text": "France garden"}, {"key": "B", "text": "English garden"}, {"key": "C", "text": "Spanish garden"}, {"key": "D", "text": "Italia garden"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thế kỷ 18, thiết kế cảnh quan chuyển sang phong cách 'vườn Anh' (English landscape garden) – thiên nhiên hoang dã lý tưởng hóa, trái với vườn Pháp/Ý hình học. Câu de1-15 đã chọn English garden; ở bản de3, English garden là A. (Nguồn: https://en.wikipedia.org/wiki/English_landscape_garden)", "key_fact": "Thế kỷ 18: English garden = thiên nhiên hoang dã lý tưởng hóa.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": null}, {"id": "AET-de1-16", "question": "The official logo of the World Wildlife Fund is an adorable ...", "options": [{"key": "A", "text": "Eagle"}, {"key": "B", "text": "Cat"}, {"key": "C", "text": "Dog"}, {"key": "D", "text": "Panda"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Logo chính thức của WWF là con gấu trúc (panda). Đây là ví dụ kinh điển về động vật 'dễ thương' được dùng trong bảo tồn.", "key_fact": "Logo WWF là gấu trúc.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": null}, {"id": "AET-de1-17", "question": "During the ....... period, Christian philosophers worked to meld the philosophical principles of the classical period with the tenets of Christianity", "options": [{"key": "A", "text": "Rococo"}, {"key": "B", "text": "Baroque"}, {"key": "C", "text": "Renaissance"}, {"key": "D", "text": "Medieval"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thời Trung cổ (Medieval), các triết gia Kitô giáo như Augustine, Aquinas kết hợp triết học cổ điển với giáo lý Kitô giáo. Phục Hưng là thời kỳ quay lại cổ điển nhân văn, còn Baroque và Rococo là phong cách nghệ thuật muộn hơn.", "key_fact": "Triết học Trung cổ dung hợp triết học cổ điển với Kitô giáo.", "topic": "Lịch sử mỹ học", "note": "", "comment_answer": null}, {"id": "AET-de1-18", "question": "According to Berleant, what is the most important factor in evaluating the aesthetics of the living environment?", "options": [{"key": "A", "text": "The natural beauty of the environment."}, {"key": "B", "text": "The extent of human intervention in the environment."}, {"key": "C", "text": "How humans interact with the environment."}, {"key": "D", "text": "The economic value of the environment."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Arnold Berleant đề xuất 'mỹ học dấn thân' (engagement): giá trị thẩm mỹ của môi trường sống nằm ở cách con người tương tác, tham gia vào môi trường. Vẻ đẹp tự nhiên thuần túy hay mức độ can thiệp không phải trọng tâm của ông.", "key_fact": "Berleant: mỹ học môi trường dựa trên sự tương tác/dấn thân của con người.", "topic": "Mỹ học môi trường", "note": "", "comment_answer": null}, {"id": "AET-de1-19", "question": "Nature, Kant contends, can also give rise to feelings of ..... - what we might think of as a pronounced awe: where something is sublime, it is quite literally awesome.", "options": [{"key": "A", "text": "the sublime"}, {"key": "B", "text": "the beauty"}, {"key": "C", "text": "the tragedy"}, {"key": "D", "text": "the ugly"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kant cho rằng tự nhiên còn gây ra cảm giác về cái cao cả (the sublime) – một sự kinh sợ choáng ngợp; chính câu văn nói 'where something is sublime'. Cái đẹp (beauty) là loại cảm giác khác mà Kant phân biệt với cái cao cả.", "key_fact": "Kant: tự nhiên gợi cả cái đẹp lẫn cái cao cả (the sublime – sự kính sợ choáng ngợp).", "topic": "Mỹ học Kant", "note": "", "comment_answer": null}, {"id": "AET-de1-20", "question": "What does the Blobfish eat?", "options": [{"key": "A", "text": "Algae"}, {"key": "B", "text": "Small fish"}, {"key": "C", "text": "Organic matter particles"}, {"key": "D", "text": "Aquatic plants"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Cá giọt nước (blobfish) sống ở biển sâu, gần như không bơi chủ động mà trôi nổi và nuốt các mẩu thức ăn, chất hữu cơ trôi qua. Ở độ sâu đó không có tảo hay thực vật thủy sinh vì thiếu ánh sáng.", "key_fact": "Blobfish ăn các mẩu chất hữu cơ/sinh vật nhỏ trôi qua.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": null}, {"id": "AET-de1-21", "question": "\"Mr Blobby\" is typically found at what depth below the ocean surface?", "options": [{"key": "A", "text": "10 meters"}, {"key": "B", "text": "100 meters"}, {"key": "C", "text": "1,000 meters"}, {"key": "D", "text": "10,000 meters"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Blobfish sống ở độ sâu khoảng 600–1.200 m ngoài khơi Úc và New Zealand, nên 1.000 m là đáp án đúng. 10 m hay 100 m quá nông, 10.000 m là vực sâu nhất đại dương.", "key_fact": "Blobfish sống ở độ sâu khoảng 1.000 m.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": null}, {"id": "AET-de1-22", "question": "What sparked a renewed interest in natural aesthetics in philosophy after a period of neglect?", "options": [{"key": "A", "text": "The publication of R. W. Hepburn's influential article, \"Contemporary Aesthetics and the Neglect of Natural Beauty.\""}, {"key": "B", "text": "The rise of the fine arts."}, {"key": "C", "text": "Immanuel Kant's prioritization of natural beauty over artistic beauty."}, {"key": "D", "text": "G.W.F. Hegel's reversal of priorities, valuing artistic beauty over natural beauty."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bài báo của R. W. Hepburn 'Contemporary Aesthetics and the Neglect of Natural Beauty' (1966) đã khơi dậy lại mối quan tâm tới mỹ học tự nhiên. Việc Hegel đề cao cái đẹp nghệ thuật lại là nguyên nhân dẫn tới sự lãng quên đó.", "key_fact": "Bài báo của Hepburn (1966) phục hưng mỹ học tự nhiên.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": null}, {"id": "AET-de1-23", "question": "What is one characteristic often used to describe Tom Waits's albums?", "options": [{"key": "A", "text": "Mainstream appeal and radio-friendliness"}, {"key": "B", "text": "Smooth and polished production quality"}, {"key": "C", "text": "Varied levels of accessibility, ranging from commercially friendly to highly eclectic"}, {"key": "D", "text": "Traditional and conventional songwriting structures"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Các album của Tom Waits có mức độ dễ tiếp cận rất khác nhau, từ thân thiện thương mại đến cực kỳ phá cách, chiết trung. Các phương án 'chính thống', 'trau chuốt' trái với phong cách thô ráp của ông.", "key_fact": "Album của Tom Waits dao động từ dễ nghe đến rất phá cách.", "topic": "Âm nhạc đại chúng", "note": "", "comment_answer": null}, {"id": "AET-de1-24", "question": "How is Tom Waits's music often perceived by both critics and fellow musicians?", "options": [{"key": "A", "text": "As strictly adhering to traditional musical styles and conventions"}, {"key": "B", "text": "As predominantly blues ballads or sea shanties, reflecting his diverse influences"}, {"key": "C", "text": "As adventure songs and Halloween music, combining tradition with innovation"}, {"key": "D", "text": "As exclusively belonging to a cult following, without broader appeal"}], "answer": ["C"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Giáo trình mô tả Waits 'equal parts traditional and groundbreaking' (xem câu de3-8), nhạc của ông được gọi là ballad blues, hò thủy thủ, nhạc phiêu lưu, nhạc Halloween – tức kết hợp truyền thống và cách tân. B sai vì 'predominantly', A và D trái với thực tế (Waits có ảnh hưởng rộng, được nhiều nghệ sĩ cover). (Nguồn: https://en.wikipedia.org/wiki/Tom_Waits)", "key_fact": "Tom Waits = truyền thống + cách tân (adventure songs, Halloween music).", "topic": "Âm nhạc đại chúng", "note": "", "comment_answer": null}, {"id": "AET-de1-25", "question": "An artist learns to create art by observing great beauty and practicing one's art, says Kant, but what are the aesthetic ideas on which the artist works?", "options": [{"key": "A", "text": "Intelligence"}, {"key": "B", "text": "Intuition"}, {"key": "C", "text": "determinate concepts"}, {"key": "D", "text": "All of these answers."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Kant, ý tưởng thẩm mỹ (aesthetic idea) là một biểu tượng của trí tưởng tượng, tức một trực quan (intuition) gợi nhiều suy nghĩ mà không khái niệm xác định nào nắm trọn. Vì vậy 'determinate concepts' sai, và 'All of these' cũng sai.", "key_fact": "Ý tưởng thẩm mỹ của Kant là trực quan không thể quy về khái niệm xác định.", "topic": "Mỹ học Kant", "note": "", "comment_answer": null}, {"id": "AET-de1-26", "question": "Interpretation in art refers to the attribution of meaning to a work. ... What aestheticism maintains that a work's meaning is entirely determined by linguistic and literary conventions, thereby rejecting the relevance of the author's intention?", "options": [{"key": "A", "text": "Anti-intentionalism"}, {"key": "B", "text": "The Romantics"}, {"key": "C", "text": "Post-structuralism"}, {"key": "D", "text": "Intentionalism revisited"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thuyết phản ý định (anti-intentionalism) cho rằng nghĩa của tác phẩm hoàn toàn do quy ước ngôn ngữ và văn học quyết định, nên ý định tác giả không liên quan. Phái Lãng mạn thì ngược lại, coi trọng nội tâm nghệ sĩ.", "key_fact": "Anti-intentionalism: nghĩa do quy ước ngôn ngữ, không do ý định tác giả.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-27", "question": "In the anti-intentionalist perspective, what is the \"correct\" interpretation of a work of art?", "options": [{"key": "A", "text": "The interpretation intended by the author."}, {"key": "B", "text": "There is no interpretation that is \"correct\""}, {"key": "C", "text": "The interpretation by critics."}, {"key": "D", "text": "The interpretation that best fits the artwork."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Với thuyết phản ý định, diễn giải đúng là diễn giải phù hợp nhất với chính tác phẩm (bằng chứng nội tại, quy ước). Phương án ý định tác giả là quan điểm của thuyết ý định, còn 'không có diễn giải đúng' là thuyết hư vô phê bình.", "key_fact": "Phản ý định: diễn giải đúng là cái khớp nhất với tác phẩm.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-28", "question": "How is Tom Waits's music often described?", "options": [{"key": "A", "text": "Accessible and market-friendly"}, {"key": "B", "text": "Smooth and melodious"}, {"key": "C", "text": "Hard to listen to and incomprehensible"}, {"key": "D", "text": "Either accessible or very difficult to access"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Âm nhạc của Tom Waits được mô tả là có lúc rất dễ tiếp cận nhưng có lúc lại rất khó nghe. Các phương án chỉ nêu một thái cực đều không đầy đủ.", "key_fact": "Nhạc Tom Waits có thể rất dễ nghe hoặc rất khó tiếp cận.", "topic": "Âm nhạc đại chúng", "note": "", "comment_answer": null}, {"id": "AET-de1-29", "question": "According to Levinson, who is the \"appropriate\" reader to interpret a literary work?", "options": [{"key": "A", "text": "The reader with knowledge of the literary tradition to which the work belongs."}, {"key": "B", "text": "The reader familiar with other works by the author."}, {"key": "C", "text": "The reader knowledgeable about the public persona of the author."}, {"key": "D", "text": "All of the above."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo thuyết ý định giả định của Levinson, người đọc 'thích hợp' am hiểu truyền thống văn học của tác phẩm, các tác phẩm khác của tác giả và hình ảnh công chúng của tác giả. Vì vậy cả ba phương án đều đúng.", "key_fact": "Người đọc lý tưởng của Levinson nắm truyền thống, toàn bộ tác phẩm và hình ảnh công chúng của tác giả.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-30", "question": "The upshot of the Romantic view, what does the artwork represent?", "options": [{"key": "A", "text": "The artwork represents something that exists in social life - but this can only be felt by the artist."}, {"key": "B", "text": "Artworks embody something that exists within the audience - something we perceive thanks to the artist."}, {"key": "C", "text": "Artworks embody something that exists within the artist - something that, because we lack his sort of genius, we depend on the artist to communicate to us."}, {"key": "D", "text": "None of these answers."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo quan điểm Lãng mạn, tác phẩm thể hiện điều gì đó tồn tại bên trong người nghệ sĩ, và vì thiếu thiên tài như họ, ta phải nhờ nghệ sĩ truyền đạt. Các phương án đặt nguồn gốc ở xã hội hay khán giả là sai.", "key_fact": "Lãng mạn: tác phẩm biểu đạt nội tâm thiên tài của nghệ sĩ.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-31", "question": "Fill in the blank with the correct words: Schaper argues that first-order beliefs are about our........, and that second-order beliefs are about the world of the ...........", "options": [{"key": "A", "text": "world, story"}, {"key": "B", "text": "story, world"}, {"key": "C", "text": "None of the answer"}, {"key": "D", "text": "world, life"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Schaper cho rằng niềm tin bậc một là về thế giới của chúng ta (ví dụ: biết câu chuyện là hư cấu), còn niềm tin bậc hai là về thế giới của câu chuyện. Phương án B đảo ngược thứ tự này.", "key_fact": "Schaper: niềm tin bậc một về thế giới thực, bậc hai về thế giới truyện.", "topic": "Nghịch lý hư cấu", "note": "", "comment_answer": null}, {"id": "AET-de1-32", "question": "Fill in the blank with the correct words: It seems reasonable, to describe a piece of music as '..........' just in case it excites listeners, a film as '..............' just in case it frightens viewers, or a landscape painting as '...........' only if it calms those who look at it.", "options": [{"key": "A", "text": "exciting, scary, calming"}, {"key": "B", "text": "happy, sad, calming"}, {"key": "C", "text": "happy, scary, thrilling"}, {"key": "D", "text": "exciting, scary, thrilling"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Có thể gọi một bản nhạc là 'exciting' nếu nó kích thích người nghe, phim là 'scary' nếu làm khán giả sợ, tranh phong cảnh là 'calming' nếu làm người xem bình tâm. Các phương án khác không khớp với từng tác dụng được mô tả.", "key_fact": "Thuộc tính phản ứng: exciting–kích thích, scary–sợ, calming–bình tâm.", "topic": "Thuộc tính thẩm mỹ", "note": "", "comment_answer": null}, {"id": "AET-de1-33", "question": "In his 1973 review of the film, critic Roger Ebert gave The Exorcist four out of ... stars, calling it 'one of the best movies of its type ever made'", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Roger Ebert chấm The Exorcist 4/4 sao (điểm tối đa) và gọi nó là một trong những phim hay nhất thể loại. Các phương án nhỏ hơn mâu thuẫn với lời khen tuyệt đối.", "key_fact": "Ebert chấm The Exorcist 4/4 sao.", "topic": "Phim ảnh và phê bình", "note": "", "comment_answer": null}, {"id": "AET-de1-34", "question": "What is “Baker-Miller pink” supposed to represent?", "options": [{"key": "A", "text": "'calm' colour"}, {"key": "B", "text": "'creative' colour"}, {"key": "C", "text": "'dynamic' colour"}, {"key": "D", "text": "'romantic' colour"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Baker-Miller pink' được cho là màu 'làm dịu' (calm), từng được sơn trong phòng giam để giảm hung hăng. Nó không gắn với sáng tạo hay lãng mạn.", "key_fact": "Baker-Miller pink được coi là màu làm dịu.", "topic": "Màu sắc và cảm xúc", "note": "", "comment_answer": null}, {"id": "AET-de1-35", "question": "Schaper suggests that the term 'suspension of disbelief' is actually a misnomer and that when dealing with fictional narratives, what are we to do?", "options": [{"key": "A", "text": "we do not suspend or put aside any beliefs; rather, we compound beliefs."}, {"key": "B", "text": "we suspend or dismiss all beliefs"}, {"key": "C", "text": "we suspend or put aside any beliefs; rather, we compound beliefs."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Schaper cho rằng 'tạm ngưng hoài nghi' là cách gọi sai, vì ta không gác bỏ niềm tin nào mà thực ra 'chồng' (compound) các niềm tin. Phương án C tự mâu thuẫn, B trái với quan điểm của bà.", "key_fact": "Schaper: ta không tạm ngưng niềm tin mà chồng ghép chúng.", "topic": "Nghịch lý hư cấu", "note": "", "comment_answer": null}, {"id": "AET-de1-36", "question": "Fill in the blank with the correct words: “Catharsis” is...", "options": [{"key": "A", "text": "a phenomenon was called by Aristotle allows us to vent and so purge our emotions of pity and fear"}, {"key": "B", "text": "a phenomenon was called by Baumgarten allows us to vent and so purge our emotions of pity and fear"}, {"key": "C", "text": "a phenomenon was called by Plato allows us to vent and so purge our emotions of pity and fear"}, {"key": "D", "text": "a phenomenon was called by Kant allows us to vent and so purge our emotions of pity and fear"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Catharsis (thanh lọc) là khái niệm của Aristotle trong Poetics: bi kịch giúp xả và thanh lọc cảm xúc thương xót và sợ hãi. Plato thì lo ngại thi ca kích động cảm xúc, còn Baumgarten và Kant không đề xuất khái niệm này.", "key_fact": "Catharsis là khái niệm của Aristotle.", "topic": "Mỹ học Aristotle", "note": "", "comment_answer": null}, {"id": "AET-de1-37", "question": "Fill in the blank with the correct words: Marsilio Ficino, argued that beauty could be found not only in the relations between things - ..., ... - but also in their ...", "options": [{"key": "A", "text": "Order- proportion- harmony"}, {"key": "B", "text": "Order- proportion- harmony- brilliance"}, {"key": "C", "text": "Brilliance- Harmony- order"}, {"key": "D", "text": "Proportion- Harmony- Brilliance"}], "answer": ["D"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Ficino (Tân Platon) cho rằng cái đẹp không chỉ ở quan hệ giữa các bộ phận (tỉ lệ, hài hòa) mà còn ở sự rực rỡ/ánh sáng (splendor) của chính sự vật – cái đẹp là 'ánh sáng rực rỡ của thiện thần linh'. B thừa một từ, A và C sai thứ tự/thiếu 'brilliance' ở vị trí cuối. (Nguồn: https://www.sav.sk/journals/uploads/021511452022-Weiss-20-35.pdf)", "key_fact": "Ficino: proportion, harmony + brilliance.", "topic": "Mỹ học Phục Hưng", "note": "", "comment_answer": null}, {"id": "AET-de1-38", "question": "Who explicitly places the beauty of art above that of nature?", "options": [{"key": "A", "text": "Plato"}, {"key": "B", "text": "Aristotle"}, {"key": "C", "text": "I. Kant"}, {"key": "D", "text": "Hegel"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hegel đặt cái đẹp nghệ thuật cao hơn cái đẹp tự nhiên vì nghệ thuật là sản phẩm của tinh thần. Kant thì ngược lại, ưu tiên cái đẹp tự nhiên.", "key_fact": "Hegel đặt cái đẹp nghệ thuật trên cái đẹp tự nhiên.", "topic": "Mỹ học Hegel", "note": "", "comment_answer": null}, {"id": "AET-de1-39", "question": "Fill in the blank with the correct words: St Thomas Aquinas, the most influential philosopher of the ... period.", "options": [{"key": "A", "text": "Ancient"}, {"key": "B", "text": "Medieval"}, {"key": "C", "text": "Renaissance"}, {"key": "D", "text": "Romantic"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thomas Aquinas (thế kỷ 13) là triết gia có ảnh hưởng nhất thời Trung cổ. Ông không thuộc thời Cổ đại, Phục Hưng hay Lãng mạn.", "key_fact": "Aquinas là triết gia tiêu biểu thời Trung cổ.", "topic": "Lịch sử mỹ học", "note": "", "comment_answer": null}, {"id": "AET-de1-40", "question": "........, for one, has challenged Budd's claim that to value something as art is to value it non-instrumentally.", "options": [{"key": "A", "text": "Malcolm Budd"}, {"key": "B", "text": "Joel Feinberg"}, {"key": "C", "text": "Monroe Beardsley"}, {"key": "D", "text": "Robert Stecker"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Robert Stecker đã phản bác quan điểm của Malcolm Budd rằng coi trọng thứ gì như nghệ thuật là coi trọng nó một cách phi công cụ. Budd không thể tự phản bác mình, Feinberg và Beardsley không gắn với cuộc tranh luận này.", "key_fact": "Stecker phản bác Budd về giá trị phi công cụ của nghệ thuật.", "topic": "Giá trị nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-41", "question": "Russian artist Kasimir Malevich outgrew the movement he himself had founded, and created its successor, ....", "options": [{"key": "A", "text": "Futurism"}, {"key": "B", "text": "Cubism"}, {"key": "C", "text": "Suprematism"}, {"key": "D", "text": "Romanticsm"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Malevich gắn liền với Suprematism (Chủ nghĩa Tối thượng), trường phái kế tiếp và vượt khỏi Cubo-Futurism mà ông từng tham gia. Futurism và Cubism là các phong trào có trước, Romanticism không liên quan.", "key_fact": "Malevich sáng lập Suprematism.", "topic": "Các trường phái hội họa", "note": "", "comment_answer": null}, {"id": "AET-de1-42", "question": "In the eighteenth century, who argued that beauty would be found in 'uniformity amidst variety ?", "options": [{"key": "A", "text": "Imanuel Kant"}, {"key": "B", "text": "Francis Hutcheson"}, {"key": "C", "text": "Marsilio Ficino"}, {"key": "D", "text": "St Thomas Aquinas"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Francis Hutcheson (thế kỷ 18) định nghĩa cái đẹp là 'uniformity amidst variety' (thống nhất trong đa dạng). Ficino (thế kỷ 15) và Aquinas (thế kỷ 13) không thuộc thế kỷ 18 và không dùng công thức này.", "key_fact": "Hutcheson: cái đẹp = thống nhất trong đa dạng.", "topic": "Lịch sử mỹ học", "note": "", "comment_answer": null}, {"id": "AET-de1-43", "question": "Fill the blank: The most important thing, according to Pettit, to experience a work of art is ...", "options": [{"key": "A", "text": "Understanding the author and the artwork."}, {"key": "B", "text": "Experiencing the artwork under suitable conditions."}, {"key": "C", "text": "Having knowledge about art."}, {"key": "D", "text": "Having well-functioning senses."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Pettit cho rằng đặc tính thẩm mỹ chỉ được nắm bắt qua trải nghiệm tri giác trực tiếp tác phẩm trong điều kiện phù hợp. Hiểu tác giả hay kiến thức nghệ thuật không thay được việc tự trải nghiệm.", "key_fact": "Pettit: phải trải nghiệm tác phẩm trực tiếp trong điều kiện thích hợp.", "topic": "Thuộc tính thẩm mỹ", "note": "", "comment_answer": null}, {"id": "AET-de1-44", "question": "In his dialogue the Laws, Plato suggests that beauty is found in certain ..., ... and ...", "options": [{"key": "A", "text": "Order- Regularity"}, {"key": "B", "text": "Harmonies- Order- Regularity"}, {"key": "C", "text": "Order- Proportions- Regularity"}, {"key": "D", "text": "Proportions- Harmonies- Order"}], "answer": ["D"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Trong Laws, Plato gắn cái đẹp với tỉ lệ, hòa âm và trật tự (proportions, harmonies, order). 'Regularity' là từ giáo trình dùng cho Pythagoras (harmony, order, regularity), nên các phương án có 'regularity' là bẫy.", "key_fact": "Plato (Laws): proportions – harmonies – order; Pythagoras: harmony – order – regularity.", "topic": "Mỹ học Plato", "note": "", "comment_answer": null}, {"id": "AET-de1-45", "question": "Shaftesbury argues: What is the “inward eye”?", "options": [{"key": "A", "text": "This 'inward eye' applies to both the ethical and the aesthetic, distinguishing harmony and proportion from their opposites in both arenas."}, {"key": "B", "text": "This 'inward eye' applies to both the beauty and the aesthetic, distinguishing harmony and proportion from their opposites in both arenas."}, {"key": "C", "text": "This 'inward eye' applies to both the ethical and the emotion, distinguishing harmony and proportion from their opposites in both arenas."}, {"key": "D", "text": "None of these answer."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Shaftesbury cho rằng 'con mắt bên trong' (inward eye) áp dụng cho cả đạo đức lẫn thẩm mỹ, phân biệt hài hòa và cân xứng với cái đối lập ở cả hai lĩnh vực. Các phương án khác thay 'ethical' bằng từ không đúng.", "key_fact": "Shaftesbury: 'inward eye' nhận biết cả cái đẹp lẫn cái thiện.", "topic": "Lịch sử mỹ học", "note": "", "comment_answer": null}, {"id": "AET-de1-46", "question": "According to Anne Eaton, why is it 'naive' or 'mischievous' to remove the special position of the artist or critic from the equation?", "options": [{"key": "A", "text": "Because it would make art meaningless."}, {"key": "B", "text": "Because it would perpetuate the 'default' dominant position in history, historically assigned to men and women corresponding roles."}, {"key": "C", "text": "Because it would make art apolitical."}, {"key": "D", "text": "Because it would make art amoral."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Anne Eaton (góc nhìn nữ quyền) cho rằng bỏ vị trí đặc biệt của nghệ sĩ/nhà phê bình là ngây thơ, vì điều đó duy trì vị thế thống trị 'mặc định' trong lịch sử dành cho nam giới cùng vai trò tương ứng của phụ nữ. Các phương án khác không thể hiện lập luận về giới.", "key_fact": "Eaton: bỏ qua vị trí người sáng tạo sẽ duy trì sự thống trị nam giới.", "topic": "Nghệ thuật và đạo đức", "note": "", "comment_answer": null}, {"id": "AET-de1-47", "question": "Which statement is correct about Marcel Duchamp's artwork Fountain?", "options": [{"key": "A", "text": "Fountain was exhibited at the 1917 exhibition of the Society of Independent Artists in New York."}, {"key": "B", "text": "Fountain is considered the most famous artwork of the 20th century."}, {"key": "C", "text": "Fountain is Marcel Duchamp's first Readymade artwork."}, {"key": "D", "text": "Fountain was rejected by the Society of Independent Artists at the 1917 exhibition."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Fountain (1917) được gửi tới triển lãm của Society of Independent Artists ở New York nhưng bị từ chối, không được trưng bày. Nó không phải readymade đầu tiên (Bicycle Wheel 1913 có trước), và được bầu là tác phẩm 'có ảnh hưởng nhất' chứ không phải 'nổi tiếng nhất'.", "key_fact": "Fountain bị Hội Nghệ sĩ Độc lập từ chối năm 1917.", "topic": "Định nghĩa nghệ thuật", "note": "", "comment_answer": null}, {"id": "AET-de1-48", "question": "Originally installed in Denmark's Trapholt Art Museum, .... consists of ten water-filled Moulinex-Optiblend 2000 blenders, each containing a live goldfish", "options": [{"key": "A", "text": "Maria"}, {"key": "B", "text": "Helena"}, {"key": "C", "text": "Anna"}, {"key": "D", "text": "Karla"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tác phẩm 10 máy xay Moulinex chứa cá vàng tại bảo tàng Trapholt (Đan Mạch, 2000) của Marco Evaristti tên là 'Helena' (cùng câu de1-48 đã chọn Helena). Đáp án B 'Maria' trong bản này là sai do đảo thứ tự phương án. (Nguồn: https://en.wikipedia.org/wiki/Helena_(artwork))", "key_fact": "Helena (Marco Evaristti, 2000, Trapholt) – 10 máy xay cá vàng.", "topic": "Nghệ thuật và đạo đức", "note": "", "comment_answer": null}, {"id": "AET-de1-49", "question": "Fill in the blank with the correct words: Aesthetics and ethics each deal with sorts of value. We evaluate works of art, non-artefacts and certainly each other........; and we evaluate actions, events and persons..........", "options": [{"key": "A", "text": "aesthetically, ethically"}, {"key": "B", "text": "ethically, aesthetically,"}, {"key": "C", "text": "aesthetically, emotionally"}, {"key": "D", "text": "Emotionally, ethically"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ta đánh giá tác phẩm, vật tự nhiên và con người về mặt thẩm mỹ (aesthetically), còn hành động, sự kiện và con người về mặt đạo đức (ethically). Phương án B đảo ngược thứ tự này.", "key_fact": "Thẩm mỹ đánh giá vẻ ngoài, đạo đức đánh giá hành động.", "topic": "Mỹ học và đạo đức", "note": "", "comment_answer": null}, {"id": "AET-de1-50", "question": "What is the primary prediction of the scenario “a major social network company becoming the first social credit provider”?", "options": [{"key": "A", "text": "The service evaluates a person's suitability for workplace, cultures, and stress levels using their public social media posts and their likes. Algorithms can identify individuals who are likely suffering from various mental illnesses, from depression to sociopathy."}, {"key": "B", "text": "The company bases mortgage rates, loan approvals, and credit access on deep data collected by its social platform. It takes into consideration the credit histories of your close friends and family, locations you have visited, and it uses semantic analysis of messages and photos to indicate whether you are generally happy, angry, anxious, or depressed. All this data can affect what financial opportunities you have in your future."}, {"key": "C", "text": "Many of these drones are fitted with cameras and other sensors to collect data as they fly over neighborhoods, providing an additional revenue stream for shippers and merchants. Individuals who opt for free unlimited drone delivery consent to the collection of data from their homes and their yards."}, {"key": "D", "text": "These actions include doxxing, revenge porn, swatting, social media harassment, vandalism, and even violence. With one tap, you can pay someone else to act on your anger, your frustration, or your hate. Smart contracts pay out the bounties immediately in untraceable cryptocurrencies upon proof of completed action."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kịch bản 'mạng xã hội trở thành nhà cung cấp tín dụng xã hội' dự đoán công ty dựa vào dữ liệu mạng xã hội (bạn bè, vị trí, cảm xúc) để quyết định lãi suất và khoản vay. Các phương án khác lần lượt mô tả kịch bản sàng lọc nhân sự, giao hàng bằng drone và thuê người trả thù.", "key_fact": "Tín dụng xã hội: dữ liệu mạng xã hội quyết định cơ hội tài chính.", "topic": "Công nghệ và văn hóa", "note": "", "comment_answer": null}]}, {"id": "de2", "name": "Đề 2", "questions": [{"id": "AET-de2-1", "question": "Which term from the passage typically denotes a value judgment when assessing artworks?", "options": [{"key": "A", "text": "Elegant"}, {"key": "B", "text": "Black"}, {"key": "C", "text": "Square"}, {"key": "D", "text": "Imposing"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Elegant' (thanh lịch) là thuật ngữ mang tính đánh giá thẩm mỹ. 'Black' và 'Square' chỉ mô tả màu và hình, còn 'imposing' thiên về mô tả đặc tính hơn là đánh giá.", "key_fact": "'Elegant' là từ mang tính phán đoán giá trị thẩm mỹ.", "topic": "Thuộc tính thẩm mỹ", "note": "", "comment_answer": "A"}, {"id": "AET-de2-2", "question": "Regarding the interpretation of a work, what is the point of 'critical nihilism'?", "options": [{"key": "A", "text": "There are no correct interpretations of the work - because no work really means any particular thing."}, {"key": "B", "text": "There is only one truly correct explanation."}, {"key": "C", "text": "There are many correct explanations."}, {"key": "D", "text": "None of these answers"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thuyết hư vô phê bình (critical nihilism) cho rằng không có diễn giải nào đúng, vì tác phẩm không thực sự mang một nghĩa cụ thể nào. 'Chỉ một diễn giải đúng' là monism, 'nhiều diễn giải đúng' là pluralism.", "key_fact": "Critical nihilism: không có diễn giải đúng nào.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": "A"}, {"id": "AET-de2-3", "question": "\"Mr Blobby\" was awarded what title by the Ugly Animal Preservation Society in 2013?", "options": [{"key": "A", "text": "Most beautiful in the world"}, {"key": "B", "text": "The best at being ugly."}, {"key": "C", "text": "The most intelligent"}, {"key": "D", "text": "The fiercest"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Năm 2013, Ugly Animal Preservation Society bầu blobfish là 'động vật xấu nhất thế giới', tương ứng với phương án 'giỏi nhất về sự xấu xí'. Các danh hiệu đẹp nhất, thông minh nhất, hung dữ nhất đều sai.", "key_fact": "Blobfish được bầu là động vật xấu nhất thế giới năm 2013.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": "B"}, {"id": "AET-de2-4", "question": "How did Louis Daguerre influence the artistic views of the 19th century?", "options": [{"key": "A", "text": "Triggered a revolution in the history of painting"}, {"key": "B", "text": "Affirmed art's departure from imitation"}, {"key": "C", "text": "Introduced a definition of art"}, {"key": "D", "text": "Changed the perception of expression in art"}], "answer": ["B"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Phát minh nhiếp ảnh của Daguerre (1839) khiến việc mô phỏng hiện thực trở thành việc của máy, từ đó nghệ thuật thế kỷ 19 rời bỏ thuyết mô phỏng (mimesis), mở đường cho Ấn tượng và nghệ thuật hiện đại. Daguerre không đưa ra định nghĩa nghệ thuật (C); A quá chung chung. (Nguồn: https://www.britannica.com/technology/photography/Daguerreotype ; https://bigthink.com/articles/how-photography-changed-painting-and-vice-versa/)", "key_fact": "Daguerre (nhiếp ảnh 1839) → nghệ thuật rời bỏ mô phỏng.", "topic": "Định nghĩa nghệ thuật", "note": "", "comment_answer": "A,B,D"}, {"id": "AET-de2-5", "question": "How many versions of 'Institutional Theory of Art' that produced by  George Dickie?", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "George Dickie đưa ra hai phiên bản thuyết thể chế: bản đầu (1974, 'trao vị thế') và bản sửa đổi (1984, The Art Circle). Vì vậy đáp án là 2.", "key_fact": "Dickie có hai phiên bản thuyết thể chế (1974 và 1984).", "topic": "Định nghĩa nghệ thuật", "note": "", "comment_answer": "B"}, {"id": "AET-de2-6", "question": "According to the anti-intentionalist perspective of Wimsatt and Beardsley, which interpretation of the film \"Plan 9 from Outer Space\" is correct?", "options": [{"key": "A", "text": "The interpretation intended by the author."}, {"key": "B", "text": "The interpretation that best fits the artwork."}, {"key": "C", "text": "The interpretation agreed upon by film critics."}, {"key": "D", "text": "The interpretation that makes the film successful."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Wimsatt và Beardsley (phản ý định), ý định tác giả là không liên quan, nên diễn giải đúng là diễn giải khớp nhất với chính tác phẩm. Phương án ý định tác giả là thuyết ý định, đồng thuận của giới phê bình không phải tiêu chí của họ.", "key_fact": "Wimsatt & Beardsley: diễn giải dựa vào tác phẩm, không vào ý định tác giả.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": "B"}, {"id": "AET-de2-7", "question": "You were well aware that 'In the Gloaming' was a fictional story when you started reading it. So who are you sad about? It seems thoroughly irrational to be sad about someone who you are fully aware never existed. In recent years, what is this problem called? and was reintroduced by British philosopher Colin Radford.", "options": [{"key": "A", "text": "'paradox of fiction'"}, {"key": "B", "text": "'the tragedy of the novel'"}, {"key": "C", "text": "'Literal Interpretation'"}, {"key": "D", "text": "'Realism in Art'"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Vấn đề buồn vì nhân vật mà ta biết là không có thật được gọi là 'nghịch lý hư cấu' (paradox of fiction), được Colin Radford khơi lại. Các phương án khác không phải tên vấn đề này.", "key_fact": "Colin Radford khơi lại 'nghịch lý hư cấu'.", "topic": "Nghịch lý hư cấu", "note": "", "comment_answer": "A"}, {"id": "AET-de2-8", "question": "Affectionately named 'Mr Blobby', the 285mm specimen was caught off the coast of New Zealand in 2003 by the crew of the RV Tangaroa, a deep-water scientific research vessel, named for the Māori god of the sea. Name of fish in this text?", "options": [{"key": "A", "text": "The kingfish"}, {"key": "B", "text": "The Archerfish"}, {"key": "C", "text": "The Hagfish"}, {"key": "D", "text": "The Blobfish"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Mr Blobby' là mẫu cá giọt nước (blobfish) bị tàu RV Tangaroa bắt năm 2003 ngoài khơi New Zealand. Các loài cá khác không phải nhân vật này.", "key_fact": "Mr Blobby là một con blobfish.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": "D"}, {"id": "AET-de2-9", "question": "Following the Impressionists in the late nineteenth century were the...., a loose collection of painters variously inspired by the Impressionists", "options": [{"key": "A", "text": "Fauvism"}, {"key": "B", "text": "Post-Impressionists"}, {"key": "C", "text": "Expressionism"}, {"key": "D", "text": "Cubism"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo sau Ấn tượng cuối thế kỷ 19 là nhóm Hậu Ấn tượng (Post-Impressionists) như Cézanne, Van Gogh, Gauguin, Seurat. Fauvism, Expressionism, Cubism xuất hiện muộn hơn và là trường phái chứ không phải 'một nhóm họa sĩ'.", "key_fact": "Hậu Ấn tượng nối tiếp trường phái Ấn tượng.", "topic": "Các trường phái hội họa", "note": "", "comment_answer": "B"}, {"id": "AET-de2-10", "question": "Unlike articles of nature, Hegel suggests, a work of art is apprehended on a .... or spiritual plane", "options": [{"key": "A", "text": "Physical"}, {"key": "B", "text": "Mental"}, {"key": "C", "text": "Emotinal"}, {"key": "D", "text": "Intellectual"}], "answer": ["D"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Câu trùng de2-10 nhưng hai bản chọn khác nhau (de2-10: Intellectual; de3-45: Mental). Hegel: tác phẩm nghệ thuật tồn tại cho cảm quan nhưng chủ yếu cho sự lĩnh hội tinh thần (Geist); cụm 'intellectual or spiritual plane' có khả năng là nguyên văn giáo trình hơn. Cần thống nhất một đáp án; chưa xác minh được nguyên văn. (Nguồn: https://www.cambridge.org/core/books/poetry-and-the-romantic-musical-aesthetic/nature-music-and-the-imagination-in-wordsworths-poetry/5F876F26BD430DBE571A2C15CC04B158)", "key_fact": "Hegel: tác phẩm được lĩnh hội ở bình diện trí tuệ/tinh thần (intellectual or spiritual).", "topic": "Mỹ học Hegel", "note": "", "comment_answer": "D"}, {"id": "AET-de2-11", "question": "Regarding the interpretation of a work, what is the point of 'critical monism'?", "options": [{"key": "A", "text": "There are no correct interpretations of the work - because no work really means any particular thing."}, {"key": "B", "text": "There is only one truly correct explanation."}, {"key": "C", "text": "There are many correct explanations."}, {"key": "D", "text": "None of these answers"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thuyết nhất nguyên phê bình (critical monism) cho rằng chỉ có một diễn giải đúng duy nhất. 'Không có diễn giải đúng' là nihilism, 'nhiều diễn giải đúng' là pluralism.", "key_fact": "Critical monism: chỉ một diễn giải đúng.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": "B"}, {"id": "AET-de2-12", "question": "In 2001, Michael Mandiberg scanned the same photographs from First and Last and posted them to his website, AfterSherrieLevine.com. If you visit the site, you can print out a high-resolution copy of the image originally taken by Evans - now titled ... (AfterSherrieLevine.com/2.jpg) - along with a certificate of authenticity", "options": [{"key": "A", "text": "After Walker Evans: 4"}, {"key": "B", "text": "Untitled"}, {"key": "C", "text": "Alabama Tenant Farmer Wife"}, {"key": "D", "text": "After Sherrie Levine"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mandiberg đặt tên ảnh trên trang AfterSherrieLevine.com là 'Untitled (AfterSherrieLevine.com/2.jpg)'. 'After Walker Evans: 4' là tên tác phẩm của Levine, 'Alabama Tenant Farmer Wife' là tên ảnh gốc của Evans.", "key_fact": "Mandiberg (2001): 'Untitled (AfterSherrieLevine.com/2.jpg)'.", "topic": "Tính nguyên bản và sao chép", "note": "", "comment_answer": "B"}, {"id": "AET-de2-13", "question": "The claim \"Last Leaf\" is a song about death according to Krausz's theory, is it correct?", "options": [{"key": "A", "text": "True, because it adds to the meaning of the work."}, {"key": "B", "text": "False, because it changes the meaning of the work."}, {"key": "C", "text": "Cannot be determined, because the meaning of the work is not predetermined."}, {"key": "D", "text": "Depends on the context."}], "answer": ["A"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Krausz theo thuyết gán (imputationalism) và đa diễn giải (multiplism): diễn giải có thể gán thêm thuộc tính/ý nghĩa cho tác phẩm, nên đọc 'Last Leaf' như bài hát về cái chết là chấp nhận được vì nó bổ sung ý nghĩa. Krausz không cho rằng không thể xác định (C). (Nguồn: https://en.wikipedia.org/wiki/Michael_Krausz)", "key_fact": "Krausz: diễn giải 'gán' thêm nghĩa → 'Last Leaf' về cái chết là đúng.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": "C"}, {"id": "AET-de2-14", "question": "According to Levinson, who is the \"appropriate\" reader to interpret a literary work?", "options": [{"key": "A", "text": "The reader with knowledge of the literary tradition to which the work belongs."}, {"key": "B", "text": "The reader familiar with other works by the author."}, {"key": "C", "text": "The reader knowledgeable about the public persona of the author."}, {"key": "D", "text": "All of the above."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo thuyết ý định giả định của Levinson, người đọc 'thích hợp' am hiểu truyền thống văn học của tác phẩm, các tác phẩm khác của tác giả và hình ảnh công chúng của tác giả. Vì vậy cả ba phương án đều đúng.", "key_fact": "Người đọc lý tưởng của Levinson nắm truyền thống, toàn bộ tác phẩm và hình ảnh công chúng của tác giả.", "topic": "Diễn giải nghệ thuật", "note": "", "comment_answer": "D"}, {"id": "AET-de2-15", "question": "Emily Brady suggests, allow for aesthetic revelation - the realization of aesthetic truths. However, for such appreciation to be appropriate, it must be both disinterested and of proper depth. As Brady puts it, we must ... well.", "options": [{"key": "A", "text": "Live"}, {"key": "B", "text": "Creative"}, {"key": "C", "text": "Imagine"}, {"key": "D", "text": "Think"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Emily Brady nhấn mạnh vai trò của trí tưởng tượng trong thưởng thức thiên nhiên, với yêu cầu 'phải tưởng tượng tốt' (imagine well). Các từ khác không phải cụm từ đặc trưng của bà.", "key_fact": "Brady: thưởng thức thiên nhiên cần 'tưởng tượng tốt'.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": "C"}, {"id": "AET-de2-16", "question": "What is the key difference between Aristotle's view on beauty and the views of his predecessors?", "options": [{"key": "A", "text": "He believes beauty is based on objective qualities, not subjective experience."}, {"key": "B", "text": "He emphasizes the importance of moderation in achieving beauty."}, {"key": "C", "text": "He defines beauty solely in terms of size and order."}, {"key": "D", "text": "He rejects the Pythagorean connection of beauty to mathematics."}], "answer": ["C"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Điểm mới của Aristotle so với Pythagoras/Plato là đưa kích thước (magnitude) cùng trật tự vào định nghĩa cái đẹp (Poetics ch.7; xem câu de3-15 'beauty is bound up in size and order'). Moderation thuộc đạo đức học; ông không bác bỏ toán học.", "key_fact": "Aristotle: beauty = size (magnitude) + order.", "topic": "Mỹ học Aristotle", "note": "", "comment_answer": "B"}, {"id": "AET-de2-17", "question": "Fill in the blank with the correct words:\n...praised the imitative arts for their imitation and contends that all of us are born both with the instinct to imitate and the instinct to enjoy works of imitation.", "options": [{"key": "A", "text": "Heraklitus"}, {"key": "B", "text": "Socrates"}, {"key": "C", "text": "Plato"}, {"key": "D", "text": "Aristotle"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong Poetics, Aristotle ca ngợi nghệ thuật mô phỏng và cho rằng con người bẩm sinh có bản năng mô phỏng và thích thú với tác phẩm mô phỏng. Plato ngược lại chỉ trích nghệ thuật mô phỏng vì xa rời chân lý.", "key_fact": "Aristotle: con người bẩm sinh có bản năng mô phỏng và thích thú với sự mô phỏng.", "topic": "Mỹ học Aristotle", "note": "", "comment_answer": "C"}, {"id": "AET-de2-18", "question": "According to Ronald W. Hepburn, why are philosophers indifferent to natural beauty?", "options": [{"key": "A", "text": "Natural beauty is not important."}, {"key": "B", "text": "Natural beauty cannot be explained."}, {"key": "C", "text": "Natural beauty is not as beautiful as art."}, {"key": "D", "text": "Natural beauty is not suitable for aesthetic studies."}], "answer": ["D"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Hepburn (1966) chỉ ra mỹ học phân tích đồng nhất mỹ học với triết học nghệ thuật, nên vẻ đẹp tự nhiên (không khung, không tác giả) bị xem là nằm ngoài, không phù hợp làm đối tượng nghiên cứu thẩm mỹ. Ông không nói tự nhiên kém đẹp hay không thể giải thích. (Nguồn: https://plato.stanford.edu/entries/environmental-aesthetics/)", "key_fact": "Hepburn: mỹ học chỉ lo nghệ thuật → tự nhiên bị coi không hợp để nghiên cứu.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": "B"}, {"id": "AET-de2-19", "question": "Poetry, including theatre, allows us to vent and so purge our emotions of pity and fear, a phenomenon Aristotle called .....", "options": [{"key": "A", "text": "Comedy"}, {"key": "B", "text": "Tragedy"}, {"key": "C", "text": "Beauty"}, {"key": "D", "text": "Catharsis"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Aristotle gọi hiện tượng thi ca/bi kịch giúp thanh lọc cảm xúc thương xót và sợ hãi là catharsis. 'Tragedy' là thể loại gây ra catharsis chứ không phải tên hiện tượng.", "key_fact": "Catharsis là sự thanh lọc cảm xúc theo Aristotle.", "topic": "Mỹ học Aristotle", "note": "", "comment_answer": "D"}, {"id": "AET-de2-20", "question": "It is worth noticing that in Beardsley's view, ... of a work of art arises entirely from the work's formal qualities.", "options": [{"key": "A", "text": "the value"}, {"key": "B", "text": "the price"}, {"key": "C", "text": "the ideas"}, {"key": "D", "text": "the date"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Câu giống hệt de2-20: theo Beardsley, giá trị (the value) của tác phẩm hoàn toàn phát sinh từ các phẩm chất hình thức. Ở bản de3 thứ tự phương án bị đảo, 'the value' là B, còn A là 'the price' – sai. (Nguồn: https://plato.stanford.edu/entries/aesthetic-concept/ ; trùng câu AET-de2-20)", "key_fact": "Beardsley: value của tác phẩm đến từ phẩm chất hình thức.", "topic": "Giá trị nghệ thuật", "note": "", "comment_answer": "A"}, {"id": "AET-de2-21", "question": "According to critic Daniel Durchholz, how was Tom Waits's singing voice developed?", "options": [{"key": "A", "text": "Through extensive vocal training and classical techniques"}, {"key": "B", "text": "By performing in smoky bars and clubs for many years"}, {"key": "C", "text": "By soaking his voice in a vat of bourbon, leaving it in a smokehouse, and running it over with a car"}, {"key": "D", "text": "Through a combination of natural talent and professional coaching"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Daniel Durchholz mô tả giọng Waits như được 'ngâm trong thùng bourbon, để trong lò hun khói rồi bị xe cán qua'. Phương án D (tài năng + huấn luyện) không có trong nguồn.", "key_fact": "Durchholz: giọng Waits như 'ngâm bourbon, hun khói, bị xe cán'.", "topic": "Âm nhạc đại chúng", "note": "", "comment_answer": "D"}, {"id": "AET-de2-22", "question": "In ...., First and Last, a catalogue of 219 of Evans's 20,000 photographs, was published", "options": [{"key": "A", "text": "1978"}, {"key": "B", "text": "1979"}, {"key": "C", "text": "1980"}, {"key": "D", "text": "1981"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Walker Evans: First and Last' được Harper & Row xuất bản năm 1978 (khớp đáp án de2-22). Ở bản de3, 1978 là phương án B; 1979 là sai. (Nguồn: https://biblio.co.uk/0060112611 ; https://www.cca.qc.ca/en/search/details/library/publication/04516166)", "key_fact": "First and Last (Walker Evans) – 1978.", "topic": "Nhiếp ảnh Walker Evans", "note": "", "comment_answer": "A"}, {"id": "AET-de2-23", "question": "What do 'feminist art' and the aesthetics of Black people have in common?", "options": [{"key": "A", "text": "No commonality"}, {"key": "B", "text": "Both focus on the beauty of the human body."}, {"key": "C", "text": "Both are created by Black women."}, {"key": "D", "text": "Both challenge the assumptions about the nature of art and artistic beauty."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nghệ thuật nữ quyền và mỹ học của người da đen đều đặt câu hỏi, thách thức những giả định truyền thống (thường mang tính nam giới, da trắng, phương Tây) về bản chất của nghệ thuật và cái đẹp. Chúng không chỉ tập trung vào vẻ đẹp cơ thể và không nhất thiết do phụ nữ da đen tạo ra.", "key_fact": "Nghệ thuật nữ quyền và mỹ học da đen cùng thách thức quan niệm truyền thống về nghệ thuật và cái đẹp.", "topic": "Mỹ học nữ quyền và chủng tộc", "note": "", "comment_answer": "D"}, {"id": "AET-de2-24", "question": "The ancient Greek philosopher Pythagoras believed that beauty arose from mathematical harmony, order and regularity. In this way, Pythagoras and his followers did not distinguish between ...", "options": [{"key": "A", "text": "the beauty of nature"}, {"key": "B", "text": "the beauty of art"}, {"key": "C", "text": "the beauty of art and the beauty of nature"}, {"key": "D", "text": "the beauty of harmony and the beauty of morality"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Với Pythagoras, cái đẹp đến từ sự hài hòa, trật tự toán học có mặt ở cả vũ trụ lẫn tác phẩm (như âm nhạc), nên ông không phân biệt cái đẹp của nghệ thuật với cái đẹp của tự nhiên. Các phương án A, B chỉ nêu một vế; D liên quan đạo đức không phải trọng tâm câu này.", "key_fact": "Pythagoras: cái đẹp là hài hòa toán học, không tách cái đẹp nghệ thuật khỏi cái đẹp tự nhiên.", "topic": "Mỹ học Pythagoras", "note": "", "comment_answer": "C"}, {"id": "AET-de2-25", "question": "According to Clive Bell, what is art?", "options": [{"key": "A", "text": "It is a means to achieve a beautiful spiritual state."}, {"key": "B", "text": "It is something that evokes aesthetic emotions."}, {"key": "C", "text": "It is a human activity that brings moral benefits."}, {"key": "D", "text": "All of the above answers are correct."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Clive Bell định nghĩa nghệ thuật qua 'hình thức có ý nghĩa' (significant form) – thứ khơi gợi cảm xúc thẩm mỹ. Lợi ích đạo đức hay trạng thái tinh thần không phải định nghĩa của Bell nên D sai.", "key_fact": "Clive Bell: nghệ thuật = hình thức có ý nghĩa khơi gợi cảm xúc thẩm mỹ.", "topic": "Chủ nghĩa hình thức Clive Bell", "note": "", "comment_answer": "D"}, {"id": "AET-de2-26", "question": "According to contextualists, what is the main difference between an original work of art and a derivative work?", "options": [{"key": "A", "text": "The value of the artwork."}, {"key": "B", "text": "The reputation of the author."}, {"key": "C", "text": "The creative conditions of the artwork."}, {"key": "D", "text": "The aesthetic properties of the artwork."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thuyết ngữ cảnh (contextualism) cho rằng hai vật trông giống hệt nhau vẫn khác nhau vì hoàn cảnh/điều kiện sáng tạo (lịch sử, ý định, bối cảnh nghệ thuật). Vì vậy khác biệt giữa bản gốc và bản phái sinh nằm ở điều kiện sáng tạo, không chỉ ở thuộc tính thẩm mỹ cảm nhận được hay danh tiếng tác giả.", "key_fact": "Contextualism: tác phẩm được xác định bởi bối cảnh/điều kiện sáng tạo của nó.", "topic": "Thuyết ngữ cảnh", "note": "", "comment_answer": "C"}, {"id": "AET-de2-27", "question": "What causes the paradox in the novel to arise?", "options": [{"key": "A", "text": "The paradox arises from a conflict in our beliefs, not a conflict between our beliefs and facts"}, {"key": "B", "text": "paradox arises from acceptance of our beliefs, not conflict between our beliefs and our truth."}, {"key": "C", "text": "the paradox arises from a failure to accept our beliefs, not a conflict between our beliefs and our truth."}, {"key": "D", "text": "None of these answer"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nghịch lý hư cấu (paradox of fiction) nảy sinh vì ba niềm tin đều có vẻ hợp lý nhưng mâu thuẫn với nhau (ta xúc động với nhân vật; cảm xúc cần niềm tin rằng đối tượng tồn tại; ta biết nhân vật không tồn tại). Tức là xung đột nằm trong chính các niềm tin của ta, không phải giữa niềm tin và sự thật.", "key_fact": "Nghịch lý hư cấu: mâu thuẫn giữa các niềm tin hợp lý của chính chúng ta.", "topic": "Nghịch lý hư cấu", "note": "", "comment_answer": "A"}, {"id": "AET-de2-28", "question": "According to Tom Leddy, what roles do \"superficial aesthetic qualities\" like tidiness or messiness play? Is tidiness or messiness a criterion for evaluating whether a work is art or non-art?", "options": [{"key": "A", "text": "They are unimportant parts of our aesthetic experience."}, {"key": "B", "text": "They are important parts of our aesthetic experience, but only applicable to the artistic environment."}, {"key": "C", "text": "They are important parts of our aesthetic experience, applicable to both artistic and non-artistic environments."}, {"key": "D", "text": "They are important parts of our aesthetic experience, but only applicable to non-artistic environments."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tom Leddy, người nghiên cứu mỹ học đời thường, cho rằng các phẩm chất thẩm mỹ 'bề mặt' như gọn gàng hay bừa bộn là phần quan trọng của trải nghiệm thẩm mỹ và áp dụng cho cả môi trường nghệ thuật lẫn phi nghệ thuật. Vì vậy chúng không dùng làm tiêu chí phân biệt nghệ thuật/phi nghệ thuật; các phương án giới hạn vào một môi trường là sai.", "key_fact": "Leddy: phẩm chất thẩm mỹ bề mặt (gọn gàng, bừa bộn) có mặt cả trong nghệ thuật lẫn đời thường.", "topic": "Mỹ học đời thường", "note": "", "comment_answer": null}, {"id": "AET-de2-29", "question": "According to which view is the meaning of a work of art primarily determined by?", "options": [{"key": "A", "text": "The author's intention"}, {"key": "B", "text": "The content of the work"}, {"key": "C", "text": "The reader"}, {"key": "D", "text": "All three factors above"}], "answer": ["A"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Câu hỏi mơ hồ; quan điểm tiêu biểu xem nghĩa tác phẩm 'được quyết định chủ yếu' bởi một yếu tố là thuyết ý định (Hirsch): ý định tác giả. 'Cả ba' (D) mâu thuẫn với 'primarily'. (Nguồn: https://plato.stanford.edu/entries/art-interpretation/ (tham khảo))", "key_fact": "Intentionalism (Hirsch): nghĩa = ý định tác giả.", "topic": "Diễn giải tác phẩm", "note": "", "comment_answer": "D"}, {"id": "AET-de2-30", "question": "According to Torquato Tasso, where does the beauty of art originate from?", "options": [{"key": "A", "text": "The creative ability of humans."}, {"key": "B", "text": "The techniques and tools of the artist."}, {"key": "C", "text": "Direct imitation of the beauty of nature."}, {"key": "D", "text": "Religious belief and spirituality."}], "answer": ["C"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Tasso theo truyền thống Phục hưng–Aristotle coi thơ/nghệ thuật là mô phỏng tự nhiên, nên cái đẹp của nghệ thuật bắt nguồn từ việc mô phỏng cái đẹp tự nhiên. Không tìm được câu gốc trong giáo trình. (Nguồn: https://literariness.org/2017/12/15/literary-criticism-of-torquato-tasso/)", "key_fact": "Tasso: đẹp của nghệ thuật = mô phỏng đẹp của tự nhiên.", "topic": "Mỹ học Phục hưng", "note": "", "comment_answer": "C"}, {"id": "AET-de2-31", "question": "Anthony Ashley Cooper,3rd Earl of Shaftesbury said:\n\"The painting and the music invite us to do what we would seldom do in ordinary life - pay attention only to what we are ...., and ignore everything else.\"", "options": [{"key": "A", "text": "Tasting or touching"}, {"key": "B", "text": "Looking or smelling"}, {"key": "C", "text": "seeing or hearing"}, {"key": "D", "text": "Loving or understanding"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Shaftesbury nói hội họa và âm nhạc mời ta chỉ chú ý vào những gì ta đang nhìn hoặc nghe (seeing or hearing) và bỏ qua mọi thứ khác – tiền đề của ý niệm thái độ thẩm mỹ vô vụ lợi. Hội họa gắn với thị giác, âm nhạc gắn với thính giác nên các giác quan khác không phù hợp.", "key_fact": "Shaftesbury: nghệ thuật khiến ta chỉ chú tâm vào điều đang thấy hoặc nghe.", "topic": "Shaftesbury và thái độ thẩm mỹ", "note": "", "comment_answer": "C"}, {"id": "AET-de2-32", "question": "According to Berys Gaut, intentionalist critics like Hirsch and anti-intentionalist critics like Wimsatt and Beardsley are trying to do?", "options": [{"key": "A", "text": "Explaining the meaning of a work of art."}, {"key": "B", "text": "Analysis of various aspects of interpretation"}, {"key": "C", "text": "To find a universal theory of interpretation"}, {"key": "D", "text": "Evaluating the value of a work of art"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Gaut cho rằng cả phe theo ý định (Hirsch) và phe chống ý định (Wimsatt, Beardsley) đều đi tìm một lý thuyết diễn giải phổ quát, đơn nhất; ông đề xuất 'patchwork theory' đa nguyên thay thế. Phân tích nhiều khía cạnh (B) chính là cách tiếp cận của Gaut, không phải của họ.", "key_fact": "Gaut: Hirsch và Wimsatt–Beardsley đều tìm một lý thuyết diễn giải phổ quát; Gaut chủ trương 'patchwork'.", "topic": "Diễn giải tác phẩm", "note": "", "comment_answer": "B"}, {"id": "AET-de2-33", "question": "We looked at David Hume's theory of taste, in which he argues that the critic's job is to distance himself from his own sentimentality, to overcome his own prejudices and to become, as much as possible, a 'man in ...'", "options": [{"key": "A", "text": "Special"}, {"key": "B", "text": "Normal"}, {"key": "C", "text": "General"}, {"key": "D", "text": "Loyal"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hume cho rằng nhà phê bình phải gạt bỏ định kiến và trở thành 'man in general' (con người nói chung), xem xét tác phẩm từ quan điểm chung chứ không riêng tư. Các từ 'special', 'normal', 'loyal' không phải thuật ngữ của Hume.", "key_fact": "Hume: nhà phê bình lý tưởng là 'man in general'.", "topic": "Lý thuyết thị hiếu Hume", "note": "", "comment_answer": "C"}, {"id": "AET-de2-34", "question": "According to Virginia Woolf, what is necessary for a woman to be able to write?", "options": [{"key": "A", "text": "Natural talent."}, {"key": "B", "text": "Formal education."}, {"key": "C", "text": "Natural talent and formal education."}, {"key": "D", "text": "Money, a room of one's own, and educational attainment."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong 'A Room of One's Own', Virginia Woolf khẳng định người phụ nữ cần có tiền và một căn phòng riêng (cùng điều kiện học vấn) để có thể viết. Tài năng tự nhiên hay giáo dục chính quy đơn thuần không phải luận điểm chính của bà.", "key_fact": "Woolf: phụ nữ cần tiền và một căn phòng riêng để viết.", "topic": "Nữ quyền và nghệ thuật", "note": "", "comment_answer": "D"}, {"id": "AET-de2-35", "question": "Who argues that although we value art for something it gives us, we should nevertheless distinguish this sort of value from instrumental value, broadly speaking ?", "options": [{"key": "A", "text": "Malcolm Budd"}, {"key": "B", "text": "Joel Feinberg"}, {"key": "C", "text": "Monroe Beardsley"}, {"key": "D", "text": "Willem de Kooning"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Malcolm Budd lập luận rằng ta trân trọng nghệ thuật vì trải nghiệm mà nó mang lại, nhưng giá trị này là nội tại trong trải nghiệm tác phẩm, cần phân biệt với giá trị công cụ thông thường. Feinberg là triết gia luật, de Kooning là họa sĩ.", "key_fact": "Malcolm Budd: giá trị nghệ thuật nằm trong trải nghiệm tác phẩm, khác giá trị công cụ.", "topic": "Giá trị nghệ thuật", "note": "", "comment_answer": "A"}, {"id": "AET-de2-36", "question": "In his book, ... Richard Wollheim considers what he calls the 'physical-object hypothesis': the view that artworks simply are physical objects", "options": [{"key": "A", "text": "Love and Its Objects"}, {"key": "B", "text": "Aesthetics and Its Objects"}, {"key": "C", "text": "Beauty and Its Objects"}, {"key": "D", "text": "Art and Its Objects"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Richard Wollheim bàn về 'giả thuyết vật thể vật lý' trong cuốn 'Art and Its Objects' (1968). Các tên sách còn lại là bịa đặt.", "key_fact": "Wollheim, 'Art and Its Objects': phê phán giả thuyết tác phẩm là vật thể vật lý.", "topic": "Bản thể luận nghệ thuật", "note": "", "comment_answer": "D"}, {"id": "AET-de2-37", "question": "In his book Language of Art, Nelson Goodman introduces the terms '....' and 'allographic' to determine what makes something a genuine instance of a given work", "options": [{"key": "A", "text": "Biographic"}, {"key": "B", "text": "Calligraphic"}, {"key": "C", "text": "Typographic"}, {"key": "D", "text": "Autographic"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nelson Goodman trong 'Languages of Art' phân biệt nghệ thuật 'autographic' (có thể làm giả, như hội họa) và 'allographic' (không làm giả được, như âm nhạc có bản nhạc). Các từ khác không phải thuật ngữ của Goodman.", "key_fact": "Goodman: autographic (hội họa) vs allographic (âm nhạc, văn học).", "topic": "Bản thể luận nghệ thuật", "note": "", "comment_answer": "D"}, {"id": "AET-de2-38", "question": "The Exorcist was a cultural phenomenon. It remains the highest-grossing R-rated film of all time, and was nominated for ten Academy Awards, including Best Picture. Although it didn't win that highest award, it does have the honour of being the very first horror movie to be nominated for a Best Picture ...", "options": [{"key": "A", "text": "Oscar"}, {"key": "B", "text": "Tiff"}, {"key": "C", "text": "Cannes"}, {"key": "D", "text": "Golden globe awards"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "The Exorcist là phim kinh dị đầu tiên được đề cử giải Phim hay nhất của Oscar (Academy Awards). Câu hỏi nói rõ 'Academy Awards', nên không phải Cannes, TIFF hay Quả cầu vàng.", "key_fact": "The Exorcist là phim kinh dị đầu tiên được đề cử Oscar Phim hay nhất.", "topic": "Điện ảnh kinh dị", "note": "", "comment_answer": "A"}, {"id": "AET-de2-39", "question": "According to Shusterman, how can the suppression of bad art to allow good art to flourish be justified?", "options": [{"key": "A", "text": "By arguing that bad art can harm society."}, {"key": "B", "text": "By arguing that good art serves the ultimate moral benefit."}, {"key": "C", "text": "By arguing that good art will always prevail over bad art."}, {"key": "D", "text": "By arguing that bad art is a waste of time and money."}], "answer": ["B"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Lập luận (kiểu Plato, được Shusterman phân tích) biện minh việc dẹp nghệ thuật xấu bằng lợi ích đạo đức tối hậu mà nghệ thuật tốt mang lại. Không tìm được nguồn trực tiếp xác nhận. (Nguồn: https://www.stephenhicks.org/2012/01/21/plato-on-censoring-artists-a-summary/)", "key_fact": "Shusterman: dẹp art xấu được biện minh bằng lợi ích đạo đức tối hậu của art tốt.", "topic": "Nghệ thuật đại chúng Shusterman", "note": "", "comment_answer": "B"}, {"id": "AET-de2-40", "question": "Fill in the blank :\nAccording to Kant why cannot genius be taught?\nKant argues:...............", "options": [{"key": "A", "text": "Art does not follow determinate rules."}, {"key": "B", "text": "Rules that can simply be explained to, and followed by, anyone else."}, {"key": "C", "text": "All of these answers."}, {"key": "D", "text": "None of these answers."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kant lập luận nghệ thuật không theo những quy tắc xác định – những quy tắc có thể đơn giản được giải thích cho và làm theo bởi bất kỳ ai – nên thiên tài không thể dạy được. A và B là hai nửa của cùng một câu nên 'All of these answers' là đúng.", "key_fact": "Kant: thiên tài không thể dạy vì nghệ thuật không theo quy tắc xác định.", "topic": "Thiên tài theo Kant", "note": "", "comment_answer": "C"}, {"id": "AET-de2-41", "question": "Who painted \"Nude Descending a Staircase\", No. 2 (1912)?", "options": [{"key": "A", "text": "Hans Arp"}, {"key": "B", "text": "Marcel Duchamp"}, {"key": "C", "text": "Salvador Dalí"}, {"key": "D", "text": "Man Ray"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Nude Descending a Staircase, No. 2' (1912) là tác phẩm của Marcel Duchamp, gây chấn động tại Armory Show 1913. Arp, Dalí, Man Ray không phải tác giả.", "key_fact": "Duchamp vẽ 'Nude Descending a Staircase, No. 2' (1912).", "topic": "Nghệ thuật hiện đại", "note": "", "comment_answer": "B"}, {"id": "AET-de2-42", "question": "The intertwining of ... and ... goes back to Western philosophy's beginnings in ancient Greece, long before either had truly become its own discrete area of concern.", "options": [{"key": "A", "text": "Aesthetics-philosophy"}, {"key": "B", "text": "Aesthetics- ethics"}, {"key": "C", "text": "Ethics- philosophy"}, {"key": "D", "text": "Ethics- Love"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sự đan xen giữa mỹ học và đạo đức học có từ khởi đầu triết học phương Tây ở Hy Lạp cổ đại (khái niệm kalon vừa là đẹp vừa là tốt). Cả hai đều là nhánh của triết học nên phương án có 'philosophy' không hợp lý.", "key_fact": "Mỹ học và đạo đức học gắn bó từ thời Hy Lạp cổ đại.", "topic": "Mỹ học và đạo đức", "note": "", "comment_answer": "B"}, {"id": "AET-de2-43", "question": "When we practice futures thinking methods, they can help you build SEVEN key strengths. One of the strengths is Empathy. Which of the following best describes Empathy in terms of futures thinking?", "options": [{"key": "A", "text": "You transcend traditional ideas, and invent new possibilities. You can imagine things that don't exist today or have never happened before"}, {"key": "B", "text": "You anticipate hard to see possibilities that others can't or won't see. You don't get blindsided by the future. You see it coming."}, {"key": "C", "text": "You accept that things can be different than they are now, that virtually anything can change. This is the opposite of having a fixed or a stuck mindset."}, {"key": "D", "text": "You have a strong awareness of the hopes and fears of others. You pay close attention to how any future could affect different groups of people and communities differently."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sự đồng cảm (Empathy) trong tư duy tương lai là nhận thức sâu sắc về hy vọng và nỗi sợ của người khác, chú ý tác động khác nhau của tương lai đến các nhóm cộng đồng. A là trí tưởng tượng, B là khả năng tiên liệu, C là sự linh hoạt (tư duy mở).", "key_fact": "Empathy trong futures thinking: hiểu hy vọng, nỗi sợ và tác động khác nhau lên các nhóm người.", "topic": "Tư duy tương lai", "note": "", "comment_answer": "D"}, {"id": "AET-de2-44", "question": "Walton argues that, in almost all cases, one of the latter ....conditions will trump the others. It would be strange, for instance, to suggest that a work belongs to a category with which its artist was unfamiliar.", "options": [{"key": "A", "text": "One"}, {"key": "B", "text": "Two"}, {"key": "C", "text": "Three"}, {"key": "D", "text": "Four"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Walton nêu bốn điều kiện xác định một tác phẩm thuộc phạm trù nào; hai điều kiện sau (ý định/kỳ vọng của nghệ sĩ và sự công nhận phạm trù trong xã hội) thường lấn át các điều kiện khác. Ví dụ nghệ sĩ không biết đến phạm trù thì tác phẩm khó thuộc phạm trù đó gắn với hai điều kiện này.", "key_fact": "Walton: hai điều kiện cuối (ý định nghệ sĩ, sự công nhận xã hội) thường quyết định phạm trù.", "topic": "Phạm trù nghệ thuật Walton", "note": "", "comment_answer": "B"}, {"id": "AET-de2-45", "question": "Among the philosophers below, who argued that art is an 'open' concept?", "options": [{"key": "A", "text": "Monroe Beardsley"}, {"key": "B", "text": "Morris Weitz"}, {"key": "C", "text": "R.G. Collingwood"}, {"key": "D", "text": "Arthur Danto"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Morris Weitz (1956) dùng ý tưởng 'tương đồng gia đình' của Wittgenstein để lập luận 'nghệ thuật' là một khái niệm mở, không thể định nghĩa bằng điều kiện cần và đủ. Danto, Beardsley, Collingwood đều đưa ra định nghĩa nghệ thuật.", "key_fact": "Morris Weitz: nghệ thuật là khái niệm mở (open concept).", "topic": "Định nghĩa nghệ thuật", "note": "", "comment_answer": "B"}, {"id": "AET-de2-46", "question": "Why is the audience, as well as Ion himself, overcome with emotion during the recitation of the Trojan War stories, even though the events took place centuries ago and everyone already knows the outcome?", "options": [{"key": "A", "text": "The audience is unfamiliar with the story, creating suspense and surprise."}, {"key": "B", "text": "Ion's emotional portrayal adds a new perspective to the well-known story."}, {"key": "C", "text": "The events of the Trojan War hold intrinsic emotional power that transcends time and familiarity."}, {"key": "D", "text": "Socrates suggests that Ion is not actually emotional; it's a theatrical performance."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong 'Ion' của Plato, khán giả và Ion xúc động dù đã biết cốt truyện vì sức mạnh cảm xúc của câu chuyện (qua cảm hứng thần thánh lan truyền) vượt thời gian và sự quen thuộc. A sai vì khán giả đã biết truyện; D sai vì Ion thừa nhận mình thực sự xúc động.", "key_fact": "Plato 'Ion': câu chuyện quen thuộc vẫn gây xúc động mạnh nhờ sức mạnh cảm xúc nội tại/cảm hứng.", "topic": "Mỹ học Plato", "note": "", "comment_answer": "C"}, {"id": "AET-de2-47", "question": "On Susan Feagin's view, we can distinguish between 'direct responses' and '.... responses'.", "options": [{"key": "A", "text": "Alpha-"}, {"key": "B", "text": "Beta-"}, {"key": "C", "text": "Gama-"}, {"key": "D", "text": "Meta-"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Susan Feagin phân biệt 'direct responses' (phản ứng trực tiếp với tác phẩm) và 'meta-responses' (phản ứng về chính phản ứng của mình), dùng để giải thích nghịch lý bi kịch. Alpha, Beta, Gamma không phải thuật ngữ của bà.", "key_fact": "Feagin: direct responses và meta-responses.", "topic": "Nghịch lý bi kịch", "note": "", "comment_answer": "D"}, {"id": "AET-de2-48", "question": "How does Levinson define a new work of art?", "options": [{"key": "A", "text": "Some exhibited features of the artwork."}, {"key": "B", "text": "Its relationship with a formal or informal artistic organization."}, {"key": "C", "text": "Its relationship with pre-existing art."}, {"key": "D", "text": "Our experience of the artwork."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Jerrold Levinson đưa ra định nghĩa lịch sử: một thứ là nghệ thuật nếu được dự định để được xem xét theo những cách mà các tác phẩm nghệ thuật trước đó đã được xem xét, tức dựa trên quan hệ với nghệ thuật có từ trước. B là thuyết thể chế (Dickie).", "key_fact": "Levinson: định nghĩa lịch sử – quan hệ với nghệ thuật đã có trước.", "topic": "Định nghĩa nghệ thuật", "note": "", "comment_answer": "C"}, {"id": "AET-de2-49", "question": "Who produced the most well-known formalist theory of art?", "options": [{"key": "A", "text": "Cezanne"}, {"key": "B", "text": "Man Ray"}, {"key": "C", "text": "Clive Bell"}, {"key": "D", "text": "Roger Fry"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thuyết hình thức nổi tiếng nhất là của Clive Bell trong 'Art' (1914) với khái niệm 'significant form'. Roger Fry cũng là nhà hình thức luận nhưng Bell được xem là người đưa ra lý thuyết tiêu biểu nhất.", "key_fact": "Clive Bell là tác giả lý thuyết hình thức luận nổi tiếng nhất.", "topic": "Chủ nghĩa hình thức", "note": "", "comment_answer": "C"}, {"id": "AET-de2-50", "question": "What is an advantage in Collingwood's artistic view/perspective?", "options": [{"key": "A", "text": "It can be applied universally to all forms of art."}, {"key": "B", "text": "Distinguishes artwork from art itself, essentially a spiritual rather than a material thing."}, {"key": "C", "text": "Argues about \"entertainment art\"."}, {"key": "D", "text": "Argues about magic art."}], "answer": ["B"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Collingwood (The Principles of Art) phân biệt vật thể nghệ thuật với tác phẩm thật nằm trong trí tưởng tượng – nghệ thuật về bản chất là tinh thần chứ không vật chất; điều này giúp tránh rắc rối về đối tượng trừu tượng (câu de1-12). Nghệ thuật giải trí/ma thuật là 'nghệ thuật giả' ông phê phán, không phải ưu điểm. (Nguồn: https://plato.stanford.edu/entries/collingwood-aesthetics/)", "key_fact": "Collingwood: art thật ở trong trí tưởng tượng (tinh thần), không phải vật chất.", "topic": "Mỹ học Collingwood", "note": "", "comment_answer": "A"}]}, {"id": "de3", "name": "Đề 3", "questions": [{"id": "AET-de3-1", "question": "In 1981, ... re-photographed a number of the images in First and Last, including Evans's Alabama Tenant Farmer Wife - a portrait of Allie Mae Burroughs - titling her 're-photograph' of Evans's iconic image After Walker Evans: 4.", "options": [{"key": "A", "text": "Michael Mandiberg"}, {"key": "B", "text": "Sherrie Levine"}, {"key": "C", "text": "Walker Evans"}, {"key": "D", "text": "James Agee"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Năm 1981 Sherrie Levine chụp lại các ảnh của Walker Evans và đặt tên 'After Walker Evans: 4'. Walker Evans là tác giả ảnh gốc, James Agee là nhà văn cộng tác với Evans, còn Mandiberg làm lại vào năm 2001.", "key_fact": "Sherrie Levine – 'After Walker Evans' (1981).", "topic": "Tính nguyên bản và sao chép", "note": "", "comment_answer": "B"}, {"id": "AET-de3-2", "question": "Who produced the most well-known formalist theory of art?", "options": [{"key": "A", "text": "Cezanne"}, {"key": "B", "text": "Clive Bell"}, {"key": "C", "text": "Roger Fry"}, {"key": "D", "text": "Man Ray"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thuyết hình thức nổi tiếng nhất là của Clive Bell trong 'Art' (1914) với khái niệm 'significant form'. Roger Fry cũng là nhà hình thức luận nhưng Bell được xem là người đưa ra lý thuyết tiêu biểu nhất.", "key_fact": "Clive Bell là tác giả lý thuyết hình thức luận nổi tiếng nhất.", "topic": "Chủ nghĩa hình thức", "note": "", "comment_answer": "B"}, {"id": "AET-de3-3", "question": "Nature, Kant contends, can also give rise to feelings of ..... - what we might think of as a pronounced awe: where something is sublime, it is quite literally awesome.", "options": [{"key": "A", "text": "the ugly"}, {"key": "B", "text": "the sublime"}, {"key": "C", "text": "the tragedy"}, {"key": "D", "text": "the beauty"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kant cho rằng tự nhiên còn gây ra cảm giác về cái cao cả (the sublime) – một sự kinh sợ choáng ngợp; chính câu văn nói 'where something is sublime'. Cái đẹp (beauty) là loại cảm giác khác mà Kant phân biệt với cái cao cả.", "key_fact": "Kant: tự nhiên gợi cả cái đẹp lẫn cái cao cả (the sublime – sự kính sợ choáng ngợp).", "topic": "Mỹ học Kant", "note": "", "comment_answer": "B"}, {"id": "AET-de3-4", "question": "Fill the blank with the correct words: ...would go on to become one of the best-known works of the twentieth century.", "options": [{"key": "A", "text": "Les Demoiselles d'Avignon (1907)"}, {"key": "B", "text": "Fountain (1917)"}, {"key": "C", "text": "Nude Descending a Staircase, No. 2 (1912)"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Fountain (1917) của Duchamp bị Hội Nghệ sĩ Độc lập từ chối nhưng 'về sau trở thành' một trong những tác phẩm nổi tiếng nhất thế kỷ 20 – cách nói 'would go on to become' phù hợp với một tác phẩm ban đầu bị bác bỏ. Nude Descending (C) cũng gây tranh cãi nhưng không phải tác phẩm được bàn trong đoạn này.", "key_fact": "Fountain (Duchamp, 1917) bị từ chối, về sau thành tác phẩm nổi tiếng bậc nhất thế kỷ 20.", "topic": "Nghệ thuật hiện đại", "note": "", "comment_answer": "B"}, {"id": "AET-de3-5", "question": "Who was the director of a film The good earth (1937)?", "options": [{"key": "A", "text": "Luise Rainer"}, {"key": "B", "text": "Tilly Losch"}, {"key": "C", "text": "Paul Muni"}, {"key": "D", "text": "Sidney Franklin."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Phim 'The Good Earth' (1937) do Sidney Franklin đạo diễn. Luise Rainer (đoạt Oscar với vai O-Lan), Paul Muni và Tilly Losch là diễn viên.", "key_fact": "Đạo diễn 'The Good Earth' (1937) là Sidney Franklin.", "topic": "Điện ảnh Hollywood", "note": "", "comment_answer": "D"}, {"id": "AET-de3-6", "question": "Who introduced the technique of Pointillism, replacing brushstrokes with countless dots of colour?", "options": [{"key": "A", "text": "George Seurat"}, {"key": "B", "text": "Manet"}, {"key": "C", "text": "Monet"}, {"key": "D", "text": "Picasso"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Georges Seurat khởi xướng kỹ thuật điểm họa (Pointillism), thay nét cọ bằng vô số chấm màu, tiêu biểu là 'A Sunday Afternoon on the Island of La Grande Jatte'. Monet, Manet thuộc trường phái Ấn tượng; Picasso gắn với Lập thể.", "key_fact": "Georges Seurat là cha đẻ của kỹ thuật điểm họa (Pointillism).", "topic": "Hội họa Hậu ấn tượng", "note": "", "comment_answer": "A"}, {"id": "AET-de3-7", "question": "During the second and first century bce, Hellenistic philosophers known as the Stoics took this line of thought a step further, suggesting that the world as a whole was beautiful, regarding nature as both art and ...., the universe as the most perfect work of art.", "options": [{"key": "A", "text": "Musician"}, {"key": "B", "text": "Artist"}, {"key": "C", "text": "Architect"}, {"key": "D", "text": "Sculpturer"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Phái Khắc kỷ coi thế giới là đẹp, xem tự nhiên vừa là tác phẩm nghệ thuật vừa là nghệ sĩ (art and artist), vũ trụ là tác phẩm hoàn hảo nhất. Cặp 'art và artist' tạo đối xứng hợp lý, các nghề cụ thể như kiến trúc sư không phù hợp.", "key_fact": "Phái Khắc kỷ: tự nhiên vừa là nghệ thuật vừa là nghệ sĩ.", "topic": "Mỹ học Khắc kỷ", "note": "", "comment_answer": "B"}, {"id": "AET-de3-8", "question": "Fill the blank: Rolling Stone places Waits at No. 55 on their list of the '100 Greatest Songwriters of All Time' and at No. 81 on their list of the '100 Greatest Singers', sandwiched between blues legend John Lee Hooker and 'punk poet laureate' Patti Smith. It's as comfortable a place as any for Waits, who is equal parts ....", "options": [{"key": "A", "text": "traditional"}, {"key": "B", "text": "traditional and groundbreaking"}, {"key": "C", "text": "groundbreaking."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tom Waits được mô tả là vừa truyền thống vừa đột phá ('equal parts' đòi hỏi hai thành phần). Vị trí giữa huyền thoại blues John Lee Hooker (truyền thống) và Patti Smith (punk, đột phá) phản ánh điều đó.", "key_fact": "Tom Waits: nửa truyền thống, nửa đột phá.", "topic": "Âm nhạc đại chúng", "note": "", "comment_answer": "B"}, {"id": "AET-de3-9", "question": "Stecker agrees with Beardsley and Schlesinger (among others) that art functions are normally tied to experience - to ...", "options": [{"key": "A", "text": "Aesthetic experience."}, {"key": "B", "text": "Aesthetic propoties"}, {"key": "C", "text": "Aesthetic funtions"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Stecker đồng ý với Beardsley và Schlesinger rằng chức năng của nghệ thuật thường gắn với trải nghiệm, cụ thể là trải nghiệm thẩm mỹ. Các phương án còn lại là thuộc tính/chức năng chứ không phải trải nghiệm.", "key_fact": "Stecker: chức năng nghệ thuật gắn với trải nghiệm thẩm mỹ.", "topic": "Định nghĩa chức năng nghệ thuật", "note": "", "comment_answer": "A"}, {"id": "AET-de3-10", "question": "Briefly mentioned in Chapter 1 was ... 1991 work 'Untitled' (Throat), consisting of an ordinary pile of packaged cough drops on an ordinary handkerchief. This work was just one in a series of works in which audience members were encouraged to take part of the work with them - in this case, a lozenge", "options": [{"key": "A", "text": "Felix Gonzales-Torres'"}, {"key": "B", "text": "Helena"}, {"key": "C", "text": "Carl Andre's"}, {"key": "D", "text": "Marco Evaristti'"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Untitled' (Throat) 1991 – đống viên ngậm ho trên khăn tay mà khán giả được lấy mang về – là tác phẩm của Felix Gonzalez-Torres. Carl Andre nổi tiếng với tác phẩm tấm chì; Marco Evaristti với 'Helena' (máy xay sinh tố có cá vàng).", "key_fact": "Felix Gonzalez-Torres: 'Untitled' (Throat), khán giả lấy một phần tác phẩm.", "topic": "Nghệ thuật đương đại", "note": "", "comment_answer": "A"}, {"id": "AET-de3-11", "question": "Affectionately named 'Mr Blobby', the 285mm specimen was caught off the coast of New Zealand in 2003 by the crew of the RV Tangoroa, a deep-water scientific research vessel, named for the Māori god of the sea. Name of fish in this text?", "options": [{"key": "A", "text": "The Blobfish"}, {"key": "B", "text": "The Hagfish"}, {"key": "C", "text": "The Archerfish"}, {"key": "D", "text": "The kingfish"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Mr Blobby' là con cá giọt nước (blobfish) bắt ngoài khơi New Zealand năm 2003, sau được bầu là loài vật xấu xí nhất thế giới. Hagfish, archerfish, kingfish không phải nhân vật này.", "key_fact": "'Mr Blobby' là cá giọt nước (blobfish).", "topic": "Thẩm mỹ cái xấu", "note": "", "comment_answer": "A"}, {"id": "AET-de3-12", "question": "Choose the answer that best fills the blank: Duchamp' studio was in ....", "options": [{"key": "A", "text": "New- York"}, {"key": "B", "text": "Paris"}, {"key": "C", "text": "Portuga"}, {"key": "D", "text": "Mandrid"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khi tạo 'Fountain' (1917), Duchamp sống và làm việc tại New York; bồn tiểu được mua ở New York và mang về studio của ông. Dù ông là người Pháp, bối cảnh trong giáo trình là New York.", "key_fact": "Studio của Duchamp (thời 'Fountain') ở New York.", "topic": "Duchamp và Fountain", "note": "", "comment_answer": "A"}, {"id": "AET-de3-13", "question": "Who is considered by many to be the father of Western philosophy?", "options": [{"key": "A", "text": "Plato"}, {"key": "B", "text": "Socrates"}, {"key": "C", "text": "Heraklitus"}, {"key": "D", "text": "Pythagoras"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Socrates thường được xem là cha đẻ của triết học phương Tây vì đặt nền móng cho đạo đức học và phương pháp đối thoại; Plato là học trò của ông. Một số nguồn coi Thales là triết gia đầu tiên nhưng không có trong lựa chọn.", "key_fact": "Socrates được nhiều người xem là cha đẻ của triết học phương Tây.", "topic": "Triết học Hy Lạp", "note": "", "comment_answer": "B"}, {"id": "AET-de3-14", "question": "Fill the blank: Russian artist Kasimir Malevich outgrew the movement he himself had founded, and created its successor, ....", "options": [{"key": "A", "text": "Romanticsm"}, {"key": "B", "text": "Cubism"}, {"key": "C", "text": "Suprematism."}, {"key": "D", "text": "Futurism"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Malevich vượt qua trào lưu Lập thể-Vị lai (Cubo-Futurism) và sáng lập trào lưu kế tiếp là Chủ nghĩa Tối thượng (Suprematism), với tác phẩm tiêu biểu 'Black Square'. Lập thể do Picasso, Braque khởi xướng.", "key_fact": "Malevich sáng lập Suprematism (Chủ nghĩa Tối thượng).", "topic": "Nghệ thuật tiên phong Nga", "note": "", "comment_answer": "C"}, {"id": "AET-de3-15", "question": "Is it corect, Aristotle suggested that beauty is bound up in size and order?", "options": [{"key": "A", "text": "No"}, {"key": "B", "text": "Yes"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Aristotle trong 'Poetics' cho rằng cái đẹp gắn với kích thước và trật tự (vật đẹp phải có trật tự các phần và kích thước phù hợp). Vì vậy câu nhận định là đúng.", "key_fact": "Aristotle: cái đẹp gắn với kích thước và trật tự.", "topic": "Mỹ học Aristotle", "note": "", "comment_answer": "B"}, {"id": "AET-de3-16", "question": "Originally installed in Denmark's Trapholt Art Museum, ..... consists of ten water-filled Moulinex-Optiblend 2000 blenders, each containing a live goldfish", "options": [{"key": "A", "text": "Helena"}, {"key": "B", "text": "Maria"}, {"key": "C", "text": "Anna"}, {"key": "D", "text": "Karla"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tác phẩm 10 máy xay Moulinex chứa cá vàng tại bảo tàng Trapholt (Đan Mạch, 2000) của Marco Evaristti tên là 'Helena' (cùng câu de1-48 đã chọn Helena). Đáp án B 'Maria' trong bản này là sai do đảo thứ tự phương án. (Nguồn: https://en.wikipedia.org/wiki/Helena_(artwork))", "key_fact": "Helena (Marco Evaristti, 2000, Trapholt) – 10 máy xay cá vàng.", "topic": "Nghệ thuật và đạo đức", "note": "", "comment_answer": "A"}, {"id": "AET-de3-17", "question": "When was the exhibition in the Dobychina Gallery, Russia's leading private commercial gallery, Subtitled 'The Last Futurist Exhibition', '0,10' is perhaps better known for its role as the first Suprematist exhibition be held?", "options": [{"key": "A", "text": "1917"}, {"key": "B", "text": "1918"}, {"key": "C", "text": "1916"}, {"key": "D", "text": "1915"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Triển lãm '0,10' – 'Triển lãm Vị lai cuối cùng' tại Phòng tranh Dobychina, Petrograd – diễn ra năm 1915, là triển lãm Suprematist đầu tiên với 'Black Square'. 1916-1918 là gây nhiễu.", "key_fact": "Triển lãm '0,10' diễn ra năm 1915.", "topic": "Nghệ thuật tiên phong Nga", "note": "", "comment_answer": "D"}, {"id": "AET-de3-18", "question": "It is worth noticing that in Beardsley's view, .... of a work of art arises entirely from the work's formal qualities.", "options": [{"key": "A", "text": "the price"}, {"key": "B", "text": "the value"}, {"key": "C", "text": "the date"}, {"key": "D", "text": "the ideas"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Câu giống hệt de2-20: theo Beardsley, giá trị (the value) của tác phẩm hoàn toàn phát sinh từ các phẩm chất hình thức. Ở bản de3 thứ tự phương án bị đảo, 'the value' là B, còn A là 'the price' – sai. (Nguồn: https://plato.stanford.edu/entries/aesthetic-concept/ ; trùng câu AET-de2-20)", "key_fact": "Beardsley: value của tác phẩm đến từ phẩm chất hình thức.", "topic": "Giá trị nghệ thuật", "note": "", "comment_answer": "B"}, {"id": "AET-de3-19", "question": "In 1998, for its twenty-fifth anniversary, The Exorcist was re-released in cinemas as '...'.", "options": [{"key": "A", "text": "The Exorcist 2"}, {"key": "B", "text": "The Version You've Never Seen'"}, {"key": "C", "text": "The Scariest Movie of All Time"}, {"key": "D", "text": "The cultural phenomenon."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Dịp kỷ niệm, The Exorcist được tái phát hành với tên 'The Version You've Never Seen' (bản mở rộng có các cảnh bị cắt). Các phương án khác là phần tiếp theo hoặc khẩu hiệu không phải tên bản phát hành.", "key_fact": "Bản tái phát hành của The Exorcist: 'The Version You've Never Seen'.", "topic": "Điện ảnh kinh dị", "note": "", "comment_answer": "B"}, {"id": "AET-de3-20", "question": "The official logo of the World Wildlife Fund is an adorable ..", "options": [{"key": "A", "text": "Cat"}, {"key": "B", "text": "Dog"}, {"key": "C", "text": "Eagle"}, {"key": "D", "text": "Panda"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Logo chính thức của WWF là con gấu trúc (panda). Đây là ví dụ kinh điển về động vật 'dễ thương' được dùng trong bảo tồn.", "key_fact": "Logo WWF là gấu trúc.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": "D"}, {"id": "AET-de3-21", "question": "Fill in the blank with the correct words: In the history of aesthetics and the philosophy of art tends to go overlooked by contemporary philosophers except.....?", "options": [{"key": "A", "text": "Plato"}, {"key": "B", "text": "Kant"}, {"key": "C", "text": "Plato, Aristotle and Kant"}, {"key": "D", "text": "Aristotle"}], "answer": ["C"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Ý giáo trình: ngoài Plato, Aristotle và Kant – những người vẫn được đọc rộng rãi – lịch sử mỹ học thường bị các triết gia đương đại bỏ qua. Chọn riêng một người là thiếu.", "key_fact": "Ngoại lệ: Plato, Aristotle và Kant.", "topic": "Lịch sử mỹ học", "note": "", "comment_answer": "A"}, {"id": "AET-de3-22", "question": "Emily Brady suggests, allow for aesthetic revelation - the realization of aesthetic truths. However, for such appreciation to be appropriate, it must be both disinterested and of proper depth. As Brady puts it, we must ... well.", "options": [{"key": "A", "text": "Live"}, {"key": "B", "text": "Think"}, {"key": "C", "text": "Creative"}, {"key": "D", "text": "Imagine"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Emily Brady nhấn mạnh vai trò của trí tưởng tượng trong thưởng thức thiên nhiên, với yêu cầu 'phải tưởng tượng tốt' (imagine well). Các từ khác không phải cụm từ đặc trưng của bà.", "key_fact": "Brady: thưởng thức thiên nhiên cần 'tưởng tượng tốt'.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": "D"}, {"id": "AET-de3-23", "question": "Name the exhibition in 1915, Russian artist Kasimir Malevich contributed thirty-nine paintings to the exhibition in the Dobychina Gallery, Russia's leading private commercial gallery.", "options": [{"key": "A", "text": "'0,10' ('Zero-Ten')"}, {"key": "B", "text": "The Last Futurist Exhibition'"}, {"key": "C", "text": "Les Demoiselles d'Avignon"}, {"key": "D", "text": "Black Square"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Malevich góp 39 bức tranh cho triển lãm '0,10' (Zero-Ten) năm 1915 tại Phòng tranh Dobychina. 'The Last Futurist Exhibition' chỉ là phụ đề; 'Black Square' là một tác phẩm, 'Les Demoiselles d'Avignon' là tranh của Picasso.", "key_fact": "Tên triển lãm năm 1915 là '0,10' (Zero-Ten).", "topic": "Nghệ thuật tiên phong Nga", "note": "", "comment_answer": "A"}, {"id": "AET-de3-24", "question": "We looked at David Hume's theory of taste, in which he argues that the critic's job is to distance himself from his own sentimentality, to overcome his own prejudices and to become, as much as possible, a 'man in ...'", "options": [{"key": "A", "text": "Nomarl"}, {"key": "B", "text": "Special"}, {"key": "C", "text": "Loyal"}, {"key": "D", "text": "General"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hume cho rằng nhà phê bình phải vượt qua định kiến để trở thành 'man in general' (con người nói chung). Đây là câu lặp lại với phương án được xáo trộn.", "key_fact": "Hume: nhà phê bình lý tưởng là 'man in general'.", "topic": "Lý thuyết thị hiếu Hume", "note": "", "comment_answer": "D"}, {"id": "AET-de3-25", "question": "Who painted \"Nude Descending a Staircase\", No. 2 (1912)?", "options": [{"key": "A", "text": "Marcel Duchamp"}, {"key": "B", "text": "Hans Arp"}, {"key": "C", "text": "Salvador Dalí"}, {"key": "D", "text": "Man Ray"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Nude Descending a Staircase, No. 2' (1912) là tác phẩm của Marcel Duchamp, gây chấn động tại Armory Show 1913. Arp, Dalí, Man Ray không phải tác giả.", "key_fact": "Duchamp vẽ 'Nude Descending a Staircase, No. 2' (1912).", "topic": "Nghệ thuật hiện đại", "note": "", "comment_answer": "A"}, {"id": "AET-de3-26", "question": "Like the paradox of fiction, the problem, of tragedy finds its roots in ancient ..", "options": [{"key": "A", "text": "Greece"}, {"key": "B", "text": "China"}, {"key": "C", "text": "Mesopotamia"}, {"key": "D", "text": "Egypt"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nghịch lý bi kịch (vì sao ta thích thú khi xem bi kịch gây đau buồn) có nguồn gốc từ Hy Lạp cổ đại, nơi Plato và Aristotle (catharsis) bàn về bi kịch. Các nền văn minh khác không phải nguồn gốc của vấn đề này trong triết học phương Tây.", "key_fact": "Nghịch lý bi kịch bắt nguồn từ Hy Lạp cổ đại.", "topic": "Nghịch lý bi kịch", "note": "", "comment_answer": "A"}, {"id": "AET-de3-27", "question": "In ....., First and Last, a catalogue of 219 of Evans's 20,000 photographs, was published", "options": [{"key": "A", "text": "1979"}, {"key": "B", "text": "1978"}, {"key": "C", "text": "1981"}, {"key": "D", "text": "1980"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Walker Evans: First and Last' được Harper & Row xuất bản năm 1978 (khớp đáp án de2-22). Ở bản de3, 1978 là phương án B; 1979 là sai. (Nguồn: https://biblio.co.uk/0060112611 ; https://www.cca.qc.ca/en/search/details/library/publication/04516166)", "key_fact": "First and Last (Walker Evans) – 1978.", "topic": "Nhiếp ảnh Walker Evans", "note": "", "comment_answer": "B"}, {"id": "AET-de3-28", "question": "Fill in the blank with the correct words: ...was a disciple of Socrates whose cornerstone of thought was his theory of Forms, in which there was another world of perfection.", "options": [{"key": "A", "text": "I.Kant"}, {"key": "B", "text": "Heraklite"}, {"key": "C", "text": "Plato"}, {"key": "D", "text": "Aristotle"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Plato là học trò của Socrates, nền tảng tư tưởng là học thuyết Ý niệm (Forms) về một thế giới hoàn hảo khác. Aristotle là học trò của Plato và phê phán thuyết Ý niệm.", "key_fact": "Plato – học trò Socrates, học thuyết Ý niệm (Forms).", "topic": "Mỹ học Plato", "note": "", "comment_answer": "C"}, {"id": "AET-de3-29", "question": "In the eighteenth century, however, the practice of landscape design turned to the '....' style, an idealized version of wild nature, with properties looking on the one hand natural and accidentally placed, and, on the other hand, polished.", "options": [{"key": "A", "text": "English garden"}, {"key": "B", "text": "Italia garden'"}, {"key": "C", "text": "France garden'"}, {"key": "D", "text": "Spanish garden'"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thế kỷ 18, thiết kế cảnh quan chuyển sang phong cách 'vườn Anh' (English landscape garden) – thiên nhiên hoang dã lý tưởng hóa, trái với vườn Pháp/Ý hình học. Câu de1-15 đã chọn English garden; ở bản de3, English garden là A. (Nguồn: https://en.wikipedia.org/wiki/English_landscape_garden)", "key_fact": "Thế kỷ 18: English garden = thiên nhiên hoang dã lý tưởng hóa.", "topic": "Mỹ học tự nhiên", "note": "", "comment_answer": "A"}, {"id": "AET-de3-30", "question": "The Exorcist was a cultural phenomenon. It remains the highest-grossing R-rated film of all time, and was nominated for ten Academy Awards, including Best Picture. Although it didn't win that highest award, it does have the honour of being the very first horror movie to be nominated for a Best Picture ...", "options": [{"key": "A", "text": "Tiff"}, {"key": "B", "text": "Cannes"}, {"key": "C", "text": "Golden globe awards"}, {"key": "D", "text": "Oscar"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "The Exorcist là phim kinh dị đầu tiên được đề cử giải Phim hay nhất của Oscar (Academy Awards). Câu hỏi nói rõ 'Academy Awards', nên không phải Cannes, TIFF hay Quả cầu vàng.", "key_fact": "The Exorcist là phim kinh dị đầu tiên được đề cử Oscar Phim hay nhất.", "topic": "Điện ảnh kinh dị", "note": "", "comment_answer": "D"}, {"id": "AET-de3-31", "question": "Anthony Ashley Cooper,3rd Earl of Shaftesbury said: \"The painting and the music invite us to do what we would seldom do in ordinary life - pay attention only to what we are ....., and ignore everything else.\"", "options": [{"key": "A", "text": "seeing or hearing"}, {"key": "B", "text": "Tasting or touching"}, {"key": "C", "text": "Looking or smelling"}, {"key": "D", "text": "Loving or understandinh"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Shaftesbury nói hội họa và âm nhạc mời ta chỉ chú ý vào những gì ta đang thấy hoặc nghe (seeing or hearing), bỏ qua mọi thứ khác. Đây là câu lặp với phương án xáo trộn.", "key_fact": "Shaftesbury: nghệ thuật khiến ta chỉ chú tâm vào điều đang thấy hoặc nghe.", "topic": "Shaftesbury và thái độ thẩm mỹ", "note": "", "comment_answer": "A"}, {"id": "AET-de3-32", "question": "Carl Andre's 1969 installation, 144 Lead ...., still housed in New York's Museum of Modern Art, consists of 144 square lead tiles arranged in a 12-by-12-foot grid.", "options": [{"key": "A", "text": "Cube"}, {"key": "B", "text": "Square"}, {"key": "C", "text": "Triangle"}, {"key": "D", "text": "Round"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tác phẩm của Carl Andre là '144 Lead Square' (1969), gồm 144 tấm chì vuông xếp lưới 12x12. Mô tả 'square lead tiles' cũng gợi ý đáp án.", "key_fact": "Carl Andre: '144 Lead Square' (1969).", "topic": "Nghệ thuật tối giản", "note": "", "comment_answer": "B"}, {"id": "AET-de3-33", "question": "In 1941, Hattie McDaniel became the first black performer to win an Academy Award, taking the Best Supporting Actress Oscar for her role as Mammy, the house servant in .....", "options": [{"key": "A", "text": "The Green Hornet"}, {"key": "B", "text": "Ghost in the Shell"}, {"key": "C", "text": "Gone With the Wind"}, {"key": "D", "text": "Doctor Strange"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hattie McDaniel đoạt Oscar Nữ phụ (lễ trao giải 1940) với vai Mammy trong 'Gone With the Wind', là người da đen đầu tiên giành Oscar. Các phim còn lại ra đời muộn hơn nhiều.", "key_fact": "Hattie McDaniel đoạt Oscar với vai Mammy trong 'Gone With the Wind'.", "topic": "Điện ảnh và chủng tộc", "note": "", "comment_answer": "C"}, {"id": "AET-de3-34", "question": "When we asked what a given work means - what it is about there are a number of theoretical positions. Check all that were mentioned in lecture:", "options": [{"key": "A", "text": "First, it might be suggested that there are no correct interpretations the word- because no word really means any particular thing"}, {"key": "B", "text": "A second possibility is that, for any given work, there is one truly correct interpretation"}, {"key": "C", "text": "That all of this talk about a correct interpretation of a work is misleading"}, {"key": "D", "text": "All of these answers"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bài giảng nêu ba lập trường: không có diễn giải đúng; có một diễn giải đúng duy nhất; nói về 'diễn giải đúng' là gây hiểu lầm. Đề chỉ cho chọn một nên chọn 'All of these answers' bao gồm cả ba.", "key_fact": "Ba lập trường về ý nghĩa tác phẩm: không có/duy nhất một/khái niệm 'đúng' gây hiểu lầm.", "topic": "Diễn giải tác phẩm", "note": "", "comment_answer": "D"}, {"id": "AET-de3-35", "question": "George Seurat introduced the technique of Pointillism?", "options": [{"key": "A", "text": "Not given"}, {"key": "B", "text": "True"}, {"key": "C", "text": "False"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Georges Seurat đúng là người khởi xướng kỹ thuật điểm họa (Pointillism). Do đó nhận định là True.", "key_fact": "Seurat là người khởi xướng Pointillism.", "topic": "Hội họa Hậu ấn tượng", "note": "", "comment_answer": "B"}, {"id": "AET-de3-36", "question": "Who suggested that the sense of beauty - grounded in such formal matters as proportion, harmony and order - is a sense peculiar to man, and which connects him to the gods ?", "options": [{"key": "A", "text": "Hegel"}, {"key": "B", "text": "I.Kant"}, {"key": "C", "text": "Aristotle"}, {"key": "D", "text": "Plato"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Plato cho rằng cảm thức về cái đẹp, dựa trên tỷ lệ, hài hòa và trật tự, là đặc thù của con người và nối con người với thần linh (thế giới Ý niệm). Aristotle cũng bàn về trật tự nhưng không gắn với thần thánh theo cách này; Kant, Hegel thuộc thời hiện đại.", "key_fact": "Plato: cảm thức về cái đẹp (tỷ lệ, hài hòa) là riêng của con người, nối con người với thần linh.", "topic": "Mỹ học Plato", "note": "", "comment_answer": "D"}, {"id": "AET-de3-37", "question": "When was the first annual exhibition of Society of Independent Artists in New York City?", "options": [{"key": "A", "text": "1918"}, {"key": "B", "text": "1915"}, {"key": "C", "text": "1916"}, {"key": "D", "text": "1917"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Triển lãm thường niên đầu tiên của Hội Nghệ sĩ Độc lập ở New York diễn ra năm 1917, nơi Duchamp gửi 'Fountain' và bị từ chối trưng bày.", "key_fact": "Triển lãm đầu tiên của Society of Independent Artists: 1917.", "topic": "Duchamp và Fountain", "note": "", "comment_answer": "D"}, {"id": "AET-de3-38", "question": "The particular flamingos are the pair designed by Don Featherstone back in 1957?", "options": [{"key": "A", "text": "False"}, {"key": "B", "text": "True"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chim hồng hạc nhựa trang trí sân vườn được Don Featherstone thiết kế năm 1957 cho hãng Union Products. Nhận định là đúng.", "key_fact": "Hồng hạc nhựa do Don Featherstone thiết kế năm 1957.", "topic": "Kitsch và văn hóa đại chúng", "note": "", "comment_answer": "B"}, {"id": "AET-de3-39", "question": "..... famously entered the American public consciousness in 1966 playing the role of Kato in the short-lived TV action series The Green Hornet.", "options": [{"key": "A", "text": "Chistoph Waltz"}, {"key": "B", "text": "Bruce Lee"}, {"key": "C", "text": "Châu Kiệt Luân"}, {"key": "D", "text": "Seth Rogen"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Lý Tiểu Long (Bruce Lee) được công chúng Mỹ biết đến năm 1966 qua vai Kato trong series 'The Green Hornet'. Seth Rogen và Châu Kiệt Luân đóng bản điện ảnh 2011.", "key_fact": "Bruce Lee đóng Kato trong 'The Green Hornet' (1966).", "topic": "Điện ảnh và chủng tộc", "note": "", "comment_answer": "B"}, {"id": "AET-de3-40", "question": "In 1999, Entertainment Weekly released its ranking of the 'Scariest Movies of All Time,' and .... Topped the list ahead of Alien, ahead of The Shining, ahead of Jaws.", "options": [{"key": "A", "text": "The Exorcist"}, {"key": "B", "text": "Docter strange"}, {"key": "C", "text": "Ghost in the shell"}, {"key": "D", "text": "Titanic"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Năm 1999, Entertainment Weekly xếp 'The Exorcist' đứng đầu danh sách phim đáng sợ nhất mọi thời đại, trên Alien, The Shining, Jaws. Titanic hay Doctor Strange không phải phim kinh dị.", "key_fact": "The Exorcist đứng đầu danh sách phim đáng sợ nhất của Entertainment Weekly (1999).", "topic": "Điện ảnh kinh dị", "note": "", "comment_answer": "A"}, {"id": "AET-de3-41", "question": "On Susan Feagin's view, we can distinguish between 'direct- responses' and '........-responses'.", "options": [{"key": "A", "text": "Beta-"}, {"key": "B", "text": "Meta-"}, {"key": "C", "text": "Alpha-"}, {"key": "D", "text": "Gama-"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Susan Feagin phân biệt 'direct responses' và 'meta-responses'. Đây là câu lặp với phương án xáo trộn.", "key_fact": "Feagin: direct responses và meta-responses.", "topic": "Nghịch lý bi kịch", "note": "", "comment_answer": "B"}, {"id": "AET-de3-42", "question": "Fill in the blank with the correct words: Leon Battista Alberti, was an Italian Renaissance humanist author, artist, architect, poet, priest, linguist, philosopher, and cryptographer; he epitomised the Renaissance Man. Alberti authored three groundbreaking treatises: ...., ..., ...?", "options": [{"key": "A", "text": "On Painting, On Poem, On Literature"}, {"key": "B", "text": "On Architecture, On Literature, On Poem"}, {"key": "C", "text": "On Sculpture, On Music, On Poem"}, {"key": "D", "text": "On Painting, On Sculpture and On Architecture"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Alberti viết ba chuyên luận nổi tiếng: 'On Painting' (De pictura), 'On Sculpture' (De statua) và 'On Architecture' (De re aedificatoria). Các phương án có thơ, văn học, âm nhạc là sai.", "key_fact": "Alberti: On Painting, On Sculpture, On Architecture.", "topic": "Mỹ học Phục hưng", "note": "", "comment_answer": "D"}, {"id": "AET-de3-43", "question": "Match the statement with the most appropriate opinion: \"Art, ............... argues, does not follow determinate rules- rules that can simply be explained to, and followed by, anyone else- and so genius cannot be taught\"", "options": [{"key": "A", "text": "None of them"}, {"key": "B", "text": "Kant"}, {"key": "C", "text": "Plato"}, {"key": "D", "text": "Hegel"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Luận điểm 'nghệ thuật không theo quy tắc xác định nên thiên tài không thể dạy' là của Kant trong 'Phê phán năng lực phán đoán'. Plato coi nghệ sĩ được thần linh truyền cảm hứng; Hegel không phải tác giả câu này.", "key_fact": "Kant: thiên tài không thể dạy vì nghệ thuật không theo quy tắc xác định.", "topic": "Thiên tài theo Kant", "note": "", "comment_answer": "B"}, {"id": "AET-de3-44", "question": "Does morality have anything to do with aesthetics?", "options": [{"key": "A", "text": "No"}, {"key": "B", "text": "Yes"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đạo đức có liên quan đến mỹ học: từ Hy Lạp cổ đại (Plato) đến tranh luận hiện đại (moralism, autonomism) đều bàn về quan hệ giữa giá trị đạo đức và giá trị thẩm mỹ của nghệ thuật.", "key_fact": "Đạo đức và mỹ học có mối liên hệ chặt chẽ.", "topic": "Mỹ học và đạo đức", "note": "", "comment_answer": "B"}, {"id": "AET-de3-45", "question": "Unlike articles of nature, Hegel suggests, a work of art is apprehended on a ..... or spiritual plane", "options": [{"key": "A", "text": "Physical"}, {"key": "B", "text": "Intellectual"}, {"key": "C", "text": "Emotinal"}, {"key": "D", "text": "Mental"}], "answer": ["B"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Câu trùng de2-10 nhưng hai bản chọn khác nhau (de2-10: Intellectual; de3-45: Mental). Hegel: tác phẩm nghệ thuật tồn tại cho cảm quan nhưng chủ yếu cho sự lĩnh hội tinh thần (Geist); cụm 'intellectual or spiritual plane' có khả năng là nguyên văn giáo trình hơn. Cần thống nhất một đáp án; chưa xác minh được nguyên văn. (Nguồn: https://www.cambridge.org/core/books/poetry-and-the-romantic-musical-aesthetic/nature-music-and-the-imagination-in-wordsworths-poetry/5F876F26BD430DBE571A2C15CC04B158)", "key_fact": "Hegel: tác phẩm được lĩnh hội ở bình diện trí tuệ/tinh thần (intellectual or spiritual).", "topic": "Mỹ học Hegel", "note": "", "comment_answer": "B"}, {"id": "AET-de3-46", "question": "In 2001, Michael Mandiberg scanned the same photographs from First and Last and posted them to his website, AfterSherrieLevine.com. If you visit the site, you can print out a high-resolution copy of the image originally taken by Evans - now titled ... (AfterSherrieLevine.com/2.jpg) - along with a certificate of authenticity", "options": [{"key": "A", "text": "After Sherrie Levine"}, {"key": "B", "text": "Untitled"}, {"key": "C", "text": "After Walker Evans: 4."}, {"key": "D", "text": "Alabama Tenant Farmer Wife"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mandiberg đặt tên ảnh trên trang AfterSherrieLevine.com là 'Untitled (AfterSherrieLevine.com/2.jpg)'. 'After Walker Evans: 4' là tên tác phẩm của Levine, 'Alabama Tenant Farmer Wife' là tên ảnh gốc của Evans.", "key_fact": "Mandiberg (2001): 'Untitled (AfterSherrieLevine.com/2.jpg)'.", "topic": "Tính nguyên bản và sao chép", "note": "", "comment_answer": "B"}, {"id": "AET-de3-47", "question": "................. argues that accurately reporting at least some of a work's aesthetic features depends upon actually experiencing that work for another reason.", "options": [{"key": "A", "text": "Pablo Picasso"}, {"key": "B", "text": "Kasimir Malevic"}, {"key": "C", "text": "Plato"}, {"key": "D", "text": "Roger Scruton"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Roger Scruton lập luận rằng việc mô tả chính xác ít nhất một số đặc điểm thẩm mỹ của tác phẩm phụ thuộc vào việc trực tiếp trải nghiệm tác phẩm (gắn với 'nguyên tắc làm quen' – acquaintance principle). Picasso, Malevich là họa sĩ; Plato không bàn vấn đề này.", "key_fact": "Scruton: báo cáo đặc điểm thẩm mỹ đòi hỏi trải nghiệm trực tiếp tác phẩm.", "topic": "Phán đoán thẩm mỹ", "note": "", "comment_answer": "D"}, {"id": "AET-de3-48", "question": "In the eighteenth century, who argued that beauty would be found in 'uniformity amidst variety ?", "options": [{"key": "A", "text": "Marsilio Ficino"}, {"key": "B", "text": "St Thomas Aquinas"}, {"key": "C", "text": "Francis Hutcheson"}, {"key": "D", "text": "Imanuel Kant"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Francis Hutcheson (thế kỷ 18) định nghĩa cái đẹp là 'uniformity amidst variety' (thống nhất trong đa dạng). Ficino (thế kỷ 15) và Aquinas (thế kỷ 13) không thuộc thế kỷ 18 và không dùng công thức này.", "key_fact": "Hutcheson: cái đẹp = thống nhất trong đa dạng.", "topic": "Lịch sử mỹ học", "note": "", "comment_answer": "C"}, {"id": "AET-de3-49", "question": "In his book, ... Richard Wollheim considers what he calls the 'physical-object hypothesis': the view that artworks simply are physical objects", "options": [{"key": "A", "text": "Beauty and Its Objects"}, {"key": "B", "text": "Aesthetics and Its Objects"}, {"key": "C", "text": "Art and Its Objects"}, {"key": "D", "text": "Love and Its Objects"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Richard Wollheim bàn về 'giả thuyết vật thể vật lý' trong cuốn 'Art and Its Objects' (1968). Các tên sách còn lại là bịa đặt.", "key_fact": "Wollheim, 'Art and Its Objects': phê phán giả thuyết tác phẩm là vật thể vật lý.", "topic": "Bản thể luận nghệ thuật", "note": "", "comment_answer": "C"}, {"id": "AET-de3-50", "question": "Choose the answer that best fills the blank: The album - Waits's seventeenth studio album, released after a seven-year wait - was met with enormous acclaim, and Richards's croaking voice joins Waits's on the waltzing ballad named '.... Leaf' ?", "options": [{"key": "A", "text": "Last"}, {"key": "B", "text": "New"}, {"key": "C", "text": "Black"}, {"key": "D", "text": "Red"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Album 'Bad as Me' (2011) của Tom Waits có ca khúc valse 'Last Leaf' song ca với Keith Richards. Các tên lá khác không đúng.", "key_fact": "Tom Waits và Keith Richards song ca 'Last Leaf' trong 'Bad as Me'.", "topic": "Âm nhạc đại chúng", "note": "", "comment_answer": "A"}]}]}, {"id": "HOD", "code": "HOD102", "name": "History of Design (đề tiếng Anh)", "note": "Đề gốc không kèm đáp án. Mỗi câu được giải độc lập 2 lần; câu nào lệch nhau hoặc lệch đáp án bình luận FUOverflow thì được phân xử lại (có xem ảnh gốc, tra cứu). Câu đánh dấu ⚠️ là câu vẫn còn chưa chắc chắn.", "sets": [{"id": "de1", "name": "Đề 1", "questions": [{"id": "HOD-de1-1", "question": "What was a major design feature of the German Tiger I tank? Check one option.", "options": [{"key": "A", "text": "Its welded armor made of high-performance steel alloy"}, {"key": "B", "text": "Its lightweight design."}, {"key": "C", "text": "Its ability to navigate underwater."}, {"key": "D", "text": "Its capability to fly short distances."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xe tăng Tiger I nổi tiếng với lớp giáp hàn dày làm từ thép hợp kim chất lượng cao cùng pháo 88 mm uy lực. Nó rất nặng (khoảng 57 tấn) nên phương án 'thiết kế nhẹ' là sai; lội nước hay bay là vô lý.", "key_fact": "Tiger I nổi bật nhờ giáp thép hợp kim hàn dày và hỏa lực mạnh.", "topic": "Thiết kế thời chiến", "note": "", "comment_answer": null}, {"id": "HOD-de1-2", "question": "Who led the De Stijl group? Check one option.", "options": [{"key": "A", "text": "Theo van Doesburg"}, {"key": "B", "text": "Piet Mondrian"}, {"key": "C", "text": "Frank Lloyd Wright"}, {"key": "D", "text": "Walter Gropius"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo van Doesburg sáng lập và dẫn dắt nhóm De Stijl cũng như tạp chí cùng tên năm 1917. Piet Mondrian là thành viên tiêu biểu nhưng không phải người lãnh đạo; Gropius gắn với Bauhaus, Wright là kiến trúc sư Mỹ.", "key_fact": "Theo van Doesburg là người sáng lập, lãnh đạo De Stijl (1917).", "topic": "De Stijl", "note": "", "comment_answer": null}, {"id": "HOD-de1-3", "question": "(Choose 1 answer) In which year did Thomas Edison first unveil the electric light bulb?", "options": [{"key": "A", "text": "1875"}, {"key": "B", "text": "1881"}, {"key": "C", "text": "1879"}, {"key": "D", "text": "1883"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Edison công bố bóng đèn sợi đốt thành công vào cuối năm 1879 (trình diễn công khai tại Menlo Park). Các năm 1881, 1883 là giai đoạn thương mại hóa và mở rộng hệ thống điện sau đó.", "key_fact": "Edison giới thiệu bóng đèn điện năm 1879.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": null}, {"id": "HOD-de1-4", "question": "Who was one of the prominent architects of the Modernism movement with significant influence in 20th-century architecture?", "options": [{"key": "A", "text": "Frank Lloyd Wright."}, {"key": "B", "text": "Antoni Gaudí."}, {"key": "C", "text": "Salvador Dalí."}, {"key": "D", "text": "Le Corbusier."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Le Corbusier là kiến trúc sư tiêu biểu nhất của chủ nghĩa Hiện đại, với 'năm điểm kiến trúc mới' và câu 'ngôi nhà là cỗ máy để ở'. Frank Lloyd Wright cũng có ảnh hưởng lớn nhưng gắn với kiến trúc hữu cơ; Gaudí thuộc Art Nouveau/Modernisme Catalan, Dalí là họa sĩ Siêu thực.", "key_fact": "Le Corbusier là kiến trúc sư tiêu biểu của chủ nghĩa Hiện đại thế kỷ 20.", "topic": "Chủ nghĩa Hiện đại", "note": "", "comment_answer": null}, {"id": "HOD-de1-5", "question": "Which designer's work at the 1925 Paris exhibition epitomized the luxurious and decorative nature of Art Deco? Check one option.", "options": [{"key": "A", "text": "Le Corbusier"}, {"key": "B", "text": "Emile-Jacques Ruhlmann"}, {"key": "C", "text": "Marcel Breuer"}, {"key": "D", "text": "Walter Gropius"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Émile-Jacques Ruhlmann với đồ nội thất gỗ quý, khảm ngà tại Triển lãm Paris 1925 là hình mẫu cho Art Deco xa hoa. Le Corbusier ở triển lãm này lại trưng bày Pavillon de l'Esprit Nouveau mang tinh thần Hiện đại, đối lập với trang trí; Breuer và Gropius thuộc Bauhaus.", "key_fact": "Ruhlmann là đại diện cho Art Deco sang trọng tại Triển lãm Paris 1925.", "topic": "Art Deco", "note": "", "comment_answer": null}, {"id": "HOD-de1-6", "question": "What is one of the key design principles of the Bauhaus movement?", "options": [{"key": "A", "text": "Using complex decorative elements to highlight the product."}, {"key": "B", "text": "Focusing on combining art and technology with the goal of mass industrial production."}, {"key": "C", "text": "Creating luxurious and intricate designs."}, {"key": "D", "text": "Emphasizing the use of natural materials in all products."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bauhaus chủ trương thống nhất nghệ thuật và kỹ thuật (\"Art and Technology – A New Unity\") để tạo ra sản phẩm phù hợp sản xuất công nghiệp hàng loạt. Các phương án trang trí phức tạp, xa hoa đi ngược tinh thần công năng của Bauhaus.", "key_fact": "Bauhaus: kết hợp nghệ thuật và công nghệ cho sản xuất công nghiệp hàng loạt.", "topic": "Bauhaus", "note": "", "comment_answer": null}, {"id": "HOD-de1-7", "question": "What was the primary aim of the manifesto outlined by the De Stijl group in their magazine's first issue?", "options": [{"key": "A", "text": "Emphasizing individualism over universalism"}, {"key": "B", "text": "Advocating for traditional art forms"}, {"key": "C", "text": "Calling for a cultural purging and spiritual universality"}, {"key": "D", "text": "Rejecting the influence of modern art movements"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tuyên ngôn De Stijl (1918) kêu gọi thanh lọc văn hóa và hướng tới tính phổ quát tinh thần, đặt cái phổ quát lên trên cái cá nhân. Vì thế phương án đề cao chủ nghĩa cá nhân hay nghệ thuật truyền thống là sai.", "key_fact": "Tuyên ngôn De Stijl đề cao tính phổ quát, thanh lọc văn hóa và tinh thần.", "topic": "De Stijl", "note": "", "comment_answer": null}, {"id": "HOD-de1-8", "question": "What term was used to describe the heavily decorated goods of the High Victorian style?", "options": [{"key": "A", "text": "Modernist Style"}, {"key": "B", "text": "Industrial Revolution Style"}, {"key": "C", "text": "Georgian Neoclassicism"}, {"key": "D", "text": "Fashionable High Victorian Style"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hàng hóa trang trí dày đặc giữa thế kỷ 19 được gọi là phong cách 'Fashionable High Victorian'. Georgian Neoclassicism là phong cách thế kỷ 18 thanh lịch, tiết chế; 'Modernist' thì ngược hẳn với trang trí dày đặc.", "key_fact": "Hàng trang trí rườm rà thời Victoria gọi là 'Fashionable High Victorian Style'.", "topic": "Phong cách Victoria", "note": "", "comment_answer": null}, {"id": "HOD-de1-9", "question": "Which marketing strategy was NOT mentioned as part of Samuel Colt's approach?", "options": [{"key": "A", "text": "Public relations"}, {"key": "B", "text": "Product sampling"}, {"key": "C", "text": "Free firearm distribution to the military"}, {"key": "D", "text": "Print advertisements"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Colt nổi tiếng với chiến lược marketing gồm quan hệ công chúng, tặng mẫu súng khắc trang trí cho nhân vật có ảnh hưởng (product sampling) và quảng cáo in ấn. Việc phân phát súng miễn phí cho quân đội không được nêu là một phần chiến lược của ông.", "key_fact": "Samuel Colt tiên phong marketing: PR, tặng mẫu sản phẩm và quảng cáo in.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-10", "question": "What field did the Aesthetics Movement of the late 19th century belong to?", "options": [{"key": "A", "text": "Architectual"}, {"key": "B", "text": "Fashion"}, {"key": "C", "text": "Product"}, {"key": "D", "text": "All of them"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Phong trào Thẩm mỹ (Aesthetic Movement) lan tỏa trong kiến trúc, nội thất – đồ dùng, và cả thời trang (trang phục 'aesthetic dress'). Vì vậy không giới hạn ở một lĩnh vực đơn lẻ.", "key_fact": "Phong trào Thẩm mỹ ảnh hưởng tới kiến trúc, sản phẩm và thời trang.", "topic": "Phong trào Thẩm mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-11", "question": "(Find the missing words) During the mid-to late nineteenth century, another important .......... also emerged with the formation of the Pre-Raphaelite Brotherhood (PRB).", "options": [{"key": "A", "text": "Exhibition"}, {"key": "B", "text": "Strand of design reform"}, {"key": "C", "text": "Designer"}, {"key": "D", "text": "Artist"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Câu gốc nói rằng việc hình thành Hội Tiền Raphael (PRB) là một 'nhánh cải cách thiết kế' (strand of design reform) quan trọng khác. Các từ 'exhibition', 'designer', 'artist' không hợp ngữ pháp và nghĩa với 'formation of the PRB'.", "key_fact": "Hội Tiền Raphael (PRB) là một nhánh của cải cách thiết kế thế kỷ 19.", "topic": "Cải cách thiết kế thế kỷ 19", "note": "", "comment_answer": null}, {"id": "HOD-de1-12", "question": "(Find the missing words) The Aesthetic movement was spurred on by the idea of ..........", "options": [{"key": "A", "text": "\"art for design sake\"."}, {"key": "B", "text": "\"art for art's sake\"."}, {"key": "C", "text": "\"art for human sake\"."}, {"key": "D", "text": "\"art for women sake\"."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Phong trào Thẩm mỹ được thúc đẩy bởi khẩu hiệu 'art for art's sake' (nghệ thuật vị nghệ thuật), coi trọng cái đẹp tự thân. Các phương án còn lại là biến thể bịa đặt.", "key_fact": "Khẩu hiệu Phong trào Thẩm mỹ: 'art for art's sake'.", "topic": "Phong trào Thẩm mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-13", "question": "What was Henry Cole's role in the Museum of Manufactures? Check one option.", "options": [{"key": "A", "text": "He was the chief financial officer."}, {"key": "B", "text": "He was the curator of the 'Chamber of Horrors.'"}, {"key": "C", "text": "He was a tour guide for visitors."}, {"key": "D", "text": "He was the main architect."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Henry Cole lập 'Chamber of Horrors' trong Museum of Manufactures (1852) để trưng bày ví dụ thiết kế tồi nhằm giáo dục công chúng về 'nguyên tắc sai'. Ông không phải kiến trúc sư hay hướng dẫn viên của bảo tàng.", "key_fact": "Henry Cole tạo 'Chamber of Horrors' trưng bày thiết kế tồi ở Museum of Manufactures.", "topic": "Cải cách thiết kế thế kỷ 19", "note": "", "comment_answer": null}, {"id": "HOD-de1-14", "question": "(Choose 1 answer) In the ___ century, the heavy moldboard plow increased food production.", "options": [{"key": "A", "text": "7th"}, {"key": "B", "text": "8th"}, {"key": "C", "text": "9th"}, {"key": "D", "text": "10th"}], "answer": ["C"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Cày nặng có lưỡi lật (carruca) được các tài liệu về công nghệ Trung Cổ xếp vào khoảng thế kỷ 6–9, và năng suất nông nghiệp châu Âu tăng từ thế kỷ 9. Mạch giáo trình xếp: bánh xe nước cải tiến (7) – đồng hồ cát (8) – cày nặng (9), nên chọn 9th. (Nguồn: https://en.wikipedia.org/wiki/Medieval_technology ; https://www.medievalists.net/2013/06/the-heavy-plough-and-the-agricultural-revolution-in-medieval-europe/)", "key_fact": "Cày nặng lưỡi lật: thế kỷ 9 (sau water wheel 7, hourglass 8)", "topic": "Thiết kế thời Trung cổ", "note": "", "comment_answer": null}, {"id": "HOD-de1-15", "question": "What invention from the thirteenth century mechanized the process of twisting wool or cotton into threads?", "options": [{"key": "A", "text": "The spinning wheel."}, {"key": "B", "text": "The blast furnace."}, {"key": "C", "text": "The hourglass."}, {"key": "D", "text": "The water wheel."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Guồng quay tơ (spinning wheel) xuất hiện ở châu Âu thế kỷ 13, cơ giới hóa việc xe sợi len, bông. Lò cao dùng luyện kim, đồng hồ cát đo thời gian, bánh xe nước tạo năng lượng.", "key_fact": "Guồng quay sợi (thế kỷ 13) cơ giới hóa việc xe sợi.", "topic": "Thiết kế thời Trung cổ", "note": "", "comment_answer": null}, {"id": "HOD-de1-16", "question": "What was the primary purpose of the Terracotta Army?", "options": [{"key": "A", "text": "To honor and protect Emperor Qin Shi Huang in the afterlife."}, {"key": "B", "text": "To serve as a ceremonial offering to the gods."}, {"key": "C", "text": "To showcase the craftsmanship of Qin's workforce."}, {"key": "D", "text": "To act as a training ground for soldiers."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đội quân đất nung được chôn theo lăng Tần Thủy Hoàng để bảo vệ và phục vụ hoàng đế ở thế giới bên kia. Nó không nhằm cúng thần hay làm nơi huấn luyện; tay nghề thợ chỉ là hệ quả chứ không phải mục đích.", "key_fact": "Đội quân đất nung bảo vệ Tần Thủy Hoàng ở thế giới bên kia.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": null}, {"id": "HOD-de1-17", "question": "What common misunderstanding exists about invention and design?", "options": [{"key": "A", "text": "Invention is purely accidental, while design is planned, such as drawing, trial-and-error experimentation, or model-making."}, {"key": "B", "text": "Design and invention are entirely separate processes."}, {"key": "C", "text": "Invention does not require design-led thinking."}, {"key": "D", "text": "Invention and design are somehow different from one another, yet an invention can only be the result of design-led thinking and some form of developmental process, such as drawing, trial-and-error experimentation, or model-making."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Giáo trình chỉ ra hiểu lầm phổ biến là cho rằng phát minh và thiết kế khác nhau, trong khi phát minh thực chất là kết quả của tư duy thiết kế và quá trình phát triển (vẽ, thử–sai, làm mô hình). Phương án D trích gần nguyên văn đoạn này.", "key_fact": "Phát minh luôn là kết quả của tư duy thiết kế và quá trình phát triển.", "topic": "Khái niệm thiết kế", "note": "", "comment_answer": null}, {"id": "HOD-de1-18", "question": "Why did many of Leonardo da Vinci's designs remain theoretical?", "options": [{"key": "A", "text": "He lacked the materials to construct them."}, {"key": "B", "text": "They were far ahead of their time and lacked practical application."}, {"key": "C", "text": "He focused on painting rather than engineering."}, {"key": "D", "text": "His clients were not interested in his inventions."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhiều thiết kế của Leonardo da Vinci (máy bay, xe tăng...) đi trước thời đại quá xa, chưa có công nghệ, vật liệu và ứng dụng thực tế để hiện thực hóa. Ông vẫn tích cực nghiên cứu kỹ thuật nên phương án 'chỉ tập trung vẽ tranh' không đúng.", "key_fact": "Thiết kế của Leonardo vượt thời đại nên chủ yếu nằm trên giấy.", "topic": "Phục hưng", "note": "", "comment_answer": null}, {"id": "HOD-de1-19", "question": "Which medieval invention allowed for the harnessing of water power into energy? Check one option.", "options": [{"key": "A", "text": "The windmill"}, {"key": "B", "text": "The blast furnace"}, {"key": "C", "text": "The improved water wheel"}, {"key": "D", "text": "The mechanical clock"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bánh xe nước cải tiến thời Trung cổ cho phép khai thác sức nước thành năng lượng để xay bột, cưa gỗ, giặt len. Cối xay gió dùng sức gió; lò cao và đồng hồ cơ không khai thác sức nước.", "key_fact": "Bánh xe nước cải tiến biến sức nước thành năng lượng sản xuất.", "topic": "Thiết kế thời Trung cổ", "note": "", "comment_answer": null}, {"id": "HOD-de1-20", "question": "What influenced American designers during the early 1940s to move away from streamlined forms?", "options": [{"key": "A", "text": "The increasing influence of Bauhaus design"}, {"key": "B", "text": "New tendencies in contemporary fine art exploring biomorphic shapes"}, {"key": "C", "text": "The need for more durable and functional designs"}, {"key": "D", "text": "Wartime restrictions on materials"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đầu thập niên 1940, nhà thiết kế Mỹ chuyển từ phong cách khí động (streamlining) sang thiết kế hữu cơ do ảnh hưởng của mỹ thuật đương đại khám phá hình khối sinh học (biomorphic) như Arp, Miró. Hạn chế vật liệu thời chiến có tác động nhưng không phải nguồn cảm hứng thẩm mỹ được nêu.", "key_fact": "Thiết kế hữu cơ thập niên 1940 lấy cảm hứng từ hình khối biomorphic của mỹ thuật đương đại.", "topic": "Thiết kế hữu cơ", "note": "", "comment_answer": null}, {"id": "HOD-de1-21", "question": "How did Samuel Colt influence the field of modern industrial design?", "options": [{"key": "A", "text": "By focusing only on functional improvements"}, {"key": "B", "text": "By pioneering a marketing-driven approach to manufacturing"}, {"key": "C", "text": "By rejecting public relations in favor of direct sales"}, {"key": "D", "text": "By designing firearms exclusively for military use"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Colt kết hợp sản xuất hàng loạt với chiến lược marketing (PR, quảng cáo, tặng mẫu), đặt nền móng cho cách tiếp cận sản xuất hướng thị trường. Ông dùng PR rất nhiều và bán cả cho dân sự nên các phương án khác sai.", "key_fact": "Colt tiên phong sản xuất gắn với marketing.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-22", "question": "What material did Harley Earl use for modeling and styling which became standard practice among car manufactures, and was then taken up by other indutries? Check one option.", "options": [{"key": "A", "text": "Metal"}, {"key": "B", "text": "Clay"}, {"key": "C", "text": "Plastic"}, {"key": "D", "text": "Fiber Carbon"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Harley Earl (GM) tiên phong dùng mô hình đất sét (clay) để tạo dáng ô tô, sau trở thành chuẩn mực của ngành xe hơi và các ngành khác. Kim loại, nhựa, sợi carbon không phải vật liệu dựng mẫu tạo dáng của ông.", "key_fact": "Harley Earl phổ biến việc tạo mẫu ô tô bằng đất sét.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-23", "question": "What was the primary advantage of the design of the German pressed-steel jerry can fuel container?", "options": [{"key": "A", "text": "Its lightweight construction"}, {"key": "B", "text": "Its low production cost."}, {"key": "C", "text": "Its aesthetic appeal"}, {"key": "D", "text": "Its robust construction with stamped indentations for extra strength and safety"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Can xăng Jerry can của Đức làm từ thép ép, có các gân dập nổi hình chữ X giúp tăng độ cứng và an toàn, kèm tay cầm ba và nắp khóa nhanh. Ưu điểm chính là độ bền chắc chứ không phải nhẹ hay rẻ.", "key_fact": "Jerry can: thép ép với gân dập tăng độ cứng, bền và an toàn.", "topic": "Thiết kế thời chiến", "note": "", "comment_answer": null}, {"id": "HOD-de1-24", "question": "What made the Tiger I heavy tank a notable vehicle during World War II?", "options": [{"key": "A", "text": "Its lightweight design and high speed"}, {"key": "B", "text": "Its simple and cost-effective manufacturing process"}, {"key": "C", "text": "Its impressive firepower and welded armor"}, {"key": "D", "text": "Its ability to fly short distances"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tiger I nổi bật nhờ pháo 88 mm mạnh và giáp hàn dày. Nó nặng, chậm và chế tạo phức tạp, tốn kém nên A và B sai.", "key_fact": "Tiger I: hỏa lực mạnh và giáp hàn dày, nhưng nặng và đắt.", "topic": "Thiết kế thời chiến", "note": "", "comment_answer": null}, {"id": "HOD-de1-25", "question": "Which notable American fighter aircraft designed during World War II was built for long-range bombing missions?", "options": [{"key": "A", "text": "P-51 Mustang"}, {"key": "B", "text": "F4U Corsair"}, {"key": "C", "text": "B-17 Flying Fortress"}, {"key": "D", "text": "P-40 Warhawk"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "B-17 Flying Fortress là máy bay ném bom tầm xa của Mỹ trong Thế chiến II (câu hỏi gọi nhầm là 'fighter'). P-51, F4U, P-40 đều là máy bay tiêm kích, không dùng để ném bom tầm xa.", "key_fact": "B-17 Flying Fortress là máy bay ném bom hạng nặng tầm xa của Mỹ.", "topic": "Thiết kế thời chiến", "note": "", "comment_answer": null}, {"id": "HOD-de1-26", "question": "How did Dresser's viewpoint shift the design-reform debate?", "options": [{"key": "A", "text": "From Gothic Revival to Victorian Classicism"}, {"key": "B", "text": "From the Arts and Crafts Movement to Art Nouveau"}, {"key": "C", "text": "From the Aesthetic Movement's \"art for art's sake\" to \"art for industry's sake\""}, {"key": "D", "text": "From Baroque Revival to Modern Minimalism"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Christopher Dresser chuyển tranh luận cải cách thiết kế từ 'art for art's sake' của Phong trào Thẩm mỹ sang 'art for industry's sake', chấp nhận máy móc và sản xuất công nghiệp. Các cặp phong cách khác không liên quan đến quan điểm của ông.", "key_fact": "Dresser: 'art for industry's sake' – nghệ thuật phục vụ công nghiệp.", "topic": "Christopher Dresser", "note": "", "comment_answer": null}, {"id": "HOD-de1-27", "question": "What is Morris's tendency?", "options": [{"key": "A", "text": "Mainly use machinery in production"}, {"key": "B", "text": "Avoid using machinery in production"}, {"key": "C", "text": "Full use of machinery in production"}, {"key": "D", "text": "All is incorrect"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "William Morris phản đối sản xuất máy móc vì cho rằng nó làm mất giá trị lao động thủ công và niềm vui làm việc, nên ông tránh dùng máy. Các phương án dùng máy chủ yếu hoặc toàn phần là ngược với quan điểm của ông.", "key_fact": "Morris tránh dùng máy móc, đề cao thủ công.", "topic": "Arts and Crafts", "note": "", "comment_answer": null}, {"id": "HOD-de1-28", "question": "What century does Christopher Dresser belong to?", "options": [{"key": "A", "text": "17th"}, {"key": "B", "text": "18th"}, {"key": "C", "text": "19th"}, {"key": "D", "text": "20th"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Christopher Dresser (1834–1904) hoạt động trong thế kỷ 19, được xem là một trong những nhà thiết kế công nghiệp độc lập đầu tiên. Ông mất năm 1904 nên không thuộc thế kỷ 20.", "key_fact": "Christopher Dresser là nhà thiết kế thế kỷ 19.", "topic": "Christopher Dresser", "note": "", "comment_answer": null}, {"id": "HOD-de1-29", "question": "(Choose 1 answer) Which style this design belong to?", "options": [{"key": "A", "text": "Art Nouveau"}, {"key": "B", "text": "Renaissance"}, {"key": "C", "text": "Art and Crafl"}, {"key": "D", "text": "Modern Art"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ảnh là nội thất kiến trúc với đèn thủy tinh hình hoa, các thanh kim loại uốn lượn như dây leo và đường cong hữu cơ – đặc trưng rõ của Art Nouveau (kiểu Horta/Bruxelles). Không có yếu tố cổ điển đối xứng của Renaissance hay sự mộc mạc thủ công của Arts and Crafts.", "key_fact": "Art Nouveau nhận diện qua đường cong hữu cơ, họa tiết hoa lá, kim loại uốn lượn và kính màu.", "topic": "Nhận diện phong cách", "note": "", "comment_answer": null}, {"id": "HOD-de1-30", "question": "Which customers are Morris products aimed at?", "options": [{"key": "A", "text": "The rich"}, {"key": "B", "text": "Poor people"}, {"key": "C", "text": "Middle class"}, {"key": "D", "text": "Everyone"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sản phẩm của Morris làm thủ công tốn kém nên chỉ người giàu mới mua được – nghịch lý lớn khi ông muốn nghệ thuật cho mọi người. Vì thế phương án 'mọi người' hay 'người nghèo' là sai trên thực tế.", "key_fact": "Sản phẩm thủ công của Morris đắt, chỉ người giàu mua được.", "topic": "Arts and Crafts", "note": "", "comment_answer": null}, {"id": "HOD-de1-31", "question": "What was the main goal of Morris, Marshall, Faulkner & Co., founded by William Morris in 1861?", "options": [{"key": "A", "text": "To promote mechanized production."}, {"key": "B", "text": "To infuse design with art and revitalize craft traditions."}, {"key": "C", "text": "To create minimalist modern designs."}, {"key": "D", "text": "To establish a Gothic Revival architecture firm."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Morris, Marshall, Faulkner & Co. (1861) nhằm đưa nghệ thuật vào thiết kế và phục hưng truyền thống thủ công. Morris phản đối cơ giới hóa và không theo tối giản hiện đại.", "key_fact": "Công ty Morris (1861) hướng đến nghệ thuật hóa thiết kế và phục hưng thủ công.", "topic": "Arts and Crafts", "note": "", "comment_answer": null}, {"id": "HOD-de1-32", "question": "What term was coined for the mechanized mass-manufacture of standardized products in America? Check one option.", "options": [{"key": "A", "text": "Factory practice"}, {"key": "B", "text": "Mass production"}, {"key": "C", "text": "Armory practice"}, {"key": "D", "text": "Industrial practice"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Armory practice' (hay American system of manufactures) là thuật ngữ cho sản xuất hàng loạt cơ giới hóa các sản phẩm tiêu chuẩn với chi tiết lắp lẫn ở Mỹ, bắt nguồn từ các xưởng vũ khí. 'Mass production' là thuật ngữ chung, xuất hiện muộn hơn.", "key_fact": "Sản xuất tiêu chuẩn hóa ở Mỹ thế kỷ 19 gọi là 'armory practice'.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-33", "question": "What role did artists like John Flaxman play in Wedgwood's business?", "options": [{"key": "A", "text": "They worked as general laborers in his factories."}, {"key": "B", "text": "They helped design aesthetically appealing products for industrial production."}, {"key": "C", "text": "They developed new ceramic materials for his pottery."}, {"key": "D", "text": "They managed Wedgwood's marketing campaigns."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Wedgwood thuê nghệ sĩ như John Flaxman thiết kế hoa văn, phù điêu cho đồ gốm (như dòng Jasperware), giúp sản phẩm công nghiệp có tính thẩm mỹ cao. Họ không làm công nhân phổ thông hay quản lý marketing.", "key_fact": "Flaxman thiết kế mẫu thẩm mỹ cho gốm Wedgwood sản xuất công nghiệp.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": null}, {"id": "HOD-de1-34", "question": "During the Industrial Revolution, where did people move as a result of mass urbanization? Check one option.", "options": [{"key": "A", "text": "From cities to the countryside"}, {"key": "B", "text": "From the countryside to cities"}, {"key": "C", "text": "Between various industrial cities"}, {"key": "D", "text": "From America to Europe"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đô thị hóa trong Cách mạng công nghiệp là dòng người từ nông thôn đổ về thành phố làm việc trong nhà máy. Các hướng di chuyển khác không phải đặc trưng chính.", "key_fact": "Cách mạng công nghiệp kéo người từ nông thôn ra thành thị.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": null}, {"id": "HOD-de1-35", "question": "Which invention by James Hargreaves in 1764 significantly increased productivity in textile manufacturing? Check one option.", "options": [{"key": "A", "text": "The power loom"}, {"key": "B", "text": "The steam engine"}, {"key": "C", "text": "The spinning jenny"}, {"key": "D", "text": "The water frame"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "James Hargreaves phát minh máy kéo sợi Spinning Jenny năm 1764, cho phép một người kéo nhiều sợi cùng lúc. Water frame là của Arkwright, power loom của Cartwright, động cơ hơi nước gắn với Watt.", "key_fact": "Hargreaves – Spinning Jenny (1764).", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": null}, {"id": "HOD-de1-36", "question": "What production method contributed significantly to the industrialization of the United States in the nineteenth century?", "options": [{"key": "A", "text": "Traditional handcrafting techniques"}, {"key": "B", "text": "Importation of European machinery"}, {"key": "C", "text": "Adoption of \"armory practice\" for mass production"}, {"key": "D", "text": "Reliance on agricultural exports"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Việc áp dụng 'armory practice' – sản xuất hàng loạt với chi tiết tiêu chuẩn, lắp lẫn – thúc đẩy công nghiệp hóa nước Mỹ thế kỷ 19. Thủ công truyền thống hay xuất khẩu nông sản không tạo ra bước nhảy công nghiệp này.", "key_fact": "Armory practice thúc đẩy công nghiệp hóa Mỹ thế kỷ 19.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-37", "question": "What characteristic of the United States made it more receptive to industrial change compared to Europe? Check one option.", "options": [{"key": "A", "text": "Its historical baggage"}, {"key": "B", "text": "Its decorative traditions"}, {"key": "C", "text": "Its young, forward-looking nature"}, {"key": "D", "text": "Its resistance to change"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mỹ là quốc gia trẻ, hướng tới tương lai, ít 'gánh nặng lịch sử' và truyền thống trang trí như châu Âu nên dễ đón nhận đổi mới công nghiệp. Các phương án A, B, D mô tả ngược lại.", "key_fact": "Mỹ trẻ trung, hướng tương lai nên dễ tiếp nhận công nghiệp hóa.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-38", "question": "What role did the educational system play in Germany's industrial revolution? Check one option.", "options": [{"key": "A", "text": "It had little to no impact on industrial growth"}, {"key": "B", "text": "It focused mainly on the arts rather than sciences"}, {"key": "C", "text": "It provided a highly educated workforce necessary for industrial development"}, {"key": "D", "text": "It was underdeveloped and required significant reforms"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hệ thống giáo dục kỹ thuật – khoa học tiên tiến của Đức tạo lực lượng lao động trình độ cao cho công nghiệp hóa. Nó không yếu kém hay chỉ thiên về nghệ thuật.", "key_fact": "Giáo dục Đức cung cấp lao động trình độ cao cho công nghiệp.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": null}, {"id": "HOD-de1-39", "question": "Which invention by Thomas Edison transformed the world by turning night into day? Check one option.", "options": [{"key": "A", "text": "Phonograph"}, {"key": "B", "text": "Electric lightbulb"}, {"key": "C", "text": "Telephone"}, {"key": "D", "text": "Wireless telegraph"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bóng đèn điện của Edison 'biến đêm thành ngày'. Máy hát (phonograph) cũng của Edison nhưng liên quan âm thanh; điện thoại của Bell, điện báo không dây của Marconi.", "key_fact": "Bóng đèn điện của Edison biến đêm thành ngày.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": null}, {"id": "HOD-de1-40", "question": "What technology was utilized during wartime conflicts for communication purposes in World War?", "options": [{"key": "A", "text": "Fax machines"}, {"key": "B", "text": "Primitive radios"}, {"key": "C", "text": "Satellite phones"}, {"key": "D", "text": "Morse code"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong Thế chiến, radio sơ khai được dùng để liên lạc quân sự. Fax và điện thoại vệ tinh là công nghệ muộn hơn; mã Morse là mã hóa tín hiệu chứ không phải thiết bị công nghệ được hỏi tới.", "key_fact": "Radio sơ khai được dùng liên lạc trong chiến tranh thế giới.", "topic": "Thiết kế thời chiến", "note": "", "comment_answer": null}, {"id": "HOD-de1-41", "question": "What was Earl's main innovation in car design?", "options": [{"key": "A", "text": "Creating self-driving car models"}, {"key": "B", "text": "Using environmentally friendly materials"}, {"key": "C", "text": "Making car bodies more sculpturally expressive"}, {"key": "D", "text": "Developing more powerful engine systems"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Harley Earl biến thân xe thành hình khối điêu khắc giàu biểu cảm (dùng mẫu đất sét, vây đuôi, chrome) và khởi xướng 'styling'. Ông không làm xe tự lái, vật liệu xanh hay động cơ.", "key_fact": "Harley Earl làm thân xe ô tô giàu tính điêu khắc, khởi xướng 'styling'.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": null}, {"id": "HOD-de1-42", "question": "What was the outcome of the Dresden Exhibition for the German Arts and Crafts movement? Check one option.", "options": [{"key": "A", "text": "It led to the discontinuation of the movement"}, {"key": "B", "text": "It showcased a shift towards functionality in design over artistic expressiveness"}, {"key": "C", "text": "It focused on reintroducing historical art styles"}, {"key": "D", "text": "It emphasized the need for more ornamental arts education"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Triển lãm Dresden 1906 cho thấy phong trào thủ công mỹ nghệ Đức chuyển sang đề cao công năng và sản phẩm làm bằng máy, dẫn tới việc thành lập Deutscher Werkbund năm 1907. Nó không chấm dứt phong trào hay quay lại phong cách lịch sử.", "key_fact": "Triển lãm Dresden 1906 đánh dấu chuyển hướng sang công năng, dẫn tới Deutscher Werkbund.", "topic": "Deutscher Werkbund", "note": "", "comment_answer": null}, {"id": "HOD-de1-43", "question": "Henry Ford is famous for which statement about car color? Check one option.", "options": [{"key": "A", "text": "Color doesn't matter"}, {"key": "B", "text": "All colors are beautiful"}, {"key": "C", "text": "As long as the car runs well"}, {"key": "D", "text": "Any customer can have a car painted any color that he wants, so long as it is black"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Henry Ford nói khách hàng có thể chọn bất kỳ màu nào 'miễn là màu đen' cho Model T, phản ánh tối ưu dây chuyền sản xuất (sơn đen khô nhanh). Các phương án khác không phải câu nói nổi tiếng này.", "key_fact": "Ford: 'Any color... so long as it is black' (Model T).", "topic": "Sản xuất hàng loạt", "note": "", "comment_answer": null}, {"id": "HOD-de1-44", "question": "What characteristic is most associated with the Art Manufactures to Industrial Products period?", "options": [{"key": "A", "text": "The use of strong geometric elements and simplification of details"}, {"key": "B", "text": "Focus on minimalism and the use of industrial materials"}, {"key": "C", "text": "A combination of craftsmanship and industrial production, emphasizing the improvement of product quality and aesthetics"}, {"key": "D", "text": "Floral motifs and abundant use of gold in decoration"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Giai đoạn 'Art Manufactures to Industrial Products' là sự kết hợp tay nghề thủ công với sản xuất công nghiệp nhằm nâng cao chất lượng và thẩm mỹ sản phẩm. Hình học mạnh thuộc Art Deco, tối giản vật liệu công nghiệp thuộc Hiện đại, họa tiết hoa vàng thuộc Art Nouveau/Victoria.", "key_fact": "Art Manufactures: kết hợp thủ công và công nghiệp để nâng chất lượng, thẩm mỹ.", "topic": "Cải cách thiết kế thế kỷ 19", "note": "", "comment_answer": null}, {"id": "HOD-de1-45", "question": "Which country developed the concept of sonar? Check one option.", "options": [{"key": "A", "text": "Japan."}, {"key": "B", "text": "Germany."}, {"key": "C", "text": "The Soviet Union."}, {"key": "D", "text": "The United States."}], "answer": ["D"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Thiết bị dò âm dưới nước được Reginald Fessenden thử nghiệm ở Mỹ năm 1914, và thuật ngữ SONAR do Mỹ đặt (F. V. Hunt, Harvard, 1942); NATO sau đó bỏ tên ASDIC của Anh để dùng SONAR. Trong 4 nước, Mỹ là đáp án đúng. (Nguồn: https://en.wikipedia.org/wiki/Sonar ; https://acousticstoday.org/wp-content/uploads/2018/08/Underwater-Acoustics-A-Brief-Historical-Overview-Through-World-War-II-Thomas-G-Muir.pdf)", "key_fact": "Sonar (SOund Navigation And Ranging) – gắn với Mỹ", "topic": "Thiết kế thời chiến", "note": "", "comment_answer": null}, {"id": "HOD-de1-46", "question": "In ancient Egypt, (1) ___ and (2) ___ were developed to aid the construction of buildings.", "options": [{"key": "A", "text": "ramps / levers"}, {"key": "B", "text": "blueprints / gauges"}, {"key": "C", "text": "rails / levels"}, {"key": "D", "text": "wheelbarrows / scaffolds"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Người Ai Cập cổ dùng dốc (ramps) và đòn bẩy (levers) để vận chuyển, nâng khối đá xây kim tự tháp. Ray, xe cút kít, bản vẽ xanh không phải công cụ tiêu biểu của họ.", "key_fact": "Ai Cập cổ dùng dốc và đòn bẩy để xây dựng.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": null}, {"id": "HOD-de1-47", "question": "What were the earliest Oldowan tools primarily made from?", "options": [{"key": "A", "text": "Metal"}, {"key": "B", "text": "Clay"}, {"key": "C", "text": "Stone"}, {"key": "D", "text": "Wood"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Công cụ Oldowan (khoảng 2,6 triệu năm trước) là công cụ đá ghè đẽo, cổ nhất được biết đến. Gỗ có thể đã dùng nhưng không được bảo tồn; kim loại, đất sét xuất hiện muộn hơn nhiều.", "key_fact": "Công cụ Oldowan làm bằng đá.", "topic": "Thiết kế tiền sử", "note": "", "comment_answer": null}, {"id": "HOD-de1-48", "question": "The Roman gladius was significant because it: ... Check one option.", "options": [{"key": "A", "text": "Was the first instance of a sword being used in battle."}, {"key": "B", "text": "Was the basis for later medieval sword designs."}, {"key": "C", "text": "Represented the peak of decorative weapon design."}, {"key": "D", "text": "Could be mass-produced for the military."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiếm gladius La Mã được tiêu chuẩn hóa và có thể sản xuất hàng loạt cho quân đội, minh họa sớm cho tiêu chuẩn hóa thiết kế. Nó không phải thanh kiếm đầu tiên, cũng không phải đỉnh cao trang trí.", "key_fact": "Gladius La Mã được tiêu chuẩn hóa, sản xuất hàng loạt cho quân đội.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": null}, {"id": "HOD-de1-49", "question": "Three Ages mean", "options": [{"key": "A", "text": "Stone Age, Copper Age and Steel Age"}, {"key": "B", "text": "Brick Age, Plastic Age and Porosity Age"}, {"key": "C", "text": "Stone Age, Bronze Age and Iron Age"}, {"key": "D", "text": "Stone Age, Bronze Age and Fake Age"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hệ thống Ba thời đại gồm Thời đại Đồ đá, Đồ đồng và Đồ sắt, phân chia theo vật liệu làm công cụ. Các phương án khác bịa đặt.", "key_fact": "Ba thời đại: Đồ đá – Đồ đồng – Đồ sắt.", "topic": "Thiết kế tiền sử", "note": "", "comment_answer": null}, {"id": "HOD-de1-50", "question": "How were the figures of the Terracotta Army produced?", "options": [{"key": "A", "text": "By hand-carving each figure individually."}, {"key": "B", "text": "With imported tools from neighboring regions."}, {"key": "C", "text": "Using systemized and standardized production methods."}, {"key": "D", "text": "Through a process of trial and error."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tượng đất nung được làm theo hệ thống sản xuất tiêu chuẩn hóa, theo mô-đun (khuôn, các bộ phận lắp ghép) rồi hoàn thiện chi tiết riêng. Không phải điêu khắc tay từng tượng hoàn toàn.", "key_fact": "Đội quân đất nung được sản xuất theo phương pháp mô-đun tiêu chuẩn hóa.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": null}]}, {"id": "de2", "name": "Đề 2", "questions": [{"id": "HOD-de2-1", "question": "What is the history of design?", "options": [{"key": "A", "text": "The history of objects and their shapes"}, {"key": "B", "text": "History, culture, aesthetic ideology, interest and behaviour in the relationship between people and objects are reflected in the history of culture and civilization from the beginning until the 20th century."}, {"key": "C", "text": "History of scientific and technical developments, mentality, environment..."}, {"key": "D", "text": "All of the above."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Lịch sử thiết kế bao gồm lịch sử đồ vật và hình dáng, mối quan hệ văn hóa – thẩm mỹ giữa con người và đồ vật, cũng như sự phát triển khoa học kỹ thuật, tâm lý, môi trường. Mỗi phương án riêng lẻ chỉ là một khía cạnh nên chọn 'tất cả'.", "key_fact": "Lịch sử thiết kế là lĩnh vực đa chiều: đồ vật, văn hóa, khoa học kỹ thuật.", "topic": "Khái niệm thiết kế", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-2", "question": "This is an amphora, a type of pottery of ancient Romans. What are the most striking features of this ceramic vase?", "options": [{"key": "A", "text": "Easy carrying and pouring, thanks to its looping handles and long"}, {"key": "B", "text": "Large capacity, allowing to contain a large amount of olive oil, wine."}, {"key": "C", "text": "All of the answers"}, {"key": "D", "text": "Thick ceramic material, the glossy glaze can be easily cleaned, good hygiene, quality assurance, taste for olive oil, wine and garum for a long time."}], "answer": ["A"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Ảnh là amphora gốm đất nung thô, không tráng men bóng, nên D sai và C (All) sai. Đặc điểm nổi bật là hai quai vòng và cổ dài giúp mang, rót dễ; các bình luận có uy tín trên FUOverflow cũng chọn A.", "key_fact": "Amphora: quai vòng + cổ dài → dễ mang, dễ rót; không tráng men", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-3", "question": "What method of production has been used to make the most beautiful prehistoric ceramics come from Ban Chiang area in north-eastern Thailand?", "options": [{"key": "A", "text": "Paddle and anvil."}, {"key": "B", "text": "Turntable."}, {"key": "C", "text": "Molds made of bamboo."}, {"key": "D", "text": "Plaster molds."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Gốm tiền sử Ban Chiang (Thái Lan) được tạo hình bằng kỹ thuật đập dằn (paddle and anvil) kết hợp cuộn dải. Bàn xoay phát triển muộn hơn; khuôn thạch cao là kỹ thuật hiện đại.", "key_fact": "Gốm Ban Chiang làm bằng kỹ thuật paddle and anvil.", "topic": "Thiết kế tiền sử", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-4", "question": "In ancient Rome, the practice of featuring portraits on coins was popularized under: ...", "options": [{"key": "A", "text": "Julius Caesar to promote trade."}, {"key": "B", "text": "Augustus Caesar to display wealth."}, {"key": "C", "text": "Julius Caesar for propaganda value."}, {"key": "D", "text": "Nero to fund his artistic endeavors."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Julius Caesar là người La Mã còn sống đầu tiên in chân dung lên đồng xu, nhằm mục đích tuyên truyền chính trị. Augustus tiếp tục phổ biến nhưng không phải để 'phô trương giàu có'; Nero không liên quan.", "key_fact": "Julius Caesar đưa chân dung lên đồng xu vì giá trị tuyên truyền.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-5", "question": "In the ___ century, the improved water wheel allowed water power to be harnessed into energy to mill flour, saw wood, and cleanse woolen cloth of impurities.", "options": [{"key": "A", "text": "9th"}, {"key": "B", "text": "10th"}, {"key": "C", "text": "7th"}, {"key": "D", "text": "8th"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Giáo trình ghi: vào thế kỷ 7, bánh xe nước cải tiến cho phép khai thác sức nước để xay bột, cưa gỗ và làm sạch len; bình luận trên diễn đàn trích đúng câu này. Phương án 10th (B) không khớp với tài liệu môn học.", "key_fact": "Bánh xe nước cải tiến – thế kỷ 7.", "topic": "Thiết kế thời Trung cổ", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-6", "question": "What was the main function of the improved water wheel during the Middle Ages?", "options": [{"key": "A", "text": "To provide irrigation for agriculture"}, {"key": "B", "text": "To mill flour, saw wood, and cleanse wool"}, {"key": "C", "text": "To generate electrical power"}, {"key": "D", "text": "To drive textile machinery"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bánh xe nước cải tiến thời Trung cổ dùng để xay bột, cưa gỗ và làm sạch vải len. Tạo điện là việc của thế kỷ 19; máy dệt chạy bằng nước gắn với Cách mạng công nghiệp.", "key_fact": "Bánh xe nước Trung cổ: xay bột, cưa gỗ, làm sạch len.", "topic": "Thiết kế thời Trung cổ", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-7", "question": "Which of the following represents the characteristics of Rococo style?", "options": [{"key": "A", "text": "Popular (designed for the majority)"}, {"key": "B", "text": "Charming, delicate, overtly feminine, sumptuously opulent"}, {"key": "C", "text": "Heavy, florid, dramatic."}, {"key": "D", "text": "Aesthetic, technical and cheap."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Rococo đặc trưng bởi vẻ duyên dáng, tinh tế, nữ tính và xa hoa lộng lẫy. 'Nặng nề, hoa mỹ, kịch tính' là đặc điểm Baroque.", "key_fact": "Rococo: duyên dáng, tinh tế, nữ tính, xa hoa.", "topic": "Rococo", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-8", "question": "What are the enlightenments? Check all that apply.", "options": [{"key": "A", "text": "The age of reason"}, {"key": "B", "text": "A cultural movement of intellectuals in 16th century in Europe"}, {"key": "C", "text": "Mobilize the power of reason to reform society and advance knowledge"}, {"key": "D", "text": "Challenged age-old religious dogma and promoted scientific knowledge, industrial progress."}], "answer": ["A", "C", "D"], "multi": true, "confidence": "high", "source": "ai", "explanation": "Khai sáng là 'Thời đại Lý trí', huy động lý trí để cải cách xã hội, thách thức giáo điều tôn giáo và thúc đẩy khoa học, tiến bộ công nghiệp. Phương án B sai vì Khai sáng diễn ra chủ yếu ở thế kỷ 18, không phải thế kỷ 16.", "key_fact": "Khai sáng (thế kỷ 18) là Thời đại Lý trí, đề cao khoa học và cải cách.", "topic": "Thời kỳ Khai sáng", "note": "", "comment_answer": "A,C,D"}, {"id": "HOD-de2-9", "question": "Which manufacturer demonstrated for the first time that machinery and its logical implementation could unequivocally make designs that were not only better in quality but also capable of being produced on a much larger scale and much more cheaply - a wining outcome not only for the Royal Navy but indeed for any canny manufacturer of goods interest in turning a larger profit?", "options": [{"key": "A", "text": "Coalbrookdale"}, {"key": "B", "text": "Wedgwood"}, {"key": "C", "text": "Portsmouth Block Mills"}, {"key": "D", "text": "Danhauser Furniture Factory"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Portsmouth Block Mills (Marc Brunel, khoảng 1803) sản xuất ròng rọc cho Hải quân Hoàng gia bằng dây chuyền máy, chứng minh máy móc tạo sản phẩm tốt hơn, nhiều hơn, rẻ hơn. Wedgwood là gốm, Coalbrookdale là luyện sắt.", "key_fact": "Portsmouth Block Mills: dây chuyền máy sản xuất ròng rọc cho Hải quân Anh.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-10", "question": "Who took the Biedermeier style's simplification of form and construction to an even greater reductivist level with laminated wood, using thin veneers that were glued together, placed into molds, and then cured into the required form?", "options": [{"key": "A", "text": "Robert Adam"}, {"key": "B", "text": "Thomas Sheraton"}, {"key": "C", "text": "William Morris"}, {"key": "D", "text": "Michael Thonet"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Michael Thonet phát triển kỹ thuật gỗ dán lạng mỏng ép khuôn rồi uốn gỗ, đưa sự đơn giản hóa của Biedermeier lên mức tối giản hơn. Adam và Sheraton là nhà thiết kế Tân cổ điển, Morris thuộc Arts and Crafts.", "key_fact": "Thonet đẩy Biedermeier tới tối giản bằng gỗ dán/uốn ép khuôn.", "topic": "Michael Thonet", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-11", "question": "What laws were adopted in the United States that led to the rapid industrialization of the United States that occurred during the nineteenth century, especially after the Civil War?", "options": [{"key": "A", "text": "Low wage"}, {"key": "B", "text": "The Patent Act of 1836"}, {"key": "C", "text": "The federal Law which increased import duties"}, {"key": "D", "text": "Public Investment Policy"}], "answer": ["B", "C"], "multi": true, "confidence": "high", "source": "ai", "explanation": "Công nghiệp hóa Mỹ được thúc đẩy bởi Đạo luật Bằng sáng chế 1836 bảo vệ phát minh và luật liên bang tăng thuế nhập khẩu bảo hộ sản xuất trong nước. 'Lương thấp' và 'đầu tư công' không phải là luật được nêu.", "key_fact": "Patent Act 1836 và thuế nhập khẩu bảo hộ thúc đẩy công nghiệp Mỹ.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": "B,C"}, {"id": "HOD-de2-12", "question": "Before being known as the first to standardize the manufacturing process of weapons, what industrial invention did Eli Whitney become famous for?", "options": [{"key": "A", "text": "The ingenious cotton gin"}, {"key": "B", "text": "The Spinning jenny"}, {"key": "C", "text": "The Singer machine"}, {"key": "D", "text": "The Typewriter"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Eli Whitney nổi tiếng với máy tách hạt bông (cotton gin, 1793) trước khi gắn tên với sản xuất súng tiêu chuẩn hóa. Spinning jenny của Hargreaves, máy may của Singer.", "key_fact": "Eli Whitney phát minh cotton gin trước khi làm súng tiêu chuẩn hóa.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-13", "question": "Which social class particularly benefited from the Industrial Revolution?", "options": [{"key": "A", "text": "The lower class"}, {"key": "B", "text": "The middle class"}, {"key": "C", "text": "The aristocracy"}, {"key": "D", "text": "The peasantry"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Cách mạng công nghiệp tạo ra tầng lớp trung lưu đông đảo (chủ xưởng, thương nhân, chuyên gia) – những người hưởng lợi và trở thành khách hàng chính của hàng hóa sản xuất hàng loạt. Tầng lớp lao động thường chịu điều kiện khắc nghiệt.", "key_fact": "Tầng lớp trung lưu hưởng lợi lớn từ Cách mạng công nghiệp.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-14", "question": "In the mid-19th century, why did Henry Cole and Adolf Loos consider the ornament as one of the basic factors hindering the development of industrial design?", "options": [{"key": "A", "text": "Waste of labour and time."}, {"key": "B", "text": "Impedes the intended function of an object."}, {"key": "C", "text": "Waste of materials and energy."}, {"key": "D", "text": "All of the above."}], "answer": ["A"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Loos trong 'Ornament and Crime' cho rằng trang trí là lao động bị lãng phí (kéo theo lãng phí vật liệu, vốn), nên D cũng có lý; tuy nhiên đáp án đề được người dùng uy tín trên FUOverflow chọn A, phù hợp ý chính 'lãng phí lao động và thời gian'. Chưa tìm được nguồn giáo trình xác nhận. (Nguồn: https://depts.washington.edu/vienna/documents/Loos/Loos_Ornament.htm ; FUOverflow HOD102 FA2024 FE)", "key_fact": "Cole & Loos: trang trí = lãng phí lao động và thời gian", "topic": "Chủ nghĩa Hiện đại", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-15", "question": "Who was Henry Cole and what was his contribution to the field of industrial design?", "options": [{"key": "A", "text": "A manufacturer who resisted design changes"}, {"key": "B", "text": "A politician who promoted industrial interests"}, {"key": "C", "text": "An industrial designer who put theory into practice"}, {"key": "D", "text": "A social reformer who opposed industrialization"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Henry Cole là nhà cải cách thiết kế, vừa lý thuyết vừa thực hành: ông thiết kế bộ trà dưới bút danh Felix Summerly và lập Summerly's Art Manufactures. Ông ủng hộ công nghiệp chứ không chống đối hay cản trở đổi mới.", "key_fact": "Henry Cole đưa lý thuyết thiết kế vào thực tiễn (Felix Summerly's Art Manufactures).", "topic": "Cải cách thiết kế thế kỷ 19", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-16", "question": "Who initiated the Gothic revival movement?", "options": [{"key": "A", "text": "William Morris."}, {"key": "B", "text": "Walter Gropius."}, {"key": "C", "text": "Louis Sullivan."}, {"key": "D", "text": "A. W. N. Pugin."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "A.W.N. Pugin là người khởi xướng Phục hưng Gothic, coi Gothic là phong cách 'thật' về đạo đức và cấu trúc. Morris chịu ảnh hưởng sau đó; Gropius và Sullivan thuộc Hiện đại.", "key_fact": "Pugin khởi xướng phong trào Gothic Revival.", "topic": "Gothic Revival", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-17", "question": "What principle was fundamental to William Morris's practice of design?", "options": [{"key": "A", "text": "Mechanization and industrial production"}, {"key": "B", "text": "The idea of fellowship and sharing of interests among people"}, {"key": "C", "text": "Minimalism and simplicity"}, {"key": "D", "text": "Gothic Revival architecture"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Morris đề cao tinh thần 'fellowship' (tình đồng đội, chia sẻ lợi ích giữa con người), gắn với lý tưởng xã hội chủ nghĩa và lao động thủ công. Ông phản đối cơ giới hóa; Gothic Revival chỉ là nguồn cảm hứng chứ không phải nguyên tắc nền tảng.", "key_fact": "Nguyên tắc của Morris: 'fellowship' – tình đồng đội, chia sẻ.", "topic": "Arts and Crafts", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-18", "question": "Which statement is correct?", "options": [{"key": "A", "text": "The aesthetic movement appeared before the arts and crafts movement."}, {"key": "B", "text": "The aesthetic movement appeared same time the arts and crafts movement"}, {"key": "C", "text": "The aesthetic movement appeared after the arts and crafts movement"}, {"key": "D", "text": "All is incorrect"}], "answer": ["B"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Aesthetic Movement (khoảng 1860–1890) và Arts and Crafts (Morris & Co. 1861, gọi tên năm 1887) phát triển song song, chồng lấn nhau ở Anh. Bình luận FUOverflow đồng thuận B. (Nguồn: https://www.metmuseum.org/essays/design-reform ; FUOverflow HOD102 FA2024 FE)", "key_fact": "Aesthetic và Arts & Crafts xuất hiện cùng thời (nửa sau thế kỷ 19)", "topic": "Phong trào Thẩm mỹ", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-19", "question": "It was a style that looked optimistically to the future rather than nostalgically to the past, using as its primary source of inspiration the visually seductive and tactile forms of the natural world. It was also a truly international style that was adopted comprehensively across all realms of the applied arts: from glassware, furniture, and lighting to jewelry, graphic design, and typography. What is this style?", "options": [{"key": "A", "text": "Neo Classicism"}, {"key": "B", "text": "De Stijl"}, {"key": "C", "text": "Art Nouveau"}, {"key": "D", "text": "Organic design"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Art Nouveau hướng về tương lai, lấy cảm hứng từ hình thái tự nhiên và là phong cách quốc tế áp dụng trên mọi lĩnh vực mỹ thuật ứng dụng. Tân cổ điển nhìn về quá khứ; De Stijl dùng hình học trừu tượng.", "key_fact": "Art Nouveau: hướng tương lai, lấy cảm hứng thiên nhiên, mang tính quốc tế.", "topic": "Art Nouveau", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-20", "question": "This picture shows an image of the Salon of Victor Horta's house and studio in Brussels (now the Horta Museum), designed in 1898. What style is this?", "options": [{"key": "A", "text": "Art Nouveau"}, {"key": "B", "text": "Aesthetic movement"}, {"key": "C", "text": "High Victorian style"}, {"key": "D", "text": "Art Deco"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhà và xưởng của Victor Horta ở Brussels (1898) là kiệt tác Art Nouveau với đường cong 'whiplash' bằng sắt và họa tiết thực vật. Art Deco xuất hiện muộn hơn (thập niên 1920).", "key_fact": "Victor Horta là bậc thầy Art Nouveau ở Brussels.", "topic": "Art Nouveau", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-21", "question": "This picture shows an image of the Sagrada Familia church, a very famous Art Nouveau building in Barcelona. The architect borrowed motifs from Gothic and Moorish architecture and then transformed them into exotic melting forms that made it looks like a fanciful fairy-tale castle out of sand. Who is the author of this work?", "options": [{"key": "A", "text": "Antonio Gaudi"}, {"key": "B", "text": "Hector Guidmard"}, {"key": "C", "text": "Frank Lloyd Wright"}, {"key": "D", "text": "Henry van de Velde"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhà thờ Sagrada Familia ở Barcelona là công trình của kiến trúc sư Antoni Gaudí, đại diện tiêu biểu của Modernisme (Art Nouveau Catalan). Hector Guimard là Art Nouveau Pháp, Henry van de Velde là Bỉ, còn Frank Lloyd Wright là kiến trúc sư Mỹ.", "key_fact": "Sagrada Familia và Casa Batlló là tác phẩm của Antoni Gaudí.", "topic": "Art Nouveau", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-22", "question": "What was the outcome of the Dresden Exhibition for the German Arts and Crafts movement?", "options": [{"key": "A", "text": "It led to the discontinuation of the movement"}, {"key": "B", "text": "It showcased a shift towards functionality in design over artistic expressiveness"}, {"key": "C", "text": "It focused on reintroducing historical art styles"}, {"key": "D", "text": "It emphasized the need for more ornamental arts education"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Triển lãm Dresden 1906 đánh dấu bước chuyển của phong trào Thủ công Mỹ nghệ Đức sang đề cao tính công năng, sản xuất bằng máy và tiêu chuẩn hóa, dẫn tới việc thành lập Deutscher Werkbund năm 1907. Phong trào không bị chấm dứt mà còn phát triển mạnh hơn, và không quay lại phong cách lịch sử hay trang trí.", "key_fact": "Triển lãm Dresden 1906 thể hiện sự chuyển hướng sang thiết kế công năng, dẫn tới Deutscher Werkbund.", "topic": "Thủ công Mỹ nghệ Đức", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-23", "question": "What work of Adolf Loos has marked an intellectual turning point that led to a complete rejection of decorative motifs and towards a purely functional style?", "options": [{"key": "A", "text": "Studies in Design."}, {"key": "B", "text": "Ornament and Crime."}, {"key": "C", "text": "Arches Warenbüch."}, {"key": "D", "text": "Principles Decorative Design."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bài tiểu luận 'Ornament and Crime' (Trang trí và tội ác, 1908) của Adolf Loos là bước ngoặt tư tưởng, bác bỏ hoàn toàn họa tiết trang trí để hướng tới phong cách thuần công năng. Các lựa chọn còn lại không phải tác phẩm của Loos.", "key_fact": "Adolf Loos viết 'Ornament and Crime' (1908), cho rằng trang trí là tội ác.", "topic": "Chủ nghĩa công năng", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-24", "question": "This picture shows a red-blue chair designed by Gerrit Rietveld. What style is it?", "options": [{"key": "A", "text": "Art Nouveau."}, {"key": "B", "text": "Pop Art."}, {"key": "C", "text": "Art and Craft."}, {"key": "D", "text": "De Stijl."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ghế Red-Blue của Gerrit Rietveld (1918-23) là biểu tượng của De Stijl với các mảng phẳng hình học và màu cơ bản đỏ, xanh, vàng cùng đen. Nó không có đường cong hữu cơ của Art Nouveau hay tính thủ công của Arts and Crafts.", "key_fact": "Ghế Red-Blue của Rietveld là tác phẩm tiêu biểu của De Stijl.", "topic": "De Stijl", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-25", "question": "What are the characteristics of De Stijl movement?", "options": [{"key": "A", "text": "Considering ornament is a crime."}, {"key": "B", "text": "A rational new world would emerge from geometrically symbolic art."}, {"key": "C", "text": "Art must be associated with function."}, {"key": "D", "text": "All of the above."}], "answer": ["B"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Giống HOD-de2-25: đặc trưng De Stijl là niềm tin thế giới mới hợp lý nảy sinh từ nghệ thuật hình học mang tính biểu tượng; 'trang trí là tội ác' thuộc về Loos. (Nguồn: https://www.moma.org/collection/terms/de-stijl)", "key_fact": "De Stijl: thế giới mới hợp lý từ nghệ thuật hình học biểu tượng", "topic": "De Stijl", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-26", "question": "Like De Stijl, Constructivism had distinctly utopian goals and sought to bring about new social order by introducing a fresh formal language in art and design. Where did \"Constructivism\" movement come from?", "options": [{"key": "A", "text": "Poland."}, {"key": "B", "text": "Italy."}, {"key": "C", "text": "Russia."}, {"key": "D", "text": "Germany."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chủ nghĩa Kiến tạo (Constructivism) ra đời ở Nga khoảng năm 1913-1920 với Tatlin, Rodchenko, El Lissitzky, gắn với cách mạng Nga. Ý là quê hương của Futurism, còn Đức là quê hương của Bauhaus.", "key_fact": "Constructivism khởi nguồn từ Nga.", "topic": "Chủ nghĩa Kiến tạo", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-27", "question": "Fill in the blank: The German Pavilion at the 1929 Barcelona International Exposition by Ludwig Mies van der Rohe was one of the great landmark buildings of 20th-century architecture, harmoniously blending radically modern elemental forms and industrial materials such as steel and glass with materials more traditionally associated with luxury, namely: ...", "options": [{"key": "A", "text": "marble, red onyx, and travertine"}, {"key": "B", "text": "marble, red onyx"}, {"key": "C", "text": "red onyx and travertine"}, {"key": "D", "text": "Marble and travertine"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Gian hàng Đức (Barcelona Pavilion, 1929) của Mies van der Rohe kết hợp thép, kính với ba loại đá sang trọng: đá cẩm thạch, mã não đỏ (red onyx) và travertine. Các lựa chọn khác chỉ liệt kê thiếu.", "key_fact": "Barcelona Pavilion dùng đá cẩm thạch, mã não đỏ và travertine cùng thép và kính.", "topic": "Chủ nghĩa Hiện đại", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-28", "question": "This picture reveals an urban-planning proposal designed by Antonio Sant'Elia (1914), in which the author argued for the abolishment of decoration and for transcience in design and architecture. What style did he follow?", "options": [{"key": "A", "text": "The Aesthetic Movement"}, {"key": "B", "text": "De Sijl."}, {"key": "C", "text": "Futurism."}, {"key": "D", "text": "Constructivism."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Antonio Sant'Elia là kiến trúc sư Vị lai (Futurism) Ý, với dự án 'La Città Nuova' (1914) đề cao tốc độ, máy móc, tính tạm thời và bỏ trang trí. Constructivism là của Nga, De Stijl là của Hà Lan.", "key_fact": "Sant'Elia là kiến trúc sư tiêu biểu của Futurism Ý.", "topic": "Chủ nghĩa Vị lai", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-29", "question": "Which designer's work at the 1925 Paris exhibition epitomized the luxurious and decorative nature of Art Deco?", "options": [{"key": "A", "text": "Le Corbusier"}, {"key": "B", "text": "Emile-Jacques Ruhlmann"}, {"key": "C", "text": "Marcel Breuer"}, {"key": "D", "text": "Walter Gropius"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Émile-Jacques Ruhlmann với đồ nội thất gỗ quý, khảm ngà là biểu tượng của Art Deco xa hoa tại Triển lãm Paris 1925. Le Corbusier (Pavillon de l'Esprit Nouveau), Breuer và Gropius đều theo hướng Hiện đại tối giản.", "key_fact": "Ruhlmann đại diện cho Art Deco xa hoa tại Triển lãm Paris 1925.", "topic": "Art Deco", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-30", "question": "Fill in the blank: American culture was now heavily driven by mass consumption. One of the greatest symbols of America's new culture and its industrial ascendancy was General Motors (GM), which during the 1950s became the first corporation ever to gross ......... dollars a year.", "options": [{"key": "A", "text": "nine billion"}, {"key": "B", "text": "ten billion"}, {"key": "C", "text": "five hundred million"}, {"key": "D", "text": "a billion"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong những năm 1950, General Motors trở thành tập đoàn đầu tiên đạt doanh thu một tỷ đô la mỗi năm, biểu tượng của sức mạnh công nghiệp Mỹ. Các con số khác không khớp với tài liệu.", "key_fact": "GM là tập đoàn đầu tiên đạt doanh thu 1 tỷ USD/năm trong thập niên 1950.", "topic": "Thiết kế Mỹ hậu chiến", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-31", "question": "What are the criteria (or characteristics) of Good Design?", "options": [{"key": "A", "text": "Pure forms, practical function, appropriate use of materials, restrained use of colour, high-quality construction, good value for money"}, {"key": "B", "text": "Pure forms, practical function, appropriate use of materials, restrained use of colour and emotional connections."}, {"key": "C", "text": "Based on decorative details, focusing on performance, high-quality construction, good value for money"}, {"key": "D", "text": "Based on aesthetic value and functional use of the product, high-quality construction, good value for money"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Các tiêu chí 'Good Design' gồm: hình khối thuần khiết, công năng thực tiễn, sử dụng vật liệu phù hợp, tiết chế màu sắc, chất lượng chế tạo cao và đáng giá tiền. Phương án B thay bằng 'kết nối cảm xúc', C nhấn vào chi tiết trang trí, đều không đúng.", "key_fact": "Good Design: hình khối thuần khiết, công năng, vật liệu phù hợp, màu tiết chế, chế tạo tốt, giá trị hợp lý.", "topic": "Good Design", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-32", "question": "Fill in the blank: The success of Organic Design, meanwhile, prompted the rise of........., which, rather than attempting to capture the abstracted essence of natural forms, distorted them for purely decorative purposes.", "options": [{"key": "A", "text": "constructivism"}, {"key": "B", "text": "biomorphism"}, {"key": "C", "text": "theory of speed"}, {"key": "D", "text": "rationalism"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thành công của Organic Design dẫn tới Biomorphism (thiết kế sinh hình), vốn bóp méo hình dạng tự nhiên chỉ nhằm mục đích trang trí thay vì nắm bắt bản chất trừu tượng của chúng. Constructivism và Rationalism thuộc xu hướng hình học, lý tính.", "key_fact": "Biomorphism bóp méo hình dạng tự nhiên để trang trí, khác với Organic Design.", "topic": "Thiết kế hữu cơ", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-33", "question": "What is the meaning of the word \"Pop\" in the name of Pop Art style?", "options": [{"key": "A", "text": "Modern and trendy."}, {"key": "B", "text": "Nostalgia."}, {"key": "C", "text": "Traditional."}, {"key": "D", "text": "Popular (designed for a mass audience)."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Pop' là viết tắt của 'popular', tức nghệ thuật/thiết kế đại chúng hướng tới số đông, rẻ, dùng một lần, hợp thị hiếu giới trẻ. Không mang nghĩa truyền thống hay hoài cổ.", "key_fact": "'Pop' nghĩa là 'popular' – đại chúng.", "topic": "Pop Art", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-34", "question": "When did the Pop art movement begin to thrive?", "options": [{"key": "A", "text": "1960s."}, {"key": "B", "text": "1970s."}, {"key": "C", "text": "1980s."}, {"key": "D", "text": "1990s."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Pop Art và Pop design phát triển rực rỡ vào thập niên 1960, đặc biệt ở Anh và Mỹ. Những thập niên sau là thời của Anti-design, Postmodernism, Memphis.", "key_fact": "Pop Art thịnh hành vào thập niên 1960.", "topic": "Pop Art", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-35", "question": "In the late of 1960s and 1970s, many designers looked to the future optimistically and created products for an age in which everything would be shiny, clean, and bright; the visions they conjured offered a much-needed respite from the Vietnam War and other earthbound troubles. What kind of design movement is mentioned above?", "options": [{"key": "A", "text": "Plastic age."}, {"key": "B", "text": "Design goes pop."}, {"key": "C", "text": "Space-Age visions"}, {"key": "D", "text": "Postmodernism."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mô tả về tương lai lạc quan, mọi thứ sáng bóng, sạch sẽ, là xu hướng 'Space-Age visions' cuối thập niên 1960-1970, chịu ảnh hưởng cuộc chinh phục vũ trụ. Pop design nhấn vào tính rẻ, dùng một lần; Postmodernism thì đến sau.", "key_fact": "Space-Age design phản ánh sự lạc quan về tương lai thời chinh phục vũ trụ.", "topic": "Thiết kế Thời đại Vũ trụ", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-36", "question": "What are the roots of Ergonomic design?", "options": [{"key": "A", "text": "Social ideas related to health and inclusivity"}, {"key": "B", "text": "A manifestation of the wider return to rationalism in design"}, {"key": "C", "text": "The social ideas related to health and inclusivity, but it was also a manifestation of the wider return to rationalism in design."}, {"key": "D", "text": "None of the answer"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thiết kế công thái học (ergonomic) bắt nguồn từ tư tưởng xã hội về sức khỏe và tính hòa nhập, đồng thời là biểu hiện của sự quay trở lại chủ nghĩa duy lý trong thiết kế. Phương án C kết hợp cả hai nên đầy đủ nhất.", "key_fact": "Ergonomic design xuất phát từ ý tưởng xã hội về sức khỏe, hòa nhập và sự trở lại của duy lý.", "topic": "Thiết kế công thái học", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-37", "question": "This is Niels Diffrient's Humanscale 1/2/3 manual, designed by Henry Dreyfuss Associates, 1974. What is the name of the design that applies this manual?", "options": [{"key": "A", "text": "Anthropometric."}, {"key": "B", "text": "Creative Salvage."}, {"key": "C", "text": "Organic design."}, {"key": "D", "text": "Ergonomics"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bộ Humanscale của Niels Diffrient (Henry Dreyfuss Associates, 1974) cung cấp số liệu nhân trắc phục vụ thiết kế công thái học (Ergonomics). 'Anthropometric' chỉ là dữ liệu nhân trắc, không phải tên trường phái thiết kế trong giáo trình.", "key_fact": "Humanscale (1974) là cẩm nang cho thiết kế công thái học.", "topic": "Thiết kế công thái học", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-38", "question": "Fill in the blank: In New York, the Smart Design consultancy was starting revolution in the realm of housewares. This extensive line of kitchen tools, which includes numerous easy to-use products, from......to...., was the brainchild of Sam Farber.", "options": [{"key": "A", "text": "vegetable peelers - dustpans and brushes"}, {"key": "B", "text": "vegetable peelers - brushes"}, {"key": "C", "text": "vegetable peelers - knife and scissors"}, {"key": "D", "text": "cast iron pot - dustpans and brushes"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Dòng dụng cụ bếp OXO Good Grips do Sam Farber khởi xướng và Smart Design thực hiện gồm nhiều sản phẩm dễ dùng, từ dụng cụ gọt rau củ đến hót rác và chổi. Các lựa chọn khác không khớp với tài liệu.", "key_fact": "OXO Good Grips (Sam Farber, Smart Design) trải từ dụng cụ gọt rau đến hót rác và chổi.", "topic": "Thiết kế hòa nhập", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-39", "question": "By whom was the \"Form follows function\" philosophy mentioned?", "options": [{"key": "A", "text": "Adolf Loos."}, {"key": "B", "text": "William Morris."}, {"key": "C", "text": "Walter Gropius."}, {"key": "D", "text": "Louis Sullivan."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Câu 'Form follows function' (Hình thức theo sau công năng) do kiến trúc sư Mỹ Louis Sullivan đưa ra năm 1896. Adolf Loos nổi tiếng với 'Ornament and Crime', Gropius sáng lập Bauhaus.", "key_fact": "'Form follows function' là câu nói của Louis Sullivan.", "topic": "Chủ nghĩa công năng", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-40", "question": "The flowering of the \"New Art\" in the 1890s was in international phenomenon that played a key role in the story of design, which went a number of names depending on where it occurred. What did they call the \"New Art\" in Austria?", "options": [{"key": "A", "text": "Art Nouveau"}, {"key": "B", "text": "Jugendstil"}, {"key": "C", "text": "Modernisimo"}, {"key": "D", "text": "Vienna Secession"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ở Áo, 'Nghệ thuật Mới' được gọi là Vienna Secession (Secessionsstil). Jugendstil là tên ở Đức, Modernismo ở Tây Ban Nha, Art Nouveau ở Pháp và Bỉ.", "key_fact": "Art Nouveau ở Áo gọi là Vienna Secession.", "topic": "Art Nouveau", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-41", "question": "Where did Thomas Edison establish his \"invention factory\"?", "options": [{"key": "A", "text": "Menlo Park, New Jersey"}, {"key": "B", "text": "Detroit, Michigan"}, {"key": "C", "text": "Philadelphia, Pennsylvania"}, {"key": "D", "text": "Chicago, Illinois"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thomas Edison lập 'nhà máy phát minh' (phòng thí nghiệm nghiên cứu công nghiệp) tại Menlo Park, New Jersey năm 1876. Detroit gắn với ngành ô tô của Ford.", "key_fact": "Edison lập 'invention factory' tại Menlo Park, New Jersey.", "topic": "Điện khí hóa", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-42", "question": "What were a number of other military designs first appeared during World War I?", "options": [{"key": "A", "text": "chemical weapons such as mustard gas, biplanes used for bombing"}, {"key": "B", "text": "aerial reconnaissance, submarines"}, {"key": "C", "text": "tanks"}, {"key": "D", "text": "All of the answers."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chiến tranh Thế giới thứ nhất chứng kiến sự xuất hiện của vũ khí hóa học (khí mù tạt), máy bay hai tầng cánh ném bom, trinh sát trên không, tàu ngầm và xe tăng. Vì vậy tất cả các phương án đều đúng.", "key_fact": "Thế chiến I khai sinh xe tăng, vũ khí hóa học, máy bay ném bom, trinh sát trên không.", "topic": "Thiết kế thời chiến", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-43", "question": "Fill in the blank: By the mid-to-late 1920s, in the manufacturers, especially in the automotive industry, ............as a business asset, since it allowed them to offer more purchasing options to potential customers.", "options": [{"key": "A", "text": "color"}, {"key": "B", "text": "luxury styling"}, {"key": "C", "text": "premium materials"}, {"key": "D", "text": "modern design"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Cuối thập niên 1920, các nhà sản xuất ô tô (nhất là GM với sơn Duco) xem màu sắc là tài sản kinh doanh vì cho phép đưa thêm nhiều lựa chọn mua cho khách hàng, khác với Ford Model T chỉ có màu đen.", "key_fact": "Thập niên 1920, màu sắc trở thành công cụ kinh doanh trong ngành ô tô.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-44", "question": "From the mid-1930s onwards, a vast number of modern landmark designs made from plastic, were produced for the US market. What are these products?", "options": [{"key": "A", "text": "Miniature Baby Brownie Camera."}, {"key": "B", "text": "Operating desk lamp (Model No. 114)."}, {"key": "C", "text": "Refrigerator Coldspot."}, {"key": "D", "text": "All of the above."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Từ giữa thập niên 1930, nhiều thiết kế mang tính biểu tượng bằng nhựa được sản xuất cho thị trường Mỹ, như máy ảnh Baby Brownie (Teague, Bakelite), đèn bàn và tủ lạnh Coldspot (Loewy). Câu hỏi liệt kê đều là ví dụ trong tài liệu nên chọn 'tất cả'.", "key_fact": "Thập niên 1930, nhựa (Bakelite) được dùng rộng rãi cho sản phẩm tiêu dùng Mỹ.", "topic": "Thời đại nhựa", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-45", "question": "What year witnessed the arrival of the first US radio network, NBC?", "options": [{"key": "A", "text": "1925"}, {"key": "B", "text": "1926"}, {"key": "C", "text": "1927"}, {"key": "D", "text": "1945"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mạng lưới phát thanh đầu tiên của Mỹ, NBC, ra đời năm 1926. Năm 1927 là năm thành lập CBS.", "key_fact": "NBC – mạng phát thanh đầu tiên của Mỹ – ra đời năm 1926.", "topic": "Truyền thông đại chúng", "note": "", "comment_answer": "B"}, {"id": "HOD-de2-46", "question": "What is the style of the Teak ice-bucket designed by Jens Quistgard, 1960?", "options": [{"key": "A", "text": "Scandinavian Style"}, {"key": "B", "text": "Gute Form"}, {"key": "C", "text": "Italian Design"}, {"key": "D", "text": "Good Design"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xô đá bằng gỗ teak của Jens Quistgaard (Dansk, 1960) là tiêu biểu cho phong cách Scandinavia: vật liệu tự nhiên, hình khối hữu cơ, ấm áp. Gute Form là của Đức, Good Design gắn với Mỹ/Anh.", "key_fact": "Xô đá gỗ teak của Quistgaard thuộc phong cách Scandinavia.", "topic": "Thiết kế Scandinavia", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-47", "question": "What is the name of this product?", "options": [{"key": "A", "text": "TP1 portable radio and phonograph designed by Dieter Rams for Braun, 1959."}, {"key": "B", "text": "Bluebird 566 radio designed by Walter Dorwin Teague for Sparton, 1935-36-with what Edgar Kauffman, Jr., called its \"speed whiskers.\""}, {"key": "C", "text": "T24 portable transistor radio designed by Dieter Rams for Braun, 1956."}, {"key": "D", "text": "SK4 record player designed by Dieter Rams and Hans Gugelot for Braun, 1957, nicknamed \"Snow White's Coffin.\""}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ảnh là máy hát có nắp nhựa trong suốt, thân trắng với hai bên gỗ – chính là SK4 của Dieter Rams và Hans Gugelot cho Braun, biệt danh 'Quan tài Bạch Tuyết'. TP1 là máy cầm tay nhỏ, T24 là radio bỏ túi, Bluebird có mặt gương xanh tròn.", "key_fact": "SK4 (Braun, Rams & Gugelot) – 'Snow White's Coffin', nắp plexiglass trong suốt.", "topic": "Thiết kế Braun", "note": "", "comment_answer": "D"}, {"id": "HOD-de2-48", "question": "Fill in the blank: West Germany looked to build a better future once it became politically independent, in 1949. By putting its faith in the transformative power of........, West Germany eventually became a major exporter of beautifully designed and engineered products that brought about the Wirtschaftswunder-the economic miracle of the mid-1950s.", "options": [{"key": "A", "text": "Gute Form"}, {"key": "B", "text": "Good Design"}, {"key": "C", "text": "Vonstructivism"}, {"key": "D", "text": "Biomorphism"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tây Đức đặt niềm tin vào 'Gute Form' (Hình thức tốt) – thiết kế hợp lý, chức năng, chất lượng – và trở thành nước xuất khẩu lớn, góp phần tạo nên 'phép màu kinh tế' giữa thập niên 1950. Good Design là thuật ngữ tương đương ở Mỹ/Anh.", "key_fact": "Gute Form góp phần tạo nên Wirtschaftswunder của Tây Đức.", "topic": "Gute Form", "note": "", "comment_answer": "A"}, {"id": "HOD-de2-49", "question": "Fill in the blank: As part of the wider postmodern movement, Creative Salvage helped to revolutionize design in much the same way that Punk changed music and fashion. Also, it was significant to the subsequent development of avant-garde design because it helped to break down traditional barriers between ..........", "options": [{"key": "A", "text": "Art and craft"}, {"key": "B", "text": "Craft and Design"}, {"key": "C", "text": "Art, Craft, and Design"}, {"key": "D", "text": "None of the answer"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Creative Salvage góp phần phá vỡ ranh giới truyền thống giữa nghệ thuật, thủ công và thiết kế, như Punk đã làm với âm nhạc và thời trang. Các phương án A, B thiếu một thành phần.", "key_fact": "Creative Salvage xóa nhòa ranh giới giữa nghệ thuật, thủ công và thiết kế.", "topic": "Creative Salvage", "note": "", "comment_answer": "C"}, {"id": "HOD-de2-50", "question": "Creative Salvage helped to revolutionize the design in much the same way that Punk changed music and fashion. Also, it was significant to the subsequent development of avant-garde design because it helped to break down traditional barriers between art, craft, and design. What is the key to Creative Salvage's success?", "options": [{"key": "A", "text": "The recycling of scrap to form stylish and functional artefacts for the home and office."}, {"key": "B", "text": "The aesthetic and emotional values, use of natural materials."}, {"key": "C", "text": "Prioritizing the use of natural materials scrap to form stylish and functional artefacts for the home and office."}, {"key": "D", "text": "The exuberantly playful, capturing the optimism, color combinations, bold overall forms."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chìa khóa thành công của Creative Salvage là tái chế phế liệu để tạo thành đồ dùng phong cách và có công năng cho nhà ở và văn phòng (ví dụ ghế Rover của Ron Arad). Phương án C sai vì không ưu tiên vật liệu tự nhiên.", "key_fact": "Creative Salvage dựa trên việc tái chế phế liệu thành đồ dùng phong cách.", "topic": "Creative Salvage", "note": "", "comment_answer": "A"}]}, {"id": "de3", "name": "Đề 3", "questions": [{"id": "HOD-de3-1", "question": "In 1989, which British computer scientist - created a new computer language-Hypertext Transfer Protocol (HTTP)-that enabled documents to be communicated over the Internet?", "options": [{"key": "A", "text": "Rudy VanderLans"}, {"key": "B", "text": "Zuzana Licko"}, {"key": "C", "text": "Tim Berners-Lee"}, {"key": "D", "text": "None of the answer"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Năm 1989, nhà khoa học máy tính người Anh Tim Berners-Lee tạo ra HTTP và World Wide Web, cho phép truyền tài liệu qua Internet. Rudy VanderLans và Zuzana Licko là nhà thiết kế đồ họa của tạp chí Emigre.", "key_fact": "Tim Berners-Lee phát minh HTTP/World Wide Web năm 1989.", "topic": "Thời đại số", "note": "", "comment_answer": "C"}, {"id": "HOD-de3-2", "question": "Arranging the timeline corresponding to the launch of each following invention: 1. hourglass, 2. Blast furnace, 3. Improved water wheel, 4 Johannes Gutenberg Printing Press.", "options": [{"key": "A", "text": "7th century - 8th century - 12th century - 14th century"}, {"key": "B", "text": "8th century - 7th century - 12th century - 14th century"}, {"key": "C", "text": "8th century - 12th century - 7th century - 14th century"}, {"key": "D", "text": "7th century - 14th century - 8th century - 12th century"}], "answer": ["C"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Đồng hồ cát xuất hiện ở châu Âu khoảng thế kỷ 8, lò cao châu Âu khoảng thế kỷ 12 (từ ~1150), bánh xe nước cải tiến thế kỷ 7; chỉ C có thứ tự 8–12–7. Máy in Gutenberg thực tế ~1440 (thế kỷ 15) nhưng mọi phương án đều ghi 14th. (Nguồn: https://en.wikipedia.org/wiki/Medieval_technology ; https://listverse.com/2007/09/22/top-10-inventions-of-the-middle-ages/)", "key_fact": "Hourglass 8 – Blast furnace 12 – Water wheel 7 – Gutenberg (14 theo đề)", "topic": "Thủ công thời Trung cổ", "note": "", "comment_answer": "C"}, {"id": "HOD-de3-3", "question": "In the early 1970s, which company began experimenting with cellular radio technology, and the results of those tests went on to revolutionize communication devices? In 1973 the company tested the first portable radio phone\" in New York?", "options": [{"key": "A", "text": "Sony"}, {"key": "B", "text": "Samsung"}, {"key": "C", "text": "Apple"}, {"key": "D", "text": "Motorola"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đầu thập niên 1970, Motorola thử nghiệm công nghệ vô tuyến di động và năm 1973 Martin Cooper thực hiện cuộc gọi điện thoại di động đầu tiên tại New York bằng DynaTAC. Apple, Sony, Samsung không liên quan đến sự kiện này.", "key_fact": "Motorola thử nghiệm điện thoại di động đầu tiên năm 1973 tại New York.", "topic": "Thiết kế điện tử", "note": "", "comment_answer": "D"}, {"id": "HOD-de3-4", "question": "Driven by the tastes of the youth, manufacturers now began to produce a steady stream of inexpensive, expendable products that suited their customers' more casual lifestyles, focus on the bold patterns and shiny, brightly coloured designs. What kind of style is described above?", "options": [{"key": "A", "text": "Functionalism."}, {"key": "B", "text": "Minimalism."}, {"key": "C", "text": "De Stijl."}, {"key": "D", "text": "Pop design."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sản phẩm rẻ, dùng một lần, hợp lối sống thoải mái của giới trẻ, họa tiết đậm và màu sắc sáng bóng là đặc trưng của Pop design thập niên 1960. Functionalism, Minimalism và De Stijl đều đề cao sự tiết chế, lâu bền.", "key_fact": "Pop design: rẻ, dùng một lần, màu sắc rực rỡ, hướng giới trẻ.", "topic": "Pop design", "note": "", "comment_answer": "D"}, {"id": "HOD-de3-5", "question": "Fill in the blank: West Germany looked to build a better future once it became politically independent, in 1949. By putting its faith in the transformative power of........, West Germany eventually became a major exporter of beautifully designed and engineered products that brought about the Wirtschaftswunder-the economic miracle of the mid-1950s.", "options": [{"key": "A", "text": "Gute Form"}, {"key": "B", "text": "Good Design"}, {"key": "C", "text": "Vonstructivism"}, {"key": "D", "text": "Biomorphism"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tây Đức đặt niềm tin vào 'Gute Form' (Hình thức tốt) – thiết kế hợp lý, chức năng, chất lượng – và trở thành nước xuất khẩu lớn, góp phần tạo nên 'phép màu kinh tế' giữa thập niên 1950. Good Design là thuật ngữ tương đương ở Mỹ/Anh.", "key_fact": "Gute Form góp phần tạo nên Wirtschaftswunder của Tây Đức.", "topic": "Gute Form", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-6", "question": "What kind of technique that represented for the first-time designs could be replicated more or less exactly, thereby making them easier and less-time consuming to manufacture?", "options": [{"key": "A", "text": "Paddle-and-anvil method"}, {"key": "B", "text": "Simple ingot molds"}, {"key": "C", "text": "Standardization"}, {"key": "D", "text": "Interchangeability"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khuôn đúc thỏi đơn giản thời cổ đại lần đầu cho phép sao chép thiết kế gần như chính xác, giúp sản xuất nhanh và dễ hơn. Paddle-and-anvil là kỹ thuật làm gốm thủ công; tiêu chuẩn hóa và khả năng thay thế lẫn nhau là các khái niệm phát triển muộn hơn.", "key_fact": "Khuôn đúc đơn giản cho phép lần đầu sao chép thiết kế gần như y hệt.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": "B"}, {"id": "HOD-de3-7", "question": "When did the Pop art movement begin to thrive?", "options": [{"key": "A", "text": "1960s."}, {"key": "B", "text": "1970s."}, {"key": "C", "text": "1980s."}, {"key": "D", "text": "1990s."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Pop Art và Pop design phát triển rực rỡ vào thập niên 1960, đặc biệt ở Anh và Mỹ. Những thập niên sau là thời của Anti-design, Postmodernism, Memphis.", "key_fact": "Pop Art thịnh hành vào thập niên 1960.", "topic": "Pop Art", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-8", "question": "This picture shows an image of the Finnish Pavilion designed by the architect Eliel Saarinen, perhaps Finland's greatest exponent of National Romanticism, who pioneered a style of architecture and design that alluded to his country's ancient Karelian culture. Where the motifs on this building inspired?", "options": [{"key": "A", "text": "Viking-revival style"}, {"key": "B", "text": "Nature"}, {"key": "C", "text": "Nordic folk art and vernacular architecture"}, {"key": "D", "text": "Dragon motifs"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Eliel Saarinen theo chủ nghĩa Lãng mạn Dân tộc Phần Lan, lấy cảm hứng từ nghệ thuật dân gian Bắc Âu và kiến trúc bản địa gắn với văn hóa Karelia cổ. Viking-revival là xu hướng của Na Uy, còn 'thiên nhiên' quá chung chung.", "key_fact": "Lãng mạn Dân tộc Phần Lan lấy cảm hứng từ nghệ thuật dân gian Bắc Âu và kiến trúc bản địa.", "topic": "Lãng mạn Dân tộc", "note": "", "comment_answer": "C"}, {"id": "HOD-de3-9", "question": "The first successful flight of Orville and Wilbur Wright in 1903 inaugurated a new era of air travel - and with it, globalization. In 1909, they began supplying US Army Model A. What is the biggest role of the Wright brothers designers?", "options": [{"key": "A", "text": "They bring a rapid acceleration to research and development of military equipment."}, {"key": "B", "text": "Through their design approach, taught humans to fly and permanently change their way of life."}, {"key": "C", "text": "Their design has promoted tourism development worldwide."}, {"key": "D", "text": "They taught people to fly and their design became the basis for developing a series of military aircraft for war."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Vai trò lớn nhất của anh em nhà Wright là qua cách tiếp cận thiết kế đã dạy con người bay và thay đổi vĩnh viễn lối sống của nhân loại (mở ra kỷ nguyên hàng không và toàn cầu hóa). Phương án D thu hẹp vai trò vào máy bay quân sự, A và C chỉ là hệ quả phụ.", "key_fact": "Anh em Wright (1903) dạy con người bay, thay đổi vĩnh viễn lối sống nhân loại.", "topic": "Hàng không", "note": "", "comment_answer": "B"}, {"id": "HOD-de3-10", "question": "In 1873 the Remington factory produced the world's first commercial machines, which was designed by Christopher Latham Sholes and introduced the qwerty keyboard layout that is still in use today. What is the product?", "options": [{"key": "A", "text": "Selectric electric typewiter."}, {"key": "B", "text": "Typewriter."}, {"key": "C", "text": "Printing presses."}, {"key": "D", "text": "Apple Macintosh."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Năm 1873, Remington sản xuất máy đánh chữ thương mại đầu tiên do Christopher Latham Sholes thiết kế, với bàn phím QWERTY. Selectric của IBM ra đời năm 1961, Macintosh năm 1984.", "key_fact": "Máy đánh chữ Sholes & Glidden (Remington, 1873) giới thiệu bàn phím QWERTY.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "B"}, {"id": "HOD-de3-11", "question": "What are the characteristics of De Stijl movement?", "options": [{"key": "A", "text": "Considering ornament is a crime."}, {"key": "B", "text": "A rational new world would emerge from geometrically symbolic art."}, {"key": "C", "text": "Art must be associated with function."}, {"key": "D", "text": "All of the above."}], "answer": ["B"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Giống HOD-de2-25: đặc trưng De Stijl là niềm tin thế giới mới hợp lý nảy sinh từ nghệ thuật hình học mang tính biểu tượng; 'trang trí là tội ác' thuộc về Loos. (Nguồn: https://www.moma.org/collection/terms/de-stijl)", "key_fact": "De Stijl: thế giới mới hợp lý từ nghệ thuật hình học biểu tượng", "topic": "De Stijl", "note": "", "comment_answer": "D"}, {"id": "HOD-de3-12", "question": "AEG was a German company that exploited the commercial benefits of modern design, a pioneer of electrical domestic appliances. How could AGE distinguish its products from its competitors?", "options": [{"key": "A", "text": "Promoting their products through as archetypes of “artistic design” that were in “good taste”"}, {"key": "B", "text": "Good product."}, {"key": "C", "text": "The price is cheap."}, {"key": "D", "text": "Modern look"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "AEG phân biệt sản phẩm bằng cách quảng bá chúng như những hình mẫu của 'thiết kế nghệ thuật' và 'gu thẩm mỹ tốt', thuê Peter Behrens làm cố vấn nghệ thuật năm 1907, tạo bản sắc doanh nghiệp đầu tiên. Giá rẻ không phải chiến lược của họ.", "key_fact": "AEG quảng bá sản phẩm là 'thiết kế nghệ thuật' có 'gu tốt' nhờ Peter Behrens.", "topic": "AEG và Peter Behrens", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-13", "question": "Which parts of Qin Shi Huang's Terracotta Warrior were mass-produced?", "options": [{"key": "A", "text": "Arms, body."}, {"key": "B", "text": "Face."}, {"key": "C", "text": "Soles."}, {"key": "D", "text": "Head."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Các bộ phận như thân, tay, chân của tượng binh mã Tần Thủy Hoàng được sản xuất hàng loạt bằng khuôn rồi lắp ráp, còn khuôn mặt và đầu được tạo hình riêng để mỗi tượng có nét khác nhau. Vì vậy mặt và đầu không phải phần sản xuất hàng loạt.", "key_fact": "Tượng binh mã: thân, tay chân làm bằng khuôn hàng loạt, mặt được tạo hình riêng.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-14", "question": "Fill in the blank: The icons of the Mac's revolutionary graphical interface-..........., and so on-were devised by one of the great unsung design heroes of the computer revolution, Susan Kare.", "options": [{"key": "A", "text": "the trashcan"}, {"key": "B", "text": "the bomb"}, {"key": "C", "text": "the smiling monitor"}, {"key": "D", "text": "All of the answers"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Susan Kare thiết kế các biểu tượng của Macintosh như thùng rác, quả bom, màn hình mỉm cười (Happy Mac)… nên chọn tất cả.", "key_fact": "Susan Kare thiết kế các biểu tượng giao diện đồ họa của Macintosh.", "topic": "Thời đại số", "note": "", "comment_answer": "D"}, {"id": "HOD-de3-15", "question": "What was the purpose of the Great Exhibition of the Works of Industry of all Nations took place in Britain from May 1 to Oct. 11, 1851?", "options": [{"key": "A", "text": "Competition and encouragement for both art and industry."}, {"key": "B", "text": "Introduce and design houses for the middle class."}, {"key": "C", "text": "Encourage industrial development, put theory into practice."}, {"key": "D", "text": "Encourage the development of handmade arts."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Triển lãm Lớn 1851 tại Cung Pha lê, London nhằm khuyến khích và thi đua giữa nghệ thuật và công nghiệp các quốc gia, phô diễn thành tựu công nghiệp. Nó không nhằm phát triển đồ thủ công hay thiết kế nhà cho tầng lớp trung lưu.", "key_fact": "Great Exhibition 1851 nhằm thi đua, khuyến khích nghệ thuật và công nghiệp.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-16", "question": "Who was established the Staatliches Bauhaus in 1916 by merging the two Weimar art schools into a single interdisciplinary school of craft and design?", "options": [{"key": "A", "text": "Franks Lloyd Wright."}, {"key": "B", "text": "Walter Gropius."}, {"key": "C", "text": "Louis Sullivan."}, {"key": "D", "text": "Michael Thonet."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Walter Gropius sáng lập Bauhaus tại Weimar bằng cách sáp nhập hai trường nghệ thuật (thực tế là năm 1919, câu hỏi ghi nhầm năm). Frank Lloyd Wright và Louis Sullivan là kiến trúc sư Mỹ, Thonet là nhà làm ghế gỗ uốn.", "key_fact": "Walter Gropius sáng lập Bauhaus tại Weimar năm 1919.", "topic": "Bauhaus", "note": "", "comment_answer": "B"}, {"id": "HOD-de3-17", "question": "From the mid-1930s onwards, a vast number of modern landmark designs made from plastic, were produced for the US market. What are these products?", "options": [{"key": "A", "text": "Miniature Baby Brownie Camera."}, {"key": "B", "text": "Operating desk lamp (Model No. 114)."}, {"key": "C", "text": "Refrigerator Coldspot."}, {"key": "D", "text": "All of the above."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Từ giữa thập niên 1930, nhiều thiết kế mang tính biểu tượng bằng nhựa được sản xuất cho thị trường Mỹ, như máy ảnh Baby Brownie (Teague, Bakelite), đèn bàn và tủ lạnh Coldspot (Loewy). Câu hỏi liệt kê đều là ví dụ trong tài liệu nên chọn 'tất cả'.", "key_fact": "Thập niên 1930, nhựa (Bakelite) được dùng rộng rãi cho sản phẩm tiêu dùng Mỹ.", "topic": "Thời đại nhựa", "note": "", "comment_answer": "D"}, {"id": "HOD-de3-18", "question": "What design movement means \"Twentieth Century\", seeking to revitalize Classicism within a modern idiom?", "options": [{"key": "A", "text": "Futurism"}, {"key": "B", "text": "Novecento"}, {"key": "C", "text": "Rationalism"}, {"key": "D", "text": "Art Deco"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Novecento (tiếng Ý nghĩa là 'thế kỷ 20') là phong trào Ý tìm cách phục hưng Chủ nghĩa Cổ điển trong ngôn ngữ hiện đại. Rationalism Ý theo hướng hiện đại thuần túy, Futurism thì chối bỏ quá khứ.", "key_fact": "Novecento nghĩa là 'thế kỷ 20', phục hưng Cổ điển theo lối hiện đại.", "topic": "Thiết kế Ý", "note": "", "comment_answer": "B"}, {"id": "HOD-de3-19", "question": "Which German company pioneered the electrical-transmission system and was an early manufacturer of electric domestic appliances?", "options": [{"key": "A", "text": "Allgemeine Elektricitäts-Gesellschaft (AEG)"}, {"key": "B", "text": "Edison General Electric Company"}, {"key": "C", "text": "Workshop for Precision Mechanics and Electrical Enginerring"}, {"key": "D", "text": "None of the answer."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "AEG (Allgemeine Elektricitäts-Gesellschaft) là công ty Đức tiên phong trong hệ thống truyền tải điện và sản xuất đồ gia dụng điện. Edison General Electric là công ty Mỹ.", "key_fact": "AEG là công ty Đức tiên phong về truyền tải điện và đồ gia dụng điện.", "topic": "AEG và Peter Behrens", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-20", "question": "What material was first applied in mass-production in ancient times?", "options": [{"key": "A", "text": "Iron."}, {"key": "B", "text": "Steel."}, {"key": "C", "text": "Concrete."}, {"key": "D", "text": "Brick."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Gạch là vật liệu đầu tiên được sản xuất hàng loạt từ thời cổ đại nhờ khuôn đúc có kích thước tiêu chuẩn (Lưỡng Hà, Ai Cập). Thép và bê tông hiện đại xuất hiện muộn hơn nhiều; sắt không được sản xuất hàng loạt sớm như gạch.", "key_fact": "Gạch đúc khuôn là một trong những sản phẩm sản xuất hàng loạt đầu tiên thời cổ đại.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": "D"}, {"id": "HOD-de3-21", "question": "This picture shows an image of the Casa Batllo in Barcelona, redesigned by Antonio Gaudi, 1904-06. What style is this?", "options": [{"key": "A", "text": "Art Nouveau"}, {"key": "B", "text": "Neo classicism"}, {"key": "C", "text": "Memphis style"}, {"key": "D", "text": "Pop art"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Casa Batlló (1904-06) do Gaudí cải tạo, với hình dáng uốn lượn hữu cơ, là công trình Art Nouveau (Modernisme Catalan). Memphis và Pop art thuộc nửa sau thế kỷ 20.", "key_fact": "Casa Batlló của Gaudí thuộc Art Nouveau.", "topic": "Art Nouveau", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-22", "question": "In 1955, a highly influential book on the subject “Designing for People”, which introduced “Joe and Josephine”, the two diagrammatic characters based on the concept of the “average Joe”. Who is the author of the book?", "options": [{"key": "A", "text": "Henry Dreyfuss"}, {"key": "B", "text": "Peter Behrens"}, {"key": "C", "text": "Robert Bosch"}, {"key": "D", "text": "Adolf Loos"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Henry Dreyfuss viết 'Designing for People' (1955), giới thiệu hai nhân vật 'Joe và Josephine' dựa trên số liệu nhân trắc trung bình. Peter Behrens gắn với AEG, Loos với 'Ornament and Crime'.", "key_fact": "Henry Dreyfuss viết 'Designing for People' (1955) với Joe và Josephine.", "topic": "Thiết kế công thái học", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-23", "question": "During the First Industrial Revolution, what was one of the most profound effects of these early mechanized looms?", "options": [{"key": "A", "text": "The change in working patterns, with workers, instead of individually labouring at home."}, {"key": "B", "text": "Increase labour productivity."}, {"key": "C", "text": "Increase the number of products."}, {"key": "D", "text": "Reduce the cost of products."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tác động sâu sắc nhất của máy dệt cơ giới hóa là thay đổi mô hình lao động: công nhân không còn làm việc cá nhân tại nhà mà tập trung vào nhà máy. Tăng năng suất, tăng sản lượng, giảm giá là hệ quả kinh tế nhưng không phải tác động 'sâu sắc nhất' theo giáo trình.", "key_fact": "Máy dệt cơ giới chuyển lao động từ tại nhà sang nhà máy.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-24", "question": "What was the approach most used by American Arts and Crafts designers in expressing the rustic, unusual style of decoration and the use of simple elemental shapes?", "options": [{"key": "A", "text": "Rough-and-ready approach"}, {"key": "B", "text": "Human-centered approach"}, {"key": "C", "text": "Co-design approach"}, {"key": "D", "text": "All of the above"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Các nhà thiết kế Arts and Crafts Mỹ (như Gustav Stickley) dùng cách tiếp cận 'rough-and-ready' (mộc mạc, thô ráp) với hình khối đơn giản, phong cách trang trí dân dã. Human-centered và co-design là các khái niệm hiện đại.", "key_fact": "Arts and Crafts Mỹ theo cách tiếp cận mộc mạc 'rough-and-ready'.", "topic": "Arts and Crafts Mỹ", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-25", "question": "What kind of manufacturing techniques developed by Michael Thonet, which facilitated the mass production of furniture?", "options": [{"key": "A", "text": "Bend wooden sticks with steam at high temperature (the steam-bending of solid wood)"}, {"key": "B", "text": "The inox plating technique creates a shiny surface."}, {"key": "C", "text": "Use plastic materials to shape interior products."}, {"key": "D", "text": "Application of metal shaping of interior products."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Michael Thonet phát triển kỹ thuật uốn gỗ đặc bằng hơi nước, cho phép sản xuất hàng loạt ghế (như ghế số 14). Nhựa và inox không liên quan đến Thonet.", "key_fact": "Thonet dùng kỹ thuật uốn gỗ đặc bằng hơi nước để sản xuất hàng loạt.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-26", "question": "Why is Art Nouveau argued as the first modern style?", "options": [{"key": "A", "text": "Throwing off the historicizing, decorative shackles of the past"}, {"key": "B", "text": "Decoration should always be informed by a design's construction rather than applied as surface ornamentation"}, {"key": "C", "text": "Logical structure of products, uncompressing logic in the use of materials, proud and frank exhibition of working process"}, {"key": "D", "text": "All of the above"}], "answer": ["D"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Các ý B (trang trí phải xuất phát từ cấu trúc, theo Owen Jones) và C (cấu trúc logic, dùng vật liệu triệt để, phơi bày quy trình – tư tưởng Viollet-le-Duc mà Horta, Guimard tiếp thu) đều là nền tảng của Art Nouveau, cùng với việc rũ bỏ chủ nghĩa lịch sử (A). Tất cả bình luận trên FUOverflow (kể cả người uy tín) chọn D; chưa tìm được trích đoạn giáo trình. (Nguồn: https://en.wikipedia.org/wiki/Art_Nouveau ; FUOverflow HOD102 SU2024 RE)", "key_fact": "Art Nouveau 'phong cách hiện đại đầu tiên': All of the above", "topic": "Art Nouveau", "note": "Đã sửa từ A sang D sau khi tra cứu trên mạng.", "comment_answer": "D"}, {"id": "HOD-de3-27", "question": "Fill in the blank “...was one of the earliest American manufacturers to realize fully the potential of an effective marketing program that included sales promotion, publicity, product sampling, advertising, and public relations”; and he helped to alter significantly the course of modern industrial design toward a much more commercial modus operandi.", "options": [{"key": "A", "text": "Samuel Colt."}, {"key": "B", "text": "Adolf Loos."}, {"key": "C", "text": "William Morris."}, {"key": "D", "text": "Walter Gropius."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Samuel Colt là một trong những nhà sản xuất Mỹ đầu tiên khai thác hiệu quả marketing (quảng bá, quảng cáo, tặng mẫu, quan hệ công chúng), đưa thiết kế công nghiệp hướng thương mại. Loos, Morris, Gropius đều là nhà thiết kế/lý luận châu Âu.", "key_fact": "Samuel Colt tiên phong dùng marketing tổng thể trong sản xuất Mỹ.", "topic": "Hệ thống sản xuất Mỹ", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-28", "question": "During the design decade in the 1930s, what did design consultants do to increase profitability for manufacturers?", "options": [{"key": "A", "text": "Making a few seemingly insignificant changes in their redesigns. They also changed materials-say, from metal to plastic-which made products cheaper, more functional."}, {"key": "B", "text": "Design optimized for the industrial production process. They also changed materials-say, from metal to plastic-which made products cheaper, more functional."}, {"key": "C", "text": "Decreased functionality of the product to made products cheaper."}, {"key": "D", "text": "Making a few seemingly insignificant changes in their redesigns and remove all decorative motifs."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong 'thập kỷ thiết kế' 1930, các nhà tư vấn thiết kế thường chỉ thay đổi vài điểm có vẻ nhỏ khi tái thiết kế và đổi vật liệu, như từ kim loại sang nhựa, giúp sản phẩm rẻ hơn và tiện dụng hơn, qua đó tăng lợi nhuận. Họ không giảm công năng hay loại bỏ hết trang trí.", "key_fact": "Thập niên 1930: thay đổi nhỏ trong thiết kế và đổi vật liệu sang nhựa giúp tăng lợi nhuận.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-29", "question": "Fill in the blank: The American Dream was transformed into a familial vision of suburban homemaking, it reflected a widespread yearning for a lifestyle that involved ..............; one championed by a highly sophisticated advertising industry that linked aspiration to a perpetual desire for new and seemingly improved goods", "options": [{"key": "A", "text": "unparalleled levels of consumption"}, {"key": "B", "text": "high levels of frugal consumption"}, {"key": "C", "text": "moderate consumption"}, {"key": "D", "text": "relatively strong level of consumption"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Giấc mơ Mỹ hậu chiến gắn với lối sống ngoại ô và mức tiêu dùng chưa từng có, được ngành quảng cáo thúc đẩy bằng khát khao hàng mới liên tục. Các mức 'tiết kiệm' hay 'vừa phải' trái với tinh thần tiêu dùng đại chúng.", "key_fact": "Giấc mơ Mỹ thập niên 1950 gắn với mức tiêu dùng chưa từng có.", "topic": "Thiết kế Mỹ hậu chiến", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-30", "question": "Which of the following designers epitomized the French Art Nouveau style better than any other who created cast-iron entrances to the Paris Metro, designed for the Compagnie du Metropolitan in 1898, that brought him widespread acclaim?", "options": [{"key": "A", "text": "Hector Guidmard"}, {"key": "B", "text": "Emile-Jacques Ruhlmann"}, {"key": "C", "text": "Piere Chareau"}, {"key": "D", "text": "Rene Lalique"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hector Guimard thiết kế các lối vào ga tàu điện ngầm Paris bằng gang (1898-1900), tiêu biểu nhất cho Art Nouveau Pháp. Ruhlmann thuộc Art Deco, René Lalique nổi tiếng với trang sức và thủy tinh.", "key_fact": "Hector Guimard thiết kế lối vào Metro Paris theo phong cách Art Nouveau.", "topic": "Art Nouveau", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-31", "question": "In 1879, which product unleashed a new electric age across the world?", "options": [{"key": "A", "text": "Wireless telegraph"}, {"key": "B", "text": "Improved carbon-button telephone transmitter"}, {"key": "C", "text": "Phonograph"}, {"key": "D", "text": "Incandescent electric lightbulb"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Năm 1879 Edison phát triển bóng đèn sợi đốt thương mại, mở ra thời đại điện trên toàn thế giới. Máy hát (phonograph) ra đời năm 1877, điện báo không dây muộn hơn (Marconi).", "key_fact": "Bóng đèn sợi đốt của Edison (1879) mở ra thời đại điện.", "topic": "Điện khí hóa", "note": "", "comment_answer": "D"}, {"id": "HOD-de3-32", "question": "Among the great reformers during the period of the first industrial revolution, who was early identified the problems that many manufacturers saw design as the decoration of an object, rather than as an integral part of its conception, planning, and realization? (p.113)", "options": [{"key": "A", "text": "Henry Cole"}, {"key": "B", "text": "Joseph Paxton"}, {"key": "C", "text": "Owen Jones"}, {"key": "D", "text": "Augustus Welby Northmore Pugin"}], "answer": ["A"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Henry Cole (cùng Redgrave, Owen Jones) phê phán việc nhà sản xuất coi thiết kế chỉ là trang trí, chủ trương 'trang trí phục vụ công năng' và lập Journal of Design, Felix Summerly's Art Manufactures. Bình luận FUOverflow cũng chọn A. (Nguồn: https://www.metmuseum.org/essays/design-reform)", "key_fact": "Henry Cole: thiết kế phải là phần gắn liền với ý tưởng sản phẩm, không chỉ là trang trí", "topic": "Cải cách thiết kế thế kỷ 19", "note": "", "comment_answer": "A"}, {"id": "HOD-de3-33", "question": "What is the history of design?", "options": [{"key": "A", "text": "The history of objects and their shapes"}, {"key": "B", "text": "History, culture, aesthetic ideology, interest and behaviour in the relationship between people and objects are reflected in the history of culture and civilization from the beginning until the 20th century."}, {"key": "C", "text": "History of scientific and technical developments, mentality, environment..."}, {"key": "D", "text": "All of the above."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Lịch sử thiết kế bao gồm lịch sử đồ vật và hình dáng, mối quan hệ văn hóa – thẩm mỹ giữa con người và đồ vật, cũng như sự phát triển khoa học kỹ thuật, tâm lý, môi trường. Mỗi phương án riêng lẻ chỉ là một khía cạnh nên chọn 'tất cả'.", "key_fact": "Lịch sử thiết kế là lĩnh vực đa chiều: đồ vật, văn hóa, khoa học kỹ thuật.", "topic": "Khái niệm thiết kế", "note": "", "comment_answer": "D"}, {"id": "HOD-de3-34", "question": "In the US, during the 1920s, market saturation appeared. How did manufacturers make it easier for customers to remove old products and buy new ones?", "options": [{"key": "A", "text": "Constantly launching new products combined with headlining advertising."}, {"key": "B", "text": "Manufacturers have constantly launched promotions."}, {"key": "C", "text": "Support for new purchases by credit card."}, {"key": "D", "text": "Attractive promotions."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khi thị trường bão hòa thập niên 1920, nhà sản xuất Mỹ liên tục tung ra mẫu mới kết hợp quảng cáo rầm rộ (lỗi thời có kế hoạch, mẫu xe đổi hằng năm) để khuyến khích khách hàng bỏ đồ cũ mua đồ mới. Thẻ tín dụng chưa phổ biến lúc đó.", "key_fact": "Thập niên 1920: mẫu mới liên tục và quảng cáo tạo ra sự lỗi thời có kế hoạch.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": "A"}]}, {"id": "de4", "name": "Đề 4", "questions": [{"id": "HOD-de4-1", "question": "What is the style of the Teak ice-bucket designed by Jens Quistgaard, 1960?", "options": [{"key": "A", "text": "Good Design"}, {"key": "B", "text": "Italian Design"}, {"key": "C", "text": "Scandinavian Style"}, {"key": "D", "text": "Gute Form"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xô đá gỗ teak của Jens Quistgaard (1960) là ví dụ của phong cách Scandinavia với vật liệu tự nhiên và hình khối mềm mại. Gute Form là thuật ngữ Đức, Italian Design gắn với nhựa và màu sắc táo bạo.", "key_fact": "Xô đá gỗ teak của Quistgaard thuộc phong cách Scandinavia.", "topic": "Thiết kế Scandinavia", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-2", "question": "Art Deco drew its references from: ...", "options": [{"key": "A", "text": "An eclectic range of historic sources, from African tribal art to ancient Egypt."}, {"key": "B", "text": "Influenced by contemporary artistic developments."}, {"key": "C", "text": "Most notably French Cubism and Italian futurism."}, {"key": "D", "text": "All of the above."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Art Deco lấy cảm hứng từ nhiều nguồn lịch sử (nghệ thuật bộ lạc châu Phi, Ai Cập cổ đại) và từ các trào lưu nghệ thuật đương thời như Lập thể Pháp và Vị lai Ý. Vì vậy chọn tất cả.", "key_fact": "Art Deco chiết trung: châu Phi, Ai Cập cổ, Lập thể, Vị lai.", "topic": "Art Deco", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-3", "question": "In the early 1970s, which company began experimenting with cellular radio technology, and its tests went on to revolutionize communication devices? In 1973 the company tested the first \"mobile phone\" in New York?", "options": [{"key": "A", "text": "Sony"}, {"key": "B", "text": "Samsung"}, {"key": "C", "text": "Apple"}, {"key": "D", "text": "Motorola"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Motorola thử nghiệm công nghệ vô tuyến tế bào đầu thập niên 1970 và thực hiện cuộc gọi di động đầu tiên tại New York năm 1973. Apple, Sony, Samsung không liên quan.", "key_fact": "Motorola thử nghiệm điện thoại di động đầu tiên năm 1973.", "topic": "Thiết kế điện tử", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-4", "question": "Fill in the blank\nBy the mid 19th century, industrial progress had come, but at a price, and the resulting social costs seemed to outweigh the social benefits that it brought. In fact, the Industrial Revolution made ...", "options": [{"key": "A", "text": "the century embraced National romanticism"}, {"key": "B", "text": "the finance crisis"}, {"key": "C", "text": "the rich richer and the poor poorer"}, {"key": "D", "text": "about a new forward-looking cultural movement"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Giữa thế kỷ 19, Cách mạng công nghiệp mang lại tiến bộ nhưng với cái giá xã hội lớn: người giàu càng giàu, người nghèo càng nghèo. Điều này thúc đẩy các nhà cải cách như Ruskin, Morris.", "key_fact": "Cách mạng công nghiệp làm người giàu giàu hơn, người nghèo nghèo hơn.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-5", "question": "Like De Stijl, Constructivism had distinctly utopian goals and sought to bring about new social order by introducing a fresh formal language in art and design. Where did \"Constructivism\" movement originate?", "options": [{"key": "A", "text": "Poland."}, {"key": "B", "text": "Italy"}, {"key": "C", "text": "Russia."}, {"key": "D", "text": "Germany."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Constructivism khởi nguồn từ Nga quanh thời cách mạng 1917, với Tatlin, Rodchenko. Ý là quê hương Futurism, Đức là Bauhaus.", "key_fact": "Constructivism bắt nguồn từ Nga.", "topic": "Chủ nghĩa Kiến tạo", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-6", "question": "What kind of technology used by the Romans to mass-produce high volumes of fired ceramic wares, notably oil lamps?", "options": [{"key": "A", "text": "Paddle-and-anvil method."}, {"key": "B", "text": "Molding ."}, {"key": "C", "text": "Standardization."}, {"key": "D", "text": "Interchangeability."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Người La Mã dùng khuôn đúc (molding) để sản xuất hàng loạt đồ gốm nung như đèn dầu. Paddle-and-anvil là kỹ thuật đập tạo hình gốm thủ công, không phải sản xuất số lượng lớn.", "key_fact": "Người La Mã dùng khuôn đúc để sản xuất hàng loạt đèn dầu gốm.", "topic": "Thiết kế cổ đại", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-7", "question": "This picture shows an image of the interior of the Dana Thomas House in Springfield, Illinois, that the architect took an enormous care in the minute detailing of his building, and more than any other individual he bridged the transition between the Arts and Crafts movement and the later International Style through his unified architectural schemes. Who is the architect mentioned above?", "options": [{"key": "A", "text": "Frank Lloyd Wright"}, {"key": "B", "text": "Walter Gropius"}, {"key": "C", "text": "Ludwig Mies Van der Rohe"}, {"key": "D", "text": "Le Corbusier"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Dana Thomas House (Springfield, Illinois) là công trình của Frank Lloyd Wright, người làm cầu nối giữa Arts and Crafts và International Style nhờ các thiết kế kiến trúc tổng thể. Gropius, Mies và Le Corbusier là kiến trúc sư Hiện đại châu Âu.", "key_fact": "Frank Lloyd Wright nối Arts and Crafts với International Style.", "topic": "Arts and Crafts Mỹ", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-8", "question": "What were the design trends with playful design languages attract optimism in the early 1980s?", "options": [{"key": "A", "text": "Art Deco."}, {"key": "B", "text": "Memphis"}, {"key": "C", "text": "Art Nouveau"}, {"key": "D", "text": "Pop Art."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Memphis (thành lập 1981 bởi Ettore Sottsass) mang ngôn ngữ thiết kế vui nhộn, màu sắc rực rỡ, họa tiết táo bạo đầu thập niên 1980. Pop Art là thập niên 1960, Art Deco và Art Nouveau còn sớm hơn.", "key_fact": "Memphis (1981, Sottsass) là trào lưu thiết kế vui nhộn đầu thập niên 1980.", "topic": "Hậu hiện đại", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-9", "question": "What is the other name for these design styles: Art Nouveau, Jugendstil, Vienna Secession, Stile Liberty?", "options": [{"key": "A", "text": "New Art."}, {"key": "B", "text": "Art Decor."}, {"key": "C", "text": "Gothic Revival."}, {"key": "D", "text": "Good Design."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Art Nouveau, Jugendstil, Vienna Secession, Stile Liberty đều là các tên gọi khu vực của 'Nghệ thuật Mới' (New Art) cuối thế kỷ 19. Art Deco là phong cách sau đó, không phải tên gọi khác.", "key_fact": "Art Nouveau và các biến thể đều có nghĩa là 'Nghệ thuật Mới'.", "topic": "Art Nouveau", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-10", "question": "The term \"design\" was derived from the Latin word \"disegno\". When was it first mentioned?", "options": [{"key": "A", "text": "Medieval era"}, {"key": "B", "text": "Renaissance"}, {"key": "C", "text": "Industrial age"}, {"key": "D", "text": "Modern era"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thuật ngữ 'disegno' (vẽ, phác thảo ý tưởng) được dùng trong thời Phục hưng Ý để chỉ ý tưởng sáng tạo đằng sau tác phẩm. Từ đó mới hình thành từ 'design' hiện đại.", "key_fact": "'Disegno' xuất hiện từ thời Phục hưng.", "topic": "Khái niệm thiết kế", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-11", "question": "The first successful flight of Orville and Wilbur Wright in 1903 inaugurated a new era of air travel and globalization. In 1909, they began supplying US Army Model A. What is the biggest role of the Wright brothers designers?", "options": [{"key": "A", "text": "They bring a rapid acceleration to research and development of military equipment."}, {"key": "B", "text": "Through their design approach, taught humans to fly and permanently change their way of ..."}, {"key": "C", "text": "Their design has promoted tourism development worldwide."}, {"key": "D", "text": "They taught people to fly and their design became the basis for developing a series of military aircraft in war."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Anh em nhà Wright với chuyến bay thành công năm 1903 đã dạy con người bay và thay đổi vĩnh viễn lối sống của nhân loại, mở ra kỷ nguyên hàng không và toàn cầu hóa. Phương án D chỉ nhấn vào máy bay quân sự nên hẹp hơn.", "key_fact": "Anh em Wright dạy con người bay, thay đổi vĩnh viễn lối sống.", "topic": "Hàng không", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-12", "question": "Art Nouveau style is considered the most similar to which of the following design styles?", "options": [{"key": "A", "text": "Rococo"}, {"key": "B", "text": "Neo Classicism"}, {"key": "C", "text": "Memphis style"}, {"key": "D", "text": "Biomimicry"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Art Nouveau và Rococo đều dùng đường cong uốn lượn, bất đối xứng và họa tiết lấy cảm hứng từ thiên nhiên (lá, hoa, vỏ sò), nên thường được coi là gần nhau nhất. Tân cổ điển thì đối xứng, nghiêm ngặt; Memphis là Hậu hiện đại; Biomimicry là phương pháp mô phỏng sinh học chứ không phải phong cách trang trí.", "key_fact": "Art Nouveau gần Rococo nhất nhờ đường cong mềm mại và họa tiết thiên nhiên.", "topic": "Art Nouveau", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-13", "question": "This is the B3 \"Wassily\" armchair, designed by Marcel Breuer, 1925. What are the common materials to manufacture this product?", "options": [{"key": "A", "text": "Modern tubular steel and fabric."}, {"key": "B", "text": "Curling iron and fabric."}, {"key": "C", "text": "Modern tubular steel and leather."}, {"key": "D", "text": "Curling iron and leather."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ghế B3 Wassily của Marcel Breuer (Bauhaus, 1925) được làm từ thép ống uốn hiện đại, lấy cảm hứng từ ghi đông xe đạp, kết hợp với dây đai bằng da (phiên bản phổ biến). Dù bản đầu từng dùng vải canvas, chất liệu tiêu biểu được nhắc đến là thép ống và da; 'curling iron' là sai.", "key_fact": "Ghế Wassily (Breuer, 1925) làm từ thép ống uốn và da.", "topic": "Bauhaus", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-14", "question": "Who was the most famous artist in the De Stijl movement?", "options": [{"key": "A", "text": "Andy Warhol."}, {"key": "B", "text": "Piet Mondrian."}, {"key": "C", "text": "Pablo Picasso."}, {"key": "D", "text": "Henry Matisse."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Piet Mondrian là nghệ sĩ tiêu biểu nhất của De Stijl với các tranh lưới đường thẳng đen và màu cơ bản. Andy Warhol thuộc Pop Art, Picasso thuộc Lập thể, Matisse thuộc Dã thú.", "key_fact": "Piet Mondrian là nghệ sĩ nổi tiếng nhất của De Stijl.", "topic": "De Stijl", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-15", "question": "What material had a great impact on human development towards creating civilization?", "options": [{"key": "A", "text": "Concrete"}, {"key": "B", "text": "Bricks"}, {"key": "C", "text": "Steel"}, {"key": "D", "text": "Glass"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Gạch (bùn phơi khô rồi nung) xuất hiện từ thời cổ đại ở Lưỡng Hà, cho phép xây dựng nhà cửa, thành phố lâu dài – nền tảng hình thành văn minh. Bê tông, thép, kính đều là vật liệu phát triển hoặc phổ biến muộn hơn nhiều.", "key_fact": "Gạch là vật liệu then chốt giúp loài người xây dựng nền văn minh đầu tiên.", "topic": "Vật liệu thời cổ đại", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-16", "question": "For a period of roughly eighty years of seismic social and political change - from around 1750 to 1830 - which style was dominant style in art, architecture and design?", "options": [{"key": "A", "text": "Art Deco"}, {"key": "B", "text": "Art Nouveau"}, {"key": "C", "text": "Baroque"}, {"key": "D", "text": "Neoclassicism"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khoảng 1750–1830, thời kỳ Cách mạng Pháp, Cách mạng công nghiệp, Tân cổ điển là phong cách thống trị kiến trúc, nghệ thuật và thiết kế. Baroque sớm hơn (thế kỷ 17), Art Nouveau và Art Deco thuộc cuối thế kỷ 19 – đầu 20.", "key_fact": "Tân cổ điển thống trị khoảng 1750–1830.", "topic": "Tân cổ điển", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-17", "question": "For a period of roughly eighty years of seismic social and political change - from around 1750 to 1830 - which style was dominant style in art, architecture and design?", "options": [{"key": "A", "text": "Art Deco"}, {"key": "B", "text": "Art Nouveau"}, {"key": "C", "text": "Baroque"}, {"key": "D", "text": "Neoclassicism"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khoảng 1750–1830, thời kỳ Cách mạng Pháp, Cách mạng công nghiệp, Tân cổ điển là phong cách thống trị kiến trúc, nghệ thuật và thiết kế. Baroque sớm hơn (thế kỷ 17), Art Nouveau và Art Deco thuộc cuối thế kỷ 19 – đầu 20.", "key_fact": "Tân cổ điển thống trị khoảng 1750–1830.", "topic": "Tân cổ điển", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-18", "question": "Who initiated the Gothic revival movement?", "options": [{"key": "A", "text": "William Morris."}, {"key": "B", "text": "Walter Gropius."}, {"key": "C", "text": "Louis Sullivan."}, {"key": "D", "text": "A. W. N. Pugin."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "A.W.N. Pugin là người khởi xướng Phục hưng Gothic, coi Gothic là phong cách 'thật' về đạo đức và cấu trúc. Morris chịu ảnh hưởng sau đó; Gropius và Sullivan thuộc Hiện đại.", "key_fact": "Pugin khởi xướng phong trào Gothic Revival.", "topic": "Gothic Revival", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-19", "question": "What style has found looking back at the classic past, seeking to reinterpret the classic rules into a graceful modern form?", "options": [{"key": "A", "text": "Classicism."}, {"key": "B", "text": "Romanticism."}, {"key": "C", "text": "Neoclassicism."}, {"key": "D", "text": "Art Decor."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tân cổ điển nhìn lại quá khứ Hy Lạp – La Mã, diễn giải lại các quy tắc cổ điển thành hình thức thanh lịch, hiện đại hơn. 'Classicism' là chính nghệ thuật cổ điển gốc; Lãng mạn đề cao cảm xúc chứ không phải quy tắc cổ điển.", "key_fact": "Tân cổ điển = diễn giải lại quy tắc cổ điển theo hình thức thanh lịch mới.", "topic": "Tân cổ điển", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-20", "question": "What is the name of this architect?", "options": [{"key": "A", "text": "Thomas Chippendale."}, {"key": "B", "text": "Walter Gropius."}, {"key": "C", "text": "A. W. N. Pugin."}, {"key": "D", "text": "Adolf Loos."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ảnh chân dung là Adolf Loos (người đàn ông ria mép, mặc vest, ngồi ghế tựa đầu thế kỷ 20) – kiến trúc sư Áo tác giả 'Ornament and Crime'. Walter Gropius có ngoại hình khác (không ria mép kiểu này, ảnh chân dung thường muộn hơn), còn Chippendale là thợ đồ gỗ thế kỷ 18.", "key_fact": "Adolf Loos – kiến trúc sư Áo, 'Ornament and Crime' (1908).", "topic": "Nhà thiết kế tiêu biểu", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-21", "question": "When did the Pop art movement begin to thrive?", "options": [{"key": "A", "text": "1960s."}, {"key": "B", "text": "1970s."}, {"key": "C", "text": "1980s."}, {"key": "D", "text": "1990s."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Pop Art và Pop design phát triển rực rỡ vào thập niên 1960, đặc biệt ở Anh và Mỹ. Những thập niên sau là thời của Anti-design, Postmodernism, Memphis.", "key_fact": "Pop Art thịnh hành vào thập niên 1960.", "topic": "Pop Art", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-22", "question": "What year witnessed the arrival of the first US radio network, NBC?", "options": [{"key": "A", "text": "1925"}, {"key": "B", "text": "1926"}, {"key": "C", "text": "1927"}, {"key": "D", "text": "1945"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mạng lưới phát thanh đầu tiên của Mỹ, NBC, ra đời năm 1926. Năm 1927 là năm thành lập CBS.", "key_fact": "NBC – mạng phát thanh đầu tiên của Mỹ – ra đời năm 1926.", "topic": "Truyền thông đại chúng", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-23", "question": "Fill in the blank:\nMany designers looked to the future optimistically and created products for a space age in which life would be ..........; the visions they conjured offered a much-needed respite from the Vietnam War and other earthbound troubles.", "options": [{"key": "A", "text": "shiny, clean, and bright"}, {"key": "B", "text": "clean"}, {"key": "C", "text": "clean and bright"}, {"key": "D", "text": "None of the answer"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đoạn văn trong giáo trình viết rằng cuộc sống thời đại vũ trụ sẽ 'shiny, clean and bright' (bóng bẩy, sạch sẽ và tươi sáng). Các đáp án B, C chỉ là phần thiếu của cụm từ gốc.", "key_fact": "Thiết kế 'Space Age' những năm 1960 hình dung cuộc sống bóng bẩy, sạch sẽ và tươi sáng.", "topic": "Thiết kế thời đại vũ trụ", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-24", "question": "Among the Gothic Revival reformers, which of the following preferred a more romantic approach to restoring medieval buildings, which often incorporated a certain amount of creative modification of the original structure?", "options": [{"key": "A", "text": "A. W. N. Pugin"}, {"key": "B", "text": "George Edmund Street"}, {"key": "C", "text": "William Burges"}, {"key": "D", "text": "Emmanuel Viollet-le-Duc"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Viollet-le-Duc nổi tiếng với cách trùng tu công trình trung cổ mang tính lãng mạn, thường tự sáng tạo, bổ sung chi tiết để công trình đạt trạng thái 'hoàn chỉnh lý tưởng' (vd. Notre-Dame, Carcassonne). Pugin thì đề cao sự trung thực, chính xác với nguyên tắc Gothic.", "key_fact": "Viollet-le-Duc trùng tu công trình Gothic theo hướng lãng mạn, có sửa đổi sáng tạo.", "topic": "Phục hưng Gothic", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-25", "question": "In the 1920s, who realized that aesthetics would play an increasingly important role over the differentiating products?", "options": [{"key": "A", "text": "General Motors chairman Alfred Sloan"}, {"key": "B", "text": "Adolf Loos"}, {"key": "C", "text": "William Hogarth"}, {"key": "D", "text": "Henry Cole"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Alfred Sloan, chủ tịch General Motors, nhận ra vào những năm 1920 rằng thẩm mỹ (styling, đổi mẫu hàng năm) sẽ là yếu tố quyết định để phân biệt sản phẩm, đối lập với chiến lược Model T đơn điệu của Ford. Loos, Hogarth, Cole không thuộc bối cảnh này.", "key_fact": "Alfred Sloan (GM) dùng thẩm mỹ để tạo khác biệt sản phẩm từ thập niên 1920.", "topic": "Thiết kế công nghiệp Mỹ", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-26", "question": "What is the role of the Biomimicry design?", "options": [{"key": "A", "text": "The utilitarian approach made sense commercially in a society where middle-class consumers found the stylish, sculptural look too bland rationalism."}, {"key": "B", "text": "Might offer design solutions to all sorts of ecological problems, from the development of s... schemes to the construction of buildings that store carbon emissions."}, {"key": "C", "text": "The design solution is used to recycle scrap to create fashionable and functional artefacts for home and office."}, {"key": "D", "text": "It has promoted the rise of biomorphism, which, rather than attempting to capture the abs... of natural forms, distorted them for purely decorative purposes."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biomimicry (mô phỏng sinh học) học hỏi giải pháp từ tự nhiên để giải quyết các vấn đề sinh thái, như công trình lưu trữ khí carbon. Đáp án D nói về biomorphism (chỉ mô phỏng hình dáng để trang trí), C nói về tái chế phế liệu.", "key_fact": "Biomimicry học từ tự nhiên để giải quyết vấn đề sinh thái.", "topic": "Thiết kế đương đại", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-27", "question": "The humble potter's wheel was the very first machine to have been designed (from 6,000 to 4,000 BC) to enable the more efficient serial production of designed goods - making pot-throwing the earliest manufacturing process. Where did it come from?", "options": [{"key": "A", "text": "Egypt."}, {"key": "B", "text": "Mesopotamia."}, {"key": "C", "text": "Greece."}, {"key": "D", "text": "China."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bàn xoay gốm (potter's wheel) được cho là xuất hiện đầu tiên ở Lưỡng Hà (Mesopotamia) khoảng 6000–4000 TCN. Ai Cập, Hy Lạp, Trung Quốc tiếp nhận và phát triển sau.", "key_fact": "Bàn xoay gốm – cỗ máy đầu tiên – ra đời ở Lưỡng Hà.", "topic": "Thiết kế thời tiền sử", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-28", "question": "What does the Anthropometric design refer to?", "options": [{"key": "A", "text": "Aesthetics and function.."}, {"key": "B", "text": "Functional."}, {"key": "C", "text": "Human factors."}, {"key": "D", "text": "Economic profit."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thiết kế nhân trắc học (anthropometric) dựa trên số đo và đặc điểm cơ thể con người, tức là yếu tố con người (human factors/ergonomics). Các đáp án khác về thẩm mỹ, công năng, lợi nhuận không phải định nghĩa của nó.", "key_fact": "Anthropometric design gắn với yếu tố con người (human factors).", "topic": "Công thái học", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-29", "question": "Among the great reformers during the period of the first industrial revolution, who was early in identifying the problems that many manufacturers saw design as the decoration of an object, rather than as an integral part of its conception, planning, and realization? (p.113)", "options": [{"key": "A", "text": "Henry Cole"}, {"key": "B", "text": "Joseph Paxton"}, {"key": "C", "text": "Owen Jones"}, {"key": "D", "text": "Augustus Welby Northmore Pugin"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Henry Cole là một trong những nhà cải cách sớm chỉ ra rằng các nhà sản xuất coi thiết kế chỉ là trang trí bề mặt chứ không phải một phần của quá trình hình thành sản phẩm; ông lập Journal of Design và tổ chức Đại triển lãm 1851. Pugin cũng phê phán trang trí thừa nhưng chủ yếu từ góc độ Gothic Revival.", "key_fact": "Henry Cole phê phán việc coi thiết kế chỉ là trang trí, thúc đẩy cải cách thiết kế thế kỷ 19.", "topic": "Cải cách thiết kế thế kỷ 19", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-30", "question": "Who was seen as a true Renaissance man or as innovative designer thinker who during his lifetime was admired as much for his work not only in fine art but also his ability to conceptualize revolutionary inventions that helped to raise the status of design practice?", "options": [{"key": "A", "text": "Michelangelo."}, {"key": "B", "text": "Johann Gutenberg."}, {"key": "C", "text": "Leonardo da Vinci."}, {"key": "D", "text": "Hans Vredeman de Vries."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Leonardo da Vinci là 'người Phục hưng' điển hình, vừa là họa sĩ vừa là nhà phát minh với nhiều ý tưởng máy móc mang tính cách mạng, nâng cao vị thế thiết kế. Michelangelo chủ yếu là nghệ sĩ; Gutenberg là nhà phát minh máy in, không nổi tiếng về mỹ thuật.", "key_fact": "Leonardo da Vinci là nhà tư duy thiết kế tiêu biểu thời Phục hưng.", "topic": "Thời Phục hưng", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-31", "question": "What was the purpose of building the Crystal Palace in England in 1851?", "options": [{"key": "A", "text": "Playground of the royal family of England."}, {"key": "B", "text": "The venue for European glassware exhibitions."}, {"key": "C", "text": "The place for the feast of the British nobility."}, {"key": "D", "text": "Serving for international design exhibitions"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Crystal Palace (Joseph Paxton) được xây năm 1851 để làm nơi tổ chức Đại triển lãm (Great Exhibition) – triển lãm quốc tế về sản phẩm công nghiệp và thiết kế. Nó không phải nơi vui chơi hoàng gia hay triển lãm riêng đồ thủy tinh.", "key_fact": "Crystal Palace được xây để tổ chức Đại triển lãm quốc tế 1851.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-32", "question": "Which manufacturer was commissioned to make the colossal entrance gates to the 1851 Great Exhibition that brought the foundry greater international fame?", "options": [{"key": "A", "text": "The Portsmouth Block Mills"}, {"key": "B", "text": "Danhauser Furniture Factory"}, {"key": "C", "text": "Wedgwood"}, {"key": "D", "text": "Coalbrookdale"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xưởng đúc Coalbrookdale đã được giao chế tạo cổng sắt khổng lồ cho Đại triển lãm 1851, giúp xưởng nổi tiếng quốc tế. Wedgwood làm gốm, Portsmouth Block Mills làm ròng rọc, Danhauser làm nội thất ở Vienna.", "key_fact": "Coalbrookdale đúc cổng vào Đại triển lãm 1851.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-33", "question": "In 1981, which Italian designer founded a group of artists and designers called Memphis?", "options": [{"key": "A", "text": "Ettore Sottsass"}, {"key": "B", "text": "Quasar Khanh"}, {"key": "C", "text": "Ralph Nader"}, {"key": "D", "text": "Edgar Kaufmann"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ettore Sottsass sáng lập nhóm Memphis tại Milan năm 1981 – biểu tượng của thiết kế Hậu hiện đại. Ralph Nader là nhà hoạt động bảo vệ người tiêu dùng, Edgar Kaufmann Jr. là giám tuyển MoMA.", "key_fact": "Ettore Sottsass sáng lập nhóm Memphis năm 1981.", "topic": "Hậu hiện đại", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-34", "question": "Fill in the blank:\nThe concept of ............also permeated DANISH production in these years. To this day Denmark, more than any other nation, is associated with high-quality, well-designed products that have timeless appeal.", "options": [{"key": "A", "text": "Organic Design"}, {"key": "B", "text": "Italian Design"}, {"key": "C", "text": "Good Design"}, {"key": "D", "text": "Industrial design"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khái niệm 'Good Design' thời hậu chiến thấm vào sản xuất Đan Mạch, khiến Đan Mạch gắn liền với sản phẩm chất lượng cao, thiết kế tốt, vẻ đẹp vượt thời gian. 'Organic Design' tuy liên quan Scandinavia nhưng câu văn gốc nói về Good Design.", "key_fact": "Đan Mạch gắn với tinh thần 'Good Design' – chất lượng cao, vượt thời gian.", "topic": "Good Design", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-35", "question": "Where was the production of seamless tubular metal pioneered?", "options": [{"key": "A", "text": "Austria"}, {"key": "B", "text": "France"}, {"key": "C", "text": "Germany"}, {"key": "D", "text": "Russia"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Việc sản xuất ống kim loại liền mạch được tiên phong ở Đức (anh em Mannesmann), tạo điều kiện cho đồ nội thất thép ống của Bauhaus như ghế Wassily.", "key_fact": "Ống thép liền mạch được tiên phong tại Đức (Mannesmann).", "topic": "Bauhaus", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-36", "question": "Fill in the blank:\nIn 1906, German Arts and Crafts Exhibition held in Dresden revealed a more formal language of design, placing the greater emphasis on functionality, displacing the emotional and artistic expressiveness of ...", "options": [{"key": "A", "text": "Jugendstil."}, {"key": "B", "text": "Art Nouveau"}, {"key": "C", "text": "Vienna Secession"}, {"key": "D", "text": "Surrealism"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Triển lãm Thủ công Mỹ nghệ Đức tại Dresden 1906 thể hiện ngôn ngữ thiết kế hình thức, đề cao công năng, thay thế tính biểu cảm của Jugendstil – tên gọi Art Nouveau ở Đức. Vì bối cảnh là Đức nên Jugendstil phù hợp hơn Art Nouveau nói chung hay Vienna Secession (Áo).", "key_fact": "Dresden 1906 đánh dấu sự chuyển từ Jugendstil sang thiết kế công năng ở Đức.", "topic": "Deutscher Werkbund", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-37", "question": "In what style was Eero Saarinen's TWA (Trans World Airlines) Terminal (1956-62) at New York's Idlewild Airport (now John F. Kennedy Airport) designed?", "options": [{"key": "A", "text": "Good Design"}, {"key": "B", "text": "None of the answer"}, {"key": "C", "text": "Organic Design"}, {"key": "D", "text": "Italian Design"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhà ga TWA của Eero Saarinen với mái vỏ bê tông cong như cánh chim là ví dụ tiêu biểu của Organic Design. Good Design và Italian Design không mô tả kiến trúc dạng điêu khắc uốn lượn này.", "key_fact": "Nhà ga TWA (Saarinen) là tác phẩm tiêu biểu của Organic Design.", "topic": "Organic Design", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-38", "question": "This picture shows the Queen Marie Antoinette's Golden Room at Château de Versailles designed by Jean Henri Riesener in 1783? What style is it?", "options": [{"key": "A", "text": "Empire."}, {"key": "B", "text": "Neoclassicism"}, {"key": "C", "text": "Art Nouveau."}, {"key": "D", "text": "Art Deco"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Năm 1783 thuộc thời Louis XVI, khi phong cách Tân cổ điển thịnh hành; phòng Gilded Cabinet của Marie Antoinette mang họa tiết cổ điển đối xứng. Empire xuất hiện sau (thời Napoleon), Art Nouveau và Art Deco muộn hơn nhiều.", "key_fact": "Nội thất Marie Antoinette (1783) thuộc phong cách Tân cổ điển.", "topic": "Tân cổ điển", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-39", "question": "Founded in 1861, Morris & Co sought not only to infuse design with art but also to revitalize the craft traditions, which were by now under severe threat from industrialization and mechanized production. What kinds of products were produced by this above firm?", "options": [{"key": "A", "text": "Wallpaper, textiles."}, {"key": "B", "text": "Furniture, interior architectural elements."}, {"key": "C", "text": "Stained glass windows"}, {"key": "D", "text": "All of the above."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Morris & Co sản xuất giấy dán tường, vải dệt, đồ nội thất, các chi tiết kiến trúc nội thất và kính màu. Vì vậy 'tất cả các đáp án trên' là đúng.", "key_fact": "Morris & Co (1861) làm giấy dán tường, vải, nội thất, kính màu.", "topic": "Arts and Crafts", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-40", "question": "In 1949, it was the most famous house (1949) - now better known as the Eames House in Pacific Palisades, the self-designed home of Charles and Ray Eames. What is the name of this house?", "options": [{"key": "A", "text": "Case Study House No. 6"}, {"key": "B", "text": "Case Study House No. 7"}, {"key": "C", "text": "Case Study House No. 8"}, {"key": "D", "text": "Case Study House No. 9"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhà Eames ở Pacific Palisades (1949) chính là Case Study House No. 8 trong chương trình của tạp chí Arts & Architecture. Case Study House No. 9 là nhà Entenza bên cạnh.", "key_fact": "Nhà Eames = Case Study House No. 8.", "topic": "Thiết kế Mỹ thời hậu chiến", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-41", "question": "This picture shows an image of the cover of Ver Sacrum magazine, designed by Koloman Moser, 1899. What style is this?", "options": [{"key": "A", "text": "Jugendstil"}, {"key": "B", "text": "Modernisimo"}, {"key": "C", "text": "Stilo Liberty"}, {"key": "D", "text": "Vienna Secession"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ver Sacrum là tạp chí của nhóm Ly khai Vienna (Vienna Secession), Koloman Moser là thành viên sáng lập. Jugendstil là Art Nouveau Đức, Modernismo ở Tây Ban Nha, Stile Liberty ở Ý.", "key_fact": "Ver Sacrum là tạp chí của Vienna Secession.", "topic": "Vienna Secession", "note": "", "comment_answer": "D"}, {"id": "HOD-de4-42", "question": "What was the goal of the British \"Can Make It\" exhibition in 1946, at the Victoria and Albert Museum?", "options": [{"key": "A", "text": "To establish foreign markets for well-designed British products."}, {"key": "B", "text": "To educate the public about the moral and aesthetic."}, {"key": "C", "text": "To educate the public about the moral and economic benefits of Good Design."}, {"key": "D", "text": "All of the above."}], "answer": ["A", "C"], "multi": true, "confidence": "high", "source": "ai", "explanation": "Triển lãm 'Britain Can Make It' 1946 nhằm mở thị trường nước ngoài cho sản phẩm Anh được thiết kế tốt và giáo dục công chúng về lợi ích đạo đức và kinh tế của Good Design. Đáp án B thiếu/không đúng cụm 'moral and economic'; câu nhiều đáp án nên không chọn 'All of the above'.", "key_fact": "Britain Can Make It (1946): mở thị trường xuất khẩu và giáo dục công chúng về Good Design.", "topic": "Good Design", "note": "", "comment_answer": "A,C"}, {"id": "HOD-de4-43", "question": "Why is Art Nouveau argued as the first modern style?", "options": [{"key": "A", "text": "Throwing off the historicizing, decorative shackles of the past"}, {"key": "B", "text": "Decoration should always be informed by a design's construction rather than applied as superfluous ornamentation"}, {"key": "C", "text": "Logical structure of products, uncompressing logic in the use of materials, proud and frank working process"}, {"key": "D", "text": "All of the above"}], "answer": ["D"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Giống HOD-de3-26: cả ba lý do (rũ bỏ chủ nghĩa lịch sử, trang trí xuất phát từ cấu trúc, logic vật liệu và cấu trúc) được nêu cho Art Nouveau; bình luận FUOverflow đồng thuận D. (Nguồn: https://en.wikipedia.org/wiki/Art_Nouveau ; FUOverflow HOD102)", "key_fact": "Art Nouveau 'phong cách hiện đại đầu tiên': All of the above", "topic": "Art Nouveau", "note": "Đã sửa từ A sang D sau khi tra cứu trên mạng.", "comment_answer": "D"}, {"id": "HOD-de4-44", "question": "In 1959, the Left-leaning Nation magazine published an article named \"The Safe Car You Can't Buy\", the author stated the ethical issues surrounding design, manufacture, consumer protection & safety measures in car design and manufacturing. Who is the author of this article?", "options": [{"key": "A", "text": "Joe Colombo."}, {"key": "B", "text": "Victor Papanek."}, {"key": "C", "text": "Ralph Nader."}, {"key": "D", "text": "Verner Panton."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ralph Nader viết bài 'The Safe Car You Can't Buy' trên tạp chí The Nation năm 1959, sau đó là cuốn 'Unsafe at Any Speed' (1965). Victor Papanek viết 'Design for the Real World', còn Colombo và Panton là nhà thiết kế.", "key_fact": "Ralph Nader viết 'The Safe Car You Can't Buy' (1959).", "topic": "Đạo đức thiết kế", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-45", "question": "What were the two great materials of the First Industrial Revolution in the 18th century?", "options": [{"key": "A", "text": "Iron and steel."}, {"key": "B", "text": "Tubular metal and leather."}, {"key": "C", "text": "Cast iron and steel."}, {"key": "D", "text": "Steel and plastic"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Giáo trình nêu sắt và thép là hai vật liệu lớn của Cách mạng công nghiệp. Thép ống và da gắn với Bauhaus, còn nhựa là vật liệu của thế kỷ 20. Đáp án C (gang và thép) gần đúng nhưng cụm chuẩn là 'iron and steel'.", "key_fact": "Sắt và thép là hai vật liệu chủ đạo của Cách mạng công nghiệp.", "topic": "Cách mạng công nghiệp", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-46", "question": "During World War I, What kind of strategy did Japan use in order to build up an impressively strong industry?", "options": [{"key": "A", "text": "Copy, innovate."}, {"key": "B", "text": "Copy, improve, innovate."}, {"key": "C", "text": "Improve, innovate."}, {"key": "D", "text": "Copy, innovate."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhật Bản xây dựng công nghiệp theo chiến lược 'sao chép, cải tiến, đổi mới' (copy, improve, innovate). Các đáp án A, C, D thiếu bước trong chuỗi ba giai đoạn này.", "key_fact": "Chiến lược của Nhật: sao chép – cải tiến – đổi mới.", "topic": "Thiết kế Nhật Bản", "note": "", "comment_answer": "B"}, {"id": "HOD-de4-47", "question": "The mass-production of weaponry perfected in American factories during the mid-nineteenth century changed the face of military conflict permanently. Which war has been considered as the first instance of industrialized warfare?", "options": [{"key": "A", "text": "American Civil War of 1861-65"}, {"key": "B", "text": "World War I"}, {"key": "C", "text": "World War II"}, {"key": "D", "text": "None of the answer."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nội chiến Mỹ 1861–65 được coi là cuộc chiến tranh công nghiệp hóa đầu tiên, nhờ vũ khí sản xuất hàng loạt bằng linh kiện thay thế được (armory practice). Hai Thế chiến diễn ra muộn hơn.", "key_fact": "Nội chiến Mỹ (1861–65) là chiến tranh công nghiệp hóa đầu tiên.", "topic": "Thiết kế và chiến tranh", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-48", "question": "This is Niels Diffrient's Humanscale 1/2/3 manual, designed by Henry Dreyfuss Associates, 1974. What is the name of the design that applies this manual?", "options": [{"key": "A", "text": "Creative Salvage."}, {"key": "B", "text": "Organic design."}, {"key": "C", "text": "Ergonomics"}, {"key": "D", "text": "Anthropometric."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bộ Humanscale của Niels Diffrient (Henry Dreyfuss Associates, 1974) cung cấp số liệu nhân trắc phục vụ thiết kế công thái học (Ergonomics). 'Anthropometric' chỉ là dữ liệu nhân trắc, không phải tên trường phái thiết kế trong giáo trình.", "key_fact": "Humanscale (1974) là cẩm nang cho thiết kế công thái học.", "topic": "Thiết kế công thái học", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-49", "question": "Fill in the blank\nThe Italian modern design in 1920 and 1930 was the first cultural movement to distance itself from the past and instead glorify the energetic flux of the metropolis. To this end, ........ designers such as Fortunato Depero used fragmented cubistic forms as a means of evoking acceleration and speed.", "options": [{"key": "A", "text": "Futurist"}, {"key": "B", "text": "Art Deco"}, {"key": "C", "text": "Bauhaus"}, {"key": "D", "text": "Rococo"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chủ nghĩa Vị lai (Futurism) Ý tôn vinh tốc độ, máy móc và đô thị, đoạn tuyệt với quá khứ; Fortunato Depero là nhà thiết kế Vị lai. Art Deco, Bauhaus, Rococo không phải phong trào Ý mang đặc điểm này.", "key_fact": "Fortunato Depero là nhà thiết kế theo chủ nghĩa Vị lai Ý.", "topic": "Chủ nghĩa Vị lai", "note": "", "comment_answer": "A"}, {"id": "HOD-de4-50", "question": "Streamlining has the meaning of modernity and speed, that is the symbol of which era?", "options": [{"key": "A", "text": "Age of space."}, {"key": "B", "text": "Plastic age."}, {"key": "C", "text": "Machine age."}, {"key": "D", "text": "The era of popular arts."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Streamlining (khí động học) những năm 1930 tượng trưng cho tốc độ và sự hiện đại của Thời đại máy móc (Machine Age). Thời đại vũ trụ là thập niên 1960, thời đại nhựa sau Thế chiến II.", "key_fact": "Streamlining là biểu tượng của Thời đại máy móc.", "topic": "Streamlining", "note": "", "comment_answer": "C"}, {"id": "HOD-de4-51", "question": "The Pope Manufacturing Company achieved impressive production rates in the late nineteenth century thanks to its adoption of armory practice? Which product was considered as iconic of this American company?", "options": [{"key": "A", "text": "The Type writer"}, {"key": "B", "text": "The Sewing machine"}, {"key": "C", "text": "The Kodak Brownie camera"}, {"key": "D", "text": "The bicycle"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Pope Manufacturing Company nổi tiếng với xe đạp Columbia, sản xuất hàng loạt nhờ áp dụng 'armory practice'. Máy may gắn với Singer, máy ảnh Brownie với Kodak.", "key_fact": "Pope Manufacturing nổi tiếng với xe đạp Columbia.", "topic": "Sản xuất hàng loạt Mỹ", "note": "", "comment_answer": "D"}]}]}, {"id": "IPR", "code": "IPR", "name": "Intellectual Property Rights (đề tiếng Anh)", "note": "Đề gốc không kèm đáp án. Mỗi câu được giải độc lập 2 lần; câu nào lệch nhau hoặc lệch đáp án bình luận FUOverflow thì được phân xử lại (có xem ảnh gốc, tra cứu). Câu đánh dấu ⚠️ là câu vẫn còn chưa chắc chắn.", "sets": [{"id": "de1", "name": "Đề 1", "questions": [{"id": "IPR-de1-1", "question": "What additional copyright exists for a film besides the recording itself?", "options": [{"key": "A", "text": "Only for the actors involved"}, {"key": "B", "text": "In the script and potentially the book on which the script is based"}, {"key": "C", "text": "Only for the producer"}, {"key": "D", "text": "Only for the sound effects"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ngoài bản ghi hình (film) còn có quyền tác giả riêng đối với kịch bản (tác phẩm văn học/kịch) và cả cuốn sách gốc mà kịch bản chuyển thể. Diễn viên chỉ có quyền của người biểu diễn, nhà sản xuất là chủ sở hữu bản ghi film chứ không phải quyền 'bổ sung' duy nhất.", "key_fact": "Một bộ phim chứa nhiều lớp quyền: film, kịch bản, tác phẩm gốc, nhạc phim.", "topic": "Quyền tác giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-2", "question": "In what way can the broad definition of “literary work” create challenges in interdisciplinary engineering projects?", "options": [{"key": "A", "text": "It prevents collaboration with artists"}, {"key": "B", "text": "It increases hardware requirements"}, {"key": "C", "text": "It makes it harder to distinguish between technical documentation and protected creative expression"}, {"key": "D", "text": "Non of the answer is correct"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khái niệm 'literary work' rất rộng, bao gồm cả tài liệu kỹ thuật, bảng biểu, chương trình máy tính. Vì vậy trong dự án liên ngành khó phân biệt đâu là tài liệu kỹ thuật thuần túy và đâu là biểu đạt sáng tạo được bảo hộ. Các phương án khác không liên quan.", "key_fact": "Tác phẩm văn học theo CDPA bao gồm mọi tác phẩm viết, kể cả tài liệu kỹ thuật.", "topic": "Tác phẩm văn học", "note": "", "comment_answer": null}, {"id": "IPR-de1-3", "question": "What does copyright protection for a painting include?", "options": [{"key": "A", "text": "Only the sale of the original painting"}, {"key": "B", "text": "The reproduction, distribution, and public display of the painting"}, {"key": "C", "text": "Only the creation of derivative works"}, {"key": "D", "text": "Only the digital version of the painting"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả với tranh cho chủ sở hữu độc quyền sao chép, phân phối bản sao và trưng bày/truyền đạt công khai. Việc bán bản gốc là quyền sở hữu tài sản vật chất, không phải nội dung của quyền tác giả; các phương án 'chỉ' khác quá hẹp.", "key_fact": "Quyền tác giả là tập hợp nhiều độc quyền: sao chép, phân phối, trình bày công khai...", "topic": "Quyền tác giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-4", "question": "What makes the inclusion of copyright content in a news broadcast legal?", "options": [{"key": "A", "text": "If it's anonymous"}, {"key": "B", "text": "If it reports current events and is incidental"}, {"key": "C", "text": "If it's free-to-air"}, {"key": "D", "text": "If it's broadcast from the UK"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA, việc sử dụng tác phẩm để đưa tin thời sự (fair dealing for reporting current events) hoặc việc đưa vào một cách ngẫu nhiên (incidental inclusion, s.31) là ngoại lệ hợp pháp. Việc phát miễn phí hay phát từ UK không làm hành vi trở nên hợp pháp.", "key_fact": "Đưa tin thời sự và đưa vào ngẫu nhiên là ngoại lệ của quyền tác giả.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-5", "question": "Who traditionally owns the copyright in a sound recording?", "options": [{"key": "A", "text": "The composer of the music"}, {"key": "B", "text": "The person who performs the music"}, {"key": "C", "text": "The person making the arrangements necessary for the recording to be made, typically the producer"}, {"key": "D", "text": "The recording studio"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.9(2)(aa), tác giả (và chủ sở hữu đầu tiên) của bản ghi âm là người thực hiện các sắp xếp cần thiết để bản ghi được tạo ra, thường là nhà sản xuất. Nhà soạn nhạc sở hữu tác phẩm âm nhạc, người biểu diễn chỉ có quyền của người biểu diễn.", "key_fact": "Bản ghi âm thuộc về producer – người sắp xếp việc ghi âm.", "topic": "Bản ghi âm", "note": "", "comment_answer": null}, {"id": "IPR-de1-6", "question": "Copyright protection is available for __________", "options": [{"key": "A", "text": "A single word"}, {"key": "B", "text": "Ideas"}, {"key": "C", "text": "Test method"}, {"key": "D", "text": "A cable programme"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "CDPA 1988 (bản gốc) liệt kê 'cable programme' là một loại tác phẩm được bảo hộ (nay gộp vào broadcast). Một từ đơn lẻ không đủ là tác phẩm, còn ý tưởng và phương pháp thử nghiệm không được bảo hộ quyền tác giả.", "key_fact": "Quyền tác giả bảo hộ biểu đạt, không bảo hộ ý tưởng, phương pháp hay một từ đơn lẻ.", "topic": "Đối tượng quyền tác giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-7", "question": "Does copying only part of a work still count as infringement?", "options": [{"key": "A", "text": "Yes, if it is a substantial part"}, {"key": "B", "text": "No, partial use is free"}, {"key": "C", "text": "Only for images"}, {"key": "D", "text": "Only for songs"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "CDPA s.16(3): hành vi xâm phạm áp dụng cho toàn bộ hoặc một phần đáng kể (substantial part) của tác phẩm; 'đáng kể' được đánh giá theo chất lượng chứ không chỉ số lượng. Dùng một phần không mặc nhiên là tự do.", "key_fact": "Sao chép một phần đáng kể (về chất) vẫn là xâm phạm.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-8", "question": "What does the false attribution right protect against?", "options": [{"key": "A", "text": "Being wrongly credited for a work"}, {"key": "B", "text": "Failure to be paid"}, {"key": "C", "text": "Losing moral rights"}, {"key": "D", "text": "Being excluded from a copyright notice"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền chống ghi sai tên tác giả (false attribution, CDPA s.84) bảo vệ một người khỏi việc bị ghi là tác giả của tác phẩm mà họ không sáng tạo. Nó không liên quan đến thù lao hay thông báo bản quyền.", "key_fact": "False attribution: không ai bị gán tên cho tác phẩm mình không làm.", "topic": "Quyền nhân thân", "note": "", "comment_answer": null}, {"id": "IPR-de1-9", "question": "Can constructing a building from copied plans infringe copyright?", "options": [{"key": "A", "text": "Only if sold"}, {"key": "B", "text": "Yes, both copying and building are infringing acts"}, {"key": "C", "text": "Only if unlicensed"}, {"key": "D", "text": "Only if online"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sao chép bản vẽ và việc xây dựng công trình theo bản vẽ đều là sao chép (chuyển từ 2D sang 3D được coi là sao chép theo CDPA s.17). Việc xâm phạm không phụ thuộc vào bán hay đưa lên mạng.", "key_fact": "Xây nhà theo bản vẽ kiến trúc sao chép = xâm phạm quyền tác giả.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-10", "question": "Why might engineers include copyright markings on their drawings or software?", "options": [{"key": "A", "text": "To improve aesthetics"}, {"key": "B", "text": "To get royalties automatically"}, {"key": "C", "text": "To provide a clear notice of ownership and prevent disputes"}, {"key": "D", "text": "To submit to journals"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ở UK quyền tác giả phát sinh tự động, nhưng dấu © và tên chủ sở hữu giúp thông báo rõ quyền sở hữu, răn đe và làm bằng chứng khi tranh chấp. Nó không tự động tạo ra tiền bản quyền.", "key_fact": "Ký hiệu © không bắt buộc nhưng giúp chứng minh và thông báo quyền sở hữu.", "topic": "Quyền tác giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-11", "question": "What is the main purpose of copyright in computer programs?", "options": [{"key": "A", "text": "To protect the original expression of the program's creator"}, {"key": "B", "text": "To restrict the use of software"}, {"key": "C", "text": "To ensure only licensed software is sold"}, {"key": "D", "text": "To limit the development of similar programs"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chương trình máy tính được bảo hộ như tác phẩm văn học nhằm bảo vệ cách biểu đạt nguyên gốc của người lập trình (mã nguồn/mã máy, thiết kế chuẩn bị). Quyền tác giả không ngăn người khác độc lập viết chương trình có chức năng tương tự.", "key_fact": "Quyền tác giả bảo hộ biểu đạt của chương trình, không bảo hộ chức năng/ý tưởng.", "topic": "Chương trình máy tính", "note": "", "comment_answer": null}, {"id": "IPR-de1-12", "question": "When creating technical documentation that includes diagrams, how can engineers prevent unauthorized reuse?", "options": [{"key": "A", "text": "Publish in print"}, {"key": "B", "text": "Include copyright statements and maintain internal records of authorship"}, {"key": "C", "text": "File the content with HMRC"}, {"key": "D", "text": "Convert diagrams to image format only"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ghi thông báo bản quyền và lưu hồ sơ nội bộ về tác giả, ngày tạo giúp chứng minh quyền sở hữu và tính nguyên gốc khi tranh chấp. HMRC là cơ quan thuế, không đăng ký quyền tác giả; chuyển sang ảnh không ngăn được sao chép.", "key_fact": "Lưu bằng chứng về tác giả và ngày sáng tạo là cách tự bảo vệ quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-13", "question": "How can an engineer's paternity right be waived?", "options": [{"key": "A", "text": "By verbal agreement"}, {"key": "B", "text": "Through a written waiver"}, {"key": "C", "text": "If not asserted"}, {"key": "D", "text": "Automatically after publishing"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.87, quyền nhân thân có thể được từ bỏ bằng văn bản có chữ ký của người có quyền. Việc không 'assert' quyền ghi tên chỉ khiến quyền chưa thể thực thi, không phải là từ bỏ; thỏa thuận miệng không phải cách chuẩn.", "key_fact": "Từ bỏ quyền nhân thân phải bằng văn bản có chữ ký.", "topic": "Quyền nhân thân", "note": "", "comment_answer": null}, {"id": "IPR-de1-14", "question": "Does integrity right need to be asserted in writing?", "options": [{"key": "A", "text": "Yes"}, {"key": "B", "text": "No, it is automatic"}, {"key": "C", "text": "Only for published work"}, {"key": "D", "text": "Only if the author is named"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền bảo vệ sự toàn vẹn (integrity right) phát sinh tự động, không cần khẳng định (assert). Chỉ quyền được ghi tên (paternity right) mới phải được assert bằng văn bản.", "key_fact": "Chỉ paternity right phải assert; integrity right là tự động.", "topic": "Quyền nhân thân", "note": "", "comment_answer": null}, {"id": "IPR-de1-15", "question": "What's one reason why decompiling software is typically not fair dealing?", "options": [{"key": "A", "text": "Because it's technical"}, {"key": "B", "text": "Because it transforms protected code and bypasses licensing"}, {"key": "C", "text": "Because it uses encryption"}, {"key": "D", "text": "Because it's for IT use"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Dịch ngược phần mềm tạo ra bản sao/chuyển đổi mã được bảo hộ và thường vượt qua điều khoản giấy phép, nên không phải fair dealing; CDPA chỉ cho phép dịch ngược trong giới hạn hẹp (s.50B – để đạt tương thích). Tính chất 'kỹ thuật' hay 'dùng cho IT' không phải là lý do.", "key_fact": "Dịch ngược chỉ được phép trong phạm vi hẹp vì mục đích tương thích (s.50B).", "topic": "Chương trình máy tính", "note": "", "comment_answer": null}, {"id": "IPR-de1-16", "question": "If a design was eligible for registration but wasn't registered, what protection still applies?", "options": [{"key": "A", "text": "Patent"}, {"key": "B", "text": "Trade secret"}, {"key": "C", "text": "Design right"}, {"key": "D", "text": "Case law"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thiết kế đủ điều kiện đăng ký nhưng không đăng ký vẫn có thể được bảo hộ bởi quyền kiểu dáng chưa đăng ký (UK design right) phát sinh tự động. Sáng chế và bí mật kinh doanh không tự động bảo hộ thiết kế.", "key_fact": "Kiểu dáng không đăng ký vẫn có UK unregistered design right (10/15 năm).", "topic": "Quyền kiểu dáng", "note": "", "comment_answer": null}, {"id": "IPR-de1-17", "question": "A registered design gives broader protection than design right because:", "options": [{"key": "A", "text": "It's automatic"}, {"key": "B", "text": "It doesn't require proof of copying"}, {"key": "C", "text": "It costs less"}, {"key": "D", "text": "It covers patents too"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiểu dáng đăng ký là độc quyền thực sự (monopoly): xâm phạm không cần chứng minh sao chép, kể cả người tạo độc lập cũng xâm phạm. Design right chỉ chống sao chép. Kiểu dáng đăng ký không tự động và tốn phí hơn.", "key_fact": "Registered design = độc quyền, không cần chứng minh copying.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": null}, {"id": "IPR-de1-18", "question": "Which factor is NOT considered when determining confusion in a passing-off case?", "options": [{"key": "A", "text": "The overall impression the mark or get-up creates"}, {"key": "B", "text": "The similarity of the marks or get-ups"}, {"key": "C", "text": "The financial stability of the competitor's business"}, {"key": "D", "text": "The potential for confusion among consumers"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khi đánh giá nhầm lẫn trong passing off, tòa xem xét ấn tượng tổng thể, sự tương tự của nhãn/get-up và khả năng gây nhầm lẫn cho người tiêu dùng. Tình hình tài chính của đối thủ không liên quan.", "key_fact": "Nhầm lẫn được đánh giá theo ấn tượng tổng thể và nhận thức của công chúng.", "topic": "Passing off", "note": "", "comment_answer": null}, {"id": "IPR-de1-19", "question": "What should a trade mark owner do to maintain the distinctiveness of their mark?", "options": [{"key": "A", "text": "Allow the public to use it freely"}, {"key": "B", "text": "Always use the mark as an adjective, not as a noun or verb"}, {"key": "C", "text": "Limit the use of the mark to advertisements"}, {"key": "D", "text": "Avoid using the mark on packaging"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Để tránh nhãn hiệu trở thành tên chung (generic) và bị hủy, chủ sở hữu nên dùng nhãn như tính từ đi kèm danh từ chung (ví dụ 'Hoover vacuum cleaner'), không dùng làm danh từ hay động từ. Cho công chúng dùng tự do sẽ làm mất tính phân biệt.", "key_fact": "Dùng nhãn hiệu như tính từ để tránh bị 'generic hóa'.", "topic": "Nhãn hiệu", "note": "", "comment_answer": null}, {"id": "IPR-de1-20", "question": "If a trade mark owner receives no response to a letter about infringement, what can they do next?", "options": [{"key": "A", "text": "Take legal action in the High Court"}, {"key": "B", "text": "Stop the legal process and seek advice"}, {"key": "C", "text": "File a complaint with the trade mark registry"}, {"key": "D", "text": "Ignore the infringement as the mark is widely known"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nếu thư cảnh báo (letter before action) không được phản hồi, bước tiếp theo là khởi kiện xâm phạm tại tòa (High Court). Cơ quan đăng ký nhãn hiệu không xử lý xâm phạm, còn bỏ qua sẽ làm suy yếu quyền.", "key_fact": "Không phản hồi thư cảnh báo → khởi kiện tại tòa.", "topic": "Thực thi nhãn hiệu", "note": "", "comment_answer": null}, {"id": "IPR-de1-21", "question": "Can domain name be used as a trade mark?", "options": [{"key": "A", "text": "Yes, provided that the domain name satisfies the requirements to be registered as a trade mark."}, {"key": "B", "text": "Yes, since domain name is a part of company constituting it brands and it is thus a trade mark."}, {"key": "C", "text": "No, these are different concepts without any relevance."}, {"key": "D", "text": "Yes, domain name of a company is its trade mark on the Internet."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tên miền có thể được đăng ký làm nhãn hiệu nếu đáp ứng các điều kiện đăng ký (có tính phân biệt, không mô tả...). Tên miền không mặc nhiên là nhãn hiệu như B, D khẳng định.", "key_fact": "Tên miền chỉ thành nhãn hiệu khi đáp ứng điều kiện đăng ký.", "topic": "Tên miền", "note": "", "comment_answer": null}, {"id": "IPR-de1-22", "question": "What is the function of a logo in terms of trade mark law?", "options": [{"key": "A", "text": "To serve as a visual representation of a product or service, helping to distinguish it from competitors"}, {"key": "B", "text": "To indicate the product's features"}, {"key": "C", "text": "To describe the geographical origin of the product"}, {"key": "D", "text": "To provide a description of the product"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Logo là dấu hiệu hình ảnh giúp phân biệt hàng hóa/dịch vụ của doanh nghiệp này với doanh nghiệp khác – chức năng cốt lõi của nhãn hiệu. Mô tả đặc tính hay nguồn gốc địa lý không phải chức năng của nhãn hiệu.", "key_fact": "Chức năng chính của nhãn hiệu là phân biệt nguồn gốc thương mại.", "topic": "Nhãn hiệu", "note": "", "comment_answer": null}, {"id": "IPR-de1-23", "question": "How does the Anticybersquatting Consumer Protection Act differ from UDRP?", "options": [{"key": "A", "text": "It applies outside the US"}, {"key": "B", "text": "It offers arbitration"}, {"key": "C", "text": "It allows monetary damages and court action"}, {"key": "D", "text": "It is administered by ICANN"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "ACPA là luật liên bang Mỹ cho phép khởi kiện tại tòa và đòi bồi thường tiền (kể cả statutory damages). UDRP là thủ tục hành chính do ICANN áp dụng, chỉ cho phép hủy hoặc chuyển tên miền.", "key_fact": "UDRP chỉ chuyển/hủy tên miền; ACPA cho phép đòi bồi thường tại tòa.", "topic": "Tên miền", "note": "", "comment_answer": null}, {"id": "IPR-de1-24", "question": "What does the court consider when determining whether there has been confusion in a passing-off case?", "options": [{"key": "A", "text": "Whether the two marks are identical"}, {"key": "B", "text": "Whether the public is likely to be misled into thinking the goods or services come from the same source"}, {"key": "C", "text": "Whether the competitor intended to copy the mark"}, {"key": "D", "text": "Whether the marks were registered"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tòa xem xét liệu công chúng có khả năng bị lừa dối, nghĩ rằng hàng hóa/dịch vụ xuất phát từ cùng một nguồn (misrepresentation). Không cần nhãn giống hệt, ý định sao chép không bắt buộc, và passing off bảo vệ cả nhãn chưa đăng ký.", "key_fact": "Passing off: goodwill + misrepresentation gây nhầm lẫn + thiệt hại.", "topic": "Passing off", "note": "", "comment_answer": null}, {"id": "IPR-de1-25", "question": "Under the CTM system, why can an opposition in just one EU member state block an EU-wide registration?", "options": [{"key": "A", "text": "Because CTM applies only to countries that allow such objections"}, {"key": "B", "text": "Because the CTM must be valid across all EU member states"}, {"key": "C", "text": "Because the registry does not examine conflicting marks"}, {"key": "D", "text": "Because all trade mark offices are connected"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu cộng đồng (CTM/EUTM) có tính thống nhất (unitary): có hiệu lực như nhau trên toàn EU, nên một quyền trước ở một nước thành viên có thể ngăn đăng ký trên toàn EU.", "key_fact": "CTM có tính thống nhất – một phản đối có thể chặn toàn EU.", "topic": "Nhãn hiệu", "note": "", "comment_answer": null}, {"id": "IPR-de1-26", "question": "Which of the followings can NOT be a registrable trademark?", "options": [{"key": "A", "text": "A symbol"}, {"key": "B", "text": "A smell"}, {"key": "C", "text": "A single colour"}, {"key": "D", "text": "A generic name of the goods"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tên chung của hàng hóa (generic) không có tính phân biệt nên bị từ chối tuyệt đối (TMA 1994 s.3). Biểu tượng, mùi (nếu biểu thị được) và màu đơn có tính phân biệt đều có thể đăng ký.", "key_fact": "Tên gọi chung của hàng hóa không thể đăng ký nhãn hiệu.", "topic": "Nhãn hiệu", "note": "", "comment_answer": null}, {"id": "IPR-de1-27", "question": "Which of the following is NOT typically a consequence of counterfeiting goods in the UK?", "options": [{"key": "A", "text": "The counterfeit goods are often of inferior quality"}, {"key": "B", "text": "The counterfeit goods are usually sold at a higher price"}, {"key": "C", "text": "The goods may be dangerous or unsafe"}, {"key": "D", "text": "The manufacturer of the genuine product may suffer financial loss"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hàng giả thường được bán với giá rẻ hơn hàng thật, không phải đắt hơn. Chất lượng kém, nguy hiểm và gây thiệt hại tài chính cho nhà sản xuất thật đều là hậu quả điển hình.", "key_fact": "Hàng giả: chất lượng kém, rẻ, có thể nguy hiểm.", "topic": "Hàng giả", "note": "", "comment_answer": null}, {"id": "IPR-de1-28", "question": "What happens if a trade mark is used in a misleading or deceptive way in an advertisement?", "options": [{"key": "A", "text": "It may lead to a legal action for trade mark infringement"}, {"key": "B", "text": "It can help improve brand visibility"}, {"key": "C", "text": "It leads to a fine but no lawsuit"}, {"key": "D", "text": "It is considered fair advertising"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sử dụng nhãn hiệu của người khác trong quảng cáo một cách gây hiểu lầm/lừa dối không được hưởng ngoại lệ quảng cáo so sánh và có thể dẫn đến kiện xâm phạm nhãn hiệu. Đó không phải là quảng cáo công bằng.", "key_fact": "Quảng cáo so sánh gây hiểu lầm có thể xâm phạm nhãn hiệu.", "topic": "Nhãn hiệu", "note": "", "comment_answer": null}, {"id": "IPR-de1-29", "question": "Under UK trade mark law, in which scenario is it legal to use a trade mark that has not been registered?", "options": [{"key": "A", "text": "If the mark has not been used in advertising"}, {"key": "B", "text": "If the mark has been used consistently and built up goodwill"}, {"key": "C", "text": "If the mark is similar to a competitor's mark"}, {"key": "D", "text": "If the mark is used only in foreign countries"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ở UK, nhãn hiệu không đăng ký vẫn được sử dụng hợp pháp và được bảo vệ qua passing off nếu đã được dùng liên tục và tạo dựng goodwill. Dùng nhãn tương tự đối thủ thì có rủi ro bị kiện.", "key_fact": "Nhãn chưa đăng ký được bảo vệ bằng passing off khi có goodwill.", "topic": "Passing off", "note": "", "comment_answer": null}, {"id": "IPR-de1-30", "question": "Which type of mark is \"Apple\" used for computers classified as?", "options": [{"key": "A", "text": "A descriptive mark"}, {"key": "B", "text": "A generic mark"}, {"key": "C", "text": "A word used out of context"}, {"key": "D", "text": "A common noun"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Apple' cho máy tính là một từ thông thường dùng ngoài ngữ cảnh (arbitrary mark), nên có tính phân biệt cao. Nó chỉ là tên chung nếu dùng cho quả táo.", "key_fact": "Từ thông dụng dùng cho hàng không liên quan là nhãn tùy ý, có tính phân biệt cao.", "topic": "Nhãn hiệu", "note": "", "comment_answer": null}, {"id": "IPR-de1-31", "question": "Which of the following best describes a situation where passing-off may occur?", "options": [{"key": "A", "text": "A competitor sells secondhand goods as if they were new"}, {"key": "B", "text": "A competitor uses a similar mark or get-up that causes market confusion"}, {"key": "C", "text": "A competitor changes the product's packaging"}, {"key": "D", "text": "A competitor develops a similar product but with minor design differences"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tình huống điển hình của passing off là đối thủ dùng nhãn hoặc get-up tương tự gây nhầm lẫn trên thị trường. Bán hàng cũ như hàng mới cũng có thể là dạng passing off mở rộng, nhưng B mô tả chính xác nhất; chỉ khác chút về thiết kế không đủ.", "key_fact": "Passing off cốt lõi: nhãn/get-up tương tự gây nhầm lẫn.", "topic": "Passing off", "note": "", "comment_answer": null}, {"id": "IPR-de1-32", "question": "Which of the following could be a valid defence in a passing-off case?", "options": [{"key": "A", "text": "The competitor has used the mark for over 10 years"}, {"key": "B", "text": "The registration of the mark is invalid"}, {"key": "C", "text": "The business owner has not made a passing-off claim"}, {"key": "D", "text": "The competitor has marketed their product with full transparency"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off đòi hỏi có misrepresentation; nếu đối thủ tiếp thị minh bạch, phân biệt rõ nguồn gốc thì không có sự lừa dối nên đây là lý lẽ bào chữa. Tính hiệu lực của đăng ký không liên quan vì passing off không dựa trên đăng ký.", "key_fact": "Không có misrepresentation thì không có passing off.", "topic": "Passing off", "note": "", "comment_answer": null}, {"id": "IPR-de1-33", "question": "Who is the owner of design right?", "options": [{"key": "A", "text": "The engineer's employer, if the engineer produces the design as assigned by his employer"}, {"key": "B", "text": "The engineer who actually creates the design"}, {"key": "C", "text": "The engineer and his employer are co-owners"}, {"key": "D", "text": "None of the options"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.215 (sửa 2014), người thiết kế là chủ sở hữu đầu tiên, trừ khi thiết kế được tạo ra bởi nhân viên trong quá trình làm việc thì chủ sử dụng lao động sở hữu. Kỹ sư làm theo nhiệm vụ được giao nên quyền thuộc về chủ lao động.", "key_fact": "Design right của nhân viên tạo trong công việc thuộc về chủ lao động.", "topic": "Quyền kiểu dáng", "note": "", "comment_answer": null}, {"id": "IPR-de1-34", "question": "A general ignorance of the law was argued by a Copyist in a Design rights's infringement. Which of the following is RIGHT?", "options": [{"key": "A", "text": "The argument would be the copyists was not aware that design rights existed"}, {"key": "B", "text": "The Copyist does not have to know the basics of design right law even when they work professionally in a relevant business area."}, {"key": "C", "text": "Copyists will be assumed to know the basics of design right law especially if they work professionally in a relevant business area."}, {"key": "D", "text": "Both A&B"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Không biết luật không phải là lý do bào chữa; người làm việc chuyên nghiệp trong lĩnh vực liên quan được coi là biết các nguyên tắc cơ bản của luật design right. B ngược lại với nguyên tắc này.", "key_fact": "Không biết luật không phải là lý do bào chữa.", "topic": "Quyền kiểu dáng", "note": "", "comment_answer": null}, {"id": "IPR-de1-35", "question": "Can surface decoration on an article be protected by design right?", "options": [{"key": "A", "text": "No, it is protected by registered designs law, not design right"}, {"key": "B", "text": "Yes, it is protected by design right"}, {"key": "C", "text": "Only if the decoration is new"}, {"key": "D", "text": "Only if the decoration is functional"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "CDPA s.213(3)(c) loại trừ trang trí bề mặt (surface decoration) khỏi design right; trang trí bề mặt được bảo hộ qua kiểu dáng đăng ký (và có thể quyền tác giả). Design right chỉ bảo hộ hình dạng/cấu hình.", "key_fact": "Design right không bảo hộ surface decoration.", "topic": "Quyền kiểu dáng", "note": "", "comment_answer": null}, {"id": "IPR-de1-36", "question": "How can a licensing agreement build long-term relationships across communities?", "options": [{"key": "A", "text": "By hiding technical details"}, {"key": "B", "text": "By including mutual benefits and regular cooperation terms"}, {"key": "C", "text": "By refusing further negotiations"}, {"key": "D", "text": "By limiting all communications"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hợp đồng li-xăng xây dựng quan hệ lâu dài khi có lợi ích hai chiều và điều khoản hợp tác thường xuyên (hỗ trợ kỹ thuật, cải tiến, trao đổi). Che giấu thông tin hay hạn chế liên lạc làm suy giảm lòng tin.", "key_fact": "Li-xăng bền vững dựa trên lợi ích chung và hợp tác.", "topic": "Li-xăng", "note": "", "comment_answer": null}, {"id": "IPR-de1-37", "question": "What can be defined as “fees”?", "options": [{"key": "A", "text": "Post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits)."}, {"key": "B", "text": "A pre-calculated amount paid once or in installments"}, {"key": "C", "text": "Compensation for services and assistance rendered by technical or professional experts."}, {"key": "D", "text": "Dividend or income from related operations: commission paid to licensor for his assistance in selling."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong hợp đồng li-xăng, 'fees' là thù lao cho dịch vụ và hỗ trợ của chuyên gia kỹ thuật. A là royalties (tính theo doanh số/lợi nhuận), B là lump sum (trả trọn gói), D là hoa hồng/lợi tức khác.", "key_fact": "Royalty = theo doanh số; lump sum = trọn gói; fees = phí dịch vụ kỹ thuật.", "topic": "Li-xăng", "note": "", "comment_answer": null}, {"id": "IPR-de1-38", "question": "What is the main purpose of protecting intellectual property rights (IPRs)?", "options": [{"key": "A", "text": "Limiting access to information created by humans."}, {"key": "B", "text": "Encouraging innovation and protecting creators."}, {"key": "C", "text": "Restricting of creations and renovations."}, {"key": "D", "text": "Protecting tangible property."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mục đích chính của bảo hộ quyền SHTT là khuyến khích đổi mới sáng tạo và bảo vệ người sáng tạo bằng độc quyền có thời hạn. SHTT bảo vệ tài sản vô hình, không phải hữu hình.", "key_fact": "SHTT nhằm khuyến khích sáng tạo và bảo vệ người sáng tạo.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": null}, {"id": "IPR-de1-39", "question": "How can an engineer ensure that their innovation is protected internationally?", "options": [{"key": "A", "text": "By using international conventions and treaties such as the Patent Cooperation Treaty"}, {"key": "B", "text": "By only registering the innovation locally"}, {"key": "C", "text": "By waiting for international interest before applying for protection"}, {"key": "D", "text": "By sharing the innovation freely with the public"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền SHTT có tính lãnh thổ, nên cần dùng các điều ước quốc tế như PCT (sáng chế), Madrid, Hague, quyền ưu tiên Paris để bảo hộ ở nhiều nước. Chia sẻ công khai làm mất tính mới; chờ đợi có thể mất quyền.", "key_fact": "Bảo hộ quốc tế qua PCT/Paris/Madrid/Hague vì quyền SHTT có tính lãnh thổ.", "topic": "Điều ước quốc tế", "note": "", "comment_answer": null}, {"id": "IPR-de1-40", "question": "Why is it strategic to pursue a settlement before court action?", "options": [{"key": "A", "text": "The court is slow"}, {"key": "B", "text": "It allows both sides to preserve business cooperation"}, {"key": "C", "text": "It reduces damages"}, {"key": "D", "text": "It improves patent value"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hòa giải trước khi kiện giúp hai bên giữ quan hệ kinh doanh, đồng thời tiết kiệm chi phí và thời gian. Hòa giải không trực tiếp làm giảm bồi thường hay tăng giá trị sáng chế.", "key_fact": "Hòa giải giữ quan hệ hợp tác và tiết kiệm chi phí.", "topic": "Giải quyết tranh chấp", "note": "", "comment_answer": null}, {"id": "IPR-de1-41", "question": "What is a key factor in the court's decision for granting injunctions?", "options": [{"key": "A", "text": "Number of IP rights"}, {"key": "B", "text": "Language used in infringement"}, {"key": "C", "text": "Balance of convenience"}, {"key": "D", "text": "Design value"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khi cấp lệnh cấm tạm thời, tòa áp dụng nguyên tắc American Cyanamid, trong đó yếu tố then chốt là 'balance of convenience' – cân nhắc thiệt hại giữa các bên. Số lượng quyền hay giá trị thiết kế không phải tiêu chí.", "key_fact": "Lệnh cấm tạm thời: có vấn đề nghiêm trọng + balance of convenience.", "topic": "Chế tài", "note": "", "comment_answer": null}, {"id": "IPR-de1-42", "question": "When can account of profits be used as a fair solution in IP disputes?", "options": [{"key": "A", "text": "When no laws apply"}, {"key": "B", "text": "When sales revenue needs to be redirected"}, {"key": "C", "text": "When punishment is needed"}, {"key": "D", "text": "When the court ignores IP"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Account of profits buộc người xâm phạm chuyển giao lợi nhuận thu được từ hành vi xâm phạm cho chủ quyền – phù hợp khi cần chuyển hướng doanh thu bất chính. Đây là chế tài bồi hoàn, không phải trừng phạt.", "key_fact": "Account of profits = trả lại lợi nhuận thu từ xâm phạm, thay cho damages.", "topic": "Chế tài", "note": "", "comment_answer": null}, {"id": "IPR-de1-43", "question": "Which is the most appropriate option below regarding the potential Defendant in a Case on Intellectual Property Rights (IPRs)?", "options": [{"key": "A", "text": "The party (individual or company) that is allegedly using, selling, or reproducing the IP without proper authorization."}, {"key": "B", "text": "The party (individual or company) that is allegedly producing or selling products that infringe on a patent, trademark, or copyright."}, {"key": "C", "text": "The party (individual or company) that is allegedly involving in any action that is claimed to infringe the IP rights such as importing infringing goods or providing services that infringe on protected IP."}, {"key": "D", "text": "All of a;b and c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bị đơn trong vụ SHTT có thể là bất kỳ bên nào bị cáo buộc sử dụng, sản xuất, bán, nhập khẩu hoặc cung cấp dịch vụ xâm phạm quyền SHTT. Cả A, B, C đều mô tả đúng.", "key_fact": "Bị đơn là bất kỳ ai thực hiện hành vi bị cho là xâm phạm.", "topic": "Thực thi quyền", "note": "", "comment_answer": null}, {"id": "IPR-de1-44", "question": "Why is legal patience useful in cross-cultural IP disputes?", "options": [{"key": "A", "text": "It avoids trials"}, {"key": "B", "text": "It gives room for understanding and negotiation"}, {"key": "C", "text": "It speeds up evidence gathering"}, {"key": "D", "text": "It lowers profit"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiên nhẫn trong tranh chấp xuyên văn hóa tạo không gian để hiểu nhau và thương lượng. Nó không đảm bảo tránh xét xử hay đẩy nhanh thu thập chứng cứ.", "key_fact": "Tranh chấp xuyên văn hóa cần thời gian để hiểu và thương lượng.", "topic": "Giải quyết tranh chấp", "note": "", "comment_answer": null}, {"id": "IPR-de1-45", "question": "What is the primary purpose of the Hague Agreement concerning the International Registration of Industrial Designs (1925)?", "options": [{"key": "A", "text": "To establish an international system that allows industrial designs to be protected in multiple countries or regions with minimal formalities."}, {"key": "B", "text": "To regulate the export and import of patented products."}, {"key": "C", "text": "To provide a framework for the recognition of geographical indications."}, {"key": "D", "text": "To establish minimum standards for copyright protection."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thỏa ước La Hay (1925) lập hệ thống đăng ký quốc tế kiểu dáng công nghiệp: một đơn có thể được bảo hộ ở nhiều nước với thủ tục tối thiểu. Bản quyền thuộc Berne, chỉ dẫn địa lý thuộc Lisbon.", "key_fact": "Hague = đăng ký quốc tế kiểu dáng công nghiệp.", "topic": "Điều ước quốc tế", "note": "", "comment_answer": null}, {"id": "IPR-de1-46", "question": "What is TRIPs?", "options": [{"key": "A", "text": "An agreement under the WTO relating to IP"}, {"key": "B", "text": "A law from the EU"}, {"key": "C", "text": "A Vietnamese law"}, {"key": "D", "text": "A form of copyright"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "TRIPS là Hiệp định về các khía cạnh liên quan đến thương mại của quyền SHTT thuộc WTO (1994), đặt tiêu chuẩn tối thiểu. Nó không phải luật EU hay luật Việt Nam.", "key_fact": "TRIPS là hiệp định SHTT của WTO.", "topic": "Điều ước quốc tế", "note": "", "comment_answer": null}, {"id": "IPR-de1-47", "question": "How does the “overall impression” test differ from exact visual copying?", "options": [{"key": "A", "text": "It's based on pricing"}, {"key": "B", "text": "It evaluates similarity in feel rather than exact duplication"}, {"key": "C", "text": "It requires AI tools"}, {"key": "D", "text": "It's only used for packaging"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Phép thử 'ấn tượng tổng thể' đánh giá liệu thiết kế có tạo cảm nhận chung giống nhau với người dùng có hiểu biết, chứ không đòi hỏi sao chép y hệt. Không dựa trên giá hay công cụ AI.", "key_fact": "Kiểu dáng xâm phạm nếu tạo ấn tượng tổng thể không khác với người dùng có hiểu biết.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": null}, {"id": "IPR-de1-48", "question": "Which of the following is incorrect?", "options": [{"key": "A", "text": "To be registrable, a trademark must be represented graphically"}, {"key": "B", "text": "In the UK, sound can be registered as a trade mark by using musical notation."}, {"key": "C", "text": "A device mark must be three-dimensional."}, {"key": "D", "text": "A trade mark can be in the form of a shape or a picture, either alone or combined with a word or words."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Device mark (nhãn hình) có thể là hình vẽ hai chiều, không bắt buộc ba chiều – nên C sai. A (yêu cầu biểu diễn đồ họa theo TMA 1994 gốc), B (âm thanh bằng ký hiệu âm nhạc) và D đều đúng theo tài liệu môn học.", "key_fact": "Nhãn hình có thể là 2D; nhãn 3D là nhãn hình dạng.", "topic": "Nhãn hiệu", "note": "", "comment_answer": null}, {"id": "IPR-de1-49", "question": "A design is known it has been used earlier on furnishing fabrics. Which of the following is RIGHT?", "options": [{"key": "A", "text": "The similar design using for different classes of products such as: Wallpapers, Tablecloths, Carpets, etc. cannot be registered and protected by registered design."}, {"key": "B", "text": "The similar design using for different classes of products such as: Wallpapers, Tablecloths, Carpets, etc. can be registered and protected by registered design."}, {"key": "C", "text": "The similar design using for the same class of product i.e. furnishing fabrics cannot be registered and protected by registered design."}, {"key": "D", "text": "The similar design using for the same class of product i.e. furnishing fabrics can be registered and protected by registered design."}], "answer": ["A"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Theo RDA 1949 s.1B (sau 2001), tính mới được so với mọi kiểu dáng đã bộc lộ công khai, không phụ thuộc loại sản phẩm, nên kiểu dáng đã dùng cho vải nội thất không thể đăng ký cho giấy dán tường, khăn bàn, thảm. C cũng đúng về pháp lý nhưng điểm mấu chốt của ví dụ giáo trình là 'khác loại sản phẩm vẫn mất tính mới' (A). (Nguồn: https://www.legislation.gov.uk/ukpga/Geo6/12-13-14/88/section/1B)", "key_fact": "Tính mới kiểu dáng đăng ký xét trên mọi sản phẩm, không chỉ cùng loại.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": null}, {"id": "IPR-de1-50", "question": "What action can a registered design owner take against a suspected infringer?", "options": [{"key": "A", "text": "Trademark it"}, {"key": "B", "text": "Initiate legal proceedings for infringement"}, {"key": "C", "text": "Cancel their own registration"}, {"key": "D", "text": "Request government compensation"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chủ sở hữu kiểu dáng đăng ký có thể khởi kiện xâm phạm để yêu cầu lệnh cấm, bồi thường hoặc account of profits. Hủy đăng ký của mình hay xin chính phủ bồi thường là vô lý.", "key_fact": "Chủ kiểu dáng đăng ký có quyền khởi kiện xâm phạm.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": null}]}, {"id": "de2", "name": "Đề 2", "questions": [{"id": "IPR-de2-1", "question": "The public domain is referred to:", "options": [{"key": "A", "text": "Addresses in Web"}, {"key": "B", "text": "Any works not protected by copyright"}, {"key": "C", "text": "Public land"}, {"key": "D", "text": "The works protected by copyright"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Public domain (phạm vi công cộng) là các tác phẩm không được (hoặc không còn được) bảo hộ quyền tác giả, ai cũng có thể sử dụng tự do. Không liên quan đến địa chỉ web hay đất công.", "key_fact": "Public domain = tác phẩm không/hết được bảo hộ.", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-2", "question": "What is a \"public performance\" in terms of copyright?", "options": [{"key": "A", "text": "Any performance of a work in a public space"}, {"key": "B", "text": "A private showing of a work"}, {"key": "C", "text": "A limited distribution of a work"}, {"key": "D", "text": "A performance by a professional artist only"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biểu diễn công cộng là biểu diễn tác phẩm ở nơi công cộng hoặc trước công chúng (ngoài phạm vi gia đình). Buổi chiếu riêng tư không phải; không cần nghệ sĩ chuyên nghiệp.", "key_fact": "Biểu diễn trước công chúng ngoài gia đình là public performance.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-3", "question": "What must a work be to qualify for artistic copyright?", "options": [{"key": "A", "text": "Original, not copied from elsewhere"}, {"key": "B", "text": "Registered with an official body"}, {"key": "C", "text": "Of high artistic merit"}, {"key": "D", "text": "Published in an art magazine"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tác phẩm nghệ thuật chỉ cần nguyên gốc (không sao chép, có kỹ năng và lao động của tác giả); CDPA s.4 bảo hộ 'bất kể giá trị nghệ thuật'. Không cần đăng ký hay công bố.", "key_fact": "Tác phẩm nghệ thuật được bảo hộ không phụ thuộc giá trị nghệ thuật.", "topic": "Tác phẩm nghệ thuật", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-4", "question": "In most types of work, how long does copyright last for according to Bern Convention?", "options": [{"key": "A", "text": "10 years after the creation of the work"}, {"key": "B", "text": "50 years after the creation of the work"}, {"key": "C", "text": "10 years after the death of the person who created that work"}, {"key": "D", "text": "50 years after the death of the person who created that work"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Công ước Berne quy định thời hạn tối thiểu là suốt đời tác giả cộng 50 năm sau khi tác giả chết. UK/EU kéo dài lên 70 năm, nhưng câu hỏi hỏi theo Berne.", "key_fact": "Berne: tối thiểu life + 50; UK: life + 70.", "topic": "Thời hạn quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de2-5", "question": "If a work was created by multiple authors, when does the 70-year copyright duration begin?", "options": [{"key": "A", "text": "From the date the work is completed"}, {"key": "B", "text": "From the death of the last surviving author"}, {"key": "C", "text": "From the date of the first publication"}, {"key": "D", "text": "From the date the work is registered"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Với tác phẩm đồng tác giả, thời hạn 70 năm tính từ cuối năm tác giả cuối cùng còn sống qua đời. Không tính từ ngày hoàn thành hay công bố.", "key_fact": "Đồng tác giả: 70 năm từ khi tác giả sống lâu nhất chết.", "topic": "Thời hạn quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-6", "question": "How would you copyright a poem that you have created and sent to a poem contest?", "options": [{"key": "A", "text": "It is protected by copyright once you have written it on paper or any other medium."}, {"key": "B", "text": "You need to receive a Copyright certificate from the Copyright Office in your country."}, {"key": "C", "text": "It is never protected by copyright, because you have let people at the contest read it."}, {"key": "D", "text": "You need to register it with the Copyright Office in your country and in foreign countries."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả phát sinh tự động khi tác phẩm được định hình (viết ra) dưới dạng vật chất, không cần đăng ký (Berne). Cho người khác đọc không làm mất quyền tác giả.", "key_fact": "Quyền tác giả phát sinh tự động, không cần đăng ký.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-7", "question": "Which of the following is considered a 'literary work' under copyright law, relevant to engineering?", "options": [{"key": "A", "text": "Sound recordings"}, {"key": "B", "text": "Engineering reports"}, {"key": "C", "text": "Films"}, {"key": "D", "text": "Broadcasts"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Báo cáo kỹ thuật là tác phẩm viết nên là literary work. Bản ghi âm, phim, chương trình phát sóng là các loại tác phẩm riêng (entrepreneurial works).", "key_fact": "Báo cáo kỹ thuật được bảo hộ là tác phẩm văn học.", "topic": "Tác phẩm văn học", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-8", "question": "Which of the following is incorrect?", "options": [{"key": "A", "text": "Nonfiction information is copyrightable."}, {"key": "B", "text": "The author's intention when making a literary work is irrelevant to its copyrightability."}, {"key": "C", "text": "Short phrases are generally not protected by copyright."}, {"key": "D", "text": "None of the options"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thông tin/sự kiện thực tế (facts) không được bảo hộ quyền tác giả – chỉ cách biểu đạt chúng mới được bảo hộ, nên A là phát biểu sai. B đúng vì ý định của tác giả không quyết định khả năng bảo hộ; C đúng vì cụm từ ngắn thường không được bảo hộ.", "key_fact": "Thông tin, sự kiện không được bảo hộ; chỉ cách trình bày được bảo hộ.", "topic": "Đối tượng quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-9", "question": "How does copyright apply to computer programs?", "options": [{"key": "A", "text": "Only applies to commercial software"}, {"key": "B", "text": "They are protected as literary works under copyright law"}, {"key": "C", "text": "They are not covered by copyright"}, {"key": "D", "text": "Only the source code is protected"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "CDPA s.3(1) coi chương trình máy tính là tác phẩm văn học; bảo hộ cả mã nguồn, mã đối tượng và tài liệu thiết kế chuẩn bị. Không giới hạn ở phần mềm thương mại.", "key_fact": "Chương trình máy tính được bảo hộ như tác phẩm văn học.", "topic": "Chương trình máy tính", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-10", "question": "Which of the following is not a moral right in Vietnamese IP law?", "options": [{"key": "A", "text": "Right to make copies"}, {"key": "B", "text": "Right to attribution"}, {"key": "C", "text": "None of the options"}, {"key": "D", "text": "Right to publish the work"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Luật SHTT Việt Nam (Điều 19), quyền nhân thân gồm đặt tên, đứng tên, công bố, bảo vệ toàn vẹn tác phẩm. Quyền sao chép (Điều 20) là quyền tài sản, nên không phải quyền nhân thân.", "key_fact": "Sao chép là quyền tài sản; công bố là quyền nhân thân (Luật VN).", "topic": "Quyền nhân thân", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-11", "question": "To be protected by copyright, a creative work must be......", "options": [{"key": "A", "text": "Fixed in a tangible medium"}, {"key": "B", "text": "Original"}, {"key": "C", "text": "Both original and fixed in a tangible medium"}, {"key": "D", "text": "Spoken"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Để được bảo hộ, tác phẩm phải nguyên gốc và được định hình dưới dạng vật chất (CDPA yêu cầu literary/dramatic/musical works phải được ghi lại). Lời nói chưa ghi lại thì không được bảo hộ.", "key_fact": "Điều kiện bảo hộ: nguyên gốc + được định hình.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de2-12", "question": "Which of the following is NOT an example of literary work?", "options": [{"key": "A", "text": "A character in a novel"}, {"key": "B", "text": "A novel written by Smith"}, {"key": "C", "text": "An technical report or specification"}, {"key": "D", "text": "None of the options"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Một nhân vật trong tiểu thuyết tự thân không phải là tác phẩm văn học (UK không bảo hộ nhân vật như một tác phẩm riêng). Tiểu thuyết và báo cáo kỹ thuật đều là tác phẩm văn học.", "key_fact": "Nhân vật hư cấu tự thân không phải là tác phẩm văn học ở UK.", "topic": "Tác phẩm văn học", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-13", "question": "Which of the following is protected by copyright?", "options": [{"key": "A", "text": "Idea"}, {"key": "B", "text": "Concept"}, {"key": "C", "text": "Expression"}, {"key": "D", "text": "None of others is correct"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả bảo hộ cách biểu đạt, không bảo hộ ý tưởng hay khái niệm (idea/expression dichotomy).", "key_fact": "Quyền tác giả bảo hộ biểu đạt, không bảo hộ ý tưởng.", "topic": "Đối tượng quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de2-14", "question": "What does copyright protection in sound recordings cover?", "options": [{"key": "A", "text": "Only recordings of music"}, {"key": "B", "text": "Any type of sound recording, including spoken words and noises"}, {"key": "C", "text": "Only digital recordings"}, {"key": "D", "text": "Only films and broadcasts"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bản ghi âm theo CDPA s.5A là bất kỳ bản ghi âm thanh nào, gồm âm nhạc, lời nói, tiếng động, bất kể phương tiện. Không chỉ nhạc hay ghi âm số.", "key_fact": "Mọi loại âm thanh được ghi đều là sound recording.", "topic": "Bản ghi âm", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-15", "question": "Which of the following is a moral right in Vietnamese IP law?", "options": [{"key": "A", "text": "Public communication right"}, {"key": "B", "text": "Right to attribution"}, {"key": "C", "text": "Right to lease"}, {"key": "D", "text": "Right to make copies"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền đứng tên (attribution) là quyền nhân thân theo Điều 19 Luật SHTT VN. Truyền đạt công chúng, cho thuê, sao chép là quyền tài sản (Điều 20).", "key_fact": "Đứng tên, đặt tên, công bố, toàn vẹn = quyền nhân thân.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-16", "question": "What does the legal term \"overlap in Intellectual Property Right (IPR) protection\" mean?", "options": [{"key": "A", "text": "It indicates the simultaneous use of multiple IPR protection mechanisms to protect a single IP."}, {"key": "B", "text": "It refers to the legal conflicts arising when one type of IPR protection are applied to more than one IP."}, {"key": "C", "text": "It implies the expiration of IPR protection, allowing others to use the protected IP freely."}, {"key": "D", "text": "It is about the collaboration among creators/owners to collectively protect their IPRs."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chồng lấn bảo hộ (overlap) nghĩa là một đối tượng SHTT được bảo hộ đồng thời bởi nhiều loại quyền (ví dụ phần mềm: quyền tác giả, sáng chế, bí mật). Không phải xung đột hay hết hạn.", "key_fact": "Overlap = một đối tượng được nhiều loại quyền SHTT bảo hộ cùng lúc.", "topic": "Chồng lấn quyền SHTT", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-17", "question": "Computer program can be simultaneously protected by:", "options": [{"key": "A", "text": "Trade Mark and Registered Design"}, {"key": "B", "text": "Copyright, Patent and Confidential Information"}, {"key": "C", "text": "Design Right, Trade Mark and Copyright"}, {"key": "D", "text": "Trade secret and Trade Mark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chương trình máy tính có thể đồng thời được bảo hộ bởi quyền tác giả (tác phẩm văn học), sáng chế (nếu có hiệu quả kỹ thuật) và thông tin bí mật (mã nguồn). Kiểu dáng/design right không phù hợp với mã chương trình.", "key_fact": "Phần mềm: copyright + patent (hạn chế) + confidential information.", "topic": "Chồng lấn quyền SHTT", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-18", "question": "Get-up includes:", "options": [{"key": "A", "text": "The color of packaging and the type of lettering used on a label"}, {"key": "B", "text": "A slogan used for broadcast or printed advertising"}, {"key": "C", "text": "Visual impression of business premises, such as the style of fascia board and the color of shop fittings"}, {"key": "D", "text": "All are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Get-up là hình thức trình bày tổng thể nhận diện doanh nghiệp: màu bao bì, kiểu chữ trên nhãn, khẩu hiệu quảng cáo, thậm chí phong cách cửa hàng. Theo tài liệu môn học, tất cả đều có thể là get-up được bảo vệ qua passing off.", "key_fact": "Get-up gồm bao bì, kiểu chữ, slogan, phong cách cửa hàng.", "topic": "Passing off", "note": "", "comment_answer": "D"}, {"id": "IPR-de2-19", "question": "Acme Corporation attempted to register a trade mark that was generic and not fanciful, arbitrary, suggestive or descriptive with a secondary meaning. Under these circumstances, Acme has", "options": [{"key": "A", "text": "An excellent case for the registration of a trade mark because generic trade marks, as opposed to fanciful, arbitrary or suggestive trade marks, are capable of being copyrighted."}, {"key": "B", "text": "An excellent case for the registration of a trade mark because all trade marks are capable of being copyrighted."}, {"key": "C", "text": "No case for registration of the trade mark because a trade mark must be fanciful, arbitrary or suggestive to be capable of being copyrighted."}, {"key": "D", "text": "No case for registration of the trade mark because a trade mark must be independent, rather than fanciful, arbitrary or suggestive, to be capable of being copyrighted."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tên chung (generic) không thể đăng ký nhãn hiệu vì không có tính phân biệt; nhãn phải là tự tạo, tùy ý, gợi ý hoặc mô tả đã có ý nghĩa thứ cấp. Đáp án C đúng về kết luận (dù câu hỏi dùng chữ 'copyrighted' không chuẩn).", "key_fact": "Nhãn generic không bao giờ đăng ký được.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de2-20", "question": "Using a trade mark in a different writing style is.........", "options": [{"key": "A", "text": "An infringement of trade mark"}, {"key": "B", "text": "Not a primary infringement of trade mark"}, {"key": "C", "text": "Not a secondary infringement of trade mark"}, {"key": "D", "text": "An infringement of copyright"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Dùng nhãn hiệu với kiểu chữ khác vẫn là dùng dấu hiệu giống hệt hoặc tương tự cho cùng hàng hóa, nên vẫn xâm phạm nhãn hiệu (TMA s.10). Đổi phông chữ không loại trừ nhầm lẫn; đây không phải là vấn đề quyền tác giả.", "key_fact": "Đổi kiểu chữ không giúp tránh xâm phạm nhãn hiệu chữ.", "topic": "Xâm phạm nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-21", "question": "Which of the followings is NOT correct?", "options": [{"key": "A", "text": "The applicant must list goods/services for which the trademarks to be used"}, {"key": "B", "text": "The trademark which is registered in UK is automatically protected in Vietnam"}, {"key": "C", "text": "Under Nice Agreement, goods are divided into 34 classes"}, {"key": "D", "text": "The registration must be renewed by paying fee"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đăng ký nhãn hiệu có tính lãnh thổ: nhãn hiệu đăng ký ở Anh chỉ được bảo hộ tại Anh, muốn bảo hộ ở Việt Nam phải nộp đơn tại VN hoặc qua hệ thống Madrid. Các phương án còn lại đều đúng: phải liệt kê hàng hóa/dịch vụ, Bảng phân loại Nice có 34 nhóm hàng hóa (và 11 nhóm dịch vụ), và phải nộp phí gia hạn.", "key_fact": "Quyền nhãn hiệu mang tính lãnh thổ, không tự động được bảo hộ ở nước khác.", "topic": "Đăng ký nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-22", "question": "What trade marks international system allows anyone with a trade mark registration in one member country to make a single application covering all, or a selected number, of other member countries?", "options": [{"key": "A", "text": "Hauge Agreement"}, {"key": "B", "text": "Madrid Agreement"}, {"key": "C", "text": "Paris Convention"}, {"key": "D", "text": "Berne Convention"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hệ thống Madrid (Thỏa ước/Nghị định thư Madrid) cho phép chủ nhãn hiệu đã đăng ký/nộp đơn ở một nước thành viên nộp một đơn quốc tế chỉ định nhiều nước thành viên. Hague dành cho kiểu dáng công nghiệp, Paris là công ước chung về sở hữu công nghiệp, Berne về quyền tác giả.", "key_fact": "Madrid = đăng ký quốc tế nhãn hiệu; Hague = kiểu dáng.", "topic": "Điều ước quốc tế", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-23", "question": "Which of the followings is correct?", "options": [{"key": "A", "text": "Trade mark must be a word in English"}, {"key": "B", "text": "Trade mark must be an invented word"}, {"key": "C", "text": "Trade mark could be a symbol"}, {"key": "D", "text": "Trade mark must be pronounceable"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu là bất kỳ dấu hiệu nào có thể thể hiện bằng hình thức đồ họa và có khả năng phân biệt, nên có thể là biểu tượng/hình. Nhãn hiệu không bắt buộc phải là từ tiếng Anh, từ tự tạo hay phát âm được.", "key_fact": "Nhãn hiệu có thể là chữ, biểu tượng, hình, hình dạng… miễn có khả năng phân biệt.", "topic": "Khái niệm nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de2-24", "question": "How do you think about this statement: In the UK, a mark can be used in business course without registration?", "options": [{"key": "A", "text": "This is correct. In the UK, a mark can be used without registering although it is recommended that registration is always needed for enjoying protection."}, {"key": "B", "text": "This is not correct. Once being used, a trade mark has already been registered."}, {"key": "C", "text": "This is not correct. Trade mark must be registered before using in the course of trade"}, {"key": "D", "text": "None of the statements are correct."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ở Anh, nhãn hiệu có thể được sử dụng mà không cần đăng ký và vẫn có thể được bảo vệ qua passing off nếu tạo được goodwill; tuy nhiên đăng ký được khuyến nghị để có quyền mạnh và dễ thực thi hơn. Việc sử dụng không làm nhãn hiệu tự động được đăng ký, và luật không bắt buộc đăng ký trước khi dùng.", "key_fact": "Ở Anh được dùng nhãn hiệu chưa đăng ký; bảo vệ bằng passing off.", "topic": "Nhãn hiệu chưa đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-25", "question": "Domain names are registered by the principle of", "options": [{"key": "A", "text": "Peer-reviewed"}, {"key": "B", "text": "censorship"}, {"key": "C", "text": "Resources restriction"}, {"key": "D", "text": "first-come first-served"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tên miền được cấp theo nguyên tắc ai đăng ký trước thì được trước (first-come, first-served). Không có thẩm định nội dung hay kiểm duyệt khi đăng ký tên miền.", "key_fact": "Tên miền: first-come, first-served.", "topic": "Tên miền", "note": "", "comment_answer": "D"}, {"id": "IPR-de2-26", "question": "Who can handle the trade mark registration?", "options": [{"key": "A", "text": "A professional trade mark agent"}, {"key": "B", "text": "Anyone"}, {"key": "C", "text": "The judge in the court"}, {"key": "D", "text": "The AI"}], "answer": ["A"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Về pháp lý ở Anh người nộp đơn có thể tự nộp, nhưng giáo trình (Irish) nêu việc đăng ký nhãn hiệu thường do đại diện nhãn hiệu chuyên nghiệp xử lý vì quen thủ tục (tương tự câu de7-50 với patent attorney cho kiểu dáng). Không tìm thấy đáp án công khai; giữ A theo hướng giáo trình, B là phương án dự phòng. (Nguồn: https://www.gov.uk/how-to-register-a-trade-mark)", "key_fact": "Đăng ký nhãn hiệu: nên do trade mark agent/attorney chuyên nghiệp xử lý.", "topic": "Đăng ký nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-27", "question": "In the UK trade mark law, when is \"goodwill\" generated by the use of the mark?", "options": [{"key": "A", "text": "When the mark could have been registered but the owner decided not to register it"}, {"key": "B", "text": "When the mark is unregistrable because it does not meet the requirements of the Trade Marks Act 1994"}, {"key": "C", "text": "A and B are correct"}, {"key": "D", "text": "A and B are incorrect"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Goodwill phát sinh từ việc sử dụng thực tế nhãn hiệu trong thương mại, bất kể nhãn hiệu có thể đăng ký nhưng chủ không đăng ký, hay không thể đăng ký vì không đáp ứng TMA 1994. Goodwill này được bảo vệ bằng passing off trong cả hai trường hợp.", "key_fact": "Goodwill sinh ra từ việc sử dụng, không phụ thuộc vào đăng ký.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de2-28", "question": "What does trade libel means?", "options": [{"key": "A", "text": "Misleading advertisements and false indications of the origin of goods and services"}, {"key": "B", "text": "The original information about the quality of products or services"}, {"key": "C", "text": "An injunction against counterfeit"}, {"key": "D", "text": "A piece of information identified the products or services on mass communication"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trade libel (malicious falsehood) liên quan đến việc đưa ra tuyên bố sai lệch gây hại cho hàng hóa/dịch vụ, gắn với quảng cáo gây nhầm lẫn và chỉ dẫn sai về nguồn gốc. Các phương án khác mô tả thông tin đúng, lệnh cấm hoặc thông tin trên truyền thông, không phải trade libel.", "key_fact": "Trade libel = tuyên bố sai/gây nhầm lẫn làm tổn hại hàng hóa, dịch vụ của người khác.", "topic": "Cạnh tranh không lành mạnh", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-29", "question": "When a trade mark has become representative of a broad type of products as opposed to being descriptive of a particular brand, the trade mark has become ..... and the holder has lost the right to enforce the mark against competitors.", "options": [{"key": "A", "text": "Limited"}, {"key": "B", "text": "Authentic"}, {"key": "C", "text": "Original"}, {"key": "D", "text": "Generic"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khi nhãn hiệu trở thành tên gọi chung cho cả một loại sản phẩm (ví dụ 'escalator', 'aspirin') thì đã bị 'generic hóa' và chủ sở hữu mất quyền ngăn cấm đối thủ (có thể bị hủy bỏ theo s.46 TMA 1994). Các từ còn lại không phải thuật ngữ pháp lý này.", "key_fact": "Nhãn hiệu trở thành tên gọi chung (generic) có thể bị hủy bỏ.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de2-30", "question": "What is the best definition about \"passing-off\"?", "options": [{"key": "A", "text": "The use of identical or similar marks or get-ups to cause confusion in the public by relying on the reputation of a mark or get-up, which has already been used long enough."}, {"key": "B", "text": "The use of different mark by relying on the reputation of a mark or get-up, which has been used long enough. However, this use is not caused any confusion."}, {"key": "C", "text": "The use of distinctive marks or get-ups to cause confusion in the public"}, {"key": "D", "text": "A trade mark infringement"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off là việc sử dụng nhãn hiệu/bao bì (get-up) giống hoặc tương tự, lợi dụng uy tín (goodwill) đã được xây dựng, gây nhầm lẫn cho công chúng và gây thiệt hại. B sai vì passing off đòi hỏi có nhầm lẫn (misrepresentation); D sai vì passing off là tort theo common law, không phải xâm phạm nhãn hiệu đăng ký.", "key_fact": "Passing off = goodwill + misrepresentation (nhầm lẫn) + thiệt hại.", "topic": "Passing off", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-31", "question": "What is an invented word that used as a trade mark?", "options": [{"key": "A", "text": "A word which has been made up specially for use as a trade and has no meaning in the English language"}, {"key": "B", "text": "A word which is commonly used in specific context"}, {"key": "C", "text": "Any word with meaning is invented word"}, {"key": "D", "text": "A word which is used out of it context"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Từ tự tạo (invented word) là từ được tạo ra riêng để làm nhãn hiệu, không có nghĩa trong tiếng Anh (ví dụ Kodak). D mô tả 'từ dùng ngoài ngữ cảnh' (như Apple cho máy tính), là loại khác.", "key_fact": "Invented word: từ bịa ra, không có nghĩa, có tính phân biệt cao.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-32", "question": "How did the House of Lords rule in the case of British Leyland vs. Armstrong Patents Company Limited regarding car exhaust systems?", "options": [{"key": "A", "text": "They ruled that copyright could not be used to prevent car repairs at a reasonable price"}, {"key": "B", "text": "They upheld British Leyland's copyright claim"}, {"key": "C", "text": "They ruled in favor of Armstrong's copyright"}, {"key": "D", "text": "They decided that the exhaust system design was public domain"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong British Leyland v Armstrong (1986), House of Lords cho rằng British Leyland không thể dùng quyền tác giả đối với bản vẽ để ngăn bên thứ ba sản xuất phụ tùng thay thế (ống xả), vì người mua xe có quyền sửa chữa xe với giá hợp lý ('spare parts exception'). Án lệ này dẫn đến việc thiết lập design right và ngoại lệ must fit/must match trong CDPA 1988.", "key_fact": "British Leyland: quyền tác giả không được dùng để cản trở sửa chữa/phụ tùng thay thế.", "topic": "Án lệ kiểu dáng", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-33", "question": "Can a method of construction be protected by design right?", "options": [{"key": "A", "text": "Yes, always"}, {"key": "B", "text": "No, methods of construction are excluded from design right protection"}, {"key": "C", "text": "Only if it is innovative"}, {"key": "D", "text": "Only if it is registered"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s.213(3)(a) CDPA 1988, design right không bảo hộ phương pháp hoặc nguyên lý chế tạo (method or principle of construction). Các điều kiện 'innovative' hay 'registered' không liên quan.", "key_fact": "Design right loại trừ method or principle of construction.", "topic": "Quyền kiểu dáng chưa đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-34", "question": "In a case on Design rights dispute, if the design right owner succeeds in proving the infringement, what cannot the Court award?", "options": [{"key": "A", "text": "An injunction to stop further manufacture or import"}, {"key": "B", "text": "An arrest warrant for the infringer"}, {"key": "C", "text": "Order payment of damages (e.g. for loss of sales by the design right owner)"}, {"key": "D", "text": "The destruction of the offending articles produced during the previous 6 years or handing them over to the design right owner"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện pháp dân sự cho xâm phạm design right gồm lệnh cấm (injunction), bồi thường thiệt hại/giao nộp lợi nhuận, và giao nộp/tiêu hủy hàng xâm phạm. Lệnh bắt giữ (arrest warrant) là biện pháp hình sự, tòa không áp dụng trong vụ kiện dân sự về design right.", "key_fact": "Xâm phạm design right chỉ có chế tài dân sự, không có lệnh bắt.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-35", "question": "The assignment and licensing agreement shall be registered by the competent authority as required by law. Is this statement correct?", "options": [{"key": "A", "text": "No. Only the licensing is needed"}, {"key": "B", "text": "Yes. They can be registered upon the requirement of the law"}, {"key": "C", "text": "No. Only the assignment agreement is needed"}, {"key": "D", "text": "No. They can never be registered"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hợp đồng chuyển nhượng và hợp đồng li-xăng có thể/phải được đăng ký với cơ quan có thẩm quyền khi pháp luật yêu cầu (ví dụ chuyển nhượng quyền sở hữu công nghiệp đã đăng ký). Các phương án chỉ một loại hoặc không bao giờ đăng ký đều sai.", "key_fact": "Chuyển nhượng và li-xăng được đăng ký khi pháp luật yêu cầu.", "topic": "Chuyển giao quyền SHTT", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-36", "question": "What is an IPRs (Intellectual Property Rights) Know-how Contract?", "options": [{"key": "A", "text": "A legal agreement in which the owner of an intellectual property (IP) share specific knowledge, techniques, processes, or expertise to another party (other parties) for a particular purpose, typically in business, manufacturing, or technology."}, {"key": "B", "text": "A legal contract in which the owner of an intellectual property (IP) grants permission to another party (other parties) to use that IP under defined conditions."}, {"key": "C", "text": "A legal contract on transferring of ownership of IP from the assignor to the assignee."}, {"key": "D", "text": "Both of b&c"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hợp đồng know-how là thỏa thuận chủ sở hữu chia sẻ kiến thức, kỹ thuật, quy trình, kinh nghiệm chuyên môn cho bên khác vì mục đích kinh doanh/sản xuất. B mô tả hợp đồng li-xăng, C mô tả hợp đồng chuyển nhượng.", "key_fact": "Know-how = chuyển giao bí quyết, kỹ thuật, kinh nghiệm.", "topic": "Chuyển giao quyền SHTT", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-37", "question": "A triangle eyeglasses box can be protected by..........", "options": [{"key": "A", "text": "Design rights"}, {"key": "B", "text": "Copyright"}, {"key": "C", "text": "Patent"}, {"key": "D", "text": "Trademark"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hình dạng tam giác của hộp kính là đặc điểm hình dáng/cấu hình bên ngoài của sản phẩm, đối tượng của quyền kiểu dáng (design right/registered design). Hình dạng này không phải giải pháp kỹ thuật để được cấp patent, cũng không phải tác phẩm nghệ thuật điển hình để bảo hộ bằng quyền tác giả.", "key_fact": "Hình dạng, cấu hình sản phẩm được bảo hộ bằng quyền kiểu dáng.", "topic": "Kiểu dáng", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-38", "question": "Which of the following is NOT a type of Intellectual Property Right (IPR)?", "options": [{"key": "A", "text": "Patent"}, {"key": "B", "text": "Copyright"}, {"key": "C", "text": "Trademark"}, {"key": "D", "text": "Real Estate Ownership"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền sở hữu bất động sản là quyền tài sản hữu hình, không phải quyền sở hữu trí tuệ. Patent, quyền tác giả, nhãn hiệu đều là quyền SHTT.", "key_fact": "SHTT bảo hộ sản phẩm trí tuệ vô hình, không phải bất động sản.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de2-39", "question": "What are Civil remedies?", "options": [{"key": "A", "text": "Provisional measures, Injunction, imprisonment"}, {"key": "B", "text": "Delivery-up, Compensatory damages, Punitive damages; and Account of profits"}, {"key": "C", "text": "Imprisonment, Punitive damages; and Account of profits"}, {"key": "D", "text": "Delivery-up, Imprisonment, Compensatory damages"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện pháp dân sự gồm giao nộp hàng (delivery-up), bồi thường thiệt hại, bồi thường mang tính trừng phạt (additional damages) và giao nộp lợi nhuận (account of profits). Phạt tù (imprisonment) là chế tài hình sự nên các phương án A, C, D sai.", "key_fact": "Phạt tù là hình sự; delivery-up, damages, account of profits là dân sự.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-40", "question": "To be granted a provisional measure order, the applicant must", "options": [{"key": "A", "text": "Provide any reasonable evidence to prove that he/she is the right holder of copyright"}, {"key": "B", "text": "Provide any reasonable evidence to prove that his/her rights are being infringed or that such infringement is imminent."}, {"key": "C", "text": "Provide security"}, {"key": "D", "text": "All of others are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Để được áp dụng biện pháp khẩn cấp tạm thời, người yêu cầu phải chứng minh mình là chủ thể quyền, chứng minh quyền đang bị xâm phạm hoặc sắp bị xâm phạm, và nộp khoản bảo đảm (security) (TRIPS Điều 50; Luật SHTT VN Điều 207-208). Vì vậy tất cả các phương án đều đúng.", "key_fact": "Biện pháp khẩn cấp tạm thời: chứng minh quyền + xâm phạm/nguy cơ + nộp bảo đảm.", "topic": "Thực thi quyền SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de2-41", "question": "According to UK laws, which is not the types of IP case that the Patent Court (belonging to the Chancery Division of the High Court) hears?", "options": [{"key": "A", "text": "Cases relating to Registered designs and Design rights."}, {"key": "B", "text": "Cases relating to the theft of artworks."}, {"key": "C", "text": "Cases relating to Patent."}, {"key": "D", "text": "Cases relating to Trade marks, Passing-off and Copyright."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Patents Court thuộc Chancery Division xử các vụ về sáng chế, kiểu dáng đăng ký, design right, và cả nhãn hiệu, passing off, quyền tác giả liên quan kỹ thuật. Trộm cắp tác phẩm nghệ thuật là vụ án hình sự về tài sản, không thuộc thẩm quyền của Patents Court.", "key_fact": "Trộm tác phẩm nghệ thuật là hình sự, không phải vụ SHTT ở Patents Court.", "topic": "Tòa án SHTT Anh", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-42", "question": "Who must prove primary infringement?", "options": [{"key": "A", "text": "The right owner"}, {"key": "B", "text": "The licensee"}, {"key": "C", "text": "The infringer"}, {"key": "D", "text": "Police"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong vụ kiện xâm phạm, nghĩa vụ chứng minh thuộc về nguyên đơn – chủ sở hữu quyền – phải chứng minh hành vi xâm phạm trực tiếp (ví dụ sao chép). Bị đơn không phải chứng minh mình xâm phạm; cảnh sát chỉ tham gia trong vụ hình sự.", "key_fact": "Chủ sở hữu quyền phải chứng minh hành vi xâm phạm trực tiếp.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-43", "question": "Agreement on Trade-Related Aspects of Intellectual Property Rights (TRIPS) is an international agreement that ..... for all World Trade Organization members.", "options": [{"key": "A", "text": "Sets maximum standards for protection of intellectual property"}, {"key": "B", "text": "Sets minimum standards for intellectual property protection"}, {"key": "C", "text": "Regulates average standards for protection of intellectual property"}, {"key": "D", "text": "Sets basic limitations for intellectual property protection"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "TRIPS đặt ra tiêu chuẩn tối thiểu về bảo hộ SHTT mà mọi thành viên WTO phải tuân thủ; các nước có thể bảo hộ cao hơn. Không phải tiêu chuẩn tối đa hay trung bình.", "key_fact": "TRIPS = tiêu chuẩn tối thiểu cho thành viên WTO.", "topic": "Điều ước quốc tế", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-44", "question": "Which convention primarily deals with the protection of industrial property such as patents and trademarks?", "options": [{"key": "A", "text": "Berne Convention"}, {"key": "B", "text": "Paris Convention"}, {"key": "C", "text": "Rome Convention"}, {"key": "D", "text": "Geneva Convention"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Công ước Paris 1883 bảo hộ sở hữu công nghiệp (sáng chế, nhãn hiệu, kiểu dáng...). Berne về quyền tác giả, Rome về quyền liên quan, Geneva về luật nhân đạo.", "key_fact": "Paris = sở hữu công nghiệp; Berne = quyền tác giả.", "topic": "Điều ước quốc tế", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-45", "question": "What is the primary Law in the area of intellectual property in Vietnam?", "options": [{"key": "A", "text": "Vietnam Copyright Law"}, {"key": "B", "text": "Vietnam Trademark Law"}, {"key": "C", "text": "Vietnam Intellectual Property Law 2005 (amended and supplemented in 2009, 2019 and 2022)."}, {"key": "D", "text": "Vietnam Industrial Design Law"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Luật Sở hữu trí tuệ 2005 (sửa đổi, bổ sung 2009, 2019, 2022) là đạo luật chính điều chỉnh mọi đối tượng SHTT ở Việt Nam. Việt Nam không có các luật riêng về quyền tác giả, nhãn hiệu, kiểu dáng như các phương án khác.", "key_fact": "VN: Luật SHTT 2005, sửa đổi 2009, 2019, 2022.", "topic": "Luật SHTT Việt Nam", "note": "", "comment_answer": "C"}, {"id": "IPR-de2-46", "question": "________ indicate that the user of the mark is a member of a trade association which owns the mark.", "options": [{"key": "A", "text": "Certification trade marks"}, {"key": "B", "text": "Generic marks"}, {"key": "C", "text": "Unregistered trade marks"}, {"key": "D", "text": "Collective trade marks"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu tập thể (collective mark) cho biết người sử dụng là thành viên của hiệp hội sở hữu nhãn hiệu đó. Nhãn hiệu chứng nhận (certification mark) chứng nhận tiêu chuẩn chất lượng, nguồn gốc..., không phải tư cách thành viên.", "key_fact": "Collective mark = thành viên hiệp hội; certification mark = chứng nhận tiêu chuẩn.", "topic": "Loại nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de2-47", "question": "Get-up includes ________", "options": [{"key": "A", "text": "the type of lettering used on a label"}, {"key": "B", "text": "the colour of packaging"}, {"key": "C", "text": "internal parts of a product that can not be seen in normal use"}, {"key": "D", "text": "visual impression of business premises"}], "answer": ["A", "B", "D"], "multi": true, "confidence": "high", "source": "ai", "explanation": "Get-up là hình thức trình bày bên ngoài của sản phẩm/doanh nghiệp: kiểu chữ trên nhãn, màu sắc bao bì, và cả ấn tượng thị giác của cơ sở kinh doanh (cửa hàng). Các bộ phận bên trong không nhìn thấy khi sử dụng thông thường không tạo nên hình ảnh nhận diện nên không thuộc get-up.", "key_fact": "Get-up = vẻ ngoài nhìn thấy được (nhãn, màu bao bì, cửa hàng).", "topic": "Passing off", "note": "", "comment_answer": "A,B,D"}, {"id": "IPR-de2-48", "question": "Which statement best describe the owner of a registered design?", "options": [{"key": "A", "text": "A person who actually creates a registered design"}, {"key": "B", "text": "The company placing the commission"}, {"key": "C", "text": "The manager of the technical team of a company"}, {"key": "D", "text": "A person who contributes the idea"}], "answer": ["B"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "RDA 1949 s.2(1A) (hiệu lực đến 1/10/2014, tức thời điểm của giáo trình) quy định kiểu dáng tạo ra theo đơn đặt hàng có trả tiền thì bên đặt hàng là chủ sở hữu ban đầu. Quy định này bị Intellectual Property Act 2014 s.6 bãi bỏ, nhưng đề (và câu de6-29 Kevin/Company X) theo luật cũ. (Nguồn: https://www.legislation.gov.uk/ukpga/2014/18/section/6 ; https://www.legislation.gov.uk/ukpga/Geo6/12-13-14/88/section/2)", "key_fact": "Luật cũ (trước 10/2014): bên đặt hàng (commissioner) sở hữu kiểu dáng đăng ký.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de2-49", "question": "What is the advantage of the community right?", "options": [{"key": "A", "text": "Community right has the same effect in all EU countries, and that for the registration system there need be only one application."}, {"key": "B", "text": "The community right does not have any advantage"}, {"key": "C", "text": "Community right has the different effect in all EU countries, so in some countries it can have longer protecting duration"}, {"key": "D", "text": "Community right has the same effect in all EU countries but in some special circumstances it can have longer protecting duration"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền Cộng đồng (EU) có hiệu lực thống nhất ở tất cả các nước EU và chỉ cần một đơn đăng ký duy nhất. Hiệu lực không khác nhau giữa các nước nên C, D sai.", "key_fact": "Quyền Cộng đồng: một đơn, hiệu lực thống nhất toàn EU.", "topic": "Kiểu dáng/Nhãn hiệu EU", "note": "", "comment_answer": "A"}, {"id": "IPR-de2-50", "question": "The term \"Apple\" can NOT be a trade mark of.......", "options": [{"key": "A", "text": "Any business"}, {"key": "B", "text": "Any business selling apples"}, {"key": "C", "text": "Any business selling smartphones"}, {"key": "D", "text": "Any business selling computers"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Apple' cho doanh nghiệp bán táo là tên gọi chung/mô tả hàng hóa nên không có khả năng phân biệt, không thể đăng ký làm nhãn hiệu. Với điện thoại, máy tính thì 'Apple' là từ dùng ngoài ngữ cảnh nên có tính phân biệt.", "key_fact": "Tên gọi chung của chính sản phẩm không thể làm nhãn hiệu.", "topic": "Khả năng phân biệt", "note": "", "comment_answer": "B"}]}, {"id": "de3", "name": "Đề 3", "questions": [{"id": "IPR-de3-1", "question": "According to the UK's law, copyright for a novel, which is written by a novelist, in 2011, lasts for ________", "options": [{"key": "A", "text": "The novelist's life plus 70 years"}, {"key": "B", "text": "The novelist's life plus 50 years"}, {"key": "C", "text": "20 years"}, {"key": "D", "text": "The novelist's life"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA 1988 s.12, quyền tác giả đối với tác phẩm văn học kéo dài suốt đời tác giả cộng 70 năm tính từ cuối năm tác giả mất. 50 năm là thời hạn theo Berne/Việt Nam, không phải luật Anh hiện hành.", "key_fact": "UK: tác phẩm văn học = đời tác giả + 70 năm.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-2", "question": "Which of the following is incorrect?", "options": [{"key": "A", "text": "Nonfiction information is copyrightable."}, {"key": "B", "text": "The author's intention when making a literary work is irrelevant to its copyrightability."}, {"key": "C", "text": "Short phrases are generally not protected by copyright."}, {"key": "D", "text": "None of the options"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thông tin/sự kiện thực tế (facts) không được bảo hộ quyền tác giả – chỉ cách biểu đạt chúng mới được bảo hộ, nên A là phát biểu sai. B đúng vì ý định của tác giả không quyết định khả năng bảo hộ; C đúng vì cụm từ ngắn thường không được bảo hộ.", "key_fact": "Thông tin, sự kiện không được bảo hộ; chỉ cách trình bày được bảo hộ.", "topic": "Đối tượng quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-3", "question": "Who traditionally owns the copyright in a sound recording?", "options": [{"key": "A", "text": "The composer of the music"}, {"key": "B", "text": "The person who performs the music"}, {"key": "C", "text": "The person making the arrangements necessary for the recording to be made, typically the producer"}, {"key": "D", "text": "The recording studio"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.9(2)(aa), tác giả (và chủ sở hữu đầu tiên) của bản ghi âm là người thực hiện các sắp xếp cần thiết để bản ghi được tạo ra, thường là nhà sản xuất. Nhà soạn nhạc sở hữu tác phẩm âm nhạc, người biểu diễn chỉ có quyền của người biểu diễn.", "key_fact": "Bản ghi âm thuộc về producer – người sắp xếp việc ghi âm.", "topic": "Bản ghi âm", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-4", "question": "What does copyright in software include?", "options": [{"key": "A", "text": "Protection of the code and related documentation"}, {"key": "B", "text": "Only the visual design"}, {"key": "C", "text": "Only the underlying ideas"}, {"key": "D", "text": "Only the user interface"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Phần mềm được bảo hộ như tác phẩm văn học, bao gồm mã nguồn/mã đối tượng và tài liệu đi kèm (cả tài liệu thiết kế chuẩn bị). Quyền tác giả không bảo hộ ý tưởng nền tảng và không chỉ giới hạn ở giao diện.", "key_fact": "Copyright phần mềm bảo hộ code và tài liệu đi kèm, không bảo hộ ý tưởng.", "topic": "Bản quyền phần mềm", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-5", "question": "According to Vietnam law, duration of moral right in literature work:", "options": [{"key": "A", "text": "Lasts for 50 years from the year the film or record was made or, if it is released to the public, 50 years from its release"}, {"key": "B", "text": "Lasts for the life of its creator plus a further 50 years."}, {"key": "C", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work"}, {"key": "D", "text": "Lasts forever"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Luật SHTT VN (Điều 27), quyền nhân thân (đặt tên, đứng tên, bảo vệ toàn vẹn tác phẩm) được bảo hộ vô thời hạn, trừ quyền công bố. Phương án B là thời hạn quyền tài sản (đời tác giả + 50 năm).", "key_fact": "VN: quyền nhân thân (trừ quyền công bố) được bảo hộ vô thời hạn.", "topic": "Quyền tác giả VN", "note": "", "comment_answer": "D"}, {"id": "IPR-de3-6", "question": "Which of the followings is an infringement of copyright?", "options": [{"key": "A", "text": "Reading a book without consent of the author"}, {"key": "B", "text": "Listening to a song without consent of the author"}, {"key": "C", "text": "Translating an article without consent of the author"}, {"key": "D", "text": "Researching a paper without consent of the author"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Dịch tác phẩm là làm tác phẩm phái sinh (adaptation), một độc quyền của chủ sở hữu, nên dịch không xin phép là xâm phạm. Đọc sách, nghe nhạc, nghiên cứu không phải hành vi bị hạn chế.", "key_fact": "Dịch/chuyển thể (adaptation) cần sự cho phép của chủ sở hữu.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-7", "question": "What entity typically owns the copyright in a broadcast?", "options": [{"key": "A", "text": "The director of the broadcast"}, {"key": "B", "text": "The actors in the broadcast"}, {"key": "C", "text": "The broadcasting company that makes the broadcast"}, {"key": "D", "text": "The viewers of the broadcast"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA, tác giả của chương trình phát sóng là người thực hiện phát sóng, tức đài/công ty phát sóng, và là chủ sở hữu đầu tiên. Đạo diễn, diễn viên có thể có quyền khác nhưng không sở hữu quyền đối với buổi phát sóng.", "key_fact": "Copyright buổi phát sóng thuộc tổ chức phát sóng.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-8", "question": "Which IPR does not protect a technical report or specification?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Patent"}, {"key": "C", "text": "Confidential information"}, {"key": "D", "text": "Design right"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Báo cáo/đặc tả kỹ thuật là tác phẩm văn học (copyright), có thể chứa thông tin bí mật (confidential information) và mô tả sáng chế được bảo hộ bằng patent. Design right chỉ bảo hộ hình dạng/cấu hình của vật thể, không bảo hộ tài liệu văn bản.", "key_fact": "Design right bảo hộ hình dạng sản phẩm, không bảo hộ tài liệu.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de3-9", "question": "According to Vietnam law, duration of economics right in literature work:", "options": [{"key": "A", "text": "Lasts for 50 years from the year the film or record was made or, if it is released to the public, 50 years from its release"}, {"key": "B", "text": "Lasts for the life of its creator plus a further 50 years."}, {"key": "C", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work"}, {"key": "D", "text": "Lasts for 75 years from the end of the year in which the film was created"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Điều 27 Luật SHTT VN, quyền tài sản đối với tác phẩm văn học kéo dài suốt đời tác giả và 50 năm sau khi tác giả mất. A là thời hạn cho tác phẩm điện ảnh/nhiếp ảnh; C, D là luật nước ngoài/sai.", "key_fact": "VN: tác phẩm văn học = đời tác giả + 50 năm.", "topic": "Quyền tác giả VN", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-10", "question": "A writer has written a detective novel based on using a murder case's transcripts from court proceedings without the Court's consent. The Court is the publisher of the transcripts. Which of the following is RIGHT?", "options": [{"key": "A", "text": "The transcripts from court proceedings are protected by Copyright."}, {"key": "B", "text": "The writer has to compensate for the Court's copyright"}, {"key": "C", "text": "Transcripts from court proceedings are in the public domain"}, {"key": "D", "text": "The writer has infringed the Court's Copyright"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Văn bản tố tụng, bản ghi phiên tòa và văn bản hành chính, tư pháp không thuộc đối tượng bảo hộ quyền tác giả (Điều 15 Luật SHTT VN), nên được coi là thuộc phạm vi công cộng. Do đó nhà văn không xâm phạm và không phải bồi thường cho tòa.", "key_fact": "Văn bản tư pháp, bản ghi phiên tòa không được bảo hộ quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-11", "question": "Which of the following is not a moral right in Vietnamese IP law?", "options": [{"key": "A", "text": "Right to make copies"}, {"key": "B", "text": "Right to attribution"}, {"key": "C", "text": "None of the options"}, {"key": "D", "text": "Right to publish the work"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Luật SHTT Việt Nam (Điều 19), quyền nhân thân gồm đặt tên, đứng tên, công bố, bảo vệ toàn vẹn tác phẩm. Quyền sao chép (Điều 20) là quyền tài sản, nên không phải quyền nhân thân.", "key_fact": "Sao chép là quyền tài sản; công bố là quyền nhân thân (Luật VN).", "topic": "Quyền nhân thân", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-12", "question": "Primary copyright infringement is:", "options": [{"key": "A", "text": "Trading of those illegal copies"}, {"key": "B", "text": "Copying the material without permission."}, {"key": "C", "text": "Rewriting the material with permission."}, {"key": "D", "text": "Both of A&C"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm trực tiếp (primary infringement) là thực hiện hành vi bị hạn chế như sao chép mà không được phép. Buôn bán bản sao lậu là xâm phạm gián tiếp (secondary), còn viết lại có phép thì không xâm phạm.", "key_fact": "Primary = sao chép trái phép; secondary = buôn bán bản sao lậu.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-13", "question": "What must an idea have to be protected by copyright?", "options": [{"key": "A", "text": "Be original and registered"}, {"key": "B", "text": "Be expressed in a tangible form"}, {"key": "C", "text": "Be reviewed by an authority"}, {"key": "D", "text": "Be published"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả không bảo hộ ý tưởng mà bảo hộ hình thức thể hiện, nên ý tưởng phải được định hình dưới dạng vật chất (ghi lại). Không cần đăng ký, thẩm định hay công bố.", "key_fact": "Copyright bảo hộ sự thể hiện đã được định hình, không bảo hộ ý tưởng.", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-14", "question": "Which of the following is NOT a copyright infringement according to the UK law?", "options": [{"key": "A", "text": "Copying in a different medium to the original work, such as a photocopy of a book, or a scanned-in digital copy of a photograph"}, {"key": "B", "text": "Making a short-term or transient copy"}, {"key": "C", "text": "Speaking words aloud without making a copy whether by shorthand or on tape"}, {"key": "D", "text": "Making an object in three dimensions from a drawing of that object"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nói thành lời mà không tạo ra bản sao (không ghi chép, ghi âm) thì không phải là sao chép nên không xâm phạm. CDPA s.17 coi sao chép sang phương tiện khác, bản sao tạm thời, và chuyển từ 2D sang 3D đều là sao chép.", "key_fact": "Sao chép bao gồm đổi phương tiện, bản sao tạm thời, 2D sang 3D.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-15", "question": "What happens to copyright protection when minor bug-fixing changes are made to a computer program?", "options": [{"key": "A", "text": "The program loses its copyright protection"}, {"key": "B", "text": "The former copyright still applies"}, {"key": "C", "text": "A new copyright must be filed"}, {"key": "D", "text": "The changes are not protected by copyright"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sửa lỗi nhỏ không tạo ra đủ kỹ năng, công sức để hình thành tác phẩm mới, nên quyền tác giả cũ vẫn tiếp tục áp dụng cho chương trình. Chương trình không mất bảo hộ và quyền tác giả ở Anh không cần đăng ký.", "key_fact": "Sửa đổi nhỏ không tạo bản quyền mới; bản quyền cũ vẫn áp dụng.", "topic": "Bản quyền phần mềm", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-16", "question": "Computer program can be simultaneously protected by:", "options": [{"key": "A", "text": "Trade Mark and Registered Design"}, {"key": "B", "text": "Copyright, Patent and Confidential Information"}, {"key": "C", "text": "Design Right, Trade Mark and Copyright"}, {"key": "D", "text": "Trade secret and Trade Mark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chương trình máy tính có thể đồng thời được bảo hộ bởi quyền tác giả (tác phẩm văn học), sáng chế (nếu có hiệu quả kỹ thuật) và thông tin bí mật (mã nguồn). Kiểu dáng/design right không phù hợp với mã chương trình.", "key_fact": "Phần mềm: copyright + patent (hạn chế) + confidential information.", "topic": "Chồng lấn quyền SHTT", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-17", "question": "Assuming that an article is not common place, if this article could have been protected by a registered design but no application was filed, what is the potential result?", "options": [{"key": "A", "text": "It will be protected by design right."}, {"key": "B", "text": "It will be protected by trademark"}, {"key": "C", "text": "It will be protected by copyright"}, {"key": "D", "text": "All are not correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nếu thiết kế không phải thông thường (not commonplace) và không đăng ký thì vẫn có thể được bảo hộ tự động bởi UK unregistered design right (CDPA Part III). Nhãn hiệu cần đăng ký hoặc goodwill; copyright bị hạn chế với thiết kế công nghiệp (s.51).", "key_fact": "Kiểu dáng không đăng ký vẫn có thể được bảo hộ bằng design right.", "topic": "Quyền kiểu dáng chưa đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-18", "question": "To be protected, unregistered trade mark must.......", "options": [{"key": "A", "text": "Have reputation"}, {"key": "B", "text": "Be distinctive for the goods or services for which it has been used"}, {"key": "C", "text": "Both be distinctive and have reputation"}, {"key": "D", "text": "Be distinctive but do not have reputation"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu chưa đăng ký được bảo vệ qua passing off, đòi hỏi nhãn hiệu có tính phân biệt với hàng hóa/dịch vụ và có danh tiếng/goodwill trên thị trường. Chỉ có tính phân biệt mà không có danh tiếng thì chưa đủ để kiện passing off.", "key_fact": "Nhãn hiệu chưa đăng ký cần tính phân biệt và danh tiếng (goodwill).", "topic": "Nhãn hiệu chưa đăng ký", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-19", "question": "What are the basic requirements that trade mark should be?", "options": [{"key": "A", "text": "Easy to remember and sufficiently different from marks used by competitors"}, {"key": "B", "text": "Easy to remember and creating confusion"}, {"key": "C", "text": "Distinctive and confusion"}, {"key": "D", "text": "All are correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu tốt phải dễ nhớ và đủ khác biệt với nhãn hiệu của đối thủ (tính phân biệt). Gây nhầm lẫn là điều ngược lại với chức năng của nhãn hiệu.", "key_fact": "Nhãn hiệu: dễ nhớ và khác biệt, không gây nhầm lẫn.", "topic": "Khái niệm nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-20", "question": "A trade mark can be any of the following except a", "options": [{"key": "A", "text": "Word"}, {"key": "B", "text": "Symbol"}, {"key": "C", "text": "Formula"}, {"key": "D", "text": "Phrase"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu có thể là từ, biểu tượng, cụm từ (slogan)... Công thức (formula) là nội dung kỹ thuật, thường bảo hộ bằng bí mật kinh doanh hoặc patent, không phải dấu hiệu nhận diện.", "key_fact": "Công thức không phải nhãn hiệu (thường là bí mật kinh doanh).", "topic": "Khái niệm nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-21", "question": "Which of the following statements is true?", "options": [{"key": "A", "text": "Fair dealing means that only insubstantial part of a work may be used"}, {"key": "B", "text": "Fair deadling with all work is permitted"}, {"key": "C", "text": "Quoting from a work in criticism or review is permitted provided that the critic or review is fair"}, {"key": "D", "text": "Developing a single part of a work is fair"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.30, fair dealing cho mục đích phê bình, bình luận được phép khi việc sử dụng là công bằng và có ghi nhận nguồn đầy đủ. A sai vì fair dealing không chỉ giới hạn ở phần không đáng kể; B sai vì fair dealing chỉ áp dụng cho các mục đích luật định.", "key_fact": "Trích dẫn để phê bình/bình luận được phép nếu công bằng, có ghi nguồn.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-22", "question": "The term \"Apple\" can NOT be a trade mark of.......", "options": [{"key": "A", "text": "Any business"}, {"key": "B", "text": "Any business selling apples"}, {"key": "C", "text": "Any business selling smartphones"}, {"key": "D", "text": "Any business selling computers"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Apple' cho doanh nghiệp bán táo là tên gọi chung/mô tả hàng hóa nên không có khả năng phân biệt, không thể đăng ký làm nhãn hiệu. Với điện thoại, máy tính thì 'Apple' là từ dùng ngoài ngữ cảnh nên có tính phân biệt.", "key_fact": "Tên gọi chung của chính sản phẩm không thể làm nhãn hiệu.", "topic": "Khả năng phân biệt", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-23", "question": "Referring to a trade mark in news is.......", "options": [{"key": "A", "text": "A primary infringement of trade mark"}, {"key": "B", "text": "A secondary infringement of trade mark"}, {"key": "C", "text": "Not an infringement of trade mark"}, {"key": "D", "text": "An infringement of copyright"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhắc đến nhãn hiệu trong tin tức không phải là sử dụng trong hoạt động thương mại (in the course of trade) nên không xâm phạm nhãn hiệu. Cũng không phải xâm phạm quyền tác giả.", "key_fact": "Xâm phạm nhãn hiệu đòi hỏi sử dụng 'in the course of trade'.", "topic": "Xâm phạm nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-24", "question": "Which of followings is correct?", "options": [{"key": "A", "text": "Passing off is an infringement of only unregistered trademark"}, {"key": "B", "text": "Passing off is an infringement of only registered trademark"}, {"key": "C", "text": "Passing off is an infringement of both unregistered and registered trademark"}, {"key": "D", "text": "Passing off is an infringement of neither unregistered nor registered trademark"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off bảo vệ goodwill, nên có thể áp dụng cho cả nhãn hiệu chưa đăng ký và đã đăng ký (TMA 1994 s.2(2) giữ nguyên quyền kiện passing off). A dễ gây nhầm vì passing off thường dùng cho nhãn chưa đăng ký, nhưng không chỉ giới hạn ở đó.", "key_fact": "Passing off dùng được cho cả nhãn hiệu đăng ký và chưa đăng ký.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-25", "question": "The standard that must be met for a plaintiff to win a trade mark dilution claim is the likelihood of confusion.", "options": [{"key": "A", "text": "Yes. Likelihood of confusion is the key indicator to identify a trade mark infringement."}, {"key": "B", "text": "No. Since dilution is a form of damage in passing off, the plaintiff must show there is a reputation in the mark or get-up; there has been confusion in the marketplace, and the owner has suffered damage to win the claim."}, {"key": "C", "text": "No. The damage is the fundamental indicator in a dilution claim, that the plaintiff must prove to win the case."}, {"key": "D", "text": "There are no correct answers"}], "answer": ["D"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Dilution không đòi hỏi khả năng gây nhầm lẫn (chuẩn là khả năng làm loãng/tổn hại tính phân biệt hoặc danh tiếng, không cần chứng minh thiệt hại kinh tế thực tế theo TDRA), nên A sai, C sai; B lại mô tả bộ ba passing off có yêu cầu nhầm lẫn, mâu thuẫn với chữ 'No'. Không tìm được đáp án công khai; D là hợp lý nhất nhưng B có thể là đáp án giáo trình nếu đề coi dilution là dạng thiệt hại trong passing off. (Nguồn: https://secureyourtrademark.com/blog/trademark-infringement-dilution/ ; https://lawteacher.net/free-law-essays/business-law/dilution-under-trademark-law-business-law-essay.php)", "key_fact": "Dilution: không cần likelihood of confusion.", "topic": "Làm loãng nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de3-26", "question": "Registration of a trade mark is", "options": [{"key": "A", "text": "automatic"}, {"key": "B", "text": "subject to an approval process through the designated authoritative body"}, {"key": "C", "text": "dependent upon a corporation using a priori means to establish an original mark."}, {"key": "D", "text": "dependent upon whether the mark has been established as being diluted."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đăng ký nhãn hiệu không tự động mà phải qua thủ tục thẩm định và chấp thuận của cơ quan có thẩm quyền (UKIPO, Cục SHTT). Các phương án C, D không liên quan.", "key_fact": "Đăng ký nhãn hiệu phải qua thẩm định của cơ quan có thẩm quyền.", "topic": "Đăng ký nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-27", "question": "Distinguishing those products from the products of competitors and being capable of indicating goods or services originating from a particular source are ... element of trade mark.", "options": [{"key": "A", "text": "Comparative"}, {"key": "B", "text": "Original"}, {"key": "C", "text": "Distinctive"}, {"key": "D", "text": "Memorable"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Khả năng phân biệt sản phẩm với sản phẩm của đối thủ và chỉ ra nguồn gốc thương mại chính là yếu tố phân biệt (distinctive) của nhãn hiệu. 'Original' là tiêu chuẩn của quyền tác giả.", "key_fact": "Tính phân biệt = chỉ dẫn nguồn gốc, phân biệt với đối thủ.", "topic": "Khả năng phân biệt", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-28", "question": "A Community Trade Marks (CTM) is valid in ___", "options": [{"key": "A", "text": "All member countries of the WTO"}, {"key": "B", "text": "All member countries of the EU"}, {"key": "C", "text": "All member countries of the WIPO"}, {"key": "D", "text": "All member countries of the UN"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu Cộng đồng (CTM, nay là EUTM) có hiệu lực thống nhất tại tất cả các nước thành viên EU. Không áp dụng cho WTO, WIPO hay UN.", "key_fact": "CTM/EUTM có hiệu lực trên toàn EU.", "topic": "Nhãn hiệu EU", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-29", "question": "What does three stripes on Adidas clothing represent?", "options": [{"key": "A", "text": "A trade mark."}, {"key": "B", "text": "Trade dress."}, {"key": "C", "text": "A trade secret."}, {"key": "D", "text": "A patent."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ba sọc của Adidas là dấu hiệu hình được đăng ký nhãn hiệu (figurative/position mark) để chỉ nguồn gốc thương mại. Trade dress là tổng thể bao bì/hình thức, bí mật kinh doanh và patent không phù hợp.", "key_fact": "Ba sọc Adidas là nhãn hiệu hình.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-30", "question": "'Apple' for computers is an example of", "options": [{"key": "A", "text": "Invented words used as a trade mark"}, {"key": "B", "text": "Words used out of context as a trade mark"}, {"key": "C", "text": "Symbols used as a trade mark"}, {"key": "D", "text": "Shapes used as a trade mark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "'Apple' là từ có nghĩa (quả táo) nhưng được dùng ngoài ngữ cảnh cho máy tính nên có tính phân biệt. Không phải từ tự tạo vì từ này có nghĩa trong tiếng Anh.", "key_fact": "Apple cho máy tính = từ dùng ngoài ngữ cảnh.", "topic": "Loại nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-31", "question": "According to TRIPS, a registered mark can give the owner...", "options": [{"key": "A", "text": "Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar goods"}, {"key": "B", "text": "Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar services"}, {"key": "C", "text": "Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for identical or similar goods and services"}, {"key": "D", "text": "Exclusive right to prevent use by a third party in the course of trade of an identical or similar sign for different goods"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "TRIPS Điều 16.1 trao cho chủ nhãn hiệu đăng ký độc quyền ngăn cấm bên thứ ba sử dụng trong thương mại dấu hiệu giống hoặc tương tự cho hàng hóa hoặc dịch vụ giống hoặc tương tự nếu có khả năng gây nhầm lẫn. A, B chỉ nêu một phần; D (hàng hóa khác loại) chỉ áp dụng cho nhãn hiệu nổi tiếng.", "key_fact": "TRIPS Art.16: giống/tương tự cho hàng hóa và dịch vụ giống/tương tự.", "topic": "TRIPS", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-32", "question": "What does trade libel means?", "options": [{"key": "A", "text": "Misleading advertisements and false indications of the origin of goods and services"}, {"key": "B", "text": "The original information about the quality of products or services"}, {"key": "C", "text": "An injunction against counterfeit"}, {"key": "D", "text": "A piece of information identified the products or services on mass communication"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trade libel (malicious falsehood) liên quan đến việc đưa ra tuyên bố sai lệch gây hại cho hàng hóa/dịch vụ, gắn với quảng cáo gây nhầm lẫn và chỉ dẫn sai về nguồn gốc. Các phương án khác mô tả thông tin đúng, lệnh cấm hoặc thông tin trên truyền thông, không phải trade libel.", "key_fact": "Trade libel = tuyên bố sai/gây nhầm lẫn làm tổn hại hàng hóa, dịch vụ của người khác.", "topic": "Cạnh tranh không lành mạnh", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-33", "question": "If the design is NOT put to practical use,...", "options": [{"key": "A", "text": "Its legal protection shall last for 10 years from the time it is created"}, {"key": "B", "text": "Its legal protection shall last for 15 years from the time it is created"}, {"key": "C", "text": "Its legal protection shall last for 05 years from the time it is created"}, {"key": "D", "text": "Its legal protection shall last for 20 years from the time it is created"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA 1988 s.216, quyền kiểu dáng không đăng ký kéo dài 15 năm từ cuối năm thiết kế được tạo ra, hoặc 10 năm từ cuối năm sản phẩm lần đầu được bán nếu việc bán diễn ra trong 5 năm đầu. Nếu không được đưa vào sử dụng/thương mại thì áp dụng mốc 15 năm, nên A (10 năm) sai.", "key_fact": "UK unregistered design right: 15 năm từ khi tạo ra, hoặc 10 năm từ lần bán đầu nếu bán trong 5 năm.", "topic": "Quyền kiểu dáng chưa đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-34", "question": "In the context of the 'must fit' exception, which of the following scenarios is true?", "options": [{"key": "A", "text": "The entire car exhaust system can be copied without permission"}, {"key": "B", "text": "The design of a contact lens front surface can be copied"}, {"key": "C", "text": "Only the parts of an exhaust system that connect to the car can be copied"}, {"key": "D", "text": "The overall shape of a car cannot be copied"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ngoại lệ 'must fit' (s.213(3)(b)(i) CDPA) chỉ cho phép sao chép các đặc điểm hình dạng cần thiết để kết nối/lắp khớp với sản phẩm khác, ví dụ các phần ống xả nối với xe. Không cho sao chép toàn bộ hệ thống ống xả; mặt trước kính áp tròng không phải phần 'lắp khớp' (mặt sau mới là must fit).", "key_fact": "Must fit chỉ áp dụng cho phần tiếp xúc/kết nối với sản phẩm khác.", "topic": "Quyền kiểu dáng chưa đăng ký", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-35", "question": "Which of the following cannot be registered as a design under the Registered Designs Act?", "options": [{"key": "A", "text": "A sculpture"}, {"key": "B", "text": "A computer program"}, {"key": "C", "text": "A vehicle's external shape"}, {"key": "D", "text": "A typeface"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "RDA 1949 s.1(3) loại trừ chương trình máy tính khỏi khái niệm 'product' nên không đăng ký được kiểu dáng; phần mềm được bảo hộ bằng quyền tác giả. Typeface, hình dạng xe, tác phẩm điêu khắc có thể đăng ký kiểu dáng.", "key_fact": "Chương trình máy tính không đăng ký kiểu dáng được.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-36", "question": "Which is not the way of recovering the cost of developing an engineering technology (an IP)?", "options": [{"key": "A", "text": "Both of b&d"}, {"key": "B", "text": "Granting a license to a company, who all paid a royalty for the right to use the IP."}, {"key": "C", "text": "Applying for the IP registration at an authorized State agency."}, {"key": "D", "text": "Making a product and selling it, with the IPR keeping competitors out of the market."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thu hồi chi phí phát triển công nghệ được thực hiện bằng cách cấp li-xăng thu phí bản quyền hoặc tự sản xuất, bán sản phẩm dưới sự độc quyền. Việc nộp đơn đăng ký chỉ tạo lập quyền và tốn chi phí, không phải cách thu hồi chi phí.", "key_fact": "Thu hồi chi phí IP: li-xăng hoặc khai thác độc quyền, không phải nộp đơn.", "topic": "Khai thác quyền SHTT", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-37", "question": "How to acquire IPRs?", "options": [{"key": "A", "text": "Assignment"}, {"key": "B", "text": "Licensing"}, {"key": "C", "text": "Know-how contract"}, {"key": "D", "text": "All are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Có thể có được quyền SHTT (hoặc quyền sử dụng) thông qua chuyển nhượng (assignment), li-xăng (licensing) và hợp đồng know-how. Vì vậy tất cả đều đúng.", "key_fact": "Chuyển nhượng, li-xăng, know-how đều là cách có được quyền SHTT.", "topic": "Chuyển giao quyền SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de3-38", "question": "Which of the following is NOT a type of Intellectual Property Right (IPR)?", "options": [{"key": "A", "text": "Patent"}, {"key": "B", "text": "Copyright"}, {"key": "C", "text": "Trademark"}, {"key": "D", "text": "Real Estate Ownership"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền sở hữu bất động sản là quyền tài sản hữu hình, không phải quyền sở hữu trí tuệ. Patent, quyền tác giả, nhãn hiệu đều là quyền SHTT.", "key_fact": "SHTT bảo hộ sản phẩm trí tuệ vô hình, không phải bất động sản.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de3-39", "question": "Why is protection of Intellectual Property Rights (IPRs) significant? (check all that apply)", "options": [{"key": "A", "text": "Encouraging creations and innovations"}, {"key": "B", "text": "Protecting innovations and investments required for the development of advanced technologies."}, {"key": "C", "text": "Not sustaining long-term social growth."}, {"key": "D", "text": "Promoting a comprehensive cooperation among countries worldwide."}], "answer": ["A", "B", "D"], "multi": true, "confidence": "high", "source": "ai", "explanation": "Bảo hộ SHTT khuyến khích sáng tạo, đổi mới; bảo vệ khoản đầu tư vào phát triển công nghệ tiên tiến; và thúc đẩy hợp tác quốc tế. C sai vì SHTT giúp duy trì tăng trưởng xã hội lâu dài, không phải ngược lại.", "key_fact": "SHTT khuyến khích sáng tạo, bảo vệ đầu tư, thúc đẩy hợp tác.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "A,B,D"}, {"id": "IPR-de3-40", "question": "Company X pays Company Y for one copy of a program such as a word processing or accountancy package for a PC (Company Y is the owner of the program). Company X then makes copies for every PC in the company without the permission of the Company Y. Which of the following option is wrong?", "options": [{"key": "A", "text": "Company Y can sue Company X for the Copyright Infringement."}, {"key": "B", "text": "Company X can make copies of the program for every PC in the company for internal use only within the company as it has paid for the program already."}, {"key": "C", "text": "Company X does not have the right to make copies for every PC in the company, unless the accompanying license gives this permission."}, {"key": "D", "text": "Both of a&c"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mua một bản phần mềm chỉ cho phép sử dụng theo li-xăng; sao chép cho mọi máy trong công ty mà không được phép là xâm phạm quyền tác giả, kể cả dùng nội bộ. Do đó B là phát biểu sai; A và C đúng.", "key_fact": "Mua một bản không cho quyền sao chép thêm, trừ khi li-xăng cho phép.", "topic": "Bản quyền phần mềm", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-41", "question": "In the UK, it is a _____ offence to apply a mark identical to (or likely to be mistaken for) a registered trade mark to goods, labels, packaging or advertising materials intended for use in relation to goods without the proprietor's permission.", "options": [{"key": "A", "text": "Civil"}, {"key": "B", "text": "Moral"}, {"key": "C", "text": "Criminal"}, {"key": "D", "text": "Ethical"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s.92 TMA 1994, gắn dấu hiệu giống hoặc dễ nhầm với nhãn hiệu đăng ký lên hàng hóa, nhãn, bao bì, tài liệu quảng cáo mà không được phép là tội phạm hình sự (criminal offence). Không phải chỉ là vi phạm dân sự.", "key_fact": "TMA 1994 s.92: làm giả nhãn hiệu là tội hình sự.", "topic": "Chế tài nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de3-42", "question": "What are criteria for winning a transfer of a domain name?", "options": [{"key": "A", "text": "A domain name must be identical or confusingly similar to a registered or unregistered trade mark, the use complained of must be by someone having no legitimate interest in the name, and bad faith"}, {"key": "B", "text": "When there is innocently confusing use, an offer to sell the mark or a history of registering names based on third party trade marks."}, {"key": "C", "text": "All are correct"}, {"key": "D", "text": "None of the answers are correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo UDRP, nguyên đơn phải chứng minh: tên miền giống hoặc tương tự gây nhầm lẫn với nhãn hiệu, người đăng ký không có quyền/lợi ích hợp pháp, và đăng ký, sử dụng với dụng ý xấu. B chỉ liệt kê một số dấu hiệu của bad faith, và 'sử dụng nhầm lẫn vô tình' không phải bad faith.", "key_fact": "UDRP: giống/gây nhầm lẫn + không có lợi ích hợp pháp + dụng ý xấu.", "topic": "Tên miền", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-43", "question": "If an owner of copyright believes the material it protects is being copied without permission, which are the courts the owner will take a legal action for the infringement?", "options": [{"key": "A", "text": "Courts having the jurisdiction on labor cases."}, {"key": "B", "text": "Civil courts."}, {"key": "C", "text": "Courts having the jurisdiction on marriage issues."}, {"key": "D", "text": "Courts having the jurisdiction on administrative cases."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm quyền tác giả là tranh chấp dân sự về tài sản, do tòa dân sự giải quyết. Tòa lao động, hôn nhân gia đình, hành chính không có thẩm quyền.", "key_fact": "Kiện xâm phạm quyền tác giả tại tòa dân sự.", "topic": "Thực thi quyền SHTT", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-44", "question": "Which is litigation model applied in the countries used the civil law system?", "options": [{"key": "A", "text": "Adversarial litigation"}, {"key": "B", "text": "Inquisitorial litigation"}, {"key": "C", "text": "Civil procedure"}, {"key": "D", "text": "Court procedure"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Các nước theo hệ thống dân luật (civil law) áp dụng mô hình tố tụng thẩm vấn (inquisitorial), thẩm phán chủ động điều tra. Mô hình tranh tụng (adversarial) là đặc trưng của common law như Anh, Mỹ.", "key_fact": "Civil law = inquisitorial; common law = adversarial.", "topic": "Hệ thống tố tụng", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-45", "question": "What does this mean for Ander if he is an author of a novel based on the \"National treatment principle\" in the Berne Convention on Literary and Artistic Works 1886", "options": [{"key": "A", "text": "He is required to register his works with the Berne Convention office."}, {"key": "B", "text": "He is exempt from any copyright regulations in the Berne Convention's country members"}, {"key": "C", "text": "His novel will be in the public domain."}, {"key": "D", "text": "Ander is given the same rights and privileges (copyright) to his novel as domestic authors in any country that ratified Berne Convention."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nguyên tắc đối xử quốc gia của Công ước Berne: tác giả từ một nước thành viên được hưởng quyền như tác giả trong nước tại mọi nước thành viên. Berne không yêu cầu đăng ký (bảo hộ tự động) và không đưa tác phẩm vào phạm vi công cộng.", "key_fact": "Berne national treatment: tác giả nước ngoài được đối xử như tác giả nội địa.", "topic": "Công ước Berne", "note": "", "comment_answer": "D"}, {"id": "IPR-de3-46", "question": "What is the main domestic law applicable in the UK for copyright?", "options": [{"key": "A", "text": "The Copyright, Designs and Patents Act 1988 and its revision"}, {"key": "B", "text": "A WIPO Treaty on Copyright"}, {"key": "C", "text": "EU directives on e-commerce and digital copyright"}, {"key": "D", "text": "The Patents Act 1977"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Luật chính về quyền tác giả ở Anh là Copyright, Designs and Patents Act 1988 (và các sửa đổi). Patents Act 1977 điều chỉnh sáng chế; hiệp ước WIPO và chỉ thị EU không phải luật nội địa chính.", "key_fact": "UK copyright: CDPA 1988.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-47", "question": "What is the requirement for an invented word to be a trade mark?", "options": [{"key": "A", "text": "It must be distinctive"}, {"key": "B", "text": "It must be meaningful"}, {"key": "C", "text": "It must indicate the nature of the products"}, {"key": "D", "text": "It must be new"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Từ tự tạo muốn làm nhãn hiệu phải có tính phân biệt (thường có sẵn vì không có nghĩa). Không cần có nghĩa hay mô tả bản chất sản phẩm; mô tả sản phẩm còn làm mất tính phân biệt.", "key_fact": "Yêu cầu cốt lõi của nhãn hiệu là tính phân biệt.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de3-48", "question": "Regarding to Registration period for a registered design. Which of the following is WRONG?", "options": [{"key": "A", "text": "The initial registration period for a design last for 5 years from the application date."}, {"key": "B", "text": "The registration can be kept in force for four subsequent periods of 5 years (after the initial registration period), automatically, without fees."}, {"key": "C", "text": "The registration can be kept in force for four subsequent periods of 5 years, (after the initial registration period), if renewal fees are paid."}, {"key": "D", "text": "The registration period for a design last for 5 years only from the application date. After that period, the registration will not be extended if the owner does not pay the renewal fees"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiểu dáng đăng ký (RDA 1949) có thời hạn ban đầu 5 năm kể từ ngày nộp đơn, có thể gia hạn thêm 4 lần mỗi lần 5 năm (tối đa 25 năm) nhưng phải nộp phí gia hạn. Vì vậy phát biểu B 'tự động, không cần phí' là SAI. C và D đều đúng vì gia hạn phụ thuộc việc nộp phí.", "key_fact": "Kiểu dáng đăng ký: 5 năm, gia hạn 4 lần x 5 năm khi nộp phí, tối đa 25 năm.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-49", "question": "A wooden chair is protected by registered design. After seeing this chair, a chocolate shop makes a chocolate bar with the design of this chair. Such act is....", "options": [{"key": "A", "text": "A secondary infringement of registered design"}, {"key": "B", "text": "A primary infringement of registered design"}, {"key": "C", "text": "Not an infringement of registered design"}, {"key": "D", "text": "An infringement of patent"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo RDA 1949 (sửa đổi), kiểu dáng đăng ký được bảo hộ đối với mọi sản phẩm chứ không chỉ loại sản phẩm đã đăng ký, nên làm thanh sô-cô-la mang kiểu dáng chiếc ghế là trực tiếp sử dụng kiểu dáng – xâm phạm trực tiếp (primary). Không phải xâm phạm thứ cấp (vốn là hành vi buôn bán hàng xâm phạm) và không liên quan sáng chế.", "key_fact": "Kiểu dáng đăng ký được bảo hộ cho mọi sản phẩm, không giới hạn ở sản phẩm gốc.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de3-50", "question": "Who is the designer?", "options": [{"key": "A", "text": "The draughts person who made the drawing"}, {"key": "B", "text": "Anyone who contributes the ideas of the drawing"}, {"key": "C", "text": "Person who provides the concept for designing"}, {"key": "D", "text": "All are correct"}], "answer": ["C"], "multi": false, "confidence": "low", "source": "ai", "explanation": "CDPA s.214: designer là người tạo ra kiểu dáng; theo C&H Engineering v Klucznik (1992), người đưa ra ý tưởng/khái niệm thiết kế đủ cụ thể là designer chứ không phải người vẽ kỹ thuật chỉ ghi lại. B ('bất kỳ ai đóng góp ý tưởng') quá rộng và mâu thuẫn với câu de7-49 (người chỉ cung cấp ý tưởng không phải tác giả), nên D 'All are correct' khó đứng vững; C sát nhất. Chưa có nguồn xác nhận đáp án đề, nếu đề theo giáo trình liệt kê thì có thể là D. (Nguồn: https://www.legislation.gov.uk/ukpga/1988/48/section/214 ; https://nipclaw.blogspot.com/2018/01/design-rights-in-wedding-dresses-madine.html)", "key_fact": "Designer = người tạo ra/khởi xướng kiểu dáng, không nhất thiết là người vẽ.", "topic": "Quyền thiết kế", "note": "Đã sửa từ D sang C sau khi tra cứu trên mạng.", "comment_answer": "D"}]}, {"id": "de4", "name": "Đề 4", "questions": [{"id": "IPR-de4-1", "question": "According to Vietnam law, duration of moral right in literature work:", "options": [{"key": "A", "text": "Lasts for 50 years from the year the film or record was made or, if it is released to the public, 50 years from its release"}, {"key": "B", "text": "Lasts for the life of its creator plus a further 50 years."}, {"key": "C", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work"}, {"key": "D", "text": "Lasts forever"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Luật SHTT VN (Điều 27), quyền nhân thân (đặt tên, đứng tên, bảo vệ toàn vẹn tác phẩm) được bảo hộ vô thời hạn, trừ quyền công bố. Phương án B là thời hạn quyền tài sản (đời tác giả + 50 năm).", "key_fact": "VN: quyền nhân thân (trừ quyền công bố) được bảo hộ vô thời hạn.", "topic": "Quyền tác giả VN", "note": "", "comment_answer": "D"}, {"id": "IPR-de4-2", "question": "What does copyright protection in sound recordings cover?", "options": [{"key": "A", "text": "Only recordings of music"}, {"key": "B", "text": "Any type of sound recording, including spoken words and noises"}, {"key": "C", "text": "Only digital recordings"}, {"key": "D", "text": "Only films and broadcasts"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bản ghi âm theo CDPA s.5A là bất kỳ bản ghi âm thanh nào, gồm âm nhạc, lời nói, tiếng động, bất kể phương tiện. Không chỉ nhạc hay ghi âm số.", "key_fact": "Mọi loại âm thanh được ghi đều là sound recording.", "topic": "Bản ghi âm", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-3", "question": "The photographer owns the copyright but the person paying for the photograph to be taken can stop it being used for other purposes, which is referred to as ________", "options": [{"key": "A", "text": "Integrity right"}, {"key": "B", "text": "Paternity right"}, {"key": "C", "text": "False attribution right"}, {"key": "D", "text": "Privacy right"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s85 CDPA 1988, người đặt chụp ảnh cho mục đích riêng tư, gia đình có quyền riêng tư (right to privacy) để ngăn bức ảnh bị công bố/trưng bày, dù nhiếp ảnh gia giữ quyền tác giả. Integrity, paternity, false attribution là các quyền nhân thân của tác giả, không phải của người đặt hàng.", "key_fact": "Quyền riêng tư với ảnh đặt chụp thuộc về người đặt hàng (s85 CDPA).", "topic": "Quyền nhân thân", "note": "", "comment_answer": "D"}, {"id": "IPR-de4-4", "question": "Simplifying a written story without consent of author is.........", "options": [{"key": "A", "text": "Infringement of copyright"}, {"key": "B", "text": "Plagiarism"}, {"key": "C", "text": "Passing off"}, {"key": "D", "text": "False attribution"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Rút gọn/đơn giản hóa truyện là tạo tác phẩm phái sinh (adaptation) – một hành vi độc quyền của chủ sở hữu, nên làm mà không xin phép là xâm phạm quyền tác giả. Đạo văn (plagiarism) là nhận vơ tác phẩm của người khác; passing off và false attribution không phù hợp.", "key_fact": "Phóng tác/chuyển thể tác phẩm khi chưa được phép là xâm phạm quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-5", "question": "Does copyright apply to live broadcasts?", "options": [{"key": "A", "text": "No, only recorded broadcasts are covered"}, {"key": "B", "text": "Yes, copyright applies to both live and recorded broadcasts"}, {"key": "C", "text": "Only if the broadcast is international"}, {"key": "D", "text": "Only if the broadcast is on television"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA 1988, broadcast là một loại tác phẩm được bảo hộ, không đòi hỏi phải được ghi lại (định hình), nên cả phát sóng trực tiếp và đã ghi đều được bảo hộ. Các phương án giới hạn theo tính quốc tế hay truyền hình là sai.", "key_fact": "Bản phát sóng (kể cả trực tiếp) được bảo hộ quyền tác giả trong 50 năm.", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-6", "question": "Which of these events potentially triggers the right of attribution?", "options": [{"key": "A", "text": "Broadcasting a recording of a song on the radio"}, {"key": "B", "text": "Uploading a song to a file-sharing website"}, {"key": "C", "text": "Broadcasting a recitation of a poem on the radio"}, {"key": "D", "text": "Using a song in a film"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s77 CDPA, với tác phẩm văn học (trừ lời bài hát), quyền được nêu tên phát sinh khi tác phẩm được trình diễn công khai hoặc truyền đạt đến công chúng – ví dụ phát sóng bài thơ được ngâm trên radio. Với tác phẩm âm nhạc/lời bài hát, quyền này chỉ phát sinh khi xuất bản thương mại, phát hành bản ghi âm hoặc chiếu phim ra công chúng, nên phát bản ghi bài hát trên radio (A) không kích hoạt.", "key_fact": "Tác phẩm văn học: quyền nêu tên phát sinh cả khi trình diễn/phát sóng; nhạc thì không.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-7", "question": "Who holds the copyright in the individual works, such as songs or plays, included in a sound recording or broadcast?", "options": [{"key": "A", "text": "The original creators of those works"}, {"key": "B", "text": "The producer of the sound recording or broadcast"}, {"key": "C", "text": "The broadcasting company"}, {"key": "D", "text": "The director of the film or broadcast"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bản ghi âm và bản phát sóng là các tác phẩm riêng biệt; quyền tác giả đối với các tác phẩm gốc (bài hát, vở kịch) nằm trong đó vẫn thuộc về người sáng tạo ra chúng. Nhà sản xuất/đài phát chỉ sở hữu quyền với bản ghi âm/bản phát sóng.", "key_fact": "Quyền với tác phẩm gốc vẫn thuộc tác giả gốc, tách biệt với quyền đối với bản ghi/phát sóng.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-8", "question": "What happens if a consultant or Company B creates copyrighted material under a contract, but the contract does not specify ownership?", "options": [{"key": "A", "text": "The consultant or Company B owns the copyright, but may have limited control over its use"}, {"key": "B", "text": "The copyright is automatically assigned to Company A"}, {"key": "C", "text": "The consultant cannot use the material without permission from Company A"}, {"key": "D", "text": "The copyright remains with the consultant, with full control"}], "answer": ["A"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "CDPA s.11: tác giả là chủ sở hữu đầu tiên trừ trường hợp nhân viên làm trong phạm vi công việc; bên tư vấn/Company B giữ quyền nhưng bên đặt hàng có giấy phép ngầm định (implied licence) nên quyền kiểm soát bị hạn chế. B sai vì không có chuyển giao tự động; D sai vì không 'toàn quyền'. (Nguồn: https://nipclaw.blogspot.com/2015/07/copyright-in-commissioned-works-atelier.html ; https://www.legislation.gov.uk/ukpga/1988/48/section/11)", "key_fact": "Hợp đồng không ghi quyền sở hữu: người làm giữ copyright, bên thuê có implied licence.", "topic": "Chủ sở hữu quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de4-9", "question": "Which of the following requires permission under copyright law?", "options": [{"key": "A", "text": "Playing a song in a public venue"}, {"key": "B", "text": "Listening to music at home"}, {"key": "C", "text": "Sharing a book with a friend"}, {"key": "D", "text": "Writing a review of a movie"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trình diễn công khai (public performance) bài hát ở nơi công cộng là độc quyền của chủ sở hữu nên cần xin phép. Nghe nhạc tại nhà, cho bạn mượn sách, viết bình luận phim không thuộc độc quyền hoặc được ngoại lệ.", "key_fact": "Trình diễn công khai tác phẩm cần sự cho phép của chủ sở hữu.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-10", "question": "Adding some words in a song without consent of author is an infringement of......", "options": [{"key": "A", "text": "Reproduction right"}, {"key": "B", "text": "Public performance right"}, {"key": "C", "text": "Integrity right"}, {"key": "D", "text": "False attribution"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thêm lời vào bài hát là một 'treatment' (thêm, bớt, sửa đổi) tác phẩm; nếu làm sai lệch, ảnh hưởng danh dự tác giả thì xâm phạm quyền bảo vệ sự toàn vẹn (integrity right) theo s80 CDPA. Không phải sao chép (reproduction) hay trình diễn công khai, cũng không phải gán sai tên tác giả.", "key_fact": "Sửa đổi, thêm bớt tác phẩm gây sai lệch xâm phạm quyền toàn vẹn (integrity).", "topic": "Quyền nhân thân", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-11", "question": "The right for the creator of a literary, artistic, dramatic or musical copyright work to be named as author in certain circumstances is ______", "options": [{"key": "A", "text": "the right of integrity"}, {"key": "B", "text": "the right of privacy"}, {"key": "C", "text": "the right of false attribution"}, {"key": "D", "text": "the right of paternity"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền được đứng tên tác giả (right to be identified) gọi là quyền paternity (s77 CDPA). Integrity là chống xuyên tạc, false attribution là chống bị gán sai tên.", "key_fact": "Paternity right = quyền được nêu tên là tác giả.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "D"}, {"id": "IPR-de4-12", "question": "What is a \"public performance\" in terms of copyright?", "options": [{"key": "A", "text": "Any performance of a work in a public space"}, {"key": "B", "text": "A private showing of a work"}, {"key": "C", "text": "A limited distribution of a work"}, {"key": "D", "text": "A performance by a professional artist only"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biểu diễn công cộng là biểu diễn tác phẩm ở nơi công cộng hoặc trước công chúng (ngoài phạm vi gia đình). Buổi chiếu riêng tư không phải; không cần nghệ sĩ chuyên nghiệp.", "key_fact": "Biểu diễn trước công chúng ngoài gia đình là public performance.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-13", "question": "Smith, who is a freelance, creates copyright material as hired and assigned by Peter Company, copyright is owned by ______", "options": [{"key": "A", "text": "Peter Company"}, {"key": "B", "text": "Smith"}, {"key": "C", "text": "Smith's colleagues"}, {"key": "D", "text": "Peter Company's board of directors"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "CDPA s.11(1)-(2): tác giả là chủ sở hữu đầu tiên; chỉ tác phẩm do NHÂN VIÊN tạo ra trong công việc mới thuộc chủ lao động. Smith là freelancer nên Smith sở hữu, trừ khi có văn bản chuyển nhượng. (Nguồn: https://www.legislation.gov.uk/ukpga/1988/48/section/11)", "key_fact": "Freelancer được thuê vẫn sở hữu copyright (trừ khi chuyển nhượng bằng văn bản).", "topic": "Chủ sở hữu quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-14", "question": "What is the purpose of \"right of communication to the public\"?", "options": [{"key": "A", "text": "To control how the work is transmitted to the public, especially electronically"}, {"key": "B", "text": "To allow free sharing of the work"}, {"key": "C", "text": "To enable the sale of physical copies"}, {"key": "D", "text": "To ensure the work is only available in its original form"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền truyền đạt đến công chúng (s20 CDPA) cho phép chủ sở hữu kiểm soát việc phát sóng và cung cấp tác phẩm qua mạng (truyền điện tử). Nó không nhằm cho chia sẻ miễn phí hay bán bản sao vật lý (đó là quyền phân phối).", "key_fact": "Quyền truyền đạt đến công chúng kiểm soát phát sóng và cung cấp trực tuyến.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-15", "question": "What does the term \"moral rights\" refer to in copyright?", "options": [{"key": "A", "text": "Rights related to the integrity and authorship of a work"}, {"key": "B", "text": "The right to make a profit from the work"}, {"key": "C", "text": "The right to distribute the work"}, {"key": "D", "text": "The right to modify the work without restrictions"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền nhân thân (moral rights) gồm quyền đứng tên, quyền bảo vệ toàn vẹn, chống gán sai tên và quyền riêng tư – liên quan đến danh dự tác giả và sự toàn vẹn tác phẩm. Quyền thu lợi, phân phối là quyền kinh tế.", "key_fact": "Moral rights bảo vệ quyền đứng tên và sự toàn vẹn của tác phẩm.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-16", "question": "Computer program can be simultaneously protected by:", "options": [{"key": "A", "text": "Trade Mark and Registered Design"}, {"key": "B", "text": "Copyright, Patent and Confidential Information"}, {"key": "C", "text": "Design Right, Trade Mark and Copyright"}, {"key": "D", "text": "Trade secret and Trade Mark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chương trình máy tính có thể đồng thời được bảo hộ bởi quyền tác giả (tác phẩm văn học), sáng chế (nếu có hiệu quả kỹ thuật) và thông tin bí mật (mã nguồn). Kiểu dáng/design right không phù hợp với mã chương trình.", "key_fact": "Phần mềm: copyright + patent (hạn chế) + confidential information.", "topic": "Chồng lấn quyền SHTT", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-17", "question": "What is a potential area of overlap between copyright and industrial design protection?", "options": [{"key": "A", "text": "Copyright may protect a design as an artistic work, while industrial design may protect the same design as a three-dimensional article."}, {"key": "B", "text": "Copyright protects functional aspects; and industrial design protects artistic ideas."}, {"key": "C", "text": "Industrial design exclusively protects digital designs."}, {"key": "D", "text": "Both protect only two-dimensional designs."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Một kiểu dáng có thể vừa được bảo hộ như tác phẩm mỹ thuật (bản vẽ, tác phẩm thủ công) bởi quyền tác giả, vừa được bảo hộ như kiểu dáng của sản phẩm ba chiều. B sai vì quyền tác giả không bảo hộ khía cạnh chức năng; C, D sai về phạm vi.", "key_fact": "Quyền tác giả và kiểu dáng có thể cùng bảo hộ một thiết kế.", "topic": "Quyền tác giả và kiểu dáng", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-18", "question": "What is NOT \"get-up\" of a well-known bakery shop?", "options": [{"key": "A", "text": "Client"}, {"key": "B", "text": "Packaging"}, {"key": "C", "text": "Decoration style"}, {"key": "D", "text": "Name"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Get-up (hình thức trình bày) là diện mạo thương mại như bao bì, phong cách trang trí, tên/nhãn hiệu gắn liền. Khách hàng (client) không phải là một phần của get-up.", "key_fact": "Get-up gồm bao bì, trang trí, cách trình bày – không gồm khách hàng.", "topic": "Passing off", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-19", "question": "Acme Corporation attempted to register a trade mark that was generic and not fanciful, arbitrary, suggestive or descriptive with a secondary meaning. Under these circumstances, Acme has", "options": [{"key": "A", "text": "An excellent case for the registration of a trade mark because generic trade marks, as opposed to fanciful, arbitrary or suggestive trade marks, are capable of being copyrighted."}, {"key": "B", "text": "An excellent case for the registration of a trade mark because all trade marks are capable of being copyrighted."}, {"key": "C", "text": "No case for registration of the trade mark because a trade mark must be fanciful, arbitrary or suggestive to be capable of being copyrighted."}, {"key": "D", "text": "No case for registration of the trade mark because a trade mark must be independent, rather than fanciful, arbitrary or suggestive, to be capable of being copyrighted."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tên chung (generic) không thể đăng ký nhãn hiệu vì không có tính phân biệt; nhãn phải là tự tạo, tùy ý, gợi ý hoặc mô tả đã có ý nghĩa thứ cấp. Đáp án C đúng về kết luận (dù câu hỏi dùng chữ 'copyrighted' không chuẩn).", "key_fact": "Nhãn generic không bao giờ đăng ký được.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-20", "question": "Collective trade mark means..........", "options": [{"key": "A", "text": "There are many users of this trade mark"}, {"key": "B", "text": "There are many owners of this trade mark"}, {"key": "C", "text": "There is a collection of trademarks used by one company"}, {"key": "D", "text": "There is a collection of products sharing this trademark"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu tập thể là nhãn hiệu của một hiệp hội, dùng để phân biệt hàng hóa/dịch vụ của các thành viên; chủ sở hữu là hiệp hội nhưng có nhiều thành viên sử dụng. B sai vì chủ sở hữu là một tổ chức; C, D mô tả danh mục nhãn hiệu.", "key_fact": "Nhãn hiệu tập thể: một hiệp hội sở hữu, nhiều thành viên sử dụng.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-21", "question": "The word \"Steel\" can be add in trademark of......", "options": [{"key": "A", "text": "Only company producing steel"}, {"key": "B", "text": "Only company not producing steel"}, {"key": "C", "text": "Any company"}, {"key": "D", "text": "All company"}], "answer": ["C"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Trùng câu de4-21: 'Steel' là từ mô tả, không đăng ký riêng cho thép nhưng có thể đưa vào nhãn hiệu tổ hợp của bất kỳ công ty nào. Không tìm được đáp án công khai xác nhận. (Nguồn: https://www.gov.uk/guidance/trade-marks-manual)", "key_fact": "Từ mô tả có thể nằm trong nhãn hiệu tổ hợp, không độc quyền riêng.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-22", "question": "Is it compulsory to register a trademark?", "options": [{"key": "A", "text": "Yes. This is a legal requirement."}, {"key": "B", "text": "No. Trade marks need not be registered"}, {"key": "C", "text": "No. Because the protection of trade mark is automatic"}, {"key": "D", "text": "All are not correct."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đăng ký nhãn hiệu không bắt buộc; nhãn hiệu chưa đăng ký vẫn có thể được bảo vệ qua passing off. C sai vì nhãn hiệu không được bảo hộ 'tự động' theo TMA mà cần đăng ký để có quyền đăng ký.", "key_fact": "Đăng ký nhãn hiệu là tự nguyện; chưa đăng ký dựa vào passing off.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-23", "question": "What does a trademark protect?", "options": [{"key": "A", "text": "A work of art"}, {"key": "B", "text": "A secret formula"}, {"key": "C", "text": "Logos, names and brands"}, {"key": "D", "text": "General information"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu bảo hộ dấu hiệu phân biệt như logo, tên, thương hiệu. Tác phẩm nghệ thuật thuộc quyền tác giả, công thức bí mật thuộc thông tin bí mật.", "key_fact": "Nhãn hiệu bảo hộ dấu hiệu phân biệt nguồn gốc hàng hóa/dịch vụ.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-24", "question": "For the purpose of showing damage in a passing-off action, the owner must.......", "options": [{"key": "A", "text": "Show actual loss"}, {"key": "B", "text": "Demonstrate high risk of loss of business arising from the confusion"}, {"key": "C", "text": "Calculate the number of clients before and after passing off occurs"}, {"key": "D", "text": "Proving the activity of imitation"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong passing off (Jif Lemon), yếu tố thiệt hại chỉ cần chứng minh thiệt hại thực tế hoặc khả năng thiệt hại thật sự do nhầm lẫn; không bắt buộc chứng minh thiệt hại đã xảy ra. Đếm khách hàng hay chứng minh việc bắt chước không phải yêu cầu.", "key_fact": "Passing off: chỉ cần khả năng gây thiệt hại thật sự, không cần thiệt hại thực tế.", "topic": "Passing off", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-25", "question": "Which of followings is correct?", "options": [{"key": "A", "text": "Passing off is an infringement of only unregistered trademark"}, {"key": "B", "text": "Passing off is an infringement of only registered trademark"}, {"key": "C", "text": "Passing off is an infringement of both unregistered and registered trademark"}, {"key": "D", "text": "Passing off is an infringement of neither unregistered nor registered trademark"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off bảo vệ goodwill, nên có thể áp dụng cho cả nhãn hiệu chưa đăng ký và đã đăng ký (TMA 1994 s.2(2) giữ nguyên quyền kiện passing off). A dễ gây nhầm vì passing off thường dùng cho nhãn chưa đăng ký, nhưng không chỉ giới hạn ở đó.", "key_fact": "Passing off dùng được cho cả nhãn hiệu đăng ký và chưa đăng ký.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-26", "question": "A trade mark can be any of the following except a", "options": [{"key": "A", "text": "Word"}, {"key": "B", "text": "Symbol"}, {"key": "C", "text": "Formula"}, {"key": "D", "text": "Phrase"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu có thể là từ, biểu tượng, cụm từ (slogan)... Công thức (formula) là nội dung kỹ thuật, thường bảo hộ bằng bí mật kinh doanh hoặc patent, không phải dấu hiệu nhận diện.", "key_fact": "Công thức không phải nhãn hiệu (thường là bí mật kinh doanh).", "topic": "Khái niệm nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-27", "question": "In order to determine whether a company commits passing off, the determinative factor is whether .......", "options": [{"key": "A", "text": "Products are similar"}, {"key": "B", "text": "The buyer is misrepresented which leads the buyer to believe that the products were produced by the true owner"}, {"key": "C", "text": "Products are sold within one geographic area"}, {"key": "D", "text": "There are marketing activity using such trademark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Yếu tố quyết định của passing off là sự trình bày sai (misrepresentation) khiến người mua tin rằng hàng hóa là của chủ thể có uy tín. Sự tương tự sản phẩm hay khu vực bán chỉ là yếu tố phụ.", "key_fact": "Misrepresentation gây nhầm lẫn là yếu tố cốt lõi của passing off.", "topic": "Passing off", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-28", "question": "When you use the registered trade mark in relation to the goods/services specified in the registration, there is an infringement.", "options": [{"key": "A", "text": "True."}, {"key": "B", "text": "It depends."}, {"key": "C", "text": "False. Besides what mentioned, the infringement must be caused with confusion."}, {"key": "D", "text": "False. Because the use of registered trade mark in relation to the goods/services specified in the registration is passing off."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s10(1) TMA 1994, sử dụng dấu hiệu trùng với nhãn hiệu đã đăng ký cho hàng hóa/dịch vụ trùng với danh mục đăng ký (không được phép) là xâm phạm mà không cần chứng minh nhầm lẫn. Yêu cầu nhầm lẫn chỉ áp dụng cho trường hợp tương tự (s10(2)), nên C sai.", "key_fact": "Trùng dấu hiệu + trùng hàng hóa = xâm phạm, không cần chứng minh nhầm lẫn.", "topic": "Xâm phạm nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-29", "question": "While proving for the reputation of an unregistered mark, the owner needs to:", "options": [{"key": "A", "text": "Prove that the unregistered mark or the get-up is distinctive"}, {"key": "B", "text": "Prove that the unregistered mark is taken to show a trade connection with a particular business"}, {"key": "C", "text": "A and B are correct"}, {"key": "D", "text": "A and B are incorrect"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Để chứng minh uy tín (goodwill/reputation) của nhãn hiệu chưa đăng ký, chủ sở hữu phải chứng minh nhãn hiệu hoặc get-up có tính phân biệt và được công chúng coi là biểu thị mối liên hệ thương mại với một doanh nghiệp cụ thể. Cả A và B đều cần.", "key_fact": "Nhãn hiệu chưa đăng ký: chứng minh tính phân biệt và liên hệ với doanh nghiệp.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-30", "question": "What are the basic requirements that trade mark should be?", "options": [{"key": "A", "text": "Easy to remember and sufficiently different from marks used by competitors"}, {"key": "B", "text": "Easy to remember and creating confusion"}, {"key": "C", "text": "Distinctive and confusion"}, {"key": "D", "text": "All are correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu tốt phải dễ nhớ và đủ khác biệt với nhãn hiệu của đối thủ (tính phân biệt). Gây nhầm lẫn là điều ngược lại với chức năng của nhãn hiệu.", "key_fact": "Nhãn hiệu: dễ nhớ và khác biệt, không gây nhầm lẫn.", "topic": "Khái niệm nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-31", "question": "Which of these statements is true about the general nature of passing off?", "options": [{"key": "A", "text": "The defendant must intend to cause loss"}, {"key": "B", "text": "The misrepresentation must be intentional"}, {"key": "C", "text": "There must be a false representation"}, {"key": "D", "text": "There must be actual damages"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off bắt buộc phải có sự trình bày sai (misrepresentation), nhưng không cần cố ý (lỗi vô ý vẫn có thể bị coi là passing off) và không cần thiệt hại thực tế (chỉ cần khả năng thiệt hại). Vì vậy A, B, D sai.", "key_fact": "Passing off cần misrepresentation, không cần ý định gây hại.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-32", "question": "Confusion can be caused by a competitor using the most memorable part of the trade mark. Is this statement correct?", "options": [{"key": "A", "text": "Yes. The use of the most memorable part will be sufficient to generate the confusion."}, {"key": "B", "text": "No. The confusion happens when the competitor uses an identical or very similar trade mark or get-up."}, {"key": "C", "text": "No. The confusion happens only in the case of using identical marks for identical goods or services"}, {"key": "D", "text": "None of the abovementioned statement is correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhầm lẫn có thể xảy ra khi đối thủ dùng phần dễ nhớ, nổi bật nhất của nhãn hiệu, vì người tiêu dùng thường chỉ nhớ phần đặc trưng đó (đánh giá tổng thể với 'trí nhớ không hoàn hảo'). B, C sai vì không đòi hỏi trùng hoặc rất giống toàn bộ.", "key_fact": "Dùng phần nổi bật, dễ nhớ của nhãn hiệu có thể đủ gây nhầm lẫn.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-33", "question": "What is primary infringement of design right?", "options": [{"key": "A", "text": "Copying a design and making an article that is exactly the same or only slightly different."}, {"key": "B", "text": "Selling a product that looks similar to a protected design."}, {"key": "C", "text": "Importing a product without permission."}, {"key": "D", "text": "Hiring out an article that is identical to another."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm trực tiếp quyền thiết kế (s226 CDPA) là sao chép thiết kế để tạo ra sản phẩm giống hệt hoặc gần giống (substantially). Bán, nhập khẩu, cho thuê hàng xâm phạm là xâm phạm thứ cấp.", "key_fact": "Primary infringement = sao chép làm sản phẩm giống hệt hoặc gần giống.", "topic": "Quyền thiết kế", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-34", "question": "Design right applies for ______.", "options": [{"key": "A", "text": "the shape or configuration of an article"}, {"key": "B", "text": "a method or principle of construction"}, {"key": "C", "text": "None of the options"}, {"key": "D", "text": "surface decoration"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền thiết kế không đăng ký của UK (s213 CDPA) bảo hộ hình dạng hoặc cấu hình (shape or configuration) của sản phẩm. Nó loại trừ phương pháp/nguyên lý cấu tạo và trang trí bề mặt (surface decoration).", "key_fact": "Design right bảo hộ shape/configuration, loại trừ surface decoration.", "topic": "Quyền thiết kế", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-35", "question": "What challenge does the overlap between copyright and design right present in the engineering context?", "options": [{"key": "A", "text": "Uncertainty in whether certain structures, like a microwave tower, are considered articles or buildings"}, {"key": "B", "text": "Confusion over which law to apply"}, {"key": "C", "text": "The inability to protect engineering designs"}, {"key": "D", "text": "Conflicts between design and patent law"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong kỹ thuật, sự giao thoa gây khó khăn vì không rõ một số công trình như tháp vi ba là 'sản phẩm' (thuộc design right) hay 'công trình kiến trúc' (tác phẩm mỹ thuật – quyền tác giả). Các phương án khác quá chung chung hoặc sai.", "key_fact": "Khó xác định công trình kỹ thuật là 'article' hay 'building'.", "topic": "Quyền tác giả và kiểu dáng", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-36", "question": "What type(s) of IPR license can be?", "options": [{"key": "A", "text": "Only an exclusive license."}, {"key": "B", "text": "Can be either an exclusive; sole or non-exclusive license."}, {"key": "C", "text": "Only a sole license."}, {"key": "D", "text": "Only a non-exclusive license."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Li-xăng quyền SHTT có thể là độc quyền (exclusive), duy nhất (sole) hoặc không độc quyền (non-exclusive). Các phương án chỉ cho một loại là sai.", "key_fact": "Li-xăng gồm exclusive, sole và non-exclusive.", "topic": "Chuyển giao quyền SHTT", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-37", "question": "What is an IPRs (Intellectual Property Rights) assignment?", "options": [{"key": "A", "text": "Both of b & c."}, {"key": "B", "text": "A legal/ administration action of an authorized State agency to grant IPRs to an individual and/or organization on the IP that they created or owned."}, {"key": "C", "text": "A legal agreement in which the owner of an intellectual property (IP) grants permission to another party (other parties) to use that IP under defined conditions."}, {"key": "D", "text": "A legal agreement on transferring of ownership of IP from the assignor to the assignee."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chuyển nhượng (assignment) là thỏa thuận chuyển quyền sở hữu SHTT từ bên chuyển nhượng sang bên nhận. C là định nghĩa li-xăng (license), B là việc cấp văn bằng bảo hộ.", "key_fact": "Assignment = chuyển quyền sở hữu; license = cho phép sử dụng.", "topic": "Chuyển giao quyền SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de4-38", "question": "Which value of ideas and information that Intellectual Property Rights (IPR) protect?", "options": [{"key": "A", "text": "Ethical value"}, {"key": "B", "text": "Moral value"}, {"key": "C", "text": "Social value"}, {"key": "D", "text": "Commercial value"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền SHTT bảo vệ giá trị thương mại của ý tưởng và thông tin, giúp chủ sở hữu khai thác lợi ích kinh tế. Giá trị đạo đức, xã hội không phải trọng tâm.", "key_fact": "Quyền SHTT bảo vệ giá trị thương mại của tài sản trí tuệ.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de4-39", "question": "What is the social justification for the protection of intellectual property?", "options": [{"key": "A", "text": "To create economic inequality"}, {"key": "B", "text": "To provide creators with a monopoly"}, {"key": "C", "text": "To encourage the dissemination of knowledge"}, {"key": "D", "text": "To limit access to technology"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện minh xã hội của bảo hộ SHTT là khuyến khích sáng tạo và phổ biến tri thức (đổi độc quyền tạm thời lấy công bố). B chỉ là phương tiện, không phải lý do xã hội; A, D sai.", "key_fact": "Bảo hộ SHTT nhằm khuyến khích phổ biến tri thức.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-40", "question": "Agreement on Trade-Related Aspects of Intellectual Property Rights (TRIPS) is an international agreement that ..... for all World Trade Organization members.", "options": [{"key": "A", "text": "Sets maximum standards for protection of intellectual property"}, {"key": "B", "text": "Sets minimum standards for intellectual property protection"}, {"key": "C", "text": "Regulates average standards for protection of intellectual property"}, {"key": "D", "text": "Sets basic limitations for intellectual property protection"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "TRIPS đặt ra tiêu chuẩn tối thiểu về bảo hộ SHTT mà mọi thành viên WTO phải tuân thủ; các nước có thể bảo hộ cao hơn. Không phải tiêu chuẩn tối đa hay trung bình.", "key_fact": "TRIPS = tiêu chuẩn tối thiểu cho thành viên WTO.", "topic": "Điều ước quốc tế", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-41", "question": "Which is litigation model applied in the countries used the civil law system?", "options": [{"key": "A", "text": "Adversarial litigation"}, {"key": "B", "text": "Inquisitorial litigation"}, {"key": "C", "text": "Civil procedure"}, {"key": "D", "text": "Court procedure"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Các nước theo hệ thống dân luật (civil law) áp dụng mô hình tố tụng thẩm vấn (inquisitorial), thẩm phán chủ động điều tra. Mô hình tranh tụng (adversarial) là đặc trưng của common law như Anh, Mỹ.", "key_fact": "Civil law = inquisitorial; common law = adversarial.", "topic": "Hệ thống tố tụng", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-42", "question": "What criminal liability that a copyright infringer may face according to the UK law?", "options": [{"key": "A", "text": "10 years imprisonment"}, {"key": "B", "text": "Unlimited fine"}, {"key": "C", "text": "Both A and B"}, {"key": "D", "text": "Neither A or B"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA 1988 (s107, sửa đổi 2017), tội phạm xâm phạm quyền tác giả có thể bị phạt tù tối đa 10 năm và/hoặc phạt tiền không giới hạn khi xét xử theo thủ tục cáo trạng. Do đó cả A và B.", "key_fact": "Xâm phạm quyền tác giả hình sự UK: tù tới 10 năm và/hoặc phạt tiền không giới hạn.", "topic": "Chế tài", "note": "", "comment_answer": "C"}, {"id": "IPR-de4-43", "question": "What is the damage?", "options": [{"key": "A", "text": "A sum of money paid by the infringer to the IP owner via a court's decision"}, {"key": "B", "text": "A criminal liability"}, {"key": "C", "text": "The profit that infringer received through their infringements"}, {"key": "D", "text": "An amount that the IP owner will receive from the court"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bồi thường thiệt hại (damages) là khoản tiền bên xâm phạm phải trả cho chủ sở hữu theo quyết định của tòa án, đây là chế tài dân sự. C là 'account of profits' – một chế tài thay thế; B là trách nhiệm hình sự.", "key_fact": "Damages là tiền bồi thường bên xâm phạm trả cho chủ sở hữu theo phán quyết tòa.", "topic": "Chế tài", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-44", "question": "Company X pays Company Y for one copy of a program such as a word processing or accountancy package for a PC (Company Y is the owner of the program). Company X then makes copies for every PC in the company without the permission of the Company Y. Which of the following option is wrong?", "options": [{"key": "A", "text": "Company Y can sue Company X for the Copyright Infringement."}, {"key": "B", "text": "Company X can make copies of the program for every PC in the company for internal use only within the company as it has paid for the program already."}, {"key": "C", "text": "Company X does not have the right to make copies for every PC in the company, unless the accompanying license gives this permission."}, {"key": "D", "text": "Both of a&c"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Mua một bản phần mềm chỉ cho phép sử dụng theo li-xăng; sao chép cho mọi máy trong công ty mà không được phép là xâm phạm quyền tác giả, kể cả dùng nội bộ. Do đó B là phát biểu sai; A và C đúng.", "key_fact": "Mua một bản không cho quyền sao chép thêm, trừ khi li-xăng cho phép.", "topic": "Bản quyền phần mềm", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-45", "question": "Which convention primarily deals with the protection of industrial property such as patents and trademarks?", "options": [{"key": "A", "text": "Berne Convention"}, {"key": "B", "text": "Paris Convention"}, {"key": "C", "text": "Rome Convention"}, {"key": "D", "text": "Geneva Convention"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Công ước Paris 1883 bảo hộ sở hữu công nghiệp (sáng chế, nhãn hiệu, kiểu dáng...). Berne về quyền tác giả, Rome về quyền liên quan, Geneva về luật nhân đạo.", "key_fact": "Paris = sở hữu công nghiệp; Berne = quyền tác giả.", "topic": "Điều ước quốc tế", "note": "", "comment_answer": "B"}, {"id": "IPR-de4-46", "question": "What are the sources for IP law in the UK?", "options": [{"key": "A", "text": "International law"}, {"key": "B", "text": "Domestic (UK) law"}, {"key": "C", "text": "Precedents (Case Law)"}, {"key": "D", "text": "All of them"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nguồn luật SHTT của UK gồm điều ước quốc tế (Berne, Paris, TRIPS), luật quốc nội (CDPA, TMA, PA, RDA) và án lệ. Vì vậy chọn tất cả.", "key_fact": "Luật SHTT UK đến từ luật quốc tế, luật nội địa và án lệ.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de4-47", "question": "How to identify the infringement of the registered design?", "options": [{"key": "A", "text": "Using visual test"}, {"key": "B", "text": "Asking friends"}, {"key": "D", "text": "Using fair dealing test"}, {"key": "C", "text": "Just refer to the court or authority and wait for their opinions"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm kiểu dáng đăng ký được xác định bằng phép thử thị giác: sản phẩm có tạo ra ấn tượng tổng thể khác biệt đối với người sử dụng có hiểu biết hay không. Fair dealing là ngoại lệ quyền tác giả, không phải phép thử xâm phạm.", "key_fact": "Kiểu dáng đăng ký: phép thử thị giác về ấn tượng tổng thể với người dùng hiểu biết.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-48", "question": "Which of the following is correct?", "options": [{"key": "A", "text": "A registrable mark can infringe a third person's rights."}, {"key": "B", "text": "A mark must indicate the type, quality, purpose or geographical origin of the products to be registrable."}, {"key": "C", "text": "A registrable mark can be contrary to morality."}, {"key": "D", "text": "A mark must be distinctive to be registrable."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu phải có tính phân biệt mới đăng ký được (s3 TMA). Nhãn hiệu không được xâm phạm quyền người khác, trái đạo đức, và dấu hiệu mô tả loại, chất lượng, nguồn gốc địa lý lại bị từ chối – nên A, B, C sai.", "key_fact": "Điều kiện cốt lõi để đăng ký nhãn hiệu là tính phân biệt.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de4-49", "question": "Unregisterable marks include ________", "options": [{"key": "A", "text": "'purely' descriptive signs which indicate the nature of the product"}, {"key": "B", "text": "an invented word which is distinctive and not indicative of the nature of the products"}, {"key": "C", "text": "English words used out of context"}, {"key": "D", "text": "All of the options"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Dấu hiệu thuần mô tả bản chất sản phẩm không đăng ký được do thiếu tính phân biệt (s3(1)(c) TMA). Từ tự tạo và từ dùng ngoài ngữ cảnh lại có tính phân biệt cao nên đăng ký được.", "key_fact": "Dấu hiệu thuần mô tả không đăng ký được làm nhãn hiệu.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de4-50", "question": "What are the exclusions from design registration?", "options": [{"key": "A", "text": "A feature of a product is dictated by its function;"}, {"key": "B", "text": "A feature which allows a product to fit to another product."}, {"key": "C", "text": "A and B are correct"}, {"key": "D", "text": "A and B are not correct"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo RDA 1949, không bảo hộ đặc điểm chỉ do chức năng kỹ thuật quyết định và đặc điểm cho phép sản phẩm lắp khớp với sản phẩm khác (must-fit). Vì vậy cả A và B.", "key_fact": "Loại trừ kiểu dáng: đặc điểm do chức năng quyết định và must-fit.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "C"}]}, {"id": "de5", "name": "Đề 5", "questions": [{"id": "IPR-de5-1", "question": "Secondary copyright infringement is:", "options": [{"key": "A", "text": "Copying the material without permission."}, {"key": "B", "text": "Trading of those illegal copies"}, {"key": "C", "text": "Rewriting the material without permission."}, {"key": "D", "text": "Scanning the material without permission."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm thứ cấp là hành vi buôn bán, nhập khẩu, phân phối bản sao xâm phạm (ss22-26 CDPA). Sao chép, viết lại, scan là xâm phạm trực tiếp.", "key_fact": "Xâm phạm thứ cấp = kinh doanh bản sao xâm phạm.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-2", "question": "Copyright is NOT applied to ........", "options": [{"key": "A", "text": "Songs"}, {"key": "B", "text": "Video tapes"}, {"key": "C", "text": "Broadcasts"}, {"key": "D", "text": "None of them"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bài hát (tác phẩm âm nhạc/văn học), băng video (phim) và bản phát sóng đều được bảo hộ quyền tác giả theo CDPA 1988. Vì vậy không có phương án nào bị loại trừ.", "key_fact": "Bài hát, phim, bản phát sóng đều được bảo hộ quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-3", "question": "This IP right is associated with every literary, dramatic, musical or artistic work, to sound recordings, films, broadcasts and cable programs. What is this right?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Design right"}, {"key": "C", "text": "Registered design"}, {"key": "D", "text": "Confidential information"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả áp dụng cho tác phẩm văn học, kịch, âm nhạc, mỹ thuật, bản ghi âm, phim, bản phát sóng (s1 CDPA). Design right và registered design bảo hộ kiểu dáng sản phẩm.", "key_fact": "Quyền tác giả bao gồm tác phẩm LDMA, ghi âm, phim, phát sóng.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-4", "question": "Which is/are exceptions to copyright infringement?", "options": [{"key": "A", "text": "Public events"}, {"key": "B", "text": "Time shifting"}, {"key": "C", "text": "Education"}, {"key": "D", "text": "All of others are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "CDPA có các ngoại lệ như sử dụng cho giáo dục, ghi lại để xem sau (time shifting, s70), và đưa tin sự kiện công cộng/thời sự. Vì vậy chọn tất cả.", "key_fact": "Ngoại lệ quyền tác giả gồm giáo dục, time shifting, đưa tin thời sự.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-5", "question": "Which IPR will protect an electrical device?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Confidential information"}, {"key": "C", "text": "Trademark"}, {"key": "D", "text": "Design right"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hình dạng, cấu hình của thiết bị điện là đối tượng của quyền thiết kế (design right) – bảo hộ sản phẩm chức năng ba chiều. Quyền tác giả không bảo hộ sản phẩm công nghiệp chức năng; nhãn hiệu bảo vệ dấu hiệu chứ không phải thiết bị.", "key_fact": "Hình dạng sản phẩm chức năng được bảo hộ bởi design right.", "topic": "Quyền thiết kế", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-6", "question": "Which of the followings is not a public domain material?", "options": [{"key": "A", "text": "Works expired copyrights"}, {"key": "B", "text": "Works published by the United States government"}, {"key": "C", "text": "A novel protected by Copyright"}, {"key": "D", "text": "News and history"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tiểu thuyết đang được bảo hộ quyền tác giả không phải tài liệu thuộc phạm vi công cộng. Tác phẩm hết hạn, tác phẩm của chính phủ Mỹ và tin tức/sự kiện lịch sử thuộc phạm vi công cộng.", "key_fact": "Tác phẩm còn thời hạn bảo hộ không thuộc public domain.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-7", "question": "Which of the following is NOT a copyright infringement?", "options": [{"key": "A", "text": "Someone copies without the copyright owner's permission"}, {"key": "B", "text": "A photographer takes a photograph of a particular scenic view, even though the photograph is virtually indistinguishable to another person's photograph."}, {"key": "C", "text": "Someone creates a scene in a studio to reproduce a scene in someone else's photograph"}, {"key": "D", "text": "One similarity drawing has had access to the material which has supposedly been copied"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả chỉ chống sao chép; sáng tạo độc lập không phải xâm phạm, nên nhiếp ảnh gia tự chụp cảnh dù giống ảnh người khác không xâm phạm. Dựng lại cảnh để tái tạo ảnh người khác (C) là sao chép (Creation Records, Temple Island).", "key_fact": "Sáng tạo độc lập dù giống nhau không xâm phạm quyền tác giả.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-8", "question": "In most types of work, how long does copyright last for according to Bern Convention?", "options": [{"key": "A", "text": "10 years after the creation of the work"}, {"key": "B", "text": "50 years after the creation of the work"}, {"key": "C", "text": "10 years after the death of the person who created that work"}, {"key": "D", "text": "50 years after the death of the person who created that work"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Công ước Berne quy định thời hạn tối thiểu là suốt đời tác giả cộng 50 năm sau khi tác giả chết. UK/EU kéo dài lên 70 năm, nhưng câu hỏi hỏi theo Berne.", "key_fact": "Berne: tối thiểu life + 50; UK: life + 70.", "topic": "Thời hạn quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-9", "question": "Cindy has very detailed and interesting ideas on writing a book. Based on these ideas, David writes a book without attribution of Cindy. David ........", "options": [{"key": "A", "text": "Infringes paternity right"}, {"key": "B", "text": "Infringes adaptation right"}, {"key": "C", "text": "Infringes reproduction right"}, {"key": "D", "text": "Not infringes intellectual property right"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả không bảo hộ ý tưởng mà chỉ bảo hộ hình thức thể hiện; Cindy chưa thể hiện ý tưởng thành tác phẩm nên David không xâm phạm. Quyền đứng tên chỉ có với tác phẩm của tác giả.", "key_fact": "Ý tưởng không được bảo hộ quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-10", "question": "To be protected by copyright, a creative work must be......", "options": [{"key": "A", "text": "Fixed in a tangible medium"}, {"key": "B", "text": "Original"}, {"key": "C", "text": "Both original and fixed in a tangible medium"}, {"key": "D", "text": "Spoken"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Để được bảo hộ, tác phẩm phải nguyên gốc và được định hình dưới dạng vật chất (CDPA yêu cầu literary/dramatic/musical works phải được ghi lại). Lời nói chưa ghi lại thì không được bảo hộ.", "key_fact": "Điều kiện bảo hộ: nguyên gốc + được định hình.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-11", "question": "An author of a song wants that people will refer to his name whenever they sing that song. What type of intellectual property right can he claim?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Trademarks"}, {"key": "C", "text": "Registered designs"}, {"key": "D", "text": "Patent"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền được nêu tên (paternity) là quyền nhân thân thuộc quyền tác giả. Nhãn hiệu, kiểu dáng, sáng chế không liên quan đến tác phẩm âm nhạc.", "key_fact": "Paternity right là một phần của quyền tác giả.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-12", "question": "Simplifying a written story without consent of author is.........", "options": [{"key": "A", "text": "Infringement of copyright"}, {"key": "B", "text": "Plagiarism"}, {"key": "C", "text": "Passing off"}, {"key": "D", "text": "False attribution"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Rút gọn/đơn giản hóa truyện là tạo tác phẩm phái sinh (adaptation) – một hành vi độc quyền của chủ sở hữu, nên làm mà không xin phép là xâm phạm quyền tác giả. Đạo văn (plagiarism) là nhận vơ tác phẩm của người khác; passing off và false attribution không phù hợp.", "key_fact": "Phóng tác/chuyển thể tác phẩm khi chưa được phép là xâm phạm quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-13", "question": "Which of the following is RIGHT?", "options": [{"key": "A", "text": "As a copyright holder, you are compensated for fair use of your copyrighted work by others."}, {"key": "B", "text": "A teacher has copied a book for purpose of teaching. The teacher has to compensate for the book's copyright holder for the use."}, {"key": "C", "text": "A university professor has copied a book for purpose of his research. This is not an infringement of copyright."}, {"key": "D", "text": "If material is protected by copyright, in any cases, no anyone can use the material without copyright holder's permission."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Fair dealing cho mục đích nghiên cứu phi thương mại (s29 CDPA) là ngoại lệ, nên giáo sư sao chép sách cho nghiên cứu không xâm phạm (trong giới hạn hợp lý). A sai vì fair use không được trả tiền; D sai vì có ngoại lệ; B sai vì có ngoại lệ cho giáo dục.", "key_fact": "Fair dealing cho nghiên cứu phi thương mại không xâm phạm quyền tác giả.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-14", "question": "Which of the following is NOT a copyright infringement according to the UK law?", "options": [{"key": "A", "text": "Copying in a different medium to the original work, such as a photocopy of a book, or a scanned-in digital copy of a photograph"}, {"key": "B", "text": "Making a short-term or transient copy"}, {"key": "C", "text": "Speaking words aloud without making a copy whether by shorthand or on tape"}, {"key": "D", "text": "Making an object in three dimensions from a drawing of that object"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nói thành lời mà không tạo ra bản sao (không ghi chép, ghi âm) thì không phải là sao chép nên không xâm phạm. CDPA s.17 coi sao chép sang phương tiện khác, bản sao tạm thời, và chuyển từ 2D sang 3D đều là sao chép.", "key_fact": "Sao chép bao gồm đổi phương tiện, bản sao tạm thời, 2D sang 3D.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-15", "question": "According to Vietnam law, duration of economics right in literature work:", "options": [{"key": "A", "text": "Lasts for 50 years from the year the film or record was made or, if it is released to the public, 50 years from its release"}, {"key": "B", "text": "Lasts for the life of its creator plus a further 50 years."}, {"key": "C", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more authors were jointly involved in the work"}, {"key": "D", "text": "Lasts for 75 years from the end of the year in which the film was created"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Điều 27 Luật SHTT VN, quyền tài sản đối với tác phẩm văn học kéo dài suốt đời tác giả và 50 năm sau khi tác giả mất. A là thời hạn cho tác phẩm điện ảnh/nhiếp ảnh; C, D là luật nước ngoài/sai.", "key_fact": "VN: tác phẩm văn học = đời tác giả + 50 năm.", "topic": "Quyền tác giả VN", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-16", "question": "A design of a television set being intended for manufacture is new and has an individual character. The design is also not commonplace. What IPRs can simultaneously protect the design?", "options": [{"key": "A", "text": "Trademarks; and Copyright."}, {"key": "B", "text": "Registered Design; and Design Right."}, {"key": "C", "text": "Copyright; and Registered Design."}, {"key": "D", "text": "Copyright; Trademarks; and Registered Design."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thiết kế mới, có tính riêng biệt đáp ứng điều kiện kiểu dáng đăng ký; thiết kế nguyên gốc, không phổ biến (not commonplace) về hình dạng được bảo hộ bởi design right không đăng ký. Hai quyền này có thể cùng tồn tại.", "key_fact": "Kiểu dáng đăng ký (mới, riêng biệt) và design right (không phổ biến) có thể cùng bảo hộ.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-17", "question": "Which of the following is a generic term?", "options": [{"key": "A", "text": "\"car\" for cars"}, {"key": "B", "text": "\"Apple\" for computers"}, {"key": "C", "text": "\"Camel\" for cigarettes"}, {"key": "D", "text": "\"Kodak\" for cameras"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Từ chung (generic) là tên gọi thông thường của chính sản phẩm, như 'car' cho ô tô. 'Apple' cho máy tính, 'Camel' cho thuốc lá là nhãn hiệu tùy ý; 'Kodak' là từ tự tạo.", "key_fact": "Generic term là tên gọi thông thường của loại sản phẩm.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-18", "question": "Which of the followings can NOT be a registrable trademark?", "options": [{"key": "A", "text": "A symbol"}, {"key": "B", "text": "A smell"}, {"key": "C", "text": "A single colour"}, {"key": "D", "text": "A generic name of the goods"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tên chung của hàng hóa (generic) không có tính phân biệt nên bị từ chối tuyệt đối (TMA 1994 s.3). Biểu tượng, mùi (nếu biểu thị được) và màu đơn có tính phân biệt đều có thể đăng ký.", "key_fact": "Tên gọi chung của hàng hóa không thể đăng ký nhãn hiệu.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-19", "question": "What does trade libel means?", "options": [{"key": "A", "text": "Misleading advertisements and false indications of the origin of goods and services"}, {"key": "B", "text": "The original information about the quality of products or services"}, {"key": "C", "text": "An injunction against counterfeit"}, {"key": "D", "text": "A piece of information identified the products or services on mass communication"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trade libel (malicious falsehood) liên quan đến việc đưa ra tuyên bố sai lệch gây hại cho hàng hóa/dịch vụ, gắn với quảng cáo gây nhầm lẫn và chỉ dẫn sai về nguồn gốc. Các phương án khác mô tả thông tin đúng, lệnh cấm hoặc thông tin trên truyền thông, không phải trade libel.", "key_fact": "Trade libel = tuyên bố sai/gây nhầm lẫn làm tổn hại hàng hóa, dịch vụ của người khác.", "topic": "Cạnh tranh không lành mạnh", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-20", "question": "Which of the following statements is true?", "options": [{"key": "A", "text": "Fair dealing means that only insubstantial part of a work may be used"}, {"key": "B", "text": "Fair deadling with all work is permitted"}, {"key": "C", "text": "Quoting from a work in criticism or review is permitted provided that the critic or review is fair"}, {"key": "D", "text": "Developing a single part of a work is fair"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.30, fair dealing cho mục đích phê bình, bình luận được phép khi việc sử dụng là công bằng và có ghi nhận nguồn đầy đủ. A sai vì fair dealing không chỉ giới hạn ở phần không đáng kể; B sai vì fair dealing chỉ áp dụng cho các mục đích luật định.", "key_fact": "Trích dẫn để phê bình/bình luận được phép nếu công bằng, có ghi nguồn.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-21", "question": "After a sufficient use, a mark which is unregistrable may become registrable. What is the reason for this?", "options": [{"key": "A", "text": "Its reputation can be used as proof that the mark has become distinctive for the goods or service for which it has been used."}, {"key": "B", "text": "This can not be happened. The mark should be registered through an official process as stated by the laws."}, {"key": "C", "text": "The mark is automatically registered"}, {"key": "D", "text": "None of the answer is correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s3(1) proviso TMA 1994, dấu hiệu thiếu tính phân biệt có thể được đăng ký nếu qua sử dụng đã đạt tính phân biệt (acquired distinctiveness). Việc đăng ký không tự động, vẫn phải nộp đơn.", "key_fact": "Nhãn hiệu có thể đạt tính phân biệt qua quá trình sử dụng.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-22", "question": "Get-up includes:", "options": [{"key": "A", "text": "The color of packaging and the type of lettering used on a label"}, {"key": "B", "text": "A slogan used for broadcast or printed advertising"}, {"key": "C", "text": "Visual impression of business premises, such as the style of fascia board and the color of shop fittings"}, {"key": "D", "text": "All are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Get-up là hình thức trình bày tổng thể nhận diện doanh nghiệp: màu bao bì, kiểu chữ trên nhãn, khẩu hiệu quảng cáo, thậm chí phong cách cửa hàng. Theo tài liệu môn học, tất cả đều có thể là get-up được bảo vệ qua passing off.", "key_fact": "Get-up gồm bao bì, kiểu chữ, slogan, phong cách cửa hàng.", "topic": "Passing off", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-23", "question": "Which of the followings is NOT correct?", "options": [{"key": "A", "text": "The applicant must list goods/services for which the trademarks to be used"}, {"key": "B", "text": "The trademark which is registered in UK is automatically protected in Vietnam"}, {"key": "C", "text": "Under Nice Agreement, goods are divided into 34 classes"}, {"key": "D", "text": "The registration must be renewed by paying fee"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đăng ký nhãn hiệu có tính lãnh thổ: nhãn hiệu đăng ký ở Anh chỉ được bảo hộ tại Anh, muốn bảo hộ ở Việt Nam phải nộp đơn tại VN hoặc qua hệ thống Madrid. Các phương án còn lại đều đúng: phải liệt kê hàng hóa/dịch vụ, Bảng phân loại Nice có 34 nhóm hàng hóa (và 11 nhóm dịch vụ), và phải nộp phí gia hạn.", "key_fact": "Quyền nhãn hiệu mang tính lãnh thổ, không tự động được bảo hộ ở nước khác.", "topic": "Đăng ký nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-24", "question": "A salesman of a bags shop exhibited and sold a fake Chanel clutch for 1.000.000vnd (provided that the real Chanel clutch costs 20.000.000vnd). But he told clients that this clutch is fake. This is......", "options": [{"key": "A", "text": "A passing off"}, {"key": "B", "text": "Not a passing off but an infringement of trademark"}, {"key": "C", "text": "A passing off and an infringement of trademark"}, {"key": "D", "text": "Neither a passing off nor infringement of trademark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Người bán nói rõ là hàng giả nên không có sự trình bày sai đối với người mua – không phải passing off. Tuy nhiên dùng dấu hiệu trùng cho hàng hóa trùng trong thương mại vẫn xâm phạm nhãn hiệu (s10(1), Arsenal v Reed), việc tuyên bố hàng giả không loại trừ trách nhiệm.", "key_fact": "Xâm phạm nhãn hiệu không cần nhầm lẫn; passing off cần misrepresentation.", "topic": "Xâm phạm nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-25", "question": "A registered trade mark of one goods.........", "options": [{"key": "A", "text": "Can not be registered as trade mark of other goods in different classes"}, {"key": "B", "text": "Can not be registered as trade mark of services"}, {"key": "C", "text": "Can not be registered as trademark of other goods in the same class"}, {"key": "D", "text": "Can not be registered as trade mark of any service and goods"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu đã đăng ký cho một hàng hóa sẽ cản trở việc đăng ký nhãn hiệu trùng/tương tự cho hàng hóa trùng/tương tự (cùng nhóm) do khả năng nhầm lẫn (s5 TMA). Với hàng hóa khác nhóm, không liên quan, nhãn hiệu vẫn có thể đăng ký (trừ nhãn hiệu nổi tiếng).", "key_fact": "Nhãn hiệu bị chặn đăng ký cho hàng hóa trùng/tương tự với nhãn hiệu đã đăng ký.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-26", "question": "Confusion can be caused by a competitor using the most memorable part of the trade mark. Is this statement correct?", "options": [{"key": "A", "text": "Yes. The use of the most memorable part will be sufficient to generate the confusion."}, {"key": "B", "text": "No. The confusion happens when the competitor uses an identical or very similar trade mark or get-up."}, {"key": "C", "text": "No. The confusion happens only in the case of using identical marks for identical goods or services"}, {"key": "D", "text": "None of the abovementioned statement is correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhầm lẫn có thể xảy ra khi đối thủ dùng phần dễ nhớ, nổi bật nhất của nhãn hiệu, vì người tiêu dùng thường chỉ nhớ phần đặc trưng đó (đánh giá tổng thể với 'trí nhớ không hoàn hảo'). B, C sai vì không đòi hỏi trùng hoặc rất giống toàn bộ.", "key_fact": "Dùng phần nổi bật, dễ nhớ của nhãn hiệu có thể đủ gây nhầm lẫn.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-27", "question": "One of the requirements for a mark to be registered as trademark is....", "options": [{"key": "A", "text": "not an infringement of other's right"}, {"key": "B", "text": "to be new"}, {"key": "C", "text": "to be creative"}, {"key": "D", "text": "to be original"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu không được xâm phạm quyền trước của người khác (căn cứ tương đối, s5 TMA). Tính mới, sáng tạo, nguyên gốc là yêu cầu của sáng chế, quyền tác giả hoặc kiểu dáng.", "key_fact": "Nhãn hiệu không được xung đột với quyền có trước của người khác.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-28", "question": "Cellupro, a company that designed and manufactured cell phones, had a unique design to their products and a particular color for their phones and packaging. This design and color is known as", "options": [{"key": "A", "text": "trade dress."}, {"key": "B", "text": "a service mark."}, {"key": "C", "text": "a fanciful mark."}, {"key": "D", "text": "trade style."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trade dress là tổng thể hình ảnh, thiết kế, màu sắc của sản phẩm và bao bì nhận diện nguồn gốc. Service mark dùng cho dịch vụ; fanciful mark là từ tự tạo.", "key_fact": "Trade dress = diện mạo tổng thể sản phẩm/bao bì.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-29", "question": "What does three stripes on Adidas clothing represent?", "options": [{"key": "A", "text": "A trade mark."}, {"key": "B", "text": "Trade dress."}, {"key": "C", "text": "A trade secret."}, {"key": "D", "text": "A patent."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ba sọc của Adidas là dấu hiệu hình được đăng ký nhãn hiệu (figurative/position mark) để chỉ nguồn gốc thương mại. Trade dress là tổng thể bao bì/hình thức, bí mật kinh doanh và patent không phù hợp.", "key_fact": "Ba sọc Adidas là nhãn hiệu hình.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-30", "question": "According to TRIPS, is registration of sounds or smells allowed by countries?", "options": [{"key": "A", "text": "Yes. Provided that these are distinctive"}, {"key": "B", "text": "No. Only invented words permitted"}, {"key": "C", "text": "No. Only signs are permitted"}, {"key": "D", "text": "No. Since sounds or smells are not distinctive."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Điều 15 TRIPS: mọi dấu hiệu có khả năng phân biệt đều có thể làm nhãn hiệu; các quốc gia có thể đăng ký âm thanh, mùi nếu có tính phân biệt (TRIPS cho phép yêu cầu dấu hiệu nhìn thấy được nhưng không cấm). B, D sai.", "key_fact": "Âm thanh, mùi có thể đăng ký nhãn hiệu nếu có tính phân biệt.", "topic": "Nhãn hiệu quốc tế", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-31", "question": "The registration of a Community Trade Mark can be renewed every ...... years.", "options": [{"key": "A", "text": "CTM cannot be renewed"}, {"key": "B", "text": "5 years, for 4 consecutive times after the first registration"}, {"key": "C", "text": "5 years"}, {"key": "D", "text": "10 years"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu Cộng đồng (CTM/EUTM) có hiệu lực 10 năm và gia hạn không giới hạn mỗi 10 năm. 5 năm là chu kỳ của kiểu dáng đăng ký.", "key_fact": "Nhãn hiệu (UK/EU) gia hạn mỗi 10 năm, không giới hạn số lần.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-32", "question": "Company H designs a new type of fuse holder. Company M has copied freely the parts of the holder that actually contact the fuse. Which of the following is RIGHT?", "options": [{"key": "A", "text": "Company M infringed Company H's Design right."}, {"key": "B", "text": "Company M have to obtain Company H's permission before coping the parts"}, {"key": "C", "text": "Company M can copy and produced the parts without Company H's permission"}, {"key": "D", "text": "Company H can request Company M for a Design right compensation."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Các bộ phận tiếp xúc với cầu chì là đặc điểm 'must-fit' – cho phép sản phẩm kết nối với sản phẩm khác – bị loại trừ khỏi design right (s213(3)(b)(i) CDPA). Vì vậy M được sao chép mà không cần xin phép và không phải bồi thường.", "key_fact": "Đặc điểm must-fit không được bảo hộ design right.", "topic": "Quyền thiết kế", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-33", "question": "In a case on Design rights dispute, if the design right owner succeeds in proving the infringement, what cannot the Court award?", "options": [{"key": "A", "text": "An injunction to stop further manufacture or import"}, {"key": "B", "text": "An arrest warrant for the infringer"}, {"key": "C", "text": "Order payment of damages (e.g. for loss of sales by the design right owner)"}, {"key": "D", "text": "The destruction of the offending articles produced during the previous 6 years or handing them over to the design right owner"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện pháp dân sự cho xâm phạm design right gồm lệnh cấm (injunction), bồi thường thiệt hại/giao nộp lợi nhuận, và giao nộp/tiêu hủy hàng xâm phạm. Lệnh bắt giữ (arrest warrant) là biện pháp hình sự, tòa không áp dụng trong vụ kiện dân sự về design right.", "key_fact": "Xâm phạm design right chỉ có chế tài dân sự, không có lệnh bắt.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-34", "question": "The article made by Company X does not exactly the same with the article owned by Company Y but this article is only slightly different from Y's article. Which of the following is RIGHT?", "options": [{"key": "A", "text": "The article made by X is already different slightly from Y's article. It is not an infringement of design right."}, {"key": "B", "text": "It is an infringement of design right. Y, as the owner, will prevent X from copying the design."}, {"key": "C", "text": "X does not have to obtain Y's permission before making the article"}, {"key": "D", "text": "X does not have to compensate for Y's design right."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm design right bao gồm sao chép tạo sản phẩm giống hệt hoặc gần giống (substantially to the design). Sản phẩm chỉ khác chút ít vẫn là xâm phạm, nên Y có quyền ngăn chặn.", "key_fact": "Sản phẩm chỉ khác chút ít vẫn xâm phạm design right.", "topic": "Quyền thiết kế", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-35", "question": "Know-how contract can be existed under a form of relevant transaction such as joint-venture.", "options": [{"key": "A", "text": "True. Know-how contract can be existed under a form of relevant transaction such as joint-venture besides other forms."}, {"key": "B", "text": "False. Know-how contract can be existed only under a form of apprenticeship."}, {"key": "C", "text": "False. Know-how contract can be existed only under a form of franchising."}, {"key": "D", "text": "False. Know-how contract can be existed only under a form of supporting agreement."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hợp đồng know-how có thể tồn tại độc lập hoặc gắn với giao dịch liên quan như liên doanh, nhượng quyền, chuyển giao công nghệ. Các phương án 'chỉ' một hình thức là sai.", "key_fact": "Know-how có thể chuyển giao trong nhiều loại giao dịch, kể cả liên doanh.", "topic": "Thông tin bí mật", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-36", "question": "What can be defined as \"fees\"?", "options": [{"key": "A", "text": "Post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits)."}, {"key": "B", "text": "A pre-calculated amount paid once or in installments"}, {"key": "C", "text": "Compensation for services and assistance rendered by technical or professional experts."}, {"key": "D", "text": "Dividend or income from related operations; commission paid to licensor for his assistance in selling."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong hợp đồng li-xăng, 'fees' là thù lao cho dịch vụ và hỗ trợ của chuyên gia kỹ thuật. A là royalties (tính theo doanh số/lợi nhuận), B là lump sum (trả trọn gói), D là hoa hồng/lợi tức khác.", "key_fact": "Royalty = theo doanh số; lump sum = trọn gói; fees = phí dịch vụ kỹ thuật.", "topic": "Li-xăng", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-37", "question": "In which case you are the creator of an Intellectual Property?", "options": [{"key": "A", "text": "You employed someone creating the intellectual property."}, {"key": "B", "text": "You created the intellectual property by yourself."}, {"key": "C", "text": "You bought the intellectual property rights from the previous owner of the property."}, {"key": "D", "text": "You are donated the intellectual property rights from the previous owner of the property."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Người sáng tạo là người trực tiếp tạo ra tài sản trí tuệ. Thuê người khác, mua hoặc được tặng quyền chỉ làm bạn trở thành chủ sở hữu, không phải người sáng tạo.", "key_fact": "Tác giả/người sáng tạo khác với chủ sở hữu quyền.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-38", "question": "According to current Vietnam Intellectual Property Law, Intellectual Property Rights includes:", "options": [{"key": "A", "text": "Literatural works; Designs; Trademark."}, {"key": "B", "text": "Copyright and rights related to copyright; Industrial property rights; Rights to plant varieties."}, {"key": "C", "text": "Rights to tangible property"}, {"key": "D", "text": "Both of a&b"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Điều 4 Luật SHTT Việt Nam: quyền SHTT gồm quyền tác giả và quyền liên quan, quyền sở hữu công nghiệp và quyền đối với giống cây trồng. A liệt kê đối tượng chứ không phải quyền; C là quyền tài sản hữu hình.", "key_fact": "Quyền SHTT VN: quyền tác giả & liên quan, sở hữu công nghiệp, giống cây trồng.", "topic": "Luật SHTT Việt Nam", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-39", "question": "Liability for infringement of copyright can be avoided if...", "options": [{"key": "A", "text": "It is taken negligently"}, {"key": "B", "text": "It is taken intentionally"}, {"key": "C", "text": "It is used for commercial purpose"}, {"key": "D", "text": "It is used for educational purpose"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sử dụng cho mục đích giáo dục (trong giới hạn fair dealing) là ngoại lệ, nên có thể tránh trách nhiệm xâm phạm. Vô ý không loại trừ xâm phạm trực tiếp (trách nhiệm nghiêm ngặt), và mục đích thương mại càng không được miễn.", "key_fact": "Mục đích giáo dục là ngoại lệ quyền tác giả.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-40", "question": "What are criteria for winning a transfer of a domain name?", "options": [{"key": "A", "text": "A domain name must be identical or confusingly similar to a registered or unregistered trade mark, the use complained of must be by someone having no legitimate interest in the name, and bad faith"}, {"key": "B", "text": "When there is innocently confusing use, an offer to sell the mark or a history of registering names based on third party trade marks."}, {"key": "C", "text": "All are correct"}, {"key": "D", "text": "None of the answers are correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo UDRP, nguyên đơn phải chứng minh: tên miền giống hoặc tương tự gây nhầm lẫn với nhãn hiệu, người đăng ký không có quyền/lợi ích hợp pháp, và đăng ký, sử dụng với dụng ý xấu. B chỉ liệt kê một số dấu hiệu của bad faith, và 'sử dụng nhầm lẫn vô tình' không phải bad faith.", "key_fact": "UDRP: giống/gây nhầm lẫn + không có lợi ích hợp pháp + dụng ý xấu.", "topic": "Tên miền", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-41", "question": "What are Civil remedies?", "options": [{"key": "A", "text": "Provisional measures, Injunction, imprisonment"}, {"key": "B", "text": "Delivery-up, Compensatory damages, Punitive damages; and Account of profits"}, {"key": "C", "text": "Imprisonment, Punitive damages; and Account of profits"}, {"key": "D", "text": "Delivery-up, Imprisonment, Compensatory damages"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện pháp dân sự gồm giao nộp hàng (delivery-up), bồi thường thiệt hại, bồi thường mang tính trừng phạt (additional damages) và giao nộp lợi nhuận (account of profits). Phạt tù (imprisonment) là chế tài hình sự nên các phương án A, C, D sai.", "key_fact": "Phạt tù là hình sự; delivery-up, damages, account of profits là dân sự.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-42", "question": "To be granted a provisional measure order, the applicant must", "options": [{"key": "A", "text": "Provide any reasonable evidence to prove that he/she is the right holder of copyright"}, {"key": "B", "text": "Provide any reasonable evidence to prove that his/her rights are being infringed or that such infringement is imminent."}, {"key": "C", "text": "Provide security"}, {"key": "D", "text": "All of others are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Để được áp dụng biện pháp khẩn cấp tạm thời, người yêu cầu phải chứng minh mình là chủ thể quyền, chứng minh quyền đang bị xâm phạm hoặc sắp bị xâm phạm, và nộp khoản bảo đảm (security) (TRIPS Điều 50; Luật SHTT VN Điều 207-208). Vì vậy tất cả các phương án đều đúng.", "key_fact": "Biện pháp khẩn cấp tạm thời: chứng minh quyền + xâm phạm/nguy cơ + nộp bảo đảm.", "topic": "Thực thi quyền SHTT", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-43", "question": "Which one of the followings is NOT correct according to UK law?", "options": [{"key": "A", "text": "Injunction and delivery-up can be applied even in case the plaintiff suffers no damage."}, {"key": "B", "text": "Courts may apply provisional measures where any delay is likely to cause irreparable harm to the right holder."}, {"key": "C", "text": "Provisional measurers are applicable if there is a demonstrable risk of evidence being destroyed."}, {"key": "D", "text": "The combination of injunction and delivery-up is not available if there is no damage incurred to the plaintiff."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo luật UK, lệnh cấm (injunction) và buộc giao nộp (delivery-up) vẫn có thể áp dụng ngay cả khi nguyên đơn chưa chịu thiệt hại, nên D là phát biểu SAI. B, C đúng theo quy định về biện pháp tạm thời (TRIPS Điều 50).", "key_fact": "Injunction và delivery-up không đòi hỏi phải có thiệt hại.", "topic": "Chế tài", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-44", "question": "Which of the IP Laws below currently having legal validity in Viet Nam?", "options": [{"key": "A", "text": "The Intellectual Property Law No. 50/2005/QH11"}, {"key": "B", "text": "The Intellectual Property Law No. 50/2005/QH11 having been amended and supplemented in accordance with the Law No. 36/2009/QH12; the Law No. 42/2019/QH14; and the Law No. 07/2022/QH15"}, {"key": "C", "text": "The Intellectual Property Law No. 50/2005/QH11 having been amended and supplemented in accordance with the Law No. 36/2009/QH12 and the Law No. 42/2019/QH14."}, {"key": "D", "text": "All of the above"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Luật SHTT số 50/2005/QH11 đã được sửa đổi, bổ sung bởi Luật 36/2009/QH12, Luật 42/2019/QH14 và Luật 07/2022/QH15; đây là phiên bản đầy đủ nhất trong các phương án. A, C thiếu các lần sửa đổi.", "key_fact": "Luật SHTT 2005 sửa đổi 2009, 2019, 2022.", "topic": "Luật SHTT Việt Nam", "note": "", "comment_answer": "B"}, {"id": "IPR-de5-45", "question": "What is the \"public interest\" principle with regard to IP protection?", "options": [{"key": "A", "text": "It means that the protection and exercise of IP rights must be for the interests of the general public."}, {"key": "B", "text": "It means that the protection and exercise of IP rights must be for the profits of public corporations having important role for national economic development."}, {"key": "C", "text": "It means that the protection and exercise of IP rights must be balanced with the public interest, and that a balance must be maintained between the interests of right holders and the general public."}, {"key": "D", "text": "It means that the protection and exercise of IP rights must be for the interests of IP right holders."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nguyên tắc lợi ích công cộng yêu cầu bảo hộ và thực thi quyền SHTT phải cân bằng giữa lợi ích của chủ sở hữu và lợi ích công chúng. A và D đều nghiêng về một phía; B sai bản chất.", "key_fact": "Bảo hộ SHTT phải cân bằng lợi ích chủ thể quyền và công chúng.", "topic": "Tổng quan SHTT", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-46", "question": "A design for a car body is registered. Can the same design be used for:", "options": [{"key": "A", "text": "A toy car"}, {"key": "B", "text": "A chocolate bar"}, {"key": "C", "text": "A print on a tea towel"}, {"key": "D", "text": "Not any of A,B&C"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo RDA 1949 (sửa đổi), kiểu dáng đăng ký được bảo hộ đối với mọi sản phẩm, nên dùng cùng kiểu dáng thân xe cho xe đồ chơi, thanh sô-cô-la hay in trên khăn đều có thể xâm phạm. Vì vậy không được dùng cho bất kỳ sản phẩm nào trong A, B, C.", "key_fact": "Kiểu dáng đăng ký bảo hộ cho mọi sản phẩm mang kiểu dáng đó.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-47", "question": "Dennis has successfully registered his design (after 9 December 2001). After that, Mike, who with a similar design, applies to have the Dennis's registration invalidated on the grounds that the design was not new. Which of the following is RIGHT?", "options": [{"key": "A", "text": "Mike can do that only when Dennis' design has not been registered"}, {"key": "B", "text": "Mike can do that even after Dennis' design has been successful registered"}, {"key": "C", "text": "Mike cannot do that after Dennis' design has been successful registered"}, {"key": "D", "text": "Mike can do that after Dennis' design has been successful registered if Dennis design did not have individual character and was not new."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trùng câu de5-47: RDA s.11ZB cho phép yêu cầu vô hiệu bất cứ lúc nào sau khi đăng ký, căn cứ thiếu tính mới hoặc tính cá biệt (chỉ cần một). (Nguồn: https://legislation.gov.uk/ukpga/Geo6/12-13-14/88/section/11ZB)", "key_fact": "Kiểu dáng đã đăng ký vẫn có thể bị tuyên vô hiệu bất cứ lúc nào vì thiếu tính mới.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "D"}, {"id": "IPR-de5-48", "question": "A hybrid car is intended for manufacture and the design is new and not commonplace, has an individual character. Which of the followings is WRONG?", "options": [{"key": "A", "text": "The car can be protected by a registered design."}, {"key": "B", "text": "The car can be protected by a design right."}, {"key": "C", "text": "The car cannot be protected by a registered right."}, {"key": "D", "text": "Both A&B"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thiết kế xe mới, có tính cá biệt đáp ứng điều kiện đăng ký kiểu dáng; hình dạng xe cũng có thể được bảo hộ bằng design right (quyền kiểu dáng không đăng ký) nếu nguyên gốc và không tầm thường. Vì vậy câu SAI là C (nói xe không thể được bảo hộ bằng kiểu dáng đăng ký); A và B đều đúng nên D không phải đáp án.", "key_fact": "Một sản phẩm mới, có tính cá biệt có thể được bảo hộ đồng thời bằng kiểu dáng đăng ký và design right.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "C"}, {"id": "IPR-de5-49", "question": "Suspecting an infringement of his rights, Peter, the owner of a registered design has written a letter threatening to sue a suspected infringer. When can the threatened person sue Peter for making an unjustified threat?", "options": [{"key": "A", "text": "When there was no infringement"}, {"key": "B", "text": "When there is an infringement"}, {"key": "C", "text": "The person threatened cannot sue Peter in any cases"}, {"key": "D", "text": "Both B&C"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo quy định về đe dọa kiện không có căn cứ (unjustified threats), người bị đe dọa có thể kiện chủ sở hữu kiểu dáng, trừ khi chủ sở hữu chứng minh được hành vi thực sự xâm phạm. Do đó chỉ khi không có xâm phạm thì việc đe dọa mới là không có căn cứ; nếu có xâm phạm (B) thì lời đe dọa là chính đáng.", "key_fact": "Đe dọa kiện xâm phạm là 'unjustified' khi thực tế không có xâm phạm.", "topic": "Đe dọa kiện vô căn cứ", "note": "", "comment_answer": "A"}, {"id": "IPR-de5-50", "question": "A technical drawing is prepared for use in manufacturing a television set, the drawing is protected by:", "options": [{"key": "A", "text": "Design right"}, {"key": "B", "text": "Copyright"}, {"key": "C", "text": "Registered design"}, {"key": "D", "text": "Both of B&C"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bản vẽ kỹ thuật là tác phẩm nghệ thuật (graphic work) được bảo hộ quyền tác giả bất kể giá trị thẩm mỹ. Design right bảo hộ hình dạng/cấu hình của sản phẩm (chiếc TV) được ghi lại trong bản vẽ chứ không phải bản thân bản vẽ; kiểu dáng đăng ký cũng bảo hộ hình dáng sản phẩm, không bảo hộ bản vẽ.", "key_fact": "Bản thân bản vẽ kỹ thuật được bảo hộ bằng quyền tác giả (tác phẩm nghệ thuật).", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}]}, {"id": "de6", "name": "Đề 6", "questions": [{"id": "IPR-de6-1", "question": "Which of the followings is an infringement of copyright?", "options": [{"key": "A", "text": "Reading a book without consent of the author"}, {"key": "B", "text": "Listening to a song without consent of the author"}, {"key": "C", "text": "Translating an article without consent of the author"}, {"key": "D", "text": "Researching a paper without consent of the author"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Dịch tác phẩm là làm tác phẩm phái sinh (adaptation), một độc quyền của chủ sở hữu, nên dịch không xin phép là xâm phạm. Đọc sách, nghe nhạc, nghiên cứu không phải hành vi bị hạn chế.", "key_fact": "Dịch/chuyển thể (adaptation) cần sự cho phép của chủ sở hữu.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-2", "question": "One of the requirements for a mark to be registered as trademark is.....", "options": [{"key": "A", "text": "not an infringement of other's right"}, {"key": "B", "text": "to be new"}, {"key": "C", "text": "to be creative"}, {"key": "D", "text": "to be original"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu không được xâm phạm quyền trước của người khác (căn cứ tương đối, s5 TMA). Tính mới, sáng tạo, nguyên gốc là yêu cầu của sáng chế, quyền tác giả hoặc kiểu dáng.", "key_fact": "Nhãn hiệu không được xung đột với quyền có trước của người khác.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-3", "question": "How long is the duration of database right according to the UK law?", "options": [{"key": "A", "text": "Lasts for the life of its creator plus a further 70 years."}, {"key": "B", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more are jointly involved in the work"}, {"key": "C", "text": "For the works generated before 1 January 1996 the duration of database right is life plus 50 years."}, {"key": "D", "text": "Lasts for 15 years from the end of the year the database was created or made accessible"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền cơ sở dữ liệu (database right, Copyright and Rights in Databases Regulations 1997) kéo dài 15 năm kể từ cuối năm cơ sở dữ liệu được hoàn thành hoặc được công bố. Các phương án đời tác giả + 70/50 năm là thời hạn quyền tác giả, không phải database right.", "key_fact": "Database right: 15 năm từ cuối năm tạo ra hoặc công bố.", "topic": "Quyền cơ sở dữ liệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-4", "question": "A mechanical device is NOT protected by which IPR?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Design right"}, {"key": "C", "text": "Patent"}, {"key": "D", "text": "Registered design"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thiết bị cơ khí là sản phẩm chức năng: có thể được cấp patent (sáng chế), hình dạng của nó có thể có design right và hình dáng bên ngoài có thể đăng ký kiểu dáng. Bản thân thiết bị cơ khí không phải là loại tác phẩm được bảo hộ quyền tác giả (chỉ bản vẽ của nó mới có quyền tác giả).", "key_fact": "Thiết bị cơ khí không thuộc đối tượng quyền tác giả; nó được bảo hộ bằng patent/design.", "topic": "Đối tượng các quyền SHTT", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-5", "question": "The paternity right is NOT applied to:", "options": [{"key": "A", "text": "The creator of a literary, artistic, dramatic or musical copyright work and the director of a film (unless he or she is an employee)"}, {"key": "B", "text": "The designer of a building or other structure"}, {"key": "C", "text": "Computer programs or to any work created by a computer without human intervention"}, {"key": "D", "text": "An individual person and only when there is also a copyright"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA 1988 s.79, quyền được nêu tên (paternity right) không áp dụng cho chương trình máy tính và tác phẩm do máy tính tạo ra. A, B, D mô tả các chủ thể/điều kiện mà quyền này vẫn áp dụng.", "key_fact": "Quyền được nêu tên không áp dụng cho chương trình máy tính và tác phẩm do máy tính tạo ra.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-6", "question": "Which is the principle of \"independence of protection\" stipulated in Bern Convention?", "options": [{"key": "A", "text": "Works originating in one of the Contracting States must be given the same protection in each of the other Contracting States as the latter grants to the works of its own nationals"}, {"key": "B", "text": "Protection must not be conditional upon compliance with any formality"}, {"key": "C", "text": "Protection is independent of the existence of protection in the country of origin of the work"}, {"key": "D", "text": "As to works, protection must include \"every production in the literary, scientific and artistic domain, whatever the mode or form of its expression\""}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nguyên tắc 'bảo hộ độc lập' của Công ước Berne: việc bảo hộ không phụ thuộc vào việc tác phẩm có được bảo hộ ở nước xuất xứ hay không. A là đối xử quốc gia, B là bảo hộ tự động (không thủ tục).", "key_fact": "Bảo hộ độc lập = không phụ thuộc bảo hộ ở nước xuất xứ.", "topic": "Công ước Berne", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-7", "question": "The remedies available for the trademark infringement are ....... to those applicable for copyright", "options": [{"key": "A", "text": "the same"}, {"key": "B", "text": "more favorable"}, {"key": "C", "text": "less favorable"}, {"key": "D", "text": "completely different"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Trade Marks Act 1994 s.14, chủ nhãn hiệu được hưởng các biện pháp khắc phục (bồi thường, lệnh cấm, tính lợi nhuận...) giống như đối với xâm phạm bất kỳ quyền tài sản nào khác, tương tự quyền tác giả. Không có cơ sở cho rằng chế tài nhãn hiệu thuận lợi hơn hay hoàn toàn khác.", "key_fact": "Biện pháp khắc phục xâm phạm nhãn hiệu tương tự như với quyền tác giả.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-8", "question": "What is not relevant purpose for applying fair dealing", "options": [{"key": "A", "text": "Commercial purpose"}, {"key": "B", "text": "Educational purpose"}, {"key": "C", "text": "News reporting"}, {"key": "D", "text": "Reviewing purpose"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Fair dealing chỉ áp dụng cho các mục đích luật định như nghiên cứu phi thương mại/học tập cá nhân, phê bình, bình luận, đưa tin thời sự, giảng dạy. Mục đích thương mại không phải là mục đích hợp lệ của fair dealing.", "key_fact": "Mục đích thương mại không thuộc fair dealing.", "topic": "Fair dealing", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-9", "question": "Which is/are exceptions to copyright infringement?", "options": [{"key": "A", "text": "Public events"}, {"key": "B", "text": "Time shifting"}, {"key": "C", "text": "Education"}, {"key": "D", "text": "All of others are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "CDPA có các ngoại lệ như sử dụng cho giáo dục, ghi lại để xem sau (time shifting, s70), và đưa tin sự kiện công cộng/thời sự. Vì vậy chọn tất cả.", "key_fact": "Ngoại lệ quyền tác giả gồm giáo dục, time shifting, đưa tin thời sự.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-10", "question": "Which one of the followings is NOT correct according to UK law?", "options": [{"key": "A", "text": "Injunction and delivery-up can be applied even in case the plaintiff suffers no damage."}, {"key": "B", "text": "Courts may apply provisional measures where any delay is likely to cause irreparable harm to the right holder."}, {"key": "C", "text": "Provisional measurers are applicable if there is a demonstrable risk of evidence being destroyed."}, {"key": "D", "text": "The combination of injunction and delivery-up is not available if there is no damage incurred to the plaintiff."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo luật UK, lệnh cấm (injunction) và buộc giao nộp (delivery-up) vẫn có thể áp dụng ngay cả khi nguyên đơn chưa chịu thiệt hại, nên D là phát biểu SAI. B, C đúng theo quy định về biện pháp tạm thời (TRIPS Điều 50).", "key_fact": "Injunction và delivery-up không đòi hỏi phải có thiệt hại.", "topic": "Chế tài", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-11", "question": "What is the best definition about \"passing-off\"?", "options": [{"key": "A", "text": "The use of identical or similar marks or get-ups to cause confusion in the public by relying on the reputation of a mark or get-up, which has already been used long enough."}, {"key": "B", "text": "The use of different mark by relying on the reputation of a mark or get-up, which has been used long enough. However, this use is not caused any confusion."}, {"key": "C", "text": "The use of distinctive marks or get-ups to cause confusion in the public"}, {"key": "D", "text": "A trade mark infringement"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off là việc sử dụng nhãn hiệu/bao bì (get-up) giống hoặc tương tự, lợi dụng uy tín (goodwill) đã được xây dựng, gây nhầm lẫn cho công chúng và gây thiệt hại. B sai vì passing off đòi hỏi có nhầm lẫn (misrepresentation); D sai vì passing off là tort theo common law, không phải xâm phạm nhãn hiệu đăng ký.", "key_fact": "Passing off = goodwill + misrepresentation (nhầm lẫn) + thiệt hại.", "topic": "Passing off", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-12", "question": "Philips has taken a photograph of a particular scenic view. John knew about that photograph but still independently took a photograph with the same view, same perspectives. John's photograph is similar to the Philips' one. The two photographs are virtually indistinguishable.", "options": [{"key": "A", "text": "John had to ask Philips for consent before taking his photograph."}, {"key": "B", "text": "Philips can request John for a copyright compensation."}, {"key": "C", "text": "John made a copy of Philips' photograph and it is a copyright infringement."}, {"key": "D", "text": "It is not copying and not copyright infringement for John"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả không bảo hộ phong cảnh hay ý tưởng chụp; nếu John tự mình chụp cùng cảnh (sáng tạo độc lập, không sao chép ảnh của Philips) thì không phải sao chép. Giống nhau về kết quả không đủ để kết luận xâm phạm, nên A, B, C sai.", "key_fact": "Sáng tạo độc lập dù giống hệt cũng không phải xâm phạm quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-13", "question": "Which is an exception to copyright infringement?", "options": [{"key": "A", "text": "Research or private study"}, {"key": "B", "text": "If a technical paper is published in a periodical with an abstract, then copying the abstract is permitted, unless there is a licensing scheme in force"}, {"key": "C", "text": "Education"}, {"key": "D", "text": "All of others are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "CDPA 1988 quy định các ngoại lệ: nghiên cứu/học tập cá nhân, giảng dạy, và s.60 cho phép sao chép phần tóm tắt (abstract) của bài báo khoa học trừ khi có cơ chế cấp phép. Vì vậy tất cả đều đúng.", "key_fact": "Nghiên cứu, học tập, giáo dục và sao chép abstract đều là ngoại lệ của quyền tác giả.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-14", "question": "In Vietnam law, how long the trade mark protection is?", "options": [{"key": "A", "text": "5 years"}, {"key": "B", "text": "10 years"}, {"key": "C", "text": "15 years"}, {"key": "D", "text": "It depends but can last forever provided that the owner renews its application for protection"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Luật SHTT Việt Nam, văn bằng bảo hộ nhãn hiệu có hiệu lực 10 năm từ ngày nộp đơn và được gia hạn nhiều lần liên tiếp, mỗi lần 10 năm, không giới hạn số lần. Do đó bảo hộ có thể kéo dài vô thời hạn nếu gia hạn; chọn B (10 năm) chỉ đúng cho một chu kỳ.", "key_fact": "Nhãn hiệu ở VN: 10 năm, gia hạn không giới hạn số lần.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-15", "question": "Since the aim of a trade mark is to encourage purchasers to buy your company's product or service by using the mark when they place an order, what is deemed essential for a sign to be a \"good trade mark\" from business perspective?", "options": [{"key": "A", "text": "Trade marks should be slightly different from marks used by competitors to avoid confusion."}, {"key": "B", "text": "Trade marks should be easy to remember and sufficiently different from marks used by competitors to avoid confusion."}, {"key": "C", "text": "That trade marks should be easy to remember and similar to marks used by competitors to create confusion."}, {"key": "D", "text": "That trade marks should be similar to marks used by competitors to create more confusion and benefits from dilution."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu tốt phải dễ nhớ và đủ khác biệt với nhãn hiệu của đối thủ để tránh nhầm lẫn. 'Hơi khác' (A) không đủ, còn cố tình gây nhầm lẫn (C, D) dẫn đến xâm phạm/passing off.", "key_fact": "Nhãn hiệu tốt: dễ nhớ và đủ khác biệt để tránh nhầm lẫn.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-16", "question": "A Uniform Dispute Resolution Procedure (UDRP) is agreed by participants, which provide scope to resolve dispute in terms of domain names and intellectual property.", "options": [{"key": "A", "text": "True."}, {"key": "B", "text": "False. UDRP provide mechanism to resolve dispute in terms of domain names only"}, {"key": "C", "text": "False. UDRP provide mechanism to resolve dispute in terms of trade mark only"}, {"key": "D", "text": "False. UDRP provide mechanism to resolve dispute in terms of the ownership of trade mark..."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "UDRP do ICANN ban hành và được các bên đăng ký tên miền chấp nhận qua hợp đồng; nó giải quyết tranh chấp giữa tên miền và quyền nhãn hiệu (một loại quyền SHTT) của bên khiếu nại. Vì vậy nhận định 'tên miền và SHTT' là đúng; B, C, D thu hẹp sai phạm vi.", "key_fact": "UDRP giải quyết tranh chấp tên miền xung đột với quyền nhãn hiệu, ràng buộc người đăng ký qua hợp đồng.", "topic": "Tên miền", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-17", "question": "Are domain names intellectual property?", "options": [{"key": "A", "text": "Not really"}, {"key": "B", "text": "Yes, they are"}, {"key": "C", "text": "Yes, provided that domain names are registered with the Internet service providers"}, {"key": "D", "text": "Yes, since domain names provides the exact information of the owner of goods or services"}], "answer": ["A"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Tên miền tự thân không phải quyền SHTT: đăng ký tên miền giống đăng ký tên công ty, không tạo quyền SHTT; nó chỉ được bảo vệ gián tiếp khi hoạt động như nhãn hiệu hoặc qua passing off/UDRP (One in a Million, Yoyo.email). (Nguồn: https://www.dyoung.com/de/wissensbank/artikel/yoyorbs ; https://sprintlaw.co.uk/articles/protecting-your-domain-names-as-intellectual-property-a-legal-guide-for-businesses/)", "key_fact": "Tên miền ≠ IP tự thân; bảo vệ qua trade mark/passing off/UDRP.", "topic": "Tên miền", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-18", "question": "What are Civil remedies?", "options": [{"key": "A", "text": "Provisional measures, Injunction, imprisonment"}, {"key": "B", "text": "Delivery-up, Compensatory damages, Punitive damages; and Account of profits"}, {"key": "C", "text": "Imprisonment, Punitive damages; and Account of profits"}, {"key": "D", "text": "Delivery-up, Imprisonment, Compensatory damages"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện pháp dân sự gồm giao nộp hàng (delivery-up), bồi thường thiệt hại, bồi thường mang tính trừng phạt (additional damages) và giao nộp lợi nhuận (account of profits). Phạt tù (imprisonment) là chế tài hình sự nên các phương án A, C, D sai.", "key_fact": "Phạt tù là hình sự; delivery-up, damages, account of profits là dân sự.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-19", "question": "Cellupro, a company that designed and manufactured cell phones, had a unique design to their particular color for their phones and packaging. This design and color is known as", "options": [{"key": "A", "text": "trade dress."}, {"key": "B", "text": "a service mark."}, {"key": "C", "text": "a fanciful mark."}, {"key": "D", "text": "trade style."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trade dress là tổng thể hình thức bên ngoài, màu sắc, bao bì đặc trưng của sản phẩm giúp nhận biết nguồn gốc. Service mark dùng cho dịch vụ, fanciful mark là từ được sáng tạo.", "key_fact": "Màu sắc, kiểu dáng bao bì đặc trưng = trade dress.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-20", "question": "What does a trademark protect?", "options": [{"key": "A", "text": "A work of art"}, {"key": "B", "text": "A secret formula"}, {"key": "C", "text": "Logos, names and brands"}, {"key": "D", "text": "General information"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu bảo hộ dấu hiệu phân biệt như logo, tên, thương hiệu. Tác phẩm nghệ thuật thuộc quyền tác giả, công thức bí mật thuộc thông tin bí mật.", "key_fact": "Nhãn hiệu bảo hộ dấu hiệu phân biệt nguồn gốc hàng hóa/dịch vụ.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-21", "question": "The protection of copyright excludes", "options": [{"key": "A", "text": "A single word"}, {"key": "B", "text": "Songs"}, {"key": "C", "text": "A list of names and addresses in a telephone directory"}, {"key": "D", "text": "Computer programs"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Một từ đơn lẻ (kể cả từ sáng tạo như 'Exxon') không đủ là tác phẩm văn học để được bảo hộ quyền tác giả. Bài hát, chương trình máy tính và danh bạ điện thoại (có công sức biên soạn) đều có thể được bảo hộ.", "key_fact": "Một từ đơn lẻ không được bảo hộ quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-22", "question": "Which is NOT right about \"Copying in a different medium\"?", "options": [{"key": "A", "text": "a photocopy of a book."}, {"key": "B", "text": "a scanned-in digital copy of a photograph"}, {"key": "C", "text": "a reproduction and the copy have a material form"}, {"key": "D", "text": "a translation a copyright work"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sao chép sang phương tiện khác (photocopy sách, scan ảnh thành bản số) là hành vi sao chép (reproduction) dưới hình thức vật chất. Bản dịch là hành vi phóng tác (adaptation) chứ không phải sao chép sang phương tiện khác.", "key_fact": "Dịch tác phẩm là phóng tác, không phải sao chép sang phương tiện khác.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-23", "question": "Acme Corporation attempted to register a trade mark that was generic and not fanciful, arbitrary, suggestive or descriptive with a secondary meaning. Under these circumstances, Acme has", "options": [{"key": "A", "text": "An excellent case for the registration of a trade mark because generic trade marks, as opposed to arbitrary or suggestive trade marks, are capable of being copyrighted."}, {"key": "B", "text": "An excellent case for the registration of a trade mark because all trade marks are capable of being copyrighted."}, {"key": "C", "text": "No case for registration of the trade mark because a trade mark must be fanciful, arbitrary or suggestive, or descriptive with a secondary meaning, to be capable of being copyrighted."}, {"key": "D", "text": "No case for registration of the trade mark because a trade mark must be independent, rather than fanciful, arbitrary or suggestive, to be capable of being copyrighted."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Từ chung (generic) không thể đăng ký làm nhãn hiệu vì không có khả năng phân biệt; nhãn hiệu phải là tưởng tượng, tùy ý, gợi ý, hoặc mô tả nhưng đã có ý nghĩa thứ cấp. A, B sai vì nhãn hiệu generic không được bảo hộ.", "key_fact": "Nhãn hiệu chung (generic) không thể đăng ký.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-24", "question": "The \"Commonplace\", which is the requirement for protection of design right, means:", "options": [{"key": "A", "text": "The similarities of the design in question when compared objectively to other designs"}, {"key": "B", "text": "\"Not original\" in the design field in question."}, {"key": "C", "text": "None of A&B"}, {"key": "D", "text": "Both of A&B"}], "answer": ["D"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "CDPA s.213(4): kiểu dáng 'không nguyên gốc' nếu nó commonplace trong lĩnh vực thiết kế (B); Farmers Build v Carier Bulk yêu cầu so sánh khách quan với các thiết kế khác trong lĩnh vực (A). Cả hai đều đúng. (Nguồn: https://www.legislation.gov.uk/ukpga/1988/48/section/213)", "key_fact": "Commonplace = không original trong lĩnh vực; xét bằng so sánh khách quan.", "topic": "Design right", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-25", "question": "What protects the intellectual property created by designers?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Registered designs"}, {"key": "C", "text": "Both copyright and registered designs"}, {"key": "D", "text": "Neither copyright nor registered designs"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thành quả của nhà thiết kế có thể được bảo hộ bằng quyền tác giả (bản vẽ, tác phẩm nghệ thuật) và kiểu dáng đăng ký (hình dáng sản phẩm), ngoài ra còn design right. Chọn một loại riêng lẻ là không đầy đủ.", "key_fact": "Thiết kế được bảo hộ bằng cả quyền tác giả và kiểu dáng đăng ký.", "topic": "Bảo hộ kiểu dáng", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-26", "question": "What are criteria for winning a transfer of a domain name?", "options": [{"key": "A", "text": "A domain name must be identical or confusingly similar to a registered or unregistered trade mark, the domain name complained of must be by someone having no legitimate interest in the name, and bad faith"}, {"key": "B", "text": "When there is innocently confusing use, an offer to sell the mark or a history of registering domain names based on third party trade marks."}, {"key": "C", "text": "All are correct"}, {"key": "D", "text": "None of the answers are correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo UDRP, bên khiếu nại phải chứng minh 3 yếu tố: tên miền trùng/tương tự gây nhầm lẫn với nhãn hiệu của mình, bên đăng ký không có quyền/lợi ích hợp pháp, và đăng ký/sử dụng với dụng ý xấu. B sai vì sử dụng nhầm lẫn 'vô tình' không phải dấu hiệu dụng ý xấu.", "key_fact": "UDRP: tương tự gây nhầm lẫn + không có lợi ích hợp pháp + dụng ý xấu.", "topic": "Tên miền", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-27", "question": "A Uniform Dispute Resolution Procedure (UDRP) is run by", "options": [{"key": "A", "text": "WIPO"}, {"key": "B", "text": "WTO"}, {"key": "C", "text": "UN"}, {"key": "D", "text": "UNCITRAL"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "UDRP do ICANN thông qua và được thực hiện bởi các tổ chức giải quyết tranh chấp, trong đó nổi bật nhất là Trung tâm Trọng tài và Hòa giải của WIPO. WTO, UN, UNCITRAL không vận hành UDRP.", "key_fact": "WIPO là tổ chức chính giải quyết tranh chấp tên miền theo UDRP.", "topic": "Tên miền", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-28", "question": "What does indirect compensation include?", "options": [{"key": "A", "text": "post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits)."}, {"key": "B", "text": "a pre-calculated amount paid once or in installments"}, {"key": "C", "text": "compensation for services and assistance rendered by technical or professional experts."}, {"key": "D", "text": "dividend or income from related operations: commission paid to licensor for his assistance in selling."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo tài liệu WIPO về li-xăng, khoản bồi hoàn trực tiếp gồm khoản trả gọn (lump sum) và phí bản quyền tính theo doanh số/lợi nhuận (A, B), cùng phí dịch vụ hỗ trợ kỹ thuật; khoản bồi hoàn gián tiếp gồm cổ tức hoặc thu nhập từ hoạt động liên quan như hoa hồng cho bên cấp phép. Vì vậy D đúng.", "key_fact": "Bồi hoàn gián tiếp trong li-xăng: cổ tức, thu nhập từ hoạt động liên quan, hoa hồng.", "topic": "Li-xăng", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-29", "question": "Knowing Kevin is a self-employed designer, Charlotte has introduced Kevin to Company X. The company then commissioned Kevin for 1500 Euro to design a machine. Who owns the right to the registered design of the machine?", "options": [{"key": "A", "text": "Kevin himself"}, {"key": "B", "text": "Company X"}, {"key": "C", "text": "Charlotte"}, {"key": "D", "text": "Company X and Kevin"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo quy tắc của RDA 1949 áp dụng trong giáo trình (trước sửa đổi bởi IP Act 2014), bên đặt hàng có trả tiền (commissioner) là chủ sở hữu kiểu dáng được tạo ra theo đơn đặt hàng, nên Company X sở hữu. Charlotte chỉ giới thiệu nên không có quyền; lưu ý từ 1/10/2014 luật Anh đã đổi: nhà thiết kế (Kevin) là chủ sở hữu trừ khi có thỏa thuận khác.", "key_fact": "Kiểu dáng đặt hàng (theo giáo trình cũ): bên đặt hàng là chủ sở hữu.", "topic": "Chủ sở hữu kiểu dáng", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-30", "question": "Pictorial design or logo is protected by which IPRs?", "options": [{"key": "A", "text": "Copyright, registered design, trademark"}, {"key": "B", "text": "Topography right, trademark, design right"}, {"key": "C", "text": "Registered design, confidential information, copyright"}, {"key": "D", "text": "Topography right, confidential information, copyright"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Hình vẽ/logo có thể được bảo hộ bằng quyền tác giả (tác phẩm nghệ thuật), kiểu dáng đăng ký (họa tiết/kiểu dáng 2D) và nhãn hiệu (dấu hiệu phân biệt). Topography right chỉ dành cho mạch bán dẫn, còn design right không bảo hộ trang trí bề mặt.", "key_fact": "Logo: quyền tác giả + kiểu dáng đăng ký + nhãn hiệu.", "topic": "Đối tượng các quyền SHTT", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-31", "question": "How long is the duration of computer-generated right according to the UK law?", "options": [{"key": "A", "text": "Lasts for the life of its creator plus a further 50 years."}, {"key": "B", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more are jointly involved in the work"}, {"key": "C", "text": "The copyright lasts for 50 years from the end of the year in which the copyright material was made"}, {"key": "D", "text": "Lasts for 15 years from the end of the year the database was created or made accessible"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA 1988 s.12(7), tác phẩm do máy tính tạo ra được bảo hộ 50 năm kể từ cuối năm tác phẩm được tạo ra (không có tác giả là con người nên không tính theo đời người). D là thời hạn quyền cơ sở dữ liệu.", "key_fact": "Tác phẩm do máy tính tạo ra: 50 năm từ cuối năm tạo ra.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-32", "question": "In the 1990s, there was an explosion of names registered by US Network Solutions, the administrator of the top level domain (TLD) with the suffix .com. What sorts of problems quickly arose then:", "options": [{"key": "A", "text": "Owners of trade marks identical to the domain name objected to use of the domain name, and unscrupulous persons registered variations of famous company names and offered to sell them for large sums of money - this is called cyber-squatting."}, {"key": "B", "text": "Company can easily get their domain name as they wish on the Internet, and this is easier to build a famous brand."}, {"key": "C", "text": "People can register for domain names easier and provide such names to anyone in need."}, {"key": "D", "text": "Nothing happened."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sự bùng nổ đăng ký tên miền .com dẫn đến xung đột với chủ nhãn hiệu và hiện tượng cybersquatting – đăng ký tên của các công ty nổi tiếng rồi bán lại với giá cao. B, C, D không mô tả vấn đề phát sinh.", "key_fact": "Bùng nổ tên miền dẫn đến cybersquatting và xung đột nhãn hiệu.", "topic": "Tên miền", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-33", "question": "If a company develops a new technology for producing a special range of clothes, what type of intellectual property right can it use to prevent other from using such technology", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Trademarks"}, {"key": "C", "text": "Registered designs"}, {"key": "D", "text": "Patents"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Công nghệ/quy trình sản xuất mới là sáng chế, được bảo hộ bằng patent, cho phép ngăn người khác sử dụng kể cả khi họ phát triển độc lập. Quyền tác giả, nhãn hiệu, kiểu dáng không bảo hộ giải pháp kỹ thuật.", "key_fact": "Công nghệ/quy trình sản xuất mới được bảo hộ bằng patent.", "topic": "Sáng chế", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-34", "question": "Cindy has very detailed and interesting ideas on writing a book. Based on these ideas, David wrote a book without attribution of Cindy. David .......", "options": [{"key": "A", "text": "Infringes paternity right"}, {"key": "B", "text": "Infringes adaptation right"}, {"key": "C", "text": "Infringes reproduction right"}, {"key": "D", "text": "Not infringes intellectual property right"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả không bảo hộ ý tưởng mà chỉ bảo hộ hình thức thể hiện. David tự viết sách dựa trên ý tưởng của Cindy nên không xâm phạm; Cindy không phải tác giả nên không có quyền được nêu tên (A).", "key_fact": "Ý tưởng không được bảo hộ quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-35", "question": "To be protected by registered design, an article must ....", "options": [{"key": "A", "text": "Have an individual character"}, {"key": "B", "text": "Be original"}, {"key": "C", "text": "Be non- commonplace"}, {"key": "D", "text": "Be new"}], "answer": ["A"], "multi": false, "confidence": "low", "source": "ai", "explanation": "RDA s.1B(1): kiểu dáng đăng ký phải MỚI VÀ có TÍNH CÁ BIỆT, nên về luật cả A và D đều đúng; B, C là điều kiện của design right không đăng ký. Nếu đề cho chọn nhiều thì chọn A+D; nếu chọn một, A là điều kiện đặc trưng riêng của registered design. (Nguồn: https://www.legislation.gov.uk/ukpga/Geo6/12-13-14/88/section/1B)", "key_fact": "Registered design: new + individual character; design right: original + not commonplace.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-36", "question": "Which of these statements is true about the general nature of passing off?", "options": [{"key": "A", "text": "The defendant must intend to cause loss"}, {"key": "B", "text": "The misrepresentation must be intentional"}, {"key": "C", "text": "There must be a false representation"}, {"key": "D", "text": "There must be actual damages"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off bắt buộc phải có sự trình bày sai (misrepresentation), nhưng không cần cố ý (lỗi vô ý vẫn có thể bị coi là passing off) và không cần thiệt hại thực tế (chỉ cần khả năng thiệt hại). Vì vậy A, B, D sai.", "key_fact": "Passing off cần misrepresentation, không cần ý định gây hại.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-37", "question": "Design right applies to:", "options": [{"key": "A", "text": "Drawings produced in an industrial context"}, {"key": "B", "text": "Tangible three-dimensional Articles"}, {"key": "C", "text": "Artistic drawings"}, {"key": "D", "text": "Textbook on Design rights"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Design right (CDPA 1988 Part III) bảo hộ hình dạng hoặc cấu hình của sản phẩm ba chiều hữu hình. Bản vẽ (A, C) được bảo hộ bằng quyền tác giả; design right không áp dụng cho trang trí bề mặt.", "key_fact": "Design right bảo hộ hình dạng/cấu hình 3D của sản phẩm.", "topic": "Design right", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-38", "question": "Which of followings is correct?", "options": [{"key": "A", "text": "Passing off is an infringement of only unregistered trademark"}, {"key": "B", "text": "Passing off is an infringement of only registered trademark"}, {"key": "C", "text": "Passing off is an infringement of both unregistered and registered trademark"}, {"key": "D", "text": "Passing off is an infringement of neither unregistered nor registered trademark"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off bảo vệ goodwill, nên có thể áp dụng cho cả nhãn hiệu chưa đăng ký và đã đăng ký (TMA 1994 s.2(2) giữ nguyên quyền kiện passing off). A dễ gây nhầm vì passing off thường dùng cho nhãn chưa đăng ký, nhưng không chỉ giới hạn ở đó.", "key_fact": "Passing off dùng được cho cả nhãn hiệu đăng ký và chưa đăng ký.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-39", "question": "Anders is the copyright owner of Computer programs. Without Anders' permission, Tine has authorised Charlotte, the one working under contract with Tine, to make an copy of Anders' Computer programs with something added. The act of Tine is:", "options": [{"key": "A", "text": "A secondary infringement of Anders' Copyrights"}, {"key": "B", "text": "A primary infringement of Anders' Copyrights"}, {"key": "C", "text": "Not a copyright infringement"}, {"key": "D", "text": "Both A&B"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.16(2), cho phép (authorise) người khác thực hiện hành vi thuộc độc quyền (sao chép, phóng tác chương trình) mà không được phép là xâm phạm trực tiếp (primary infringement). Xâm phạm thứ cấp liên quan đến buôn bán, nhập khẩu, tàng trữ bản sao xâm phạm, không phải hành vi cho phép sao chép.", "key_fact": "Cho phép người khác sao chép trái phép là xâm phạm trực tiếp (primary).", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-40", "question": "Which is the principle of \"national treatment\" stipulated in Bern Convention?", "options": [{"key": "A", "text": "Works originating in one of the Contracting States must be given the same protection in each of the other Contracting States as the latter grants to the works of its own nationals"}, {"key": "B", "text": "Protection must not be conditional upon compliance with any formality"}, {"key": "C", "text": "Protection is independent of the existence of protection in the country of origin of the work"}, {"key": "D", "text": "As to works, protection must include \"every production in the literary, scientific and artistic domain, whatever the mode or form of its expression\""}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nguyên tắc đối xử quốc gia của Công ước Berne: tác phẩm có nguồn gốc từ một nước thành viên được bảo hộ ở các nước thành viên khác như tác phẩm của công dân nước đó. B là bảo hộ tự động, C là bảo hộ độc lập.", "key_fact": "Đối xử quốc gia = bảo hộ như với công dân nước mình.", "topic": "Công ước Berne", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-41", "question": "What can be defined as \"fees\"?", "options": [{"key": "A", "text": "Post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits)."}, {"key": "B", "text": "A pre-calculated amount paid once or in installments"}, {"key": "C", "text": "Compensation for services and assistance rendered by technical or professional experts."}, {"key": "D", "text": "Dividend or income from related operations: commission paid to licensor for his assistance in selling."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong hợp đồng li-xăng, 'fees' là thù lao cho dịch vụ và hỗ trợ của chuyên gia kỹ thuật. A là royalties (tính theo doanh số/lợi nhuận), B là lump sum (trả trọn gói), D là hoa hồng/lợi tức khác.", "key_fact": "Royalty = theo doanh số; lump sum = trọn gói; fees = phí dịch vụ kỹ thuật.", "topic": "Li-xăng", "note": "", "comment_answer": "C"}, {"id": "IPR-de6-42", "question": "Company M subcontracts Company H to copy and make a product which owned by Company N with a clear instruction to manufacture the copy. Company H knows the product is owned by Company N. Which of the following is RIGHT?", "options": [{"key": "A", "text": "M has transferred the legal burden to H on the infringement of Design right."}, {"key": "B", "text": "H is not responsible for the infringement"}, {"key": "C", "text": "M is not responsible for the infringement as it is not the one drectly coppied and made the product."}, {"key": "D", "text": "Both H & M infringed N's Design right."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "H trực tiếp sao chép và sản xuất sản phẩm theo thiết kế của N nên xâm phạm design right; M chỉ thị/cho phép việc sao chép nên cũng phải chịu trách nhiệm (cùng xâm phạm). Không thể 'chuyển' trách nhiệm pháp lý sang nhà thầu phụ như A, C nêu.", "key_fact": "Cả bên đặt làm và bên trực tiếp sao chép đều xâm phạm design right.", "topic": "Design right", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-43", "question": "A salesman of a bags shop exhibited and sold a fake Chanel clutch for 1.000.000vnd (provided that the real Chanel clutch costs 20.000.000vnd). But he told clients that this clutch is fake. This is......", "options": [{"key": "A", "text": "A passing off"}, {"key": "B", "text": "Not a passing off but an infringement of trademark"}, {"key": "C", "text": "A passing off and an infringement of trademark"}, {"key": "D", "text": "Neither a passing off nor infringement of trademark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Người bán nói rõ là hàng giả nên không có sự trình bày sai đối với người mua – không phải passing off. Tuy nhiên dùng dấu hiệu trùng cho hàng hóa trùng trong thương mại vẫn xâm phạm nhãn hiệu (s10(1), Arsenal v Reed), việc tuyên bố hàng giả không loại trừ trách nhiệm.", "key_fact": "Xâm phạm nhãn hiệu không cần nhầm lẫn; passing off cần misrepresentation.", "topic": "Xâm phạm nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-44", "question": "Which is considered as copying by adaption?", "options": [{"key": "A", "text": "Adapting a copyright work, which includes translating it."}, {"key": "B", "text": "Copying one line of a well-known song in a nontechnical context"}, {"key": "C", "text": "The extraction or reutilization of a computer-stored database, whether the whole or a substantial part"}, {"key": "D", "text": "A photocopy of a book, or a scanned-in digital copy of a photograph"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Phóng tác (adaptation) theo CDPA s.21 bao gồm dịch, chuyển thể tác phẩm. B là việc dùng phần không đáng kể, C là xâm phạm database right, D là sao chép sang phương tiện khác.", "key_fact": "Dịch tác phẩm là hành vi phóng tác.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-45", "question": "Collective trade mark means..........", "options": [{"key": "A", "text": "There are many users of this trade mark"}, {"key": "B", "text": "There are many owners of this trade mark"}, {"key": "C", "text": "There is a collection of trademarks used by one company"}, {"key": "D", "text": "There is a collection of products sharing this trade mark"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu tập thể thuộc sở hữu của một hiệp hội và được nhiều thành viên của hiệp hội sử dụng để phân biệt hàng hóa/dịch vụ của thành viên. Chủ sở hữu là một tổ chức duy nhất, nên B sai.", "key_fact": "Nhãn hiệu tập thể: một chủ (hiệp hội), nhiều người sử dụng (thành viên).", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de6-46", "question": "Which of the following form of a spoken word is NOT protected by copyright?", "options": [{"key": "A", "text": "A fully prepared text"}, {"key": "B", "text": "A note"}, {"key": "C", "text": "In shorthand, or on tape or disk"}, {"key": "D", "text": "None of the answer is correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Lời nói được bảo hộ quyền tác giả khi được ghi lại dưới dạng viết hoặc hình thức khác (văn bản soạn sẵn, ghi chú, tốc ký, băng, đĩa). Tất cả các hình thức A, B, C đều là bản ghi nên đều được bảo hộ; do đó không có phương án nào là 'không được bảo hộ'.", "key_fact": "Lời nói được bảo hộ khi đã được ghi lại dưới bất kỳ hình thức nào.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de6-47", "question": "A trade mark being an invented word must ......", "options": [{"key": "A", "text": "Be new"}, {"key": "B", "text": "Be distinctive"}, {"key": "C", "text": "Indicate the nature of the goods"}, {"key": "D", "text": "Be meaningful"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Từ sáng tạo (invented word) được đăng ký vì có khả năng phân biệt cao; yêu cầu cốt lõi của nhãn hiệu là tính phân biệt. Nhãn hiệu không cần 'mới' như sáng chế, không cần có nghĩa, và việc chỉ ra tính chất hàng hóa (C) là mô tả, bị từ chối.", "key_fact": "Nhãn hiệu (kể cả từ sáng tạo) phải có tính phân biệt.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-48", "question": "Which of the followings is not secondary infringement of copyrights?", "options": [{"key": "A", "text": "A copy is distributed either internally within a business or outside the company"}, {"key": "B", "text": "A single copy of a computer program bought abroad, and brought it home for using in connection with professional engineering work."}, {"key": "C", "text": "Photocopying of a book"}, {"key": "D", "text": "Showing a TV broadcast, cable programme, film or playing music to the public"}], "answer": ["C"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Photocopy sách là sao chép – xâm phạm trực tiếp (CDPA s.16-17); nhập khẩu bản sao (s.22) và phân phối trong kinh doanh (s.23) là xâm phạm thứ cấp. Lưu ý: theo CDPA s.19 việc chiếu phim/phát nhạc công cộng (D) cũng là xâm phạm trực tiếp, nên nếu đề chọn nhiều thì có thể là C+D; đáp án đơn hợp lý nhất vẫn là C. (Nguồn: https://www.legislation.gov.uk/ukpga/1988/48/part/I/chapter/II)", "key_fact": "Copying = primary; importing/dealing = secondary.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-49", "question": "To protect Registered Design, an owner of Registered design needs to do:", "options": [{"key": "A", "text": "Show that there has been copying."}, {"key": "B", "text": "Show that the same or a substantially similar design is being applied to a product."}, {"key": "C", "text": "Prove that the design was not created independently by the infringer"}, {"key": "D", "text": "All of the above"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiểu dáng đăng ký là độc quyền tuyệt đối: chủ sở hữu chỉ cần chứng minh kiểu dáng giống hoặc không tạo ấn tượng tổng thể khác được áp dụng cho sản phẩm. Không cần chứng minh có sao chép (A, C) – đó là yêu cầu của design right không đăng ký và quyền tác giả.", "key_fact": "Xâm phạm kiểu dáng đăng ký không cần chứng minh sao chép.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de6-50", "question": "Dennis has successfully registered his design (after 9 December 2001). After that, Mike, who with a similar design, applies to have the Dennis's registration invalidated on the grounds that the design was not new. Which of the following is RIGHT?", "options": [{"key": "A", "text": "Mike can do that only when Dennis' design has not been registered"}, {"key": "B", "text": "Mike can do that even after Dennis' design has been successful registered"}, {"key": "C", "text": "Mike cannot do that after Dennis' design has been successful registered"}, {"key": "D", "text": "Mike can do that after Dennis' design has been successful registered if Dennis design did not have individual character and was not new."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trùng câu de5-47: RDA s.11ZB cho phép yêu cầu vô hiệu bất cứ lúc nào sau khi đăng ký, căn cứ thiếu tính mới hoặc tính cá biệt (chỉ cần một). (Nguồn: https://legislation.gov.uk/ukpga/Geo6/12-13-14/88/section/11ZB)", "key_fact": "Kiểu dáng đã đăng ký vẫn có thể bị tuyên vô hiệu bất cứ lúc nào vì thiếu tính mới.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "D"}]}, {"id": "de7", "name": "Đề 7", "questions": [{"id": "IPR-de7-1", "question": "Anders has created a triangle classes box. The box could have been protected by a registered design but no application was filed. What is the requirement if the box is protected by Design right?", "options": [{"key": "A", "text": "Novelty"}, {"key": "B", "text": "Not commonplace"}, {"key": "C", "text": "Individual character"}, {"key": "D", "text": "All of the above"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Design right không đăng ký (CDPA s.213) yêu cầu thiết kế nguyên gốc và không tầm thường (not commonplace) trong lĩnh vực thiết kế. Tính mới và tính cá biệt (A, C) là điều kiện của kiểu dáng đăng ký.", "key_fact": "Design right: nguyên gốc và không tầm thường.", "topic": "Design right", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-2", "question": "Secondary copyright infringement is:", "options": [{"key": "A", "text": "Copying the material without permission."}, {"key": "B", "text": "Trading of those illegal copies"}, {"key": "C", "text": "Rewriting the material without permission."}, {"key": "D", "text": "Scanning the material without permission."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm thứ cấp là hành vi buôn bán, nhập khẩu, phân phối bản sao xâm phạm (ss22-26 CDPA). Sao chép, viết lại, scan là xâm phạm trực tiếp.", "key_fact": "Xâm phạm thứ cấp = kinh doanh bản sao xâm phạm.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-3", "question": "Primary copyright infringement is:", "options": [{"key": "A", "text": "Trading of those illegal copies"}, {"key": "B", "text": "Copying the material without permission."}, {"key": "C", "text": "Rewriting the material with permission."}, {"key": "D", "text": "Both of A&C"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm trực tiếp (primary infringement) là thực hiện hành vi bị hạn chế như sao chép mà không được phép. Buôn bán bản sao lậu là xâm phạm gián tiếp (secondary), còn viết lại có phép thì không xâm phạm.", "key_fact": "Primary = sao chép trái phép; secondary = buôn bán bản sao lậu.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-4", "question": "A Uniform Dispute Resolution Procedure (UDRP) is agreed by participants, which provide some mechanism to resolve dispute in terms of domain names and intellectual property.", "options": [{"key": "A", "text": "True."}, {"key": "B", "text": "False. UDRP provide mechanism to resolve dispute in terms of domain names only"}, {"key": "C", "text": "False. UDRP provide mechanism to resolve dispute in terms of trade mark only"}, {"key": "D", "text": "False. UDRP provide mechanism to resolve dispute in terms of the ownership of trade mark only."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "UDRP được các bên đăng ký tên miền chấp nhận qua hợp đồng và cung cấp cơ chế giải quyết tranh chấp giữa tên miền và quyền SHTT (nhãn hiệu). Các phương án B, C, D thu hẹp sai phạm vi của UDRP.", "key_fact": "UDRP là cơ chế giải quyết tranh chấp tên miền liên quan đến quyền nhãn hiệu.", "topic": "Tên miền", "note": "", "comment_answer": "A"}, {"id": "IPR-de7-5", "question": "A technical drawing is prepared for use in manufacturing a television set, the drawing is protected by:", "options": [{"key": "A", "text": "Design right"}, {"key": "B", "text": "Copyright"}, {"key": "C", "text": "Registered design"}, {"key": "D", "text": "Both of B&C"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bản vẽ kỹ thuật là tác phẩm nghệ thuật (graphic work) được bảo hộ quyền tác giả bất kể giá trị thẩm mỹ. Design right bảo hộ hình dạng/cấu hình của sản phẩm (chiếc TV) được ghi lại trong bản vẽ chứ không phải bản thân bản vẽ; kiểu dáng đăng ký cũng bảo hộ hình dáng sản phẩm, không bảo hộ bản vẽ.", "key_fact": "Bản thân bản vẽ kỹ thuật được bảo hộ bằng quyền tác giả (tác phẩm nghệ thuật).", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-6", "question": "Regarding to Registration period for a registered design. Which of the following is WRONG?", "options": [{"key": "A", "text": "The initial registration period for a design last for 5 years from the application date."}, {"key": "B", "text": "The registration can be kept in force for four subsequent periods of 5 years (after the initial registration period), automatically, without fees."}, {"key": "C", "text": "The registration can be kept in force for four subsequent periods of 5 years, (after the initial registration period), if renewal fees are paid."}, {"key": "D", "text": "The registration period for a design last for 5 years only from the application date. After that period, the registration will not be extended if the owner does not pay the renewal fees"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiểu dáng đăng ký (RDA 1949) có thời hạn ban đầu 5 năm kể từ ngày nộp đơn, có thể gia hạn thêm 4 lần mỗi lần 5 năm (tối đa 25 năm) nhưng phải nộp phí gia hạn. Vì vậy phát biểu B 'tự động, không cần phí' là SAI. C và D đều đúng vì gia hạn phụ thuộc việc nộp phí.", "key_fact": "Kiểu dáng đăng ký: 5 năm, gia hạn 4 lần x 5 năm khi nộp phí, tối đa 25 năm.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-7", "question": "Which of the followings is protected by copyright", "options": [{"key": "A", "text": "A word"}, {"key": "B", "text": "An idea"}, {"key": "C", "text": "A legal document"}, {"key": "D", "text": "An express of an idea"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả bảo hộ hình thức thể hiện của ý tưởng, không bảo hộ bản thân ý tưởng (B) hay một từ đơn lẻ (A). Văn bản pháp lý chính thức (C) thường không được xem là đối tượng bảo hộ thông thường.", "key_fact": "Quyền tác giả bảo hộ hình thức thể hiện, không bảo hộ ý tưởng.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-8", "question": "Referring to a trade mark in news is.......", "options": [{"key": "A", "text": "A primary infringement of trade mark"}, {"key": "B", "text": "A secondary infringement of trade mark"}, {"key": "C", "text": "Not an infringement of trade mark"}, {"key": "D", "text": "An infringement of copyright"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhắc đến nhãn hiệu trong tin tức không phải là sử dụng trong hoạt động thương mại (in the course of trade) nên không xâm phạm nhãn hiệu. Cũng không phải xâm phạm quyền tác giả.", "key_fact": "Xâm phạm nhãn hiệu đòi hỏi sử dụng 'in the course of trade'.", "topic": "Xâm phạm nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-9", "question": "For the purpose of showing damage in a passing-off action, the owner must.......", "options": [{"key": "A", "text": "Show actual loss"}, {"key": "B", "text": "Demonstrate high risk of loss of business arising from the confusion"}, {"key": "C", "text": "Calculate the number of clients before and after passing off occurs"}, {"key": "D", "text": "Proving the activity of imitation"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong passing off (Jif Lemon), yếu tố thiệt hại chỉ cần chứng minh thiệt hại thực tế hoặc khả năng thiệt hại thật sự do nhầm lẫn; không bắt buộc chứng minh thiệt hại đã xảy ra. Đếm khách hàng hay chứng minh việc bắt chước không phải yêu cầu.", "key_fact": "Passing off: chỉ cần khả năng gây thiệt hại thật sự, không cần thiệt hại thực tế.", "topic": "Passing off", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-10", "question": "Which of the following statements is true?", "options": [{"key": "A", "text": "Fair dealing means that only insubstantial part of a work may be used"}, {"key": "B", "text": "Fair dealing with a work is permitted"}, {"key": "C", "text": "Quoting from a work in criticism or review is permitted provided that the critic or review is fair"}, {"key": "D", "text": "Developing a single part of a work is fair"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.30, trích dẫn tác phẩm để phê bình, bình luận được phép nếu là fair dealing và có ghi nhận đầy đủ. A sai vì fair dealing không chỉ giới hạn ở phần không đáng kể; B quá rộng vì fair dealing chỉ áp dụng cho mục đích luật định; D không có căn cứ.", "key_fact": "Fair dealing chỉ áp dụng cho mục đích luật định như phê bình, bình luận, nghiên cứu, kèm ghi nhận nguồn.", "topic": "Fair dealing", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-11", "question": "In case of copyright infringement, the copyright holder can use", "options": [{"key": "A", "text": "Only injunction"}, {"key": "B", "text": "Only delivery-up"}, {"key": "C", "text": "Only compensatory damages"}, {"key": "D", "text": "Each of (a), (b), (c) or combination"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chủ sở hữu quyền tác giả có thể yêu cầu lệnh cấm, giao nộp bản sao xâm phạm, bồi thường thiệt hại (hoặc tính lợi nhuận), riêng lẻ hoặc kết hợp. Các phương án 'chỉ' một biện pháp đều sai.", "key_fact": "Biện pháp xâm phạm quyền tác giả có thể áp dụng riêng lẻ hoặc kết hợp.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-12", "question": "What is sole license?", "options": [{"key": "A", "text": "the licensee will have no competition"}, {"key": "B", "text": "the licensor will afford no licenses to other persons within the contractual territory"}, {"key": "C", "text": "A and B are correct"}, {"key": "D", "text": "A and B are incorrect"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Li-xăng độc quyền một phần (sole licence): bên cấp phép không cấp li-xăng cho người khác trong lãnh thổ nhưng bản thân vẫn được khai thác. Vì vậy bên nhận vẫn có thể cạnh tranh với bên cấp phép, nên A sai (đó là exclusive licence).", "key_fact": "Sole licence: không cấp cho người khác nhưng bên cấp phép vẫn được khai thác.", "topic": "Li-xăng", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-13", "question": "Which of the following is NOT a copyright infringement?", "options": [{"key": "A", "text": "Someone copies without the copyright owner's permission"}, {"key": "B", "text": "A photographer takes a photograph of a particular scenic view, even though the photograph is virtually indistinguishable to another person's photograph."}, {"key": "C", "text": "Someone creates a scene in a studio to reproduce a scene in someone else's photograph"}, {"key": "D", "text": "One similarity drawing has had access to the material which has supposedly been copied"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả chỉ chống sao chép; sáng tạo độc lập không phải xâm phạm, nên nhiếp ảnh gia tự chụp cảnh dù giống ảnh người khác không xâm phạm. Dựng lại cảnh để tái tạo ảnh người khác (C) là sao chép (Creation Records, Temple Island).", "key_fact": "Sáng tạo độc lập dù giống nhau không xâm phạm quyền tác giả.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-14", "question": "In the EU, marks registered by the Office for Harmonisation of the Internal Market (Trade Marks and Designs) and are called ...", "options": [{"key": "A", "text": "Community Trade Marks"}, {"key": "B", "text": "Global Trade Marks"}, {"key": "C", "text": "European Trade Marks"}, {"key": "D", "text": "All are correct"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu đăng ký tại OHIM (nay là EUIPO) được gọi là Community Trade Marks (từ 2016 đổi tên thành EU Trade Marks). 'Global Trade Marks' không tồn tại.", "key_fact": "Nhãn hiệu đăng ký tại OHIM gọi là Community Trade Mark.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de7-15", "question": "What does a trademark protect?", "options": [{"key": "A", "text": "A work of art"}, {"key": "B", "text": "A secret formula"}, {"key": "C", "text": "Logos, names and brands"}, {"key": "D", "text": "General information"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu bảo hộ dấu hiệu phân biệt như logo, tên, thương hiệu. Tác phẩm nghệ thuật thuộc quyền tác giả, công thức bí mật thuộc thông tin bí mật.", "key_fact": "Nhãn hiệu bảo hộ dấu hiệu phân biệt nguồn gốc hàng hóa/dịch vụ.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-16", "question": "Adding some words in a song without consent of author is an infringement of.....", "options": [{"key": "A", "text": "Reproduction right"}, {"key": "B", "text": "Public performance right"}, {"key": "C", "text": "Integrity right"}, {"key": "D", "text": "False attribution"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thêm lời vào bài hát là một 'treatment' (thêm, bớt, sửa đổi) tác phẩm; nếu làm sai lệch, ảnh hưởng danh dự tác giả thì xâm phạm quyền bảo vệ sự toàn vẹn (integrity right) theo s80 CDPA. Không phải sao chép (reproduction) hay trình diễn công khai, cũng không phải gán sai tên tác giả.", "key_fact": "Sửa đổi, thêm bớt tác phẩm gây sai lệch xâm phạm quyền toàn vẹn (integrity).", "topic": "Quyền nhân thân", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-17", "question": "To protect Registered Design, an owner of Registered design needs to do:", "options": [{"key": "A", "text": "Show that there has been copying."}, {"key": "B", "text": "Show that the same or a substantially similar design is being applied to a product."}, {"key": "C", "text": "Prove that the design was not created independently by the infringer"}, {"key": "D", "text": "All of the above"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiểu dáng đăng ký là độc quyền tuyệt đối: chủ sở hữu chỉ cần chứng minh kiểu dáng giống hoặc không tạo ấn tượng tổng thể khác được áp dụng cho sản phẩm. Không cần chứng minh có sao chép (A, C) – đó là yêu cầu của design right không đăng ký và quyền tác giả.", "key_fact": "Xâm phạm kiểu dáng đăng ký không cần chứng minh sao chép.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-18", "question": "If the technical drawings of motorbike are copied, there is infringement of:", "options": [{"key": "A", "text": "Registered design"}, {"key": "B", "text": "Design right"}, {"key": "C", "text": "Copyright."}, {"key": "D", "text": "Both of A&B"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bản vẽ kỹ thuật là tác phẩm nghệ thuật; sao chép bản vẽ (tạo bản sao 2D) là xâm phạm quyền tác giả. Design right hay kiểu dáng đăng ký chỉ bị xâm phạm khi sản xuất sản phẩm theo thiết kế, không phải sao chép bản vẽ.", "key_fact": "Sao chép bản vẽ kỹ thuật là xâm phạm quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-19", "question": "Which of these rights is not generally regarded as part of design law?", "options": [{"key": "A", "text": "Registered designs"}, {"key": "B", "text": "Design right"}, {"key": "C", "text": "Trade mark right"}, {"key": "D", "text": "Both registered designs and design right"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Luật kiểu dáng gồm kiểu dáng đăng ký và design right (không đăng ký). Quyền nhãn hiệu thuộc luật nhãn hiệu (Trade Marks Act 1994), không phải luật kiểu dáng.", "key_fact": "Luật kiểu dáng gồm kiểu dáng đăng ký và design right, không gồm nhãn hiệu.", "topic": "Luật kiểu dáng", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-20", "question": "What can be defined as \"fees\"?", "options": [{"key": "A", "text": "Post-calculated, recurring payments, the amount of which is determined under economic use or result (sales, profits)."}, {"key": "B", "text": "A pre-calculated amount paid once or in installments"}, {"key": "C", "text": "Compensation for services and assistance rendered by technical or professional experts."}, {"key": "D", "text": "Dividend or income from related operations: commission paid to licensor for his assistance in selling."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong hợp đồng li-xăng, 'fees' là thù lao cho dịch vụ và hỗ trợ của chuyên gia kỹ thuật. A là royalties (tính theo doanh số/lợi nhuận), B là lump sum (trả trọn gói), D là hoa hồng/lợi tức khác.", "key_fact": "Royalty = theo doanh số; lump sum = trọn gói; fees = phí dịch vụ kỹ thuật.", "topic": "Li-xăng", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-21", "question": "Which of the following actions may constitute an infringement?", "options": [{"key": "A", "text": "Using the descriptive sign of the goods in accordance with honest practice"}, {"key": "B", "text": "Using a well-known trade mark in the course of a business"}, {"key": "C", "text": "Using the geographical indications of the goods in accordance with honest practice"}, {"key": "D", "text": "Using his own registered trademark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sử dụng nhãn hiệu nổi tiếng của người khác trong hoạt động kinh doanh có thể xâm phạm (kể cả với hàng hóa khác nếu gây lợi dụng/tổn hại uy tín). A, C là ngoại lệ theo TMA s.11 (sử dụng phù hợp tập quán trung thực), D là dùng nhãn hiệu đã đăng ký của chính mình.", "key_fact": "Dùng nhãn hiệu nổi tiếng của người khác trong kinh doanh có thể là xâm phạm.", "topic": "Xâm phạm nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-22", "question": "In a dispute on design right, ........", "options": [{"key": "A", "text": "Alleged copyist must prove not copying."}, {"key": "B", "text": "The owner must prove copying"}, {"key": "C", "text": "The Government must prove copying"}, {"key": "D", "text": "Nobody is in charge of proving copying"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Design right chỉ bảo vệ chống sao chép, nên chủ sở hữu (nguyên đơn) phải chứng minh có sao chép. Nghĩa vụ chứng minh không thuộc bị đơn (A) hay Nhà nước (C).", "key_fact": "Tranh chấp design right: chủ sở hữu phải chứng minh sao chép.", "topic": "Design right", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-23", "question": "A false attribution as an author.....", "options": [{"key": "A", "text": "Is made if a reasonable reader of the work would think that claimant was the author"}, {"key": "B", "text": "Is made where particular words are attributed to the claimant without consent"}, {"key": "C", "text": "Is made if the name of author is not mentioned"}, {"key": "D", "text": "Is made if the work is re-written"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền chống mạo danh tác giả (CDPA s.84) bị xâm phạm khi một tác phẩm bị gán sai cho một người; tiêu chuẩn là liệu người đọc hợp lý có nghĩ người khởi kiện là tác giả không (Clark v Associated Newspapers). Không nêu tên tác giả (C) liên quan quyền được nêu tên, viết lại tác phẩm (D) liên quan quyền phản đối xuyên tạc.", "key_fact": "Mạo danh tác giả: người đọc hợp lý tin rằng nguyên đơn là tác giả.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "A"}, {"id": "IPR-de7-24", "question": "The article made by Company X does not exactly the same with the article owned by Company Y but this article is only slightly different from Y's article. Which of the following is RIGHT?", "options": [{"key": "A", "text": "The article made by X is already different slightly from Y's article. It is not an infringement of design right."}, {"key": "B", "text": "It is an infringement of design right. Y, as the owner, will prevent X from copying the design."}, {"key": "C", "text": "X does not have to obtain Y's permission before making the article"}, {"key": "D", "text": "X does not have to compensate for Y's design right."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm design right bao gồm sao chép tạo sản phẩm giống hệt hoặc gần giống (substantially to the design). Sản phẩm chỉ khác chút ít vẫn là xâm phạm, nên Y có quyền ngăn chặn.", "key_fact": "Sản phẩm chỉ khác chút ít vẫn xâm phạm design right.", "topic": "Quyền thiết kế", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-25", "question": "A writer has written a detective novel based on using a murder case's transcripts from court proceedings without the Court's consent. The Court is the publisher of the transcripts. Which of the following is RIGHT?", "options": [{"key": "A", "text": "The transcripts from court proceedings are protected by Copyright."}, {"key": "B", "text": "The writer has to compensate for the Court's copyright"}, {"key": "C", "text": "Transcripts from court proceedings are in the public domain"}, {"key": "D", "text": "The writer has infringed the Court's Copyright"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Văn bản tố tụng, bản ghi phiên tòa và văn bản hành chính, tư pháp không thuộc đối tượng bảo hộ quyền tác giả (Điều 15 Luật SHTT VN), nên được coi là thuộc phạm vi công cộng. Do đó nhà văn không xâm phạm và không phải bồi thường cho tòa.", "key_fact": "Văn bản tư pháp, bản ghi phiên tòa không được bảo hộ quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-26", "question": "In Vietnam law, how long the trade mark protection is?", "options": [{"key": "A", "text": "5 years"}, {"key": "B", "text": "10 years"}, {"key": "C", "text": "15 years"}, {"key": "D", "text": "It depends but can last forever provided that the owner renews its application for protection"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Luật SHTT Việt Nam, văn bằng bảo hộ nhãn hiệu có hiệu lực 10 năm từ ngày nộp đơn và được gia hạn nhiều lần liên tiếp, mỗi lần 10 năm, không giới hạn số lần. Do đó bảo hộ có thể kéo dài vô thời hạn nếu gia hạn; chọn B (10 năm) chỉ đúng cho một chu kỳ.", "key_fact": "Nhãn hiệu ở VN: 10 năm, gia hạn không giới hạn số lần.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-27", "question": "To be protected, unregistered trade mark must.......", "options": [{"key": "A", "text": "Have reputation"}, {"key": "B", "text": "Be distinctive for the goods or services for which it has been used"}, {"key": "C", "text": "Both be distinctive and have reputation"}, {"key": "D", "text": "Be distinctive but do not have reputation"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu chưa đăng ký được bảo vệ qua passing off, đòi hỏi nhãn hiệu có tính phân biệt với hàng hóa/dịch vụ và có danh tiếng/goodwill trên thị trường. Chỉ có tính phân biệt mà không có danh tiếng thì chưa đủ để kiện passing off.", "key_fact": "Nhãn hiệu chưa đăng ký cần tính phân biệt và danh tiếng (goodwill).", "topic": "Nhãn hiệu chưa đăng ký", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-28", "question": "One of the requirements for a mark to be registered as trademark is.....", "options": [{"key": "A", "text": "not an infringement of other's right"}, {"key": "B", "text": "to be new"}, {"key": "C", "text": "to be creative"}, {"key": "D", "text": "to be original"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu không được xâm phạm quyền trước của người khác (căn cứ tương đối, s5 TMA). Tính mới, sáng tạo, nguyên gốc là yêu cầu của sáng chế, quyền tác giả hoặc kiểu dáng.", "key_fact": "Nhãn hiệu không được xung đột với quyền có trước của người khác.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de7-29", "question": "A wooden chair is protected by registered design. After seeing this chair, a chocolate shop makes a chocolate bar with the design of this chair. Such act is.....", "options": [{"key": "A", "text": "A secondary infringement of registered design"}, {"key": "B", "text": "A primary infringement of registered design"}, {"key": "C", "text": "Not an infringement of registered design"}, {"key": "D", "text": "An infringement of patent"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo RDA 1949 (sửa đổi), kiểu dáng đăng ký được bảo hộ đối với mọi sản phẩm chứ không chỉ loại sản phẩm đã đăng ký, nên làm thanh sô-cô-la mang kiểu dáng chiếc ghế là trực tiếp sử dụng kiểu dáng – xâm phạm trực tiếp (primary). Không phải xâm phạm thứ cấp (vốn là hành vi buôn bán hàng xâm phạm) và không liên quan sáng chế.", "key_fact": "Kiểu dáng đăng ký được bảo hộ cho mọi sản phẩm, không giới hạn ở sản phẩm gốc.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-30", "question": "Anders is the copyright owner of Computer programs. Without Anders' permission, Tine has authorised Charlotte, the one working under contract with Tine, to make an copy of Anders' Computer programs with something added. The act of Tine is:", "options": [{"key": "A", "text": "A secondary infringement of Anders' Copyrights"}, {"key": "B", "text": "A primary infringement of Anders' Copyrights"}, {"key": "C", "text": "Not a copyright infringement"}, {"key": "D", "text": "Both A&B"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA s.16(2), cho phép (authorise) người khác thực hiện hành vi thuộc độc quyền (sao chép, phóng tác chương trình) mà không được phép là xâm phạm trực tiếp (primary infringement). Xâm phạm thứ cấp liên quan đến buôn bán, nhập khẩu, tàng trữ bản sao xâm phạm, không phải hành vi cho phép sao chép.", "key_fact": "Cho phép người khác sao chép trái phép là xâm phạm trực tiếp (primary).", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de7-31", "question": "Which is NOT right about \"Copying in a different medium\"?", "options": [{"key": "A", "text": "a photocopy of a book."}, {"key": "B", "text": "a scanned-in digital copy of a photograph"}, {"key": "C", "text": "a reproduction and the copy have a material form"}, {"key": "D", "text": "a translation a copyright work"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sao chép sang phương tiện khác (photocopy sách, scan ảnh thành bản số) là hành vi sao chép (reproduction) dưới hình thức vật chất. Bản dịch là hành vi phóng tác (adaptation) chứ không phải sao chép sang phương tiện khác.", "key_fact": "Dịch tác phẩm là phóng tác, không phải sao chép sang phương tiện khác.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-32", "question": "What are Civil remedies?", "options": [{"key": "A", "text": "Provisional measures, Injunction, imprisonment"}, {"key": "B", "text": "Delivery-up, Compensatory damages, Punitive damages; and Account of profits"}, {"key": "C", "text": "Imprisonment, Punitive damages; and Account of profits"}, {"key": "D", "text": "Delivery-up, Imprisonment, Compensatory damages"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện pháp dân sự gồm giao nộp hàng (delivery-up), bồi thường thiệt hại, bồi thường mang tính trừng phạt (additional damages) và giao nộp lợi nhuận (account of profits). Phạt tù (imprisonment) là chế tài hình sự nên các phương án A, C, D sai.", "key_fact": "Phạt tù là hình sự; delivery-up, damages, account of profits là dân sự.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-33", "question": "The paternity right is NOT applied to:", "options": [{"key": "A", "text": "The creator of a literary, artistic, dramatic or musical copyright work and the director of a film (unless he or she is an employee)"}, {"key": "B", "text": "The designer of a building or other structure"}, {"key": "C", "text": "Computer programs or to any work created by a computer without human intervention"}, {"key": "D", "text": "An individual person and only when there is also a copyright"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo CDPA 1988 s.79, quyền được nêu tên (paternity right) không áp dụng cho chương trình máy tính và tác phẩm do máy tính tạo ra. A, B, D mô tả các chủ thể/điều kiện mà quyền này vẫn áp dụng.", "key_fact": "Quyền được nêu tên không áp dụng cho chương trình máy tính và tác phẩm do máy tính tạo ra.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-34", "question": "Fair dealing means........", "options": [{"key": "A", "text": "Exception to IP rights infringement"}, {"key": "B", "text": "Exception to copyright infringement"}, {"key": "C", "text": "Exception to trademark infringement"}, {"key": "D", "text": "Exception to patent infringement"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Fair dealing là các ngoại lệ đối với xâm phạm quyền tác giả theo CDPA 1988 (nghiên cứu, phê bình, đưa tin...). Nó không phải ngoại lệ chung cho mọi quyền SHTT hay cho nhãn hiệu, sáng chế.", "key_fact": "Fair dealing là ngoại lệ của quyền tác giả.", "topic": "Fair dealing", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-35", "question": "Which of following is NOT passing-off?", "options": [{"key": "A", "text": "Selling used item as a new one"}, {"key": "B", "text": "Copying an existing business name"}, {"key": "C", "text": "Persuading clients of a well-known shop to try other goods or services"}, {"key": "D", "text": "Using similar decoration of an existing business names"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thuyết phục khách hàng của cửa hàng nổi tiếng thử hàng hóa khác là cạnh tranh hợp pháp, không có sự trình bày sai lệch (misrepresentation). Bán hàng cũ như hàng mới, sao chép tên doanh nghiệp, trang trí giống đều có thể là passing off.", "key_fact": "Passing off cần có misrepresentation; cạnh tranh lôi kéo khách hàng thông thường không phải passing off.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de7-36", "question": "The Fair use of copyrighted work is:", "options": [{"key": "A", "text": "The permission of copyright owner to others to use freely copyrighted material for certain uses."}, {"key": "B", "text": "The statutory permission granted expressly by the Copyright Act to the public to use copyrighted material for certain uses."}, {"key": "C", "text": "Both A&B"}, {"key": "D", "text": "Not A&B"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Fair use (fair dealing) là sự cho phép theo luật định mà Luật Bản quyền cho công chúng sử dụng tác phẩm cho một số mục đích nhất định mà không cần xin phép. Đó không phải sự cho phép của chủ sở hữu (A) – cho phép của chủ sở hữu là li-xăng.", "key_fact": "Fair use là ngoại lệ do luật định, không phải sự cho phép của chủ sở hữu.", "topic": "Fair dealing", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-37", "question": "Liability for infringement of copyright can be avoided if...", "options": [{"key": "A", "text": "It is taken negligently"}, {"key": "B", "text": "It is taken intentionally"}, {"key": "C", "text": "It is used for commercial purpose"}, {"key": "D", "text": "It is used for educational purpose"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Sử dụng cho mục đích giáo dục (trong giới hạn fair dealing) là ngoại lệ, nên có thể tránh trách nhiệm xâm phạm. Vô ý không loại trừ xâm phạm trực tiếp (trách nhiệm nghiêm ngặt), và mục đích thương mại càng không được miễn.", "key_fact": "Mục đích giáo dục là ngoại lệ quyền tác giả.", "topic": "Ngoại lệ quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-38", "question": "If a famous signer sets up her own company to sell her own range of clothes, what type of intellectual property right can she use to show that the clothes are made by her company?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Trademarks"}, {"key": "C", "text": "Registered designs"}, {"key": "D", "text": "Patents"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu là dấu hiệu chỉ dẫn nguồn gốc thương mại, giúp phân biệt quần áo do công ty của ca sĩ sản xuất. Quyền tác giả, kiểu dáng bảo hộ thiết kế, patent bảo hộ giải pháp kỹ thuật, không chỉ ra nguồn gốc.", "key_fact": "Nhãn hiệu dùng để chỉ nguồn gốc thương mại của hàng hóa.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-39", "question": "When:\n- The mark could have been registered but the owner decided not to register it, and;\n- The mark is unregistrable because it does not meet the requirements of the law (i.e Trade Marks Act 1994).\nIn both cases, use of the mark generates what is known as", "options": [{"key": "A", "text": "Good hope"}, {"key": "B", "text": "Goodwill"}, {"key": "C", "text": "Good faith"}, {"key": "D", "text": "Good use"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Việc sử dụng nhãn hiệu không đăng ký tạo ra goodwill (uy tín kinh doanh), là cơ sở để kiện passing off. Các thuật ngữ còn lại không phải là khái niệm pháp lý liên quan.", "key_fact": "Sử dụng nhãn hiệu không đăng ký tạo ra goodwill – nền tảng của passing off.", "topic": "Passing off", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-40", "question": "What can be deemed as an infringement of registered trade mark?", "options": [{"key": "A", "text": "Use the registered trade mark in relation to the goods/services specified in the registration;"}, {"key": "B", "text": "Use the registered trade mark on the similar goods/services;"}, {"key": "C", "text": "Use the similar mark on the registered or similar goods/services, so that the public is likely to be confused;"}, {"key": "D", "text": "All are correct;"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo TMA 1994 s.10, xâm phạm gồm: dấu hiệu trùng cho hàng hóa trùng; dấu hiệu trùng cho hàng hóa tương tự hoặc dấu hiệu tương tự cho hàng hóa trùng/tương tự nếu có khả năng gây nhầm lẫn. Do đó cả A, B, C đều có thể là xâm phạm.", "key_fact": "Xâm phạm nhãn hiệu: trùng/trùng, trùng/tương tự, tương tự/tương tự gây nhầm lẫn.", "topic": "Xâm phạm nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-41", "question": "How do you think about this statement: In the UK, a mark can be used in business course without registration?", "options": [{"key": "A", "text": "This is correct. In the UK, a mark can be used without registering although it is recommended that registration is always needed for enjoying protection."}, {"key": "B", "text": "This is not correct. Once being used, a trade mark has already been registered."}, {"key": "C", "text": "This is not correct. Trade mark must be registered before using in the course of trade"}, {"key": "D", "text": "None of the statements are correct."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Ở Anh, nhãn hiệu có thể được sử dụng mà không cần đăng ký và vẫn có thể được bảo vệ qua passing off nếu tạo được goodwill; tuy nhiên đăng ký được khuyến nghị để có quyền mạnh và dễ thực thi hơn. Việc sử dụng không làm nhãn hiệu tự động được đăng ký, và luật không bắt buộc đăng ký trước khi dùng.", "key_fact": "Ở Anh được dùng nhãn hiệu chưa đăng ký; bảo vệ bằng passing off.", "topic": "Nhãn hiệu chưa đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de7-42", "question": "Since the aim of a trade mark is to encourage purchasers to buy your company's product or your company's service by using the mark when they place an order, what is deemed essential for a sign to be called \"trade mark\" from business perspective?", "options": [{"key": "A", "text": "Trade marks should be slightly different from marks used by competitors to avoid confusion."}, {"key": "B", "text": "Trade marks should be easy to remember and sufficiently different from marks used by competitors to avoid confusion."}, {"key": "C", "text": "That trade marks should be easy to remember and similar to marks used by competitors to avoid confusion."}, {"key": "D", "text": "That trade marks should be similar to marks used by competitors to create more confusions to enjoy benefits from dilution."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu phải dễ nhớ và đủ khác biệt với nhãn hiệu của đối thủ để tránh nhầm lẫn. 'Hơi khác' (A) không đủ; tương tự đối thủ (C, D) gây nhầm lẫn và dẫn tới xâm phạm.", "key_fact": "Nhãn hiệu: dễ nhớ và đủ khác biệt.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-43", "question": "When is the best time to minimize the risk of being sued for infringement of a registered trade mark, for passing-off or even misuse of someone else's company name?", "options": [{"key": "A", "text": "a trade mark is selected in the last place."}, {"key": "B", "text": "a trade mark is selected in the first place."}, {"key": "C", "text": "a trade mark is newly created"}, {"key": "D", "text": "a trade mark is communicated to the public"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thời điểm tốt nhất để giảm rủi ro bị kiện là ngay khi lựa chọn nhãn hiệu ban đầu, bằng cách tra cứu nhãn hiệu, tên công ty đã có. Khi nhãn hiệu đã được tạo hoặc công bố thì rủi ro đã phát sinh.", "key_fact": "Tra cứu nhãn hiệu ngay khi lựa chọn ban đầu để tránh rủi ro.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-44", "question": "Which of the followings is secondary infringement of copyright?", "options": [{"key": "A", "text": "Possession of or dealings with infringing copies"}, {"key": "B", "text": "Performing the work in public"}, {"key": "C", "text": "Duplicating the work"}, {"key": "D", "text": "Selling a work"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Xâm phạm thứ cấp (CDPA s.22-26) gồm nhập khẩu, tàng trữ, buôn bán bản sao xâm phạm khi biết hoặc có lý do tin. Biểu diễn công khai, sao chép là xâm phạm trực tiếp.", "key_fact": "Tàng trữ/buôn bán bản sao xâm phạm là xâm phạm thứ cấp.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de7-45", "question": "According to Madrid Agreement, the single application of trade mark must be made within how many months from the initial trade mark application?", "options": [{"key": "A", "text": "6"}, {"key": "B", "text": "12"}, {"key": "C", "text": "18"}, {"key": "D", "text": "3"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo hệ thống Madrid (kết hợp Công ước Paris), đơn quốc tế có thể hưởng quyền ưu tiên nếu nộp trong 6 tháng kể từ đơn nhãn hiệu đầu tiên. 12 tháng là thời hạn ưu tiên cho sáng chế.", "key_fact": "Quyền ưu tiên nhãn hiệu: 6 tháng; sáng chế: 12 tháng.", "topic": "Hệ thống Madrid", "note": "", "comment_answer": "A"}, {"id": "IPR-de7-46", "question": "Computer programs can be protected by........", "options": [{"key": "A", "text": "Design rights"}, {"key": "B", "text": "Copyright"}, {"key": "C", "text": "Trademark"}, {"key": "D", "text": "Patent"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chương trình máy tính được bảo hộ như tác phẩm văn học theo quyền tác giả (CDPA s.3, Berne, TRIPS). Patent bị loại trừ đối với chương trình máy tính 'như vậy' (Patents Act 1977 s.1(2)).", "key_fact": "Chương trình máy tính được bảo hộ bằng quyền tác giả như tác phẩm văn học.", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de7-47", "question": "Which of the following is not a law governing intellectual property perspective?", "options": [{"key": "A", "text": "Copyright Act, 1957"}, {"key": "B", "text": "Trademark Act, 1999"}, {"key": "C", "text": "Patent Act, 1970"}, {"key": "D", "text": "Design Act, 2000"}, {"key": "E", "text": "Customs Act, 1962"}], "answer": ["E"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Copyright Act 1957, Trade Marks Act 1999, Patents Act 1970, Designs Act 2000 (Ấn Độ) đều là luật SHTT. Customs Act 1962 là luật hải quan, không phải luật SHTT.", "key_fact": "Luật Hải quan không phải luật SHTT.", "topic": "Luật SHTT", "note": "", "comment_answer": "E"}, {"id": "IPR-de7-48", "question": "Which of the followings can NOT be a registrable trademark?", "options": [{"key": "A", "text": "A symbol"}, {"key": "B", "text": "A smell"}, {"key": "C", "text": "A single colour"}, {"key": "D", "text": "A generic name of the goods"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tên chung của hàng hóa (generic) không có tính phân biệt nên bị từ chối tuyệt đối (TMA 1994 s.3). Biểu tượng, mùi (nếu biểu thị được) và màu đơn có tính phân biệt đều có thể đăng ký.", "key_fact": "Tên gọi chung của hàng hóa không thể đăng ký nhãn hiệu.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-49", "question": "Who is not an author of the artistic work?", "options": [{"key": "A", "text": "A person who solely creates the artistic work"}, {"key": "B", "text": "A person who fixes the picture on whatever medium."}, {"key": "C", "text": "A person who jointly provide significant contribution to create a copyrightable artistic work."}, {"key": "D", "text": "A person who merely provides ideas."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Người chỉ cung cấp ý tưởng không phải tác giả vì quyền tác giả bảo hộ hình thức thể hiện. Người tự sáng tạo hoặc đóng góp đáng kể vào tác phẩm chung là tác giả.", "key_fact": "Người chỉ đưa ra ý tưởng không phải tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de7-50", "question": "Regarding applying for registration of a design in the UK, which of the following is RIGHT?", "options": [{"key": "A", "text": "Applying for registration of a design in the UK is free of charge"}, {"key": "B", "text": "The application can be dealt with by a patent attorney who will be familiar with the formalities required."}, {"key": "C", "text": "An examiner (at the UK Designs Registry) will check whether the design is new."}, {"key": "D", "text": "All of the above"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Đơn đăng ký kiểu dáng có thể do patent attorney thực hiện vì họ quen thủ tục. Đăng ký không miễn phí (A sai) và từ 2006 UK IPO không còn xét tính mới (C sai) – chỉ kiểm tra hình thức.", "key_fact": "Đăng ký kiểu dáng ở UK có phí và không xét tính mới.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}]}, {"id": "de8", "name": "Đề 8", "questions": [{"id": "IPR-de8-1", "question": "Cindy has very detailed and interesting ideas on writing a book. Based on these ideas, David [writes a book] without attribution of Cindy. David ...", "options": [{"key": "A", "text": "infringes paternity right"}, {"key": "B", "text": "infringes adaptation right"}, {"key": "C", "text": "Infringes reproduction right"}, {"key": "D", "text": "not infringes intellectual property right"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả không bảo hộ ý tưởng mà chỉ bảo hộ hình thức thể hiện; Cindy chưa thể hiện ý tưởng thành tác phẩm nên David không xâm phạm. Quyền đứng tên chỉ có với tác phẩm của tác giả.", "key_fact": "Ý tưởng không được bảo hộ quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-2", "question": "The concept of design right was introduced into the UK in:", "options": [{"key": "A", "text": "The UK Trade Marks Act 1994"}, {"key": "B", "text": "The UK Patents Act 1977"}, {"key": "C", "text": "The UK Copyright, Designs and Patents Act 1988"}, {"key": "D", "text": "None of the above"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Design right (quyền kiểu dáng không đăng ký) được tạo ra bởi Part III Copyright, Designs and Patents Act 1988. TMA 1994 về nhãn hiệu, PA 1977 về sáng chế.", "key_fact": "Design right được quy định tại CDPA 1988.", "topic": "Design right", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-3", "question": "Which of the followings can NOT be a registrable trademark?", "options": [{"key": "A", "text": "A symbol"}, {"key": "B", "text": "A smell"}, {"key": "C", "text": "A single colour"}, {"key": "D", "text": "A generic name of the goods"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tên chung của hàng hóa (generic) không có tính phân biệt nên bị từ chối tuyệt đối (TMA 1994 s.3). Biểu tượng, mùi (nếu biểu thị được) và màu đơn có tính phân biệt đều có thể đăng ký.", "key_fact": "Tên gọi chung của hàng hóa không thể đăng ký nhãn hiệu.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-4", "question": "Registered design does not protect:", "options": [{"key": "A", "text": "A design on parts which are assembled into a complex product"}, {"key": "B", "text": "A design on the whole or a part of a product"}, {"key": "C", "text": "A design on handicraft item"}, {"key": "D", "text": "A design on products such as vehicle spare parts which are not seen in normal use"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo RDA 1949 s.1B(8), bộ phận của sản phẩm phức hợp chỉ được bảo hộ nếu vẫn nhìn thấy được khi sử dụng bình thường; phụ tùng không nhìn thấy khi sử dụng bình thường không được bảo hộ. A, B, C đều có thể được bảo hộ.", "key_fact": "Bộ phận không nhìn thấy khi sử dụng bình thường không được bảo hộ kiểu dáng đăng ký.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-5", "question": "A is a movie-star. B takes a photograph of A and sells it to a magazine.", "options": [{"key": "A", "text": "B infringes on A's copyright"}, {"key": "B", "text": "B infringes A's privacy right"}, {"key": "C", "text": "B does not infringe any IP right"}, {"key": "D", "text": "B infringes A's trademark"}], "answer": ["B"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Copyright bức ảnh thuộc người chụp (B), hình ảnh người không phải nhãn hiệu nên A, D sai. Theo BLDS 2015 Điều 32 (dùng hình ảnh vì mục đích thương mại cần đồng ý) thì việc bán ảnh cho tạp chí xâm phạm quyền hình ảnh/riêng tư; còn theo luật Anh thuần SHTT thì C ('không xâm phạm quyền SHTT nào') cũng có cơ sở. Không có nguồn xác nhận đáp án đề. (Nguồn: https://www.stoneslaw.net/stars-paparazzi-and-the-puzzling-law-of-copyrights)", "key_fact": "Người chụp sở hữu copyright ảnh; người được chụp chỉ có quyền hình ảnh/riêng tư.", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-6", "question": "Fair dealing means.......", "options": [{"key": "A", "text": "Exception to IP rights infringement"}, {"key": "B", "text": "Exception to copyright infringement"}, {"key": "C", "text": "Exception to trademark infringement"}, {"key": "D", "text": "Exception to patent infringement"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Fair dealing là các ngoại lệ đối với xâm phạm quyền tác giả theo CDPA 1988 (nghiên cứu, phê bình, đưa tin...). Nó không phải ngoại lệ chung cho mọi quyền SHTT hay cho nhãn hiệu, sáng chế.", "key_fact": "Fair dealing là ngoại lệ của quyền tác giả.", "topic": "Fair dealing", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-7", "question": "Which of followings can NOT be patented?", "options": [{"key": "A", "text": "Discovery of scientific theory"}, {"key": "B", "text": "New methodology of running a technique system"}, {"key": "C", "text": "New way of operating an equipment"}, {"key": "D", "text": "New application of scientific theory"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Phát minh/khám phá, lý thuyết khoa học không được coi là sáng chế (Điều 1(2) Patents Act 1977, Điều 52 EPC). Các phương pháp vận hành, cách vận hành thiết bị hay ứng dụng mới của lý thuyết khoa học vào giải pháp kỹ thuật có thể được cấp bằng.", "key_fact": "Khám phá, lý thuyết khoa học, phương pháp toán học không được cấp patent.", "topic": "Sáng chế", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-8", "question": "Which of the followings is protected by copyright", "options": [{"key": "A", "text": "A word"}, {"key": "B", "text": "An idea"}, {"key": "C", "text": "A legal document"}, {"key": "D", "text": "An express of an idea"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền tác giả bảo hộ hình thức thể hiện của ý tưởng, không bảo hộ bản thân ý tưởng (B) hay một từ đơn lẻ (A). Văn bản pháp lý chính thức (C) thường không được xem là đối tượng bảo hộ thông thường.", "key_fact": "Quyền tác giả bảo hộ hình thức thể hiện, không bảo hộ ý tưởng.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-9", "question": "In the UK law, what the owner of a trade mark must show while proving the damage?", "options": [{"key": "A", "text": "actual loss of business"}, {"key": "B", "text": "loss of orders to the competitor"}, {"key": "C", "text": "a high risk of loss of business arising from the confusion"}, {"key": "D", "text": "the market loss"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong passing off, nguyên đơn không cần chứng minh thiệt hại thực tế đã xảy ra; chỉ cần chứng minh có nguy cơ thực sự (khả năng cao) mất kinh doanh/uy tín do sự nhầm lẫn. Các phương án mất đơn hàng thực tế hay mất thị trường đòi hỏi quá mức.", "key_fact": "Yếu tố thiệt hại trong passing off chỉ cần là khả năng thiệt hại thực sự do nhầm lẫn.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-10", "question": "Collective trade mark means..........", "options": [{"key": "A", "text": "There are many users of this trade mark"}, {"key": "B", "text": "There are many owners of this trade mark"}, {"key": "C", "text": "There is a collection of trademarks used by one company"}, {"key": "D", "text": "There is a collection of products sharing this trademark"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu tập thể là nhãn hiệu của một hiệp hội, dùng để phân biệt hàng hóa/dịch vụ của các thành viên; chủ sở hữu là hiệp hội nhưng có nhiều thành viên sử dụng. B sai vì chủ sở hữu là một tổ chức; C, D mô tả danh mục nhãn hiệu.", "key_fact": "Nhãn hiệu tập thể: một hiệp hội sở hữu, nhiều thành viên sử dụng.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-11", "question": "To be protected by registered design, the owner must.....", "options": [{"key": "A", "text": "Prove copying"}, {"key": "B", "text": "Show the designs are the same or very similar"}, {"key": "C", "text": "Publish the design one year earlier"}, {"key": "D", "text": "Show an application of the design"}], "answer": ["B"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Với kiểu dáng đăng ký, chủ sở hữu KHÔNG cần chứng minh sao chép mà chỉ cần chỉ ra kiểu dáng bị kiện giống hoặc rất giống (không tạo ấn tượng tổng thể khác) – đây cũng là đáp án của câu tương tự de6-49 (B) và de1-17. D 'Show an application of the design' không phải điều kiện giáo trình nêu. (Nguồn: https://www.legislation.gov.uk/ukpga/Geo6/12-13-14/88/section/7)", "key_fact": "Registered design: chỉ cần chứng minh giống/rất giống, không cần chứng minh copy.", "topic": "Kiểu dáng đăng ký", "note": "Đã sửa từ D sang B sau khi tra cứu trên mạng.", "comment_answer": "D"}, {"id": "IPR-de8-12", "question": "When the mark could have been registered but the owner decided not to register it, and when [it is] unregistrable because it does not meet the requirements of the law (i.e Trade Marks Act 199[4]), use of the mark generates what is known as", "options": [{"key": "A", "text": "Good hope"}, {"key": "B", "text": "Goodwill"}, {"key": "C", "text": "Good faith"}, {"key": "D", "text": "Good use"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Việc sử dụng một dấu hiệu chưa đăng ký trong kinh doanh tạo ra 'goodwill' (uy tín thương mại), và goodwill này được bảo vệ bằng hành vi kiện passing off. 'Good faith' là thiện chí, không phải tài sản kinh doanh.", "key_fact": "Nhãn hiệu không đăng ký được bảo vệ qua goodwill bằng passing off.", "topic": "Passing off", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-13", "question": "In a case on Registered design dispute, if the defendant (the suspected infringer) can prove [the design] was created independently by himself/herself, then:", "options": [{"key": "A", "text": "There is not infringement"}, {"key": "B", "text": "There is an infringement"}, {"key": "C", "text": "There is an infringement only when the owner shows that there has been copying."}, {"key": "D", "text": "All of others are correct"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiểu dáng đăng ký trao độc quyền tuyệt đối (RDA s.7, s.7A): sử dụng kiểu dáng không tạo ấn tượng tổng thể khác biệt là xâm phạm, bất kể có sao chép hay không. Vì vậy việc bị đơn tự sáng tạo độc lập không phải lý do bào chữa; A và C sai vì chỉ design right không đăng ký và quyền tác giả mới đòi hỏi chứng minh sao chép.", "key_fact": "Kiểu dáng đăng ký là độc quyền tuyệt đối: sáng tạo độc lập không phải là lý do bào chữa.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-14", "question": "An author of a song wants that people will refer to his name whenever they sing that song. W[hich] intellectual property right can he claim?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Trademarks"}, {"key": "C", "text": "Registered designs"}, {"key": "D", "text": "Patent"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền được nêu tên (paternity right) là quyền nhân thân (moral right) gắn với quyền tác giả theo CDPA 1988 (s.77). Nhãn hiệu, kiểu dáng, sáng chế không bảo vệ quyền đứng tên của tác giả bài hát.", "key_fact": "Quyền đứng tên tác giả là quyền nhân thân thuộc quyền tác giả.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-15", "question": "Duration of false attribution right according to UK law", "options": [{"key": "A", "text": "Lasts for the life of its creator plus a further 50 years."}, {"key": "B", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more a[re] jointly involved in the work"}, {"key": "C", "text": "Lasts for the life of its creator plus a further 20 years."}, {"key": "D", "text": "None of others is correct"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s.86(2) CDPA 1988, quyền chống ghi sai tác giả (false attribution) kéo dài đến 20 năm sau khi người đó chết. Các quyền nhân thân khác (paternity, integrity) kéo dài bằng thời hạn quyền tác giả (đời + 70 năm), dễ gây nhầm.", "key_fact": "False attribution: suốt đời + 20 năm.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-16", "question": "A trade mark being an invented word must ......", "options": [{"key": "A", "text": "Be new"}, {"key": "B", "text": "Be distinctive"}, {"key": "C", "text": "Indicate the nature of the goods"}, {"key": "D", "text": "Be meaningful"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Từ sáng tạo (invented word) được đăng ký vì có khả năng phân biệt cao; yêu cầu cốt lõi của nhãn hiệu là tính phân biệt. Nhãn hiệu không cần 'mới' như sáng chế, không cần có nghĩa, và việc chỉ ra tính chất hàng hóa (C) là mô tả, bị từ chối.", "key_fact": "Nhãn hiệu (kể cả từ sáng tạo) phải có tính phân biệt.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-17", "question": "A company wishes to ensure that no one else can use their logo. Which IPR protects that rig[ht]?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Trademark"}, {"key": "C", "text": "Patent"}, {"key": "D", "text": "Industrial design"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Logo dùng để phân biệt hàng hóa/dịch vụ của doanh nghiệp được bảo hộ bằng nhãn hiệu, cho phép ngăn người khác sử dụng dấu hiệu trùng/tương tự trong thương mại. Quyền tác giả chỉ chống sao chép chứ không ngăn sử dụng độc lập.", "key_fact": "Logo được bảo hộ chủ yếu bằng nhãn hiệu.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-18", "question": "While proving for the reputation of an unregistered mark, the owner needs to:", "options": [{"key": "A", "text": "Prove that the unregistered mark or the get-up is distinctive"}, {"key": "B", "text": "Prove that the unregistered mark is taken to show a trade connection with a particular bus[iness]"}, {"key": "C", "text": "A and B are correct"}, {"key": "D", "text": "A and B are incorrect"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Để chứng minh uy tín (goodwill/reputation) của nhãn hiệu chưa đăng ký, chủ sở hữu phải chứng minh nhãn hiệu hoặc get-up có tính phân biệt và được công chúng coi là biểu thị mối liên hệ thương mại với một doanh nghiệp cụ thể. Cả A và B đều cần.", "key_fact": "Nhãn hiệu chưa đăng ký: chứng minh tính phân biệt và liên hệ với doanh nghiệp.", "topic": "Passing off", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-19", "question": "The public domain is referred to:", "options": [{"key": "A", "text": "Addresses in Web"}, {"key": "B", "text": "Any works not protected by copyright"}, {"key": "C", "text": "Public land"}, {"key": "D", "text": "The works protected by copyright"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Public domain (phạm vi công cộng) là các tác phẩm không được (hoặc không còn được) bảo hộ quyền tác giả, ai cũng có thể sử dụng tự do. Không liên quan đến địa chỉ web hay đất công.", "key_fact": "Public domain = tác phẩm không/hết được bảo hộ.", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-20", "question": "Adding some words in a song without consent of author is an infringement of.....", "options": [{"key": "A", "text": "Reproduction right"}, {"key": "B", "text": "Public performance right"}, {"key": "C", "text": "Integrity right"}, {"key": "D", "text": "False attribution"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thêm lời vào bài hát là một 'treatment' (thêm, bớt, sửa đổi) tác phẩm; nếu làm sai lệch, ảnh hưởng danh dự tác giả thì xâm phạm quyền bảo vệ sự toàn vẹn (integrity right) theo s80 CDPA. Không phải sao chép (reproduction) hay trình diễn công khai, cũng không phải gán sai tên tác giả.", "key_fact": "Sửa đổi, thêm bớt tác phẩm gây sai lệch xâm phạm quyền toàn vẹn (integrity).", "topic": "Quyền nhân thân", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-21", "question": "If a famous signer sets up her own company to sell her own range of clothes, what type of in[tellectual property] right can she use to show that the clothes are made by her company?", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Trademarks"}, {"key": "C", "text": "Registered designs"}, {"key": "D", "text": "Patents"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu là dấu hiệu chỉ dẫn nguồn gốc thương mại, giúp phân biệt quần áo do công ty của ca sĩ sản xuất. Quyền tác giả, kiểu dáng bảo hộ thiết kế, patent bảo hộ giải pháp kỹ thuật, không chỉ ra nguồn gốc.", "key_fact": "Nhãn hiệu dùng để chỉ nguồn gốc thương mại của hàng hóa.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-22", "question": "What protects the intellectual property created by artist?", "options": [{"key": "A", "text": "Trademarks"}, {"key": "B", "text": "Copyright"}, {"key": "C", "text": "Patents"}, {"key": "D", "text": "Confidential information"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Tác phẩm của nghệ sĩ (hội họa, âm nhạc, văn học...) được bảo hộ bằng quyền tác giả, phát sinh tự động khi tác phẩm được định hình. Sáng chế bảo hộ giải pháp kỹ thuật, nhãn hiệu bảo hộ dấu hiệu thương mại.", "key_fact": "Tác phẩm sáng tạo nghệ thuật được bảo hộ bằng quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-23", "question": "What is the intention of the UK government in recognising design right?", "options": [{"key": "A", "text": "To take technical drawings out of copyright protection"}, {"key": "B", "text": "To take functional articles out of copyright protection"}, {"key": "C", "text": "None of A&B"}, {"key": "D", "text": "Both A&B"}], "answer": ["B"], "multi": false, "confidence": "medium", "source": "ai", "explanation": "Sau vụ British Leyland v Armstrong, CDPA 1988 (s.51 và Phần III) đưa vật phẩm chức năng ra khỏi bảo hộ quyền tác giả và thay bằng design right ngắn hạn; bản vẽ kỹ thuật vẫn được bảo hộ copyright như tác phẩm mỹ thuật nên A, D sai. (Nguồn: https://www.legislation.gov.uk/ukpga/1988/48/section/51)", "key_fact": "Design right ra đời để đưa functional articles ra khỏi copyright (s.51 CDPA).", "topic": "Quyền kiểu dáng không đăng ký", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-24", "question": "In the case that the registered design of goods has been copied. Which of the following is RIGHT?", "options": [{"key": "A", "text": "The person accused of infringement can prove his/her innocence"}, {"key": "B", "text": "The person accused of infringement cannot prove his/her innocence"}, {"key": "C", "text": "In protecting by registered design, the owner needs to prove copying."}, {"key": "D", "text": "Both A&C"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiểu dáng đăng ký là độc quyền: người bị cáo buộc không thể thoát trách nhiệm bằng cách chứng minh mình vô tình hay tự sáng tạo độc lập, và chủ sở hữu không cần chứng minh sao chép. Do đó A, C và D sai.", "key_fact": "Với kiểu dáng đăng ký, chủ sở hữu không cần chứng minh sao chép và bị đơn không thể biện minh bằng sự vô tình.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-25", "question": "Knowing Kevin is a self-employed designer, Charlotte has introduced Kevin to Company X. T[hey] then commissioned Kevin for 1500 Euro to design a machine. Who owns the right to the regi[stered design of the] machine?", "options": [{"key": "A", "text": "Kevin himself"}, {"key": "B", "text": "Company X"}, {"key": "C", "text": "Charlotte"}, {"key": "D", "text": "Company X and Kevin"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo quy tắc trong tài liệu môn học (RDA 1949 trước sửa đổi 2014), kiểu dáng được đặt hàng có trả tiền thuộc về bên đặt hàng – ở đây là Company X. Charlotte chỉ giới thiệu nên không có quyền. Lưu ý: từ 10/2014 luật Anh đã đổi, nhà thiết kế được đặt hàng là chủ sở hữu nếu không có thỏa thuận khác.", "key_fact": "Theo tài liệu môn học: kiểu dáng đặt hàng (commissioned) thuộc bên đặt hàng.", "topic": "Chủ sở hữu kiểu dáng", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-26", "question": "A salesman of a bags shop exhibited and sold a fake Chanel clutch for 1.000.000vnd (provi[ded that a genuine] Chanel clutch costs 20.000.000vnđ). But he told clients that this clutch is fake. This is......", "options": [{"key": "A", "text": "A passing off"}, {"key": "B", "text": "Not a passing off but an infringement of trademark"}, {"key": "C", "text": "A passing off and an infringement of trademark"}, {"key": "D", "text": "Neither a passing off nor infringement of trademark"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Passing off cần có sự trình bày sai lệch (misrepresentation) gây nhầm lẫn; người bán đã nói rõ là hàng giả nên không có lừa dối khách hàng. Tuy nhiên dùng dấu hiệu trùng với nhãn hiệu đã đăng ký cho hàng hóa trùng (s.10(1) TMA 1994) vẫn là xâm phạm nhãn hiệu mà không cần nhầm lẫn.", "key_fact": "Dùng dấu hiệu trùng cho hàng trùng là xâm phạm nhãn hiệu dù đã báo là hàng giả.", "topic": "Nhãn hiệu và passing off", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-27", "question": "Which of the following is NOT an example of literary work?", "options": [{"key": "A", "text": "A book"}, {"key": "B", "text": "An engineer report or specification"}, {"key": "C", "text": "A bus timetable"}, {"key": "D", "text": "A legal document"}], "answer": ["C"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Sách, báo cáo/đặc tả kỹ thuật và văn bản pháp lý là ví dụ tác phẩm văn học trong giáo trình; bảng giờ xe buýt chủ yếu là dữ kiện nên đề chọn là 'không phải'. Lưu ý CDPA s.3(1) coi 'table or compilation' là tác phẩm văn học nên về luật C cũng gây tranh cãi; giữ C vì không có phương án tốt hơn. (Nguồn: https://www.legislation.gov.uk/ukpga/1988/48/section/3)", "key_fact": "Literary work: sách, báo cáo kỹ thuật, văn bản pháp lý, chương trình máy tính.", "topic": "Quyền tác giả", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-28", "question": "Case: Kastenholz, vs Office for Harmonisation in the Internal Market (OHIM), Qwatchme A/S, T-68/11 (06 June 2013). What are the findings that the OHIM's third Board of Appeal dismissed the Kastenholz's app[lication for] declaration of invalidity appeal?", "options": [{"key": "A", "text": "The contested design was different from the earlier designs"}, {"key": "B", "text": "The contested design possessed individual character"}, {"key": "C", "text": "The contested design could not be regarded as being a reproduction or an adaptation of [the work] of art."}, {"key": "D", "text": "All of the above"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong vụ Kastenholz v OHIM (T-68/11), Hội đồng Phúc thẩm và Tòa án Chung xác định kiểu dáng bị phản đối khác với các kiểu dáng trước, có tính cá biệt (individual character) và không thể coi là sao chép/phỏng theo tác phẩm nghệ thuật của Kastenholz. Vì vậy cả A, B, C đều đúng.", "key_fact": "Kastenholz: đơn tuyên bố vô hiệu bị bác vì kiểu dáng khác biệt, có tính cá biệt, không sao chép tác phẩm.", "topic": "Kiểu dáng Cộng đồng", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-29", "question": "The word “Steel” can be add in trademark of......", "options": [{"key": "A", "text": "Only company producing steel"}, {"key": "B", "text": "Only company not producing steel"}, {"key": "C", "text": "Any company"}, {"key": "D", "text": "All company"}], "answer": ["C"], "multi": false, "confidence": "low", "source": "ai", "explanation": "Trùng câu de4-21: 'Steel' là từ mô tả, không đăng ký riêng cho thép nhưng có thể đưa vào nhãn hiệu tổ hợp của bất kỳ công ty nào. Không tìm được đáp án công khai xác nhận. (Nguồn: https://www.gov.uk/guidance/trade-marks-manual)", "key_fact": "Từ mô tả có thể nằm trong nhãn hiệu tổ hợp, không độc quyền riêng.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-30", "question": "A coffee mug having a textured surface created by Kevin, the surface decoration can be prot[ected by]", "options": [{"key": "A", "text": "Registered designs"}, {"key": "B", "text": "Design right."}, {"key": "C", "text": "Copyright"}, {"key": "D", "text": "None of the above"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trang trí bề mặt (kể cả kết cấu bề mặt – texture) được bảo hộ bằng kiểu dáng đăng ký. Quyền kiểu dáng không đăng ký (design right) của Anh loại trừ rõ ràng trang trí bề mặt (s.213(3)(c) CDPA), nên B sai.", "key_fact": "Trang trí bề mặt: bảo hộ bằng kiểu dáng đăng ký, không bằng design right.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-31", "question": "Computer icon is protected by", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Design right"}, {"key": "C", "text": "Trademark"}, {"key": "D", "text": "Registered design"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biểu tượng đồ họa như icon máy tính được coi là 'sản phẩm' theo RDA 1949 nên có thể đăng ký kiểu dáng; tài liệu UK IPO nêu icon máy tính là ví dụ của registered design. Design right không bảo hộ trang trí bề mặt/hình 2D nên B sai; quyền tác giả có thể tồn tại nhưng đáp án mong đợi là kiểu dáng đăng ký.", "key_fact": "Icon máy tính có thể được bảo hộ bằng kiểu dáng đăng ký.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-32", "question": "Which of these rights is not generally regarded as part of design law?", "options": [{"key": "A", "text": "Registered designs"}, {"key": "B", "text": "Design right"}, {"key": "C", "text": "Trade mark right"}, {"key": "D", "text": "Both registered designs and design right"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Luật kiểu dáng gồm kiểu dáng đăng ký và design right (không đăng ký). Quyền nhãn hiệu thuộc luật nhãn hiệu (Trade Marks Act 1994), không phải luật kiểu dáng.", "key_fact": "Luật kiểu dáng gồm kiểu dáng đăng ký và design right, không gồm nhãn hiệu.", "topic": "Luật kiểu dáng", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-33", "question": "Paternity right is NOT applied to", "options": [{"key": "A", "text": "The creator of a literary, artistic, dramatic or musical copyright work and the director of a film (unless he or she is an employee)"}, {"key": "B", "text": "The designer of a building or other structure"}, {"key": "C", "text": "Computer programs or to any work created by a computer without human intervention"}, {"key": "D", "text": "An individual person and only when there is also a copyright"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s.79 CDPA 1988, quyền đứng tên không áp dụng cho chương trình máy tính và tác phẩm do máy tính tạo ra. Các phương án A, B mô tả đối tượng được hưởng quyền (tác giả, đạo diễn, người thiết kế công trình).", "key_fact": "Quyền đứng tên không áp dụng cho chương trình máy tính và tác phẩm do máy tạo ra.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-34", "question": "A technical drawing is protected by.........", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Registered designs"}, {"key": "C", "text": "Both copyright and registered designs"}, {"key": "D", "text": "Patent"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Bản vẽ kỹ thuật là tác phẩm mỹ thuật (artistic work) bất kể chất lượng nghệ thuật (s.4 CDPA), nên được bảo hộ quyền tác giả. Bản vẽ không phải là kiểu dáng của sản phẩm nên không được đăng ký kiểu dáng, cũng không phải sáng chế.", "key_fact": "Bản vẽ kỹ thuật được bảo hộ quyền tác giả như tác phẩm mỹ thuật.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-35", "question": "Is it necessary to prove that those knowing the mark or get-up can identify the owner?", "options": [{"key": "A", "text": "No"}, {"key": "B", "text": "Yes. It is necessary"}, {"key": "C", "text": "Yes. This is a must to protect the original owner of the trade mark"}, {"key": "D", "text": "Yes. It is important to know who is the first one registering for the trade mark"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trong passing off, không cần chứng minh công chúng biết danh tính chủ sở hữu; chỉ cần họ liên hệ dấu hiệu/bao bì với một nguồn gốc thương mại nhất định. Các phương án 'Yes' gắn với đăng ký nhãn hiệu là sai vì passing off bảo vệ dấu hiệu chưa đăng ký.", "key_fact": "Passing off không đòi hỏi công chúng biết tên chủ sở hữu.", "topic": "Passing off", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-36", "question": "If a company develops a new technology for producing a special range of clothes, what type [of intellectual] property right can it use to prevent other from using such technology", "options": [{"key": "A", "text": "Copyright"}, {"key": "B", "text": "Trademarks"}, {"key": "C", "text": "Registered designs"}, {"key": "D", "text": "Patents"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Công nghệ/quy trình sản xuất mới là sáng chế, được bảo hộ bằng patent, cho phép ngăn người khác sử dụng kể cả khi họ phát triển độc lập. Quyền tác giả, nhãn hiệu, kiểu dáng không bảo hộ giải pháp kỹ thuật.", "key_fact": "Công nghệ/quy trình sản xuất mới được bảo hộ bằng patent.", "topic": "Sáng chế", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-37", "question": "The owner of copyright of a book written on author's own is .........", "options": [{"key": "A", "text": "Its author"}, {"key": "B", "text": "The publisher of the book"}, {"key": "C", "text": "The person who prints it with consent of the author"}, {"key": "D", "text": "The person who provide the ideas for this book"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s.11 CDPA, tác giả là chủ sở hữu đầu tiên của quyền tác giả (trừ tác phẩm của người lao động trong công việc). Nhà xuất bản, nhà in chỉ được cấp phép; người cung cấp ý tưởng không có quyền vì ý tưởng không được bảo hộ.", "key_fact": "Tác giả là chủ sở hữu đầu tiên của quyền tác giả.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-38", "question": "What can be used to make a copy of a design?", "options": [{"key": "A", "text": "Only the article itself"}, {"key": "B", "text": "Only the design document of the article"}, {"key": "C", "text": "Either the article itself or its design document"}, {"key": "D", "text": "None of the article and its design document"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Kiểu dáng có thể bị sao chép bằng cách làm sản phẩm theo kiểu dáng, hoặc làm tài liệu thiết kế, từ chính sản phẩm hoặc từ tài liệu thiết kế (s.226 CDPA). Do đó cả hai nguồn đều có thể dùng để sao chép.", "key_fact": "Sao chép kiểu dáng có thể từ sản phẩm hoặc từ tài liệu thiết kế.", "topic": "Quyền kiểu dáng không đăng ký", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-39", "question": "To be protected, unregistered trade mark must.......", "options": [{"key": "A", "text": "Have reputation"}, {"key": "B", "text": "Be distinctive for the goods or services for which it has been used"}, {"key": "C", "text": "Both be distinctive and have reputation"}, {"key": "D", "text": "Be distinctive but do not have reputation"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu chưa đăng ký được bảo vệ qua passing off, đòi hỏi nhãn hiệu có tính phân biệt với hàng hóa/dịch vụ và có danh tiếng/goodwill trên thị trường. Chỉ có tính phân biệt mà không có danh tiếng thì chưa đủ để kiện passing off.", "key_fact": "Nhãn hiệu chưa đăng ký cần tính phân biệt và danh tiếng (goodwill).", "topic": "Nhãn hiệu chưa đăng ký", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-40", "question": "An article with its exterior identical to a previous design but its internal feature which cannot [be seen is new]. This article is protected by:", "options": [{"key": "A", "text": "Design right."}, {"key": "B", "text": "Copyright"}, {"key": "C", "text": "Confidential information"}, {"key": "D", "text": "Trade secret"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền kiểu dáng không đăng ký của Anh (CDPA s.213) bảo hộ hình dạng hoặc cấu hình của bất kỳ khía cạnh nào, bên trong hay bên ngoài, không cần nhìn thấy được. Vì vậy đặc điểm bên trong mới vẫn được bảo hộ bằng design right; D sai vì không cần giữ bí mật, đặc điểm này đã có chế độ bảo hộ kiểu dáng.", "key_fact": "UK design right bảo hộ cả hình dạng/cấu hình bên trong, kể cả phần không nhìn thấy.", "topic": "Quyền kiểu dáng không đăng ký", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-41", "question": "According to Vietnam law, duration of a broadcast program related right", "options": [{"key": "A", "text": "Lasts for 50 years from the year it is released to the public"}, {"key": "B", "text": "Lasts for the life of its creator plus a further 50 years."}, {"key": "C", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more a[re] jointly involved in the work"}, {"key": "D", "text": "Lasts forever"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Luật SHTT Việt Nam (Điều 34), quyền của tổ chức phát sóng được bảo hộ 50 năm tính từ năm tiếp theo năm chương trình được phát sóng. Các phương án 'đời + 50 năm' hay 'vĩnh viễn' áp dụng cho quyền tác giả/quyền nhân thân, không phải quyền liên quan.", "key_fact": "Quyền liên quan của tổ chức phát sóng (VN): 50 năm từ khi phát sóng.", "topic": "Quyền liên quan (VN)", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-42", "question": "An article is referred to without naming the author. This is an infringement of.....", "options": [{"key": "A", "text": "Reproduction right"}, {"key": "B", "text": "Paternity right"}, {"key": "C", "text": "Integrity right"}, {"key": "D", "text": "False attribution"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Trích dẫn bài viết mà không nêu tên tác giả là xâm phạm quyền được nêu tên (paternity right). False attribution là gán sai tên người không phải tác giả; integrity là xuyên tạc tác phẩm.", "key_fact": "Không nêu tên tác giả là xâm phạm quyền đứng tên.", "topic": "Quyền nhân thân", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-43", "question": "According to UK law, to be granted suspension of release by custom authorities, the applicar[nt must]", "options": [{"key": "A", "text": "Provide adequate evidence to prove that under the laws of the country of importation, the[re is prima facie] an infringement of the right holder's intellectual property right"}, {"key": "B", "text": "Supply a sufficiently detailed description of the goods to make them readily recognizable [by the customs] authorities"}, {"key": "C", "text": "Provide a security or equivalent assurance sufficient to protect the defendant and the co[mpetent authorities] and to prevent abuse"}, {"key": "D", "text": "All of others are correct"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo các Điều 52-53 TRIPS (được áp dụng trong luật Anh), người yêu cầu đình chỉ thông quan phải đưa chứng cứ xâm phạm prima facie, mô tả hàng hóa đủ chi tiết, và nộp khoản bảo đảm. Vì vậy cả ba yêu cầu đều đúng.", "key_fact": "Đình chỉ thông quan: chứng cứ, mô tả chi tiết hàng hóa và bảo đảm.", "topic": "Biện pháp biên giới", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-44", "question": "Cellupro, a company that designed and manufactured cell phones, had a unique design to t[he phones and a] particular color for their phones and packaging. This design and color is known as", "options": [{"key": "A", "text": "trade dress."}, {"key": "B", "text": "a service mark."}, {"key": "C", "text": "a fanciful mark."}, {"key": "D", "text": "trade style."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Thiết kế và màu sắc đặc trưng của sản phẩm và bao bì tạo nên tổng thể hình ảnh nhận diện, gọi là trade dress (get-up). Service mark dành cho dịch vụ; fanciful mark là từ tự tạo.", "key_fact": "Hình thức, màu sắc sản phẩm và bao bì = trade dress.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-45", "question": "The civil remedies against copyright infringement include", "options": [{"key": "A", "text": "Final remedies, compensatory damages, criminal sanctions"}, {"key": "B", "text": "Provisional measure, injunction, delivery-up, compensatory damages, punitive damages, [...]"}, {"key": "C", "text": "Injunction, compensatory damages, border measures"}, {"key": "D", "text": "Account of profits, border measures, final remedies"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện pháp dân sự gồm biện pháp tạm thời, lệnh cấm, buộc giao nộp hàng (delivery-up), bồi thường thiệt hại (kể cả bồi thường bổ sung), tính lợi nhuận. Chế tài hình sự (A) và biện pháp biên giới (C, D) không phải biện pháp dân sự.", "key_fact": "Biện pháp dân sự: lệnh cấm, giao nộp, bồi thường; không gồm hình sự, biên giới.", "topic": "Thực thi quyền SHTT", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-46", "question": "You can infringe a patent by...........", "options": [{"key": "A", "text": "Making a product for your own personal use"}, {"key": "B", "text": "Publishing drawings of the product on your website"}, {"key": "C", "text": "Selling main components of the product, together with instruction how to assemble it usin[g] available fastening components."}, {"key": "D", "text": "Talking about it"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Cung cấp các phương tiện liên quan đến yếu tố thiết yếu của sáng chế kèm hướng dẫn lắp ráp là xâm phạm gián tiếp (s.60(2) Patents Act 1977). Sử dụng riêng tư phi thương mại được miễn trừ (s.60(5)); đăng bản vẽ hay nói về sáng chế không phải hành vi xâm phạm.", "key_fact": "Bán linh kiện chính kèm hướng dẫn lắp ráp là xâm phạm gián tiếp patent.", "topic": "Sáng chế", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-47", "question": "According to TRIPS, after registration a mark must be used; if not, it can be cancelled after h[ow many years]?", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Điều 19 TRIPS: nhãn hiệu chỉ có thể bị hủy do không sử dụng sau thời gian không sử dụng liên tục ít nhất 3 năm. Luật Anh dùng mốc 5 năm (s.46 TMA) nên dễ nhầm với C.", "key_fact": "TRIPS: nhãn hiệu có thể bị hủy sau 3 năm liên tục không sử dụng.", "topic": "Nhãn hiệu (TRIPS)", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-48", "question": "Which of the following is not an intellectual property law?", "options": [{"key": "A", "text": "Copyright Act, 1957"}, {"key": "B", "text": "Trademark Act, 1999"}, {"key": "C", "text": "Patent Act, 1970"}, {"key": "D", "text": "Design Act, 2000"}, {"key": "E", "text": "Customs Act, 1962"}], "answer": ["E"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Copyright Act, Trademark Act, Patent Act, Design Act đều là luật SHTT (của Ấn Độ). Customs Act 1962 là luật hải quan, không phải luật SHTT dù có thể hỗ trợ thực thi tại biên giới.", "key_fact": "Luật Hải quan không phải luật SHTT.", "topic": "Khái quát SHTT", "note": "", "comment_answer": "E"}, {"id": "IPR-de8-49", "question": "Duration of economics right in films according to Vietnam law", "options": [{"key": "A", "text": "Lasts for 50 years from the year the film or record was made or, if it is released to the pub[lic], its release"}, {"key": "B", "text": "Lasts for the life of its creator plus a further 50 years."}, {"key": "C", "text": "Lasts for 70 years begins to run on the death of the last surviving creator if two or more a[re] jointly involved in the work"}, {"key": "D", "text": "Lasts for 75 years from the end of the year in which the film was first published"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo Điều 27 Luật SHTT Việt Nam, tác phẩm điện ảnh được bảo hộ 75 năm kể từ khi công bố lần đầu (nếu chưa công bố trong 25 năm từ khi định hình thì 100 năm từ khi định hình). Phương án A là quy tắc kiểu Anh cho bản ghi; B, C là đời tác giả.", "key_fact": "Tác phẩm điện ảnh (VN): 75 năm kể từ khi công bố lần đầu.", "topic": "Quyền tác giả (VN)", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-50", "question": "When does the owner of a registered design have the right to start proceedings for infringem[ent of his/her] rights?", "options": [{"key": "A", "text": "When the registration is applied"}, {"key": "B", "text": "When a certificate is issued and the registration is published"}, {"key": "C", "text": "When the representation of the design is completed"}, {"key": "D", "text": "When the owner of the registered design found out an infringement of her/his rights"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Chủ sở hữu kiểu dáng chỉ được khởi kiện sau khi kiểu dáng được đăng ký, cấp giấy chứng nhận và công bố (dù có thể đòi bồi thường từ ngày đăng ký). Nộp đơn hay phát hiện vi phạm chưa đủ để khởi kiện.", "key_fact": "Chỉ được kiện xâm phạm kiểu dáng sau khi được cấp đăng ký.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-51", "question": "What are Civil remedies?", "options": [{"key": "A", "text": "Provisional measures, Injunction, imprisonment"}, {"key": "B", "text": "Delivery-up, Compensatory damages, Punitive damages; and Account of profits"}, {"key": "C", "text": "Imprisonment, Punitive damages; and Account of profits"}, {"key": "D", "text": "Delivery-up, Imprisonment, Compensatory damages"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Biện pháp dân sự gồm giao nộp hàng (delivery-up), bồi thường thiệt hại, bồi thường mang tính trừng phạt (additional damages) và giao nộp lợi nhuận (account of profits). Phạt tù (imprisonment) là chế tài hình sự nên các phương án A, C, D sai.", "key_fact": "Phạt tù là hình sự; delivery-up, damages, account of profits là dân sự.", "topic": "Chế tài xâm phạm", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-52", "question": "What does a trademark protect?", "options": [{"key": "A", "text": "A work of art"}, {"key": "B", "text": "A secret formula"}, {"key": "C", "text": "Logos, names and brands"}, {"key": "D", "text": "General information"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu bảo hộ dấu hiệu phân biệt như logo, tên, thương hiệu. Tác phẩm nghệ thuật thuộc quyền tác giả, công thức bí mật thuộc thông tin bí mật.", "key_fact": "Nhãn hiệu bảo hộ dấu hiệu phân biệt nguồn gốc hàng hóa/dịch vụ.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-53", "question": "Suspecting an infringement of his rights, Peter, the owner of a registered design has written to sue a suspected infringer. When can the threatened person sue Peter for making an unjustified threat?", "options": [{"key": "A", "text": "When there was no infringement"}, {"key": "B", "text": "When there is an infringement"}, {"key": "C", "text": "The person threatened cannot sue Peter in any cases"}, {"key": "D", "text": "Both B&C"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Người bị đe dọa có thể kiện vì đe dọa vô căn cứ (unjustified threats) nếu không có xâm phạm; chủ sở hữu có thể bào chữa bằng cách chứng minh hành vi thực sự xâm phạm. Do đó khi có xâm phạm thì không kiện được, và C sai vì quyền kiện tồn tại.", "key_fact": "Đe dọa kiện vô căn cứ: người bị đe dọa có thể kiện nếu không có xâm phạm.", "topic": "Kiểu dáng đăng ký", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-54", "question": "Since the aim of a trade mark is to encourage purchasers to buy your company's product or service by using the mark when they place an order, what is deemed essential for a sign to b[e a good trade] mark” from business perspective?", "options": [{"key": "A", "text": "Trade marks should be slightly different from marks used by competitors to avoid confusi[on]"}, {"key": "B", "text": "Trade marks should be easy to remember and sufficiently different from marks used by c[ompetitors to] avoid confusion."}, {"key": "C", "text": "That trade marks should be easy to remember and similar to marks used by competitors [...] confusion."}, {"key": "D", "text": "That trade marks should be similar to marks used by competitors to create more confusi[on and] benefits from dilution."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Nhãn hiệu tốt phải dễ nhớ và đủ khác biệt so với nhãn hiệu của đối thủ để tránh nhầm lẫn. Chỉ 'hơi khác' (A) hoặc tương tự đối thủ (C, D) dẫn tới nhầm lẫn và nguy cơ xâm phạm.", "key_fact": "Nhãn hiệu tốt: dễ nhớ và đủ khác biệt.", "topic": "Nhãn hiệu", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-55", "question": "Anders is the copyright owner of Computer programs. Without Anders' permission, Tine has [authorized] Charlotte, the one working under contract with Tine, to make an copy of Anders' Computer p[rogram with] something added. The act of Tine is:", "options": [{"key": "A", "text": "A secondary infringement of Anders' Copyrights"}, {"key": "B", "text": "A primary infringement of Anders' Copyrights"}, {"key": "C", "text": "Not a copyright infringement"}, {"key": "D", "text": "Both A&B"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Theo s.16(2) CDPA, quyền tác giả bị xâm phạm bởi người không được phép mà thực hiện hoặc cho phép (authorise) người khác thực hiện hành vi độc quyền. Tine cho phép Charlotte sao chép và chỉnh sửa chương trình nên là xâm phạm trực tiếp (primary); xâm phạm thứ cấp liên quan đến buôn bán, nhập khẩu bản sao.", "key_fact": "Cho phép người khác thực hiện hành vi độc quyền là xâm phạm trực tiếp.", "topic": "Xâm phạm quyền tác giả", "note": "", "comment_answer": "B"}, {"id": "IPR-de8-56", "question": "ATM machine is protected........", "options": [{"key": "A", "text": "Only by design right"}, {"key": "B", "text": "Only by patents"}, {"key": "C", "text": "By both design right and patents"}, {"key": "D", "text": "By trademark"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Máy ATM có hình dạng/cấu hình được bảo hộ bằng quyền kiểu dáng và các giải pháp kỹ thuật bên trong có thể được bảo hộ bằng sáng chế. Các quyền SHTT có thể cùng tồn tại trên một sản phẩm, nên 'chỉ' một quyền là sai.", "key_fact": "Một sản phẩm có thể được bảo hộ đồng thời bởi kiểu dáng và sáng chế.", "topic": "Khái quát SHTT", "note": "", "comment_answer": "C"}, {"id": "IPR-de8-57", "question": "If a mark or get-up has been used long enough to have generated a reputation, the owner ca[n prevent a] competitor from 'passing-off' goods or services as if they originated with the owner by use of similar marks or get-ups. To do this the owner must show:", "options": [{"key": "A", "text": "there is a reputation in the mark or get-up"}, {"key": "B", "text": "there has been confusion in the market place"}, {"key": "C", "text": "the owner has suffered damage"}, {"key": "D", "text": "All A+B+C must be proved together"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Để kiện passing off phải chứng minh đủ 'bộ ba' (Jif Lemon): uy tín (goodwill/reputation), sự trình bày sai lệch gây nhầm lẫn, và thiệt hại. Thiếu một yếu tố thì không thành công.", "key_fact": "Passing off: reputation + nhầm lẫn + thiệt hại.", "topic": "Passing off", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-58", "question": "Which of the following is NOT protected by an artistic copyright according to UK law?", "options": [{"key": "A", "text": "A fully prepared text, a note or in shorthand, on tape or disk"}, {"key": "B", "text": "A recording of light or other radiation on any medium on which an image is produced or from which an image may by any means be produced"}, {"key": "C", "text": "Technical drawings, photographs and to designs of buildings and other structures"}, {"key": "D", "text": "Any drawing, diagram, map, chart or plan"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Văn bản viết, ghi chú, tốc ký, ghi trên băng/đĩa là tác phẩm văn học, không phải tác phẩm mỹ thuật. Ảnh (B), bản vẽ kỹ thuật, công trình kiến trúc (C), sơ đồ, bản đồ (D) đều là tác phẩm mỹ thuật theo s.4 CDPA.", "key_fact": "Văn bản viết là tác phẩm văn học, không phải mỹ thuật.", "topic": "Quyền tác giả", "note": "", "comment_answer": "A"}, {"id": "IPR-de8-59", "question": "Singing a song in a party with friends is.............", "options": [{"key": "A", "text": "Infringement of reproduction right"}, {"key": "B", "text": "Infringement of public performance right"}, {"key": "C", "text": "Infringement of false attribution right"}, {"key": "D", "text": "Not an infringement of copyright"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Quyền biểu diễn chỉ bị xâm phạm khi biểu diễn trước công chúng; hát trong bữa tiệc riêng với bạn bè là riêng tư, không phải biểu diễn công cộng. Không có sao chép hay ghi sai tác giả.", "key_fact": "Biểu diễn riêng tư không xâm phạm quyền biểu diễn công cộng.", "topic": "Quyền tác giả", "note": "", "comment_answer": "D"}, {"id": "IPR-de8-60", "question": "What is licensing?", "options": [{"key": "A", "text": "The permission to perform one or more acts covered by exclusive rights of the owner of p[atented] invention/IPRs within a specific area and for particular time."}, {"key": "B", "text": "The ownership of IPRs is transferred."}, {"key": "C", "text": "The supplier promises to deliver the know-how to another party (recipient) for the use by [...]"}, {"key": "D", "text": "Owner gives up the ownership of his/her intellectual property"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "ai", "explanation": "Li-xăng là việc chủ sở hữu cho phép người khác thực hiện một hoặc một số hành vi thuộc độc quyền trong phạm vi, thời hạn nhất định, chủ sở hữu vẫn giữ quyền sở hữu. Chuyển giao quyền sở hữu là chuyển nhượng (assignment), không phải li-xăng.", "key_fact": "Li-xăng là cho phép sử dụng, không chuyển quyền sở hữu.", "topic": "Li-xăng", "note": "", "comment_answer": "A"}]}]}, {"id": "MLN131", "code": "MLN131", "name": "Chủ nghĩa xã hội khoa học", "note": null, "sets": [{"id": "bo", "name": "Bộ câu hỏi", "questions": [{"id": "MLN131-bo-1", "question": "Tư tưởng xã hội chủ nghĩa là gì?", "options": [{"key": "A", "text": "Là một hệ thống những quan niệm phản ánh những nhu cầu, những ước mơ, nguyện vọng của các giai cấp lao động về một xã hội không có áp bức và bóc lột, mọi người đều bình đẳng và có cuộc sống ấm no, hạnh phúc."}, {"key": "B", "text": "Là những thành tựu của con người đạt được trong quá trình đấu tranh giải phóng giai cấp."}, {"key": "C", "text": "Là chế độ xã hội không có áp bức bóc lột, mọi người đều bình đẳng tự do."}, {"key": "D", "text": "Cả a, b, c"}], "answer": ["A"], "multi": false, "confidence": "medium", "source": "key", "explanation": "Định nghĩa trong giáo trình/tài liệu CNXHKH: tư tưởng XHCN là \"hệ thống những quan niệm phản ánh những nhu cầu, ước mơ, nguyện vọng của các giai cấp lao động về một xã hội không có áp bức, bóc lột, mọi người đều bình đẳng, có cuộc sống ấm no, hạnh phúc\" — trùng nguyên văn phương án A. B là 'thành tựu', C là 'chế độ xã hội' (chủ nghĩa xã hội như một chế độ) chứ không phải 'tư tưởng', nên 'Cả a, b, c' không đúng. (Nguồn: https://luatminhkhue.vn/cau-hoi-trac-nghiem-chu-nghia-xa-hoi-khoa-hoc-co-dap-an.aspx)", "key_fact": "Tư tưởng XHCN = hệ thống quan niệm phản ánh ước mơ của giai cấp lao động về xã hội không áp bức, bóc lột.", "topic": "Lịch sử tư tưởng XHCN", "note": "Đáp án gốc trong file ghi D, đã sửa sau khi tra cứu.", "comment_answer": null}, {"id": "MLN131-bo-2", "question": "Những biểu hiện cơ bản của tư tưởng xã hội chủ nghĩa là gì?", "options": [{"key": "A", "text": "Là những ước mơ nguyện vọng về một chế độ xã hội ai cũng có việc làm ai cũng lao động."}, {"key": "B", "text": "Là quan niệm về một chế độ xã hội mà tư liệu sản xuất đều thuộc về mọi thành viên xã hội."}, {"key": "C", "text": "Là những tư tưởng về một xã hội, trong đó mọi người đều bình đẳng, có cuộc sống ấm no, tự do, hạnh phúc."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tư tưởng XHCN biểu hiện ở các quan niệm về một xã hội mà tư liệu sản xuất thuộc về mọi thành viên, ai cũng lao động, có việc làm, và mọi người bình đẳng, ấm no, tự do, hạnh phúc. Cả ba phương án A, B, C đều là những biểu hiện đó nên chọn D; chọn riêng một phương án là thiếu.", "key_fact": "Biểu hiện tư tưởng XHCN: công hữu TLSX, ai cũng lao động, bình đẳng, ấm no, hạnh phúc.", "topic": "Lịch sử tư tưởng XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-3", "question": "Những yếu tố tư tưởng XHCN được xuất hiện từ khi nào?", "options": [{"key": "A", "text": "Chế độ tư bản chủ nghĩa ra đời"}, {"key": "B", "text": "Sự xuất hiện chế độ tư hữu, xuất hiện giai cấp thống trị và bóc lột."}, {"key": "C", "text": "Sự xuất hiện giai cấp công nhân"}, {"key": "D", "text": "Ngay từ thời cộng sản nguyên thuỷ."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Yếu tố tư tưởng XHCN xuất hiện khi có chế độ tư hữu, có giai cấp thống trị và bóc lột, vì đó là lúc người lao động bắt đầu mơ ước về một xã hội không có áp bức. Phương án D (thời cộng sản nguyên thủy) sai vì khi đó chưa có bóc lột nên chưa có nhu cầu phản kháng; A và C thì quá muộn.", "key_fact": "Tư tưởng XHCN manh nha từ khi xuất hiện chế độ tư hữu và giai cấp bóc lột.", "topic": "Lịch sử tư tưởng XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-4", "question": "Đối tượng nghiên cứu của chủ nghĩa xã hội khoa học là gì?", "options": [{"key": "A", "text": "Là những quy luật và tính quy luật chính trị – xã hội của quá trình phát sinh, hình thành và phát triển hình thái kinh tế - xã hội cộng sản chủ nghĩa."}, {"key": "B", "text": "Là những quy luật hình thành, phát triển và hoàn thiện của các hình thái kinh tế - xã hội."}, {"key": "C", "text": "Là những quy luật và tính quy luật chính trị – xã hội của quá trình phát sinh, hình thành và phát triển hình thái kinh tế - xã hội chủ nghĩa xã hội."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đối tượng nghiên cứu của CNXH khoa học là những quy luật và tính quy luật chính trị - xã hội của quá trình phát sinh, hình thành và phát triển hình thái kinh tế - xã hội cộng sản chủ nghĩa. Phương án C dễ nhầm vì chỉ nói đến CNXH (giai đoạn đầu), còn B là đối tượng của chủ nghĩa duy vật lịch sử.", "key_fact": "Đối tượng CNXHKH: quy luật chính trị - xã hội của sự hình thành, phát triển hình thái KT-XH cộng sản chủ nghĩa.", "topic": "Đối tượng CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-5", "question": "Chức năng và nhiệm vụ của chủ nghĩa xã hội khoa học là gì?", "options": [{"key": "A", "text": "Là trang bị những tri thức khoa học của chủ nghĩa Mác - Lênin đã phát hiện ra và luận giải về quá trình tất yếu lịch sử dẫn đến hình thành, phát triển hình thái kinh tế - xã hội cộng sản, giải phóng xã hội, giải phóng con người."}, {"key": "B", "text": "Là giáo dục, trang bị lập trường tư tưởng chính trị của giai cấp công nhân cho đảng cộng sản, giai cấp công nhân và nhân dân lao động."}, {"key": "C", "text": "Là định hướng về chính trị – xã hội cho mọi hoạt động của giai cấp công nhân, của đảng cộng sản, của nhà nước và của nhân dân lao động trên mọi lĩnh vực."}, {"key": "D", "text": "Cả a, b và c đều đúng."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "CNXH khoa học có chức năng trang bị tri thức khoa học về tính tất yếu của hình thái KT-XH cộng sản, giáo dục lập trường tư tưởng chính trị của giai cấp công nhân, và định hướng chính trị - xã hội cho mọi hoạt động của Đảng, Nhà nước và nhân dân. Ba phương án A, B, C đều là các chức năng nên chọn D.", "key_fact": "CNXHKH có chức năng trang bị lý luận, giáo dục tư tưởng và định hướng chính trị - xã hội.", "topic": "Đối tượng CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-6", "question": "Ai đã đưa ra quan niệm “CNXH là sự phản kháng và đấu tranh chống sự bóc lột người lao động, một cuộc đấu tranh nhằm hoàn toàn xoá bỏ sự bóc lột”", "options": [{"key": "A", "text": "S.Phuriê"}, {"key": "B", "text": "C.Mác"}, {"key": "C", "text": "Ph.Ănghen"}, {"key": "D", "text": "V.I.Lênin"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đây là quan niệm của V.I. Lênin, nhấn mạnh CNXH trước hết là cuộc đấu tranh nhằm hoàn toàn xóa bỏ sự bóc lột người lao động. Dễ nhầm với Mác hoặc Ăngghen vì đều là kinh điển, nhưng câu này là của Lênin.", "key_fact": "Lênin: CNXH là sự phản kháng và đấu tranh nhằm hoàn toàn xóa bỏ bóc lột.", "topic": "Lịch sử tư tưởng XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-7", "question": "Ai được coi là người mở đầu các trào lưu xã hội chủ nghĩa và cộng sản chủ nghĩa thời cận đại.", "options": [{"key": "A", "text": "Tômađô Campanenla"}, {"key": "B", "text": "Tômát Morơ"}, {"key": "C", "text": "Arítxtốt"}, {"key": "D", "text": "Platôn"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tômát Morơ (1478-1535), với tác phẩm 'Utopia' (1516), được coi là người mở đầu các trào lưu XHCN và CSCN thời cận đại. Campanenla xuất hiện sau ông; Arixtốt và Platôn là các nhà tư tưởng cổ đại.", "key_fact": "Tômát Morơ là người mở đầu trào lưu XHCN, CSCN thời cận đại.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-8", "question": "Ai là người viết tác phẩm “Không tưởng” (Utôpi)", "options": [{"key": "A", "text": "Xanh Xi Mông"}, {"key": "B", "text": "Campanenla"}, {"key": "C", "text": "Tômát Morơ"}, {"key": "D", "text": "Uynxtenli"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Utopia' (Không tưởng, 1516) là tác phẩm của Tômát Morơ; từ tên tác phẩm này mà có thuật ngữ 'chủ nghĩa xã hội không tưởng'. Campanenla nổi tiếng với 'Thành phố mặt trời' chứ không phải 'Utopia'.", "key_fact": "'Utopia' là tác phẩm của Tômát Morơ (1516).", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-9", "question": "Ai là người đã đưa ra chủ trương thiết lập nền “Chuyên chính cách mạng của những người lao động”.", "options": [{"key": "A", "text": "Tômát Morơ"}, {"key": "B", "text": "Xanh Ximông"}, {"key": "C", "text": "Grắccơ Babớp"}, {"key": "D", "text": "Morenly"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Grắccơ Babớp (Pháp, cuối thế kỷ XVIII) chủ trương dùng bạo lực để giành chính quyền và thiết lập 'chuyên chính cách mạng của những người lao động'. Xanh Ximông và Morơ chủ trương phương pháp hòa bình, không đề xuất chuyên chính.", "key_fact": "Babớp chủ trương thiết lập chuyên chính cách mạng của những người lao động.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-10", "question": "Tư tưởng về “Giang sơn ngàn năm của Chúa” xuất hiện ở thời đại nào.", "options": [{"key": "A", "text": "Cộng sản nguyên thuỷ"}, {"key": "B", "text": "Thời cổ đại"}, {"key": "C", "text": "Thời cận đại"}, {"key": "D", "text": "Thời phục hưng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tư tưởng về 'Giang sơn ngàn năm của Chúa' gắn với Kitô giáo sơ kỳ, xuất hiện từ thời cổ đại, phản ánh ước mơ của người lao động về một xã hội công bằng. Phương án D (Phục hưng) dễ nhầm, nhưng đó là thời của Morơ và Campanenla.", "key_fact": "'Giang sơn ngàn năm của Chúa' là tư tưởng XHCN sơ khai thời cổ đại.", "topic": "Lịch sử tư tưởng XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-11", "question": "Tác phẩm “Thành phố mặt trời” là của tác giả nào?", "options": [{"key": "A", "text": "Giêrắcdơ Uyxntenli"}, {"key": "B", "text": "Tômađô Campanenla"}, {"key": "C", "text": "Giăng Mêliê"}, {"key": "D", "text": "Sáclơ Phuriê"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Thành phố mặt trời' (1602) là tác phẩm của Tômađô Campanenla (Italia), mô tả một xã hội không tư hữu, ai cũng lao động. Không nhầm với Tômát Morơ (tác giả 'Utopia').", "key_fact": "'Thành phố mặt trời' là tác phẩm của Campanenla.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-12", "question": "Ai đã viết tác phẩm “ Những di chúc của tôi”", "options": [{"key": "A", "text": "Tômát Morơ"}, {"key": "B", "text": "Giăng Mêliê"}, {"key": "C", "text": "Grắccơ Babớp"}, {"key": "D", "text": "Morenly"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Di chúc' (Những di chúc của tôi) là tác phẩm của Giăng Mêliê, linh mục người Pháp thế kỷ XVIII, phê phán chế độ phong kiến và tôn giáo. Babớp nổi tiếng với 'Tuyên ngôn của những người bình dân', còn Morenly với 'Bộ luật của tự nhiên'.", "key_fact": "Giăng Mêliê là tác giả 'Di chúc'.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-13", "question": "Ai là người đã nêu ra “Tuyên ngôn của những người bình dân”?", "options": [{"key": "A", "text": "Tômát Morơ"}, {"key": "B", "text": "Xanh Ximông"}, {"key": "C", "text": "Grắccơ Babớp"}, {"key": "D", "text": "Morenly"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Tuyên ngôn của những người bình dân' gắn với Grắccơ Babớp và phong trào 'Những người bình đẳng' ở Pháp cuối thế kỷ XVIII. Xanh Ximông và Morenly có các tác phẩm khác.", "key_fact": "Babớp nêu ra 'Tuyên ngôn của những người bình dân'.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-14", "question": "Ai là người đặt vấn đề đấu tranh cho chủ nghĩa xã hội với tính cách là một phong trào thực tiễn (Phong trào hiện thực)", "options": [{"key": "A", "text": "Tômát Morơ"}, {"key": "B", "text": "Xanh Ximông"}, {"key": "C", "text": "Grắccơ Babớp"}, {"key": "D", "text": "Morenly"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Babớp là người đầu tiên đặt vấn đề đấu tranh cho CNXH như một phong trào thực tiễn, qua việc tổ chức âm mưu khởi nghĩa của 'Những người bình đẳng' (1796). Các nhà không tưởng khác chủ yếu dừng ở lý luận hoặc thực nghiệm hòa bình.", "key_fact": "Babớp đưa CNXH thành một phong trào thực tiễn (hiện thực).", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-15", "question": "Những nhà tư tưởng tiêu biểu của chủ nghĩa xã hội không tưởng phê phán đầu thế kỷ XIX?", "options": [{"key": "A", "text": "Grắccơ Babớp, Xanh Ximông, Sáclơ Phuriê"}, {"key": "B", "text": "Xanh Ximông, Sáclơ Phuriê, G. Mably"}, {"key": "C", "text": "Xanh Ximông, Sáclơ Phuriê, Rôbớt Ôoen"}, {"key": "D", "text": "Xanh Ximông, Giăng Mêliê, Rôbớt Ôoen"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Ba đại biểu tiêu biểu của CNXH không tưởng phê phán đầu thế kỷ XIX là Xanh Ximông, Sáclơ Phuriê (Pháp) và Rôbớt Ôoen (Anh). Babớp, Mably, Mêliê thuộc thế kỷ XVIII nên các phương án có tên họ đều sai.", "key_fact": "Ba nhà không tưởng phê phán đầu thế kỷ XIX: Xanh Ximông, Phuriê, Ôoen.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-16", "question": "Nhà tư tưởng xã hội chủ nghĩa không tưởng nào đã nói đến vấn đề giai cấp và xung đột giai cấp.", "options": [{"key": "A", "text": "Xanh Ximông"}, {"key": "B", "text": "Sáclơ Phuriê"}, {"key": "C", "text": "Rôbớt Ôoen"}, {"key": "D", "text": "Grắccơ Babớp"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Xanh Ximông đã thấy được vấn đề giai cấp và cuộc xung đột giữa 'những người lao động' với 'những kẻ không lao động', coi lịch sử là cuộc đấu tranh giữa các giai cấp. Phuriê và Ôoen thiên về phê phán xã hội tư bản và thực nghiệm.", "key_fact": "Xanh Ximông đã đề cập đến giai cấp và xung đột giai cấp.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-17", "question": "Nhà tư tưởng xã hội chủ nghĩa nào đã tố cáo quá trình tích luỹ tư bản chủ nghĩa bằng hình ảnh “cừu ăn thịt người”.", "options": [{"key": "A", "text": "Tômát Morơ"}, {"key": "B", "text": "Sáclơ Phuriê"}, {"key": "C", "text": "Rôbớt Ôoen"}, {"key": "D", "text": "Grắccơ Babớp"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong 'Utopia', Tômát Morơ dùng hình ảnh 'cừu ăn thịt người' để tố cáo phong trào rào đất cướp ruộng (tích lũy nguyên thủy tư bản) ở Anh. Phuriê và Ôoen sống ở giai đoạn sau, khi CNTB đã phát triển.", "key_fact": "'Cừu ăn thịt người' là hình ảnh của Tômát Morơ tố cáo tích lũy nguyên thủy tư bản.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-18", "question": "Ai là người nêu ra luận điểm: Trong nền kinh tế tư bản chủ nghĩa, “sự nghèo khổ được sinh ra từ chính sự thừa thãi”.", "options": [{"key": "A", "text": "Xanh Ximông"}, {"key": "B", "text": "Sáclơ Phuriê"}, {"key": "C", "text": "Rôbớt Ôoen"}, {"key": "D", "text": "Tômát Morơ"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sáclơ Phuriê nhận định trong CNTB 'sự nghèo khổ được sinh ra từ chính sự thừa thãi', chỉ ra mâu thuẫn của nền kinh tế tư bản. Đây là một trong những phê phán sắc sảo nhất của ông; không nhầm với Xanh Ximông.", "key_fact": "Phuriê: trong CNTB, nghèo khổ sinh ra từ chính sự thừa thãi.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-19", "question": "Nhà tư tưởng xã hội chủ nghĩa nào đã chia lịch sử phát triển của nhân loại thành các giai đoạn: mông muội, dã man, gia trưởng và văn minh.", "options": [{"key": "A", "text": "Xanh Ximông"}, {"key": "B", "text": "Sáclơ Phuriê"}, {"key": "C", "text": "Grắccơ Babớp"}, {"key": "D", "text": "Tômát Morơ"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Phuriê chia lịch sử nhân loại thành các giai đoạn: mông muội, dã man, gia trưởng và văn minh, thể hiện tư duy biện chứng về lịch sử. Xanh Ximông có quan niệm lịch sử khác, không chia theo các giai đoạn này.", "key_fact": "Phuriê chia lịch sử: mông muội, dã man, gia trưởng, văn minh.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-20", "question": "Ai đã nêu ra tư tưởng: trình độ giải phóng xã hội được đo bằng trình độ giải phóng phụ nữ?", "options": [{"key": "A", "text": "Xanh Ximông"}, {"key": "B", "text": "Sáclơ Phuriê"}, {"key": "C", "text": "Grắccơ Babớp"}, {"key": "D", "text": "Rôbớt Ôoen"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Phuriê là người nêu tư tưởng trình độ giải phóng phụ nữ là thước đo trình độ giải phóng xã hội. Đây là luận điểm nổi tiếng được Mác, Ăngghen đánh giá cao; Ôoen hay Xanh Ximông không nêu ra luận điểm này.", "key_fact": "Phuriê: giải phóng phụ nữ là thước đo giải phóng xã hội.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-21", "question": "Người mơ ước xây dựng thành phố mặt trời, mà trong đó không có nạn thất nghiệp, không có kẻ lười biếng, ai cũng lao động. Ông là ai?", "options": [{"key": "A", "text": "Giê-rắc Uynxteli"}, {"key": "B", "text": "Grắc Babơp"}, {"key": "C", "text": "Tômađô Cămpanela"}, {"key": "D", "text": "Tô mát Mo rơ"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tômađô Campanenla mô tả 'Thành phố mặt trời' - nơi không có thất nghiệp, không ai lười biếng, ai cũng lao động. Tômát Morơ dễ nhầm, nhưng ông viết 'Utopia' chứ không phải 'Thành phố mặt trời'.", "key_fact": "Campanenla mơ ước 'Thành phố mặt trời' nơi ai cũng lao động.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-22", "question": "Nhà tư tưởng xã hội chủ nghĩa nào đã tiến hành thực nghiệm xã hội cộng sản trong lòng xã hội tư bản?", "options": [{"key": "A", "text": "Xanh Ximông"}, {"key": "B", "text": "Sáclơ Phuriê"}, {"key": "C", "text": "Grắccơ Babớp"}, {"key": "D", "text": "Rôbớt Ôoen"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Rôbớt Ôoen đã tiến hành thực nghiệm xã hội cộng sản ngay trong lòng xã hội tư bản, như công xưởng New Lanark (Anh) và công xã 'Hòa hợp mới' (New Harmony, Mỹ). Phuriê có đề xướng mô hình 'Pha-lăng-xte' nhưng Ôoen là người tiến hành thực nghiệm tiêu biểu.", "key_fact": "Ôoen thực nghiệm xã hội cộng sản trong lòng CNTB (New Harmony).", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-23", "question": "Nhà tư tưởng xã hội chủ nghĩa nào đã bị phá sản trong khi thực nghiệm tư tưởng cộng sản chủ nghĩa của mình?", "options": [{"key": "A", "text": "Xanh Ximông"}, {"key": "B", "text": "Sáclơ Phuriê"}, {"key": "C", "text": "Rôbớt Ôoen"}, {"key": "D", "text": "Tômát Morơ"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Ôoen đã đầu tư toàn bộ tài sản vào thực nghiệm công xã cộng sản 'New Harmony' ở Mỹ và bị phá sản. Thất bại này cho thấy CNXH không thể thực hiện bằng thực nghiệm hòa bình trong lòng CNTB.", "key_fact": "Ôoen bị phá sản khi thực nghiệm công xã cộng sản.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-24", "question": "Những đại biểu tiêu biểu cho chủ nghĩa xã hội không tưởng phê phán thế kỷ XIX ở Pháp và Anh?", "options": [{"key": "A", "text": "Xanh xi mông"}, {"key": "B", "text": "Phuriê"}, {"key": "C", "text": "Rô Bớc Ô Oen"}, {"key": "D", "text": "Cả a, b, c."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đại biểu tiêu biểu của CNXH không tưởng phê phán đầu thế kỷ XIX là Xanh Ximông, Phuriê (Pháp) và Ôoen (Anh), nên chọn D. Chọn riêng một người là thiếu.", "key_fact": "Xanh Ximông, Phuriê, Ôoen là ba đại biểu tiêu biểu của CNXH không tưởng phê phán.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-25", "question": "Chọn những tác giả nào đúng với tác phẩm của họ?", "options": [{"key": "A", "text": "To mát Morơ: Tác phẩm Thành phố mặt trời"}, {"key": "B", "text": "Tômađô Campanenla: Tác phẩm Không tưởng (Utopie)"}, {"key": "C", "text": "Giắccơ Babớp: Tuyên ngôn của những người bình dân"}, {"key": "D", "text": "Cả ba đều sai."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Chỉ có cặp Babớp - 'Tuyên ngôn của những người bình dân' là đúng. Phương án A và B bị tráo: 'Thành phố mặt trời' là của Campanenla, còn 'Utopia' là của Tômát Morơ.", "key_fact": "Morơ - Utopia; Campanenla - Thành phố mặt trời; Babớp - Tuyên ngôn của những người bình dân.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-26", "question": "Những hạn chế cơ bản của các nhà tư tưởng xã hội chủ nghĩa trước Mác là gì?", "options": [{"key": "A", "text": "Chưa thấy được bản chất bóc lột và quá trình phát sinh phát triển và diệt vong tất yếu của chủ nghĩa tư bản."}, {"key": "B", "text": "Không dùng bạo lực cách mạng để xoá bỏ chế độ tư bản chủ nghĩa."}, {"key": "C", "text": "Không phát hiện được lực lượng xã hội tiên phong có thể thực hiện cuộc chuyển biến cách mạng từ chủ nghĩa tư bản lên chủ nghĩa xã hội và cộng sản chủ nghĩa."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hạn chế cơ bản của CNXH không tưởng: không phát hiện được quy luật vận động, phát triển và bản chất của CNTB; không chỉ ra con đường cách mạng (chủ trương hòa bình, cải lương); không phát hiện lực lượng xã hội tiên phong là giai cấp công nhân. Cả A, B, C đều đúng nên chọn D.", "key_fact": "CNXH không tưởng không thấy quy luật của CNTB, không có biện pháp cách mạng, không thấy lực lượng là GCCN.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-27", "question": "Nguyên nhân chủ yếu của những hạn chế của chủ nghĩa xã hội không tưởng là?", "options": [{"key": "A", "text": "Do trình độ nhận thức của những nhà tư tưởng."}, {"key": "B", "text": "Do khoa học chưa phát triển."}, {"key": "C", "text": "Do những điều kiện lịch sử khách quan quy định."}, {"key": "D", "text": "Cả a, b, c."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Những hạn chế của CNXH không tưởng chủ yếu do điều kiện lịch sử khách quan quy định: phương thức sản xuất TBCN chưa phát triển chín muồi, giai cấp công nhân chưa trưởng thành. Phương án A, B chỉ là biểu hiện hoặc hệ quả của điều kiện lịch sử đó.", "key_fact": "Hạn chế của CNXH không tưởng do điều kiện lịch sử khách quan quy định.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-28", "question": "C. Mác sinh ngày tháng năm nào?", "options": [{"key": "A", "text": "14.3.1918"}, {"key": "B", "text": "5.5.1820"}, {"key": "C", "text": "5.5.1818"}, {"key": "D", "text": "22.4.1818"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "C. Mác sinh ngày 5/5/1818 tại Trier, Đức. Các phương án khác là nhiễu (22/4 là ngày sinh của Lênin, năm 1820 là năm sinh của Ăngghen).", "key_fact": "C. Mác sinh ngày 5/5/1818.", "topic": "Tiểu sử nhà kinh điển", "note": "", "comment_answer": null}, {"id": "MLN131-bo-29", "question": "C. Mác mất ngày tháng năm nào?", "options": [{"key": "A", "text": "14.3.1883"}, {"key": "B", "text": "14.3.1881"}, {"key": "C", "text": "5.8.1883"}, {"key": "D", "text": "21.1.1883"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "C. Mác mất ngày 14/3/1883 tại London. Phương án C (5/8) là ngày mất của Ăngghen (1895), còn 21/1 là ngày mất của Lênin (1924).", "key_fact": "C. Mác mất ngày 14/3/1883.", "topic": "Tiểu sử nhà kinh điển", "note": "", "comment_answer": null}, {"id": "MLN131-bo-30", "question": "Ph. Ăngghen sinh ngày tháng năm nào?", "options": [{"key": "A", "text": "25.11.1818"}, {"key": "B", "text": "28.11.1820"}, {"key": "C", "text": "5.5.1820"}, {"key": "D", "text": "22.4.1820"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Ph. Ăngghen sinh ngày 28/11/1820 tại Barmen, Đức. Phương án C (5/5) là ngày sinh của Mác, D (22/4) là ngày sinh của Lênin.", "key_fact": "Ph. Ăngghen sinh ngày 28/11/1820.", "topic": "Tiểu sử nhà kinh điển", "note": "", "comment_answer": null}, {"id": "MLN131-bo-31", "question": "Ph. Ăngghen mất ngày tháng năm nào?", "options": [{"key": "A", "text": "14.3.1888"}, {"key": "B", "text": "5.8.1895"}, {"key": "C", "text": "28.11.1895"}, {"key": "D", "text": "21.1.1895"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Ph. Ăngghen mất ngày 5/8/1895 tại London. Phương án C dễ nhầm vì 28/11 là ngày sinh của ông.", "key_fact": "Ph. Ăngghen mất ngày 5/8/1895.", "topic": "Tiểu sử nhà kinh điển", "note": "", "comment_answer": null}, {"id": "MLN131-bo-32", "question": "Ai là người được Ph.Ăngghen nhận xét là “có tầm mắt rộng thiên tài”?", "options": [{"key": "A", "text": "Phurie"}, {"key": "B", "text": "Ôoen"}, {"key": "C", "text": "G. Ba lớp"}, {"key": "D", "text": "Xanh Ximông"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong 'Chống Đuyrinh' (và 'Sự phát triển của CNXH từ không tưởng đến khoa học'), Ăngghen viết rằng ở Xanh Ximông ta thấy 'một tầm mắt rộng thiên tài'. Phuriê được Ăngghen khen là nắm phép biện chứng tài tình như Hêghen (chính là câu 33 trong cùng bộ đề, đáp án Phuriê).", "key_fact": "Ăngghen nhận xét Xanh Ximông có 'tầm mắt rộng thiên tài', còn Phuriê nắm phép biện chứng như Hêghen.", "topic": "CNXH không tưởng", "note": "Đáp án gốc trong file ghi A, đã sửa sau khi kiểm tra.", "comment_answer": null}, {"id": "MLN131-bo-33", "question": "Ai là người được Ph.Ăngghen đánh giá là “nắm phép biện chứng một cách cũng tài tình như Hêghen là người đương thời với ông”?", "options": [{"key": "A", "text": "Mê li ê"}, {"key": "B", "text": "Xanh Ximông"}, {"key": "C", "text": "Phurie"}, {"key": "D", "text": "Ôoen"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Ăngghen đánh giá Phuriê 'nắm phép biện chứng một cách cũng tài tình như Hêghen là người đương thời với ông', thể hiện qua cách ông phân chia các giai đoạn lịch sử. Xanh Ximông được khen về 'tầm mắt rộng thiên tài', không phải về phép biện chứng.", "key_fact": "Ăngghen: Phuriê nắm phép biện chứng tài tình như Hêghen.", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-34", "question": "Ai là người được Ph.Ăngghen nhận xét “Mọi phong trào xã hội, mọi thành tựu thực sự đã diễn ra ở Anh vì lợi ích của công nhân đều gắn với tên tuổi của ông” ông là ai?", "options": [{"key": "A", "text": "G. Uyn xtlenli"}, {"key": "B", "text": "Xanh Ximông"}, {"key": "C", "text": "Các Mác"}, {"key": "D", "text": "Ôoen"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Ăngghen nhận xét mọi phong trào xã hội, mọi thành tựu thực sự ở Anh vì lợi ích công nhân đều gắn với tên tuổi Rôbớt Ôoen, nhà không tưởng người Anh gắn bó với thực tiễn công nhân. Xanh Ximông là người Pháp, còn Mác không phải đối tượng của nhận xét này.", "key_fact": "Mọi thành tựu vì công nhân ở Anh đều gắn với tên Ôoen (theo Ăngghen).", "topic": "CNXH không tưởng", "note": "", "comment_answer": null}, {"id": "MLN131-bo-35", "question": "Ai là người nêu ra quan điểm: “Dân vi quý, xã tắc thứ chi, quân vi khinh” (Dân là trọng hơn cả, xã tắc đứng đằng sau, vua còn nhẹ hơn”?", "options": [{"key": "A", "text": "Khổng Tử"}, {"key": "B", "text": "Mạnh Tử"}, {"key": "C", "text": "Hàn Phi Tử"}, {"key": "D", "text": "Tuân tử"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Dân vi quý, xã tắc thứ chi, quân vi khinh' là tư tưởng của Mạnh Tử, đề cao vai trò của dân. Khổng Tử là thầy của trường phái nhưng không nêu câu này; Hàn Phi Tử thuộc phái Pháp gia.", "key_fact": "'Dân vi quý, xã tắc thứ chi, quân vi khinh' là của Mạnh Tử.", "topic": "Tư tưởng chính trị phương Đông", "note": "", "comment_answer": null}, {"id": "MLN131-bo-36", "question": "Ai trong số những người sau đây được Các Mác coi là nhà tư tưởng vĩ đại nhất thời cổ đại?", "options": [{"key": "A", "text": "Đêmôcrit"}, {"key": "B", "text": "Êpiquyarơ"}, {"key": "C", "text": "Aristôt"}, {"key": "D", "text": "Platôn"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "C. Mác coi Arixtốt (Aristôt) là 'nhà tư tưởng vĩ đại nhất thời cổ đại', đánh giá cao những đóng góp của ông về logic, kinh tế và chính trị. Platôn dễ nhầm vì cũng là triết gia lớn, nhưng nhận xét này dành cho Arixtốt.", "key_fact": "Mác coi Arixtốt là nhà tư tưởng vĩ đại nhất thời cổ đại.", "topic": "Tư tưởng chính trị cổ đại", "note": "", "comment_answer": null}, {"id": "MLN131-bo-37", "question": "Nội dung cơ bản nhất mà nhờ đó chủ nghĩa xã hội từ không tưởng trở thành khoa học?", "options": [{"key": "A", "text": "Lên án mạnh mẽ chủ nghĩa tư bản."}, {"key": "B", "text": "Phản ánh đúng khát vọng của nhân dân lao động bị áp bức."}, {"key": "C", "text": "Phát hiện ra giai cấp công nhân là lực lượng xã hội có thể thủ tiêu CNTB, xây dựng CNXH."}, {"key": "D", "text": "Chỉ ra sự cần thiết phải thay thế chủ nghĩa tư bản bằng chủ nghĩa xã hội."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Điểm then chốt đưa CNXH từ không tưởng thành khoa học là phát hiện ra giai cấp công nhân - lực lượng xã hội có sứ mệnh thủ tiêu CNTB, xây dựng CNXH. Các phương án A, B, D các nhà không tưởng đều đã làm được, nên không phải là điểm khác biệt cơ bản.", "key_fact": "Phát hiện sứ mệnh lịch sử của GCCN biến CNXH từ không tưởng thành khoa học.", "topic": "Sự ra đời CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-38", "question": "Những điều kiện và tiền đề khách quan nào dẫn đến sự ra đời của chủ nghĩa xã hội khoa học:", "options": [{"key": "A", "text": "Sự ra đời và phát triển của nền đại công nghiệp tư bản chủ nghĩa"}, {"key": "B", "text": "Sự trưởng thành của giai cấp công nhân công nghiệp"}, {"key": "C", "text": "Những thành tựu khoa học tự nhiên và tư tưởng lí luận đầu thế kỉ 19"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Điều kiện khách quan cho sự ra đời của CNXH khoa học gồm: nền đại công nghiệp TBCN phát triển, giai cấp công nhân trưởng thành và đấu tranh, cùng những thành tựu khoa học tự nhiên và tư tưởng lý luận đầu thế kỷ XIX. Cả ba đều đúng nên chọn D.", "key_fact": "CNXHKH ra đời từ đại công nghiệp, sự trưởng thành của GCCN và các tiền đề khoa học, lý luận.", "topic": "Sự ra đời CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-39", "question": "Tiền đề nào là nguồn gốc lý luận trực tiếp của chủ nghĩa xã hội khoa học.", "options": [{"key": "A", "text": "Triết học cổ điển Đức"}, {"key": "B", "text": "Kinh tế chính trị học cổ điển Anh"}, {"key": "C", "text": "Chủ nghĩa xã hội không tưởng – phê phán"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giáo trình CNXHKH nêu: triết học cổ điển Đức và KTCT cổ điển Anh là tiền đề lý luận chung của chủ nghĩa Mác, còn chủ nghĩa xã hội không tưởng – phê phán là tiền đề lý luận trực tiếp của CNXHKH. Từ 'trực tiếp' trong câu hỏi loại trừ phương án 'Cả a, b và c'.", "key_fact": "Chủ nghĩa xã hội không tưởng – phê phán là tiền đề (nguồn gốc) lý luận trực tiếp của CNXHKH.", "topic": "Sự ra đời CNXH khoa học", "note": "Đáp án gốc trong file ghi D, đã sửa sau khi kiểm tra.", "comment_answer": null}, {"id": "MLN131-bo-40", "question": "Ph. Ăngghen đã đánh giá: “Hai phát hiện vĩ đại này đã đưa chủ nghĩa xã hội trở thành một khoa học”. Hai phát kiến đó là gì?", "options": [{"key": "A", "text": "Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử"}, {"key": "B", "text": "Sứ mệnh lịch sử của giai cấp công nhân – Học thuyết giá trị thặng dư"}, {"key": "C", "text": "Học thuyết giá trị thặng dư – Chủ nghĩa duy vật lịch sử"}, {"key": "D", "text": "Sứ mệnh lịch sử của giai cấp công nhân– Chủ nghĩa duy vật lịch sử"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Ăngghen khẳng định hai phát kiến vĩ đại của Mác là quan niệm duy vật về lịch sử và học thuyết giá trị thặng dư đã biến CNXH thành khoa học. Phương án B và D dễ nhầm vì sứ mệnh lịch sử của GCCN là phát kiến thứ ba, được rút ra từ hai phát kiến trên.", "key_fact": "Hai phát kiến biến CNXH thành khoa học: chủ nghĩa duy vật lịch sử và học thuyết giá trị thặng dư.", "topic": "Sự ra đời CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-41", "question": "Vì sao chủ nghĩa xã hội khoa học theo nghĩa rộng là chủ nghĩa Mác - Lênin?", "options": [{"key": "A", "text": "Vì chủ nghĩa xã hội khoa học đã phác thảo ra mô hình chủ nghĩa xã hội và chủ nghĩa cộng sản."}, {"key": "B", "text": "Vì chủ nghĩa xã hội khoa học đã luận chứng về sứ mệnh lịch sử của giai cấp công nhân hiện đại."}, {"key": "C", "text": "Vì chủ nghĩa xã hội khoa học dựa vào triết học, kinh tế chính trị để lý giải tính tất yếu lịch sử của Cách mạng xã hội chủ nghĩa và Hình thái kinh tế – xã hội cộng sản chủ nghĩa gắn liền với vai trò lãnh đạo của giai cấp công nhân."}, {"key": "D", "text": "Cả a, b và c."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hiểu theo nghĩa rộng, CNXH khoa học là chủ nghĩa Mác - Lênin, vì nó dựa trên triết học và kinh tế chính trị để luận giải tính tất yếu của cách mạng XHCN và hình thái KT-XH cộng sản gắn với vai trò lãnh đạo của GCCN. Phương án A, B chỉ là các nội dung riêng lẻ, không giải thích được vì sao lại là 'nghĩa rộng'.", "key_fact": "Nghĩa rộng, CNXHKH là chủ nghĩa Mác - Lênin vì dựa trên cả triết học và KTCT.", "topic": "Đối tượng CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-42", "question": "Tác phẩm “Phê phán cương lĩnh Gôta” là của ai?", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "Ph.Ănghen"}, {"key": "C", "text": "C.Mác và Ph. ănghen"}, {"key": "D", "text": "V.I.Lênin"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Phê phán Cương lĩnh Gôta' (1875) do C. Mác viết, phê phán cương lĩnh của Đảng Công nhân xã hội Đức. Dễ nhầm là viết chung với Ăngghen, nhưng đây là tác phẩm riêng của Mác.", "key_fact": "'Phê phán Cương lĩnh Gôta' (1875) là tác phẩm của C. Mác.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-43", "question": "Tác phẩm nào được Lênin đánh giá là “tác phẩm chủ yếu và cơ bản trình bày chủ nghĩa xã hội khoa học”", "options": [{"key": "A", "text": "Chống Đuyrinh"}, {"key": "B", "text": "Tư bản"}, {"key": "C", "text": "Hệ tư tưởng Đức"}, {"key": "D", "text": "Phê phán cương lĩnh Gôta"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Lênin đánh giá bộ 'Tư bản' là tác phẩm chủ yếu và cơ bản trình bày CNXH khoa học, vì nó chứng minh tính tất yếu diệt vong của CNTB và vai trò của GCCN. 'Chống Đuyrinh' dễ nhầm vì cũng trình bày hệ thống chủ nghĩa Mác, nhưng không được Lênin đánh giá như vậy.", "key_fact": "Lênin coi bộ 'Tư bản' là tác phẩm chủ yếu, cơ bản trình bày CNXH khoa học.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-44", "question": "Câu nói: “Thực hiện sự nghiệp giải phóng thế giới ấy - đó là sứ mệnh lịch sử của giai cấp vô sản hiện đại” là của ai", "options": [{"key": "A", "text": "Các Mác"}, {"key": "B", "text": "Ph. Ăngghen"}, {"key": "C", "text": "Lênin"}, {"key": "D", "text": "Hồ Chí Minh"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Câu này là của Ph. Ăngghen trong 'Chống Đuyrinh' (và 'Sự phát triển của CNXH từ không tưởng đến khoa học'). Dễ nhầm với Mác vì hai ông thường viết chung, nhưng câu này có trong tác phẩm riêng của Ăngghen.", "key_fact": "Ăngghen: giải phóng thế giới là sứ mệnh lịch sử của giai cấp vô sản hiện đại.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-45", "question": "Lý thuyết phân kỳ hình thái kinh tế-xã hội cộng sản chủ nghĩa lần đầu tiên được đề cập trong tác phẩm nào?", "options": [{"key": "A", "text": "Tuyên ngôn của Đảng cộng sản."}, {"key": "B", "text": "Nội chiến ở Pháp."}, {"key": "C", "text": "Bộ tư bản"}, {"key": "D", "text": "Phê phán Cương lĩnh Gôta."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sự phân kỳ hình thái KT-XH cộng sản thành thời kỳ quá độ, giai đoạn thấp (đầu) và giai đoạn cao được C.Mác trình bày lần đầu trong 'Phê phán Cương lĩnh Gôta' (1875). 'Tuyên ngôn của Đảng Cộng sản' (1848) chưa đặt ra sự phân kỳ này.", "key_fact": "Mác phân kỳ hình thái KT-XH cộng sản chủ nghĩa lần đầu trong 'Phê phán Cương lĩnh Gôta' (1875).", "topic": "Thời kỳ quá độ", "note": "Đáp án gốc trong file ghi A, đã sửa sau khi kiểm tra.", "comment_answer": null}, {"id": "MLN131-bo-46", "question": "Quốc tế cộng sản là tên gọi khác của", "options": [{"key": "A", "text": "Quốc tế I"}, {"key": "B", "text": "Quốc tế II"}, {"key": "C", "text": "Quốc tế III"}, {"key": "D", "text": "Hội liên hiệp công nhân quốc tế"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Quốc tế Cộng sản (Comintern) là tên gọi khác của Quốc tế III, do Lênin sáng lập năm 1919. Quốc tế I chính là Hội liên hiệp công nhân quốc tế (1864), còn Quốc tế II thành lập năm 1889.", "key_fact": "Quốc tế III = Quốc tế Cộng sản (1919).", "topic": "Phong trào cộng sản quốc tế", "note": "", "comment_answer": null}, {"id": "MLN131-bo-47", "question": "Tác phẩm đầu tiên mà Các Mác và Ăng ghen viết chung là tác phẩm nào?", "options": [{"key": "A", "text": "Hệ tư tưởng Đức."}, {"key": "B", "text": "Tuyên ngôn Đảng Cộng sản."}, {"key": "C", "text": "Gia đình thần thánh."}, {"key": "D", "text": "Tình cảnh giai cấp công nhân Anh"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Gia đình thần thánh' (1844-1845) là tác phẩm đầu tiên Mác và Ăngghen viết chung. 'Hệ tư tưởng Đức' (1845-1846) dễ nhầm nhưng ra đời sau; 'Tình cảnh giai cấp công nhân Anh' là tác phẩm riêng của Ăngghen.", "key_fact": "Tác phẩm viết chung đầu tiên của Mác - Ăngghen là 'Gia đình thần thánh'.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-48", "question": "Tác phẩm nào đánh dấu sự ra đời của chủ nghĩa xã hội khoa học.", "options": [{"key": "A", "text": "Hệ tư tưởng Đức"}, {"key": "B", "text": "Tình cảnh giai cấp lao động ở Anh"}, {"key": "C", "text": "Tuyên ngôn của Đảng cộng sản"}, {"key": "D", "text": "Những nguyên lý của chủ nghĩa cộng sản"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Tuyên ngôn của Đảng Cộng sản' (2/1848) được coi là văn kiện có tính cương lĩnh, đánh dấu sự ra đời của CNXH khoa học. 'Hệ tư tưởng Đức' và 'Những nguyên lý của chủ nghĩa cộng sản' chỉ là các bước chuẩn bị trước đó.", "key_fact": "Tuyên ngôn của Đảng Cộng sản (1848) đánh dấu sự ra đời của CNXH khoa học.", "topic": "Sự ra đời CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-49", "question": "Lần đầu tiên Ph.Ăngghen nói chủ nghĩa Mác cấu thành bởi ba bộ phận trong tác phẩm nào?", "options": [{"key": "A", "text": "Sự phát triển của chủ nghĩa xã hội từ không tưởng đến khoa học"}, {"key": "B", "text": "Tình cảnh giai cấp công nhân Anh"}, {"key": "C", "text": "Tuyên ngôn của Đảng cộng sản"}, {"key": "D", "text": "Chống Đuyrinh"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong 'Chống Đuyrinh' (1878), Ăngghen lần đầu trình bày chủ nghĩa Mác như một chỉnh thể gồm ba bộ phận: triết học, kinh tế chính trị và CNXH khoa học. 'Sự phát triển của CNXH từ không tưởng đến khoa học' dễ nhầm vì được trích ra từ chính 'Chống Đuyrinh' về sau.", "key_fact": "Ăngghen lần đầu nêu ba bộ phận cấu thành chủ nghĩa Mác trong 'Chống Đuyrinh'.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-50", "question": "Phát hiện nào sau đây của C. Mác và Ph. Ăngghen?", "options": [{"key": "A", "text": "Chủ nghĩa duy vật lịch sử"}, {"key": "B", "text": "Học thuyết giá trị thặng dư"}, {"key": "C", "text": "Sứ mệnh lịch sử của giai cấp công nhân"}, {"key": "D", "text": "Cả a, b, c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Mác và Ăngghen có ba phát kiến vĩ đại: chủ nghĩa duy vật lịch sử, học thuyết giá trị thặng dư và học thuyết về sứ mệnh lịch sử toàn thế giới của GCCN. Cả ba đều đúng nên chọn D.", "key_fact": "Ba phát kiến: duy vật lịch sử, giá trị thặng dư, sứ mệnh lịch sử của GCCN.", "topic": "Sự ra đời CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-51", "question": "Phạm trù nào được coi là cơ bản nhất, là xuất phát điểm của chủ nghĩa xã hội khoa học?", "options": [{"key": "A", "text": "Giai cấp công nhân"}, {"key": "B", "text": "Sứ mệnh lịch sử của giai cấp công nhân"}, {"key": "C", "text": "Chuyên chính vô sản"}, {"key": "D", "text": "Xã hội chủ nghĩa"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sứ mệnh lịch sử của giai cấp công nhân là phạm trù cơ bản nhất, là điểm xuất phát của CNXH khoa học. Phương án A (giai cấp công nhân) dễ nhầm, nhưng cái làm nên CNXH khoa học là việc luận chứng sứ mệnh lịch sử của giai cấp đó.", "key_fact": "Sứ mệnh lịch sử của GCCN là phạm trù cơ bản nhất, xuất phát điểm của CNXHKH.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-52", "question": "Câu “Sự phát triển tự do của mọi người là điều kiện cho sự phát triển tự do của tất cả mọi người là cuả ai ’’", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "Ph.Ăng ghen"}, {"key": "C", "text": "C.Mác và Ph.Ăng ghen"}, {"key": "D", "text": "V.I. Lênin"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Câu \"sự phát triển tự do của mỗi người là điều kiện cho sự phát triển tự do của tất cả mọi người\" nằm ở cuối phần II \"Tuyên ngôn của Đảng Cộng sản\" (1848) — tác phẩm do C.Mác và Ph.Ăngghen cùng viết (C.Mác và Ph.Ăngghen: Toàn tập, t.4). Đã có phương án 'C.Mác và Ph.Ăngghen' nên chọn C. (Nguồn: https://www.marxists.org/vietnamese/marx-engels/1840s/tuyen/phan_02.htm ; https://www.quanlynhanuoc.vn/2026/08/04/dao-duc-xa-hoi-chu-nghia-trong-thoi-ky-qua-do/)", "key_fact": "Câu nói trong Tuyên ngôn của Đảng Cộng sản — tác phẩm chung của Mác và Ăngghen.", "topic": "Xã hội cộng sản chủ nghĩa", "note": "Đáp án gốc trong file ghi A, đã sửa sau khi tra cứu.", "comment_answer": null}, {"id": "MLN131-bo-53", "question": "C. Mác và Ph. Ăngghen đã dựa vào những phát kiến nào để xây dựng luận chứng về sứ mệnh lịch sử của giai cấp công nhân.", "options": [{"key": "A", "text": "Chủ nghĩa xã hội không tưởng – phê phán"}, {"key": "B", "text": "Chủ nghĩa duy vật lịch sử và Học thuyết giá trị thặng dư"}, {"key": "C", "text": "Triết học cổ điển Đức và Kinh tế chính trị học cổ điển Anh."}, {"key": "D", "text": "Cả ba đều đúng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Mác và Ăngghen dựa vào hai phát kiến chủ nghĩa duy vật lịch sử và học thuyết giá trị thặng dư để luận chứng về sứ mệnh lịch sử của GCCN. Phương án C dễ nhầm, nhưng triết học cổ điển Đức và KTCT cổ điển Anh chỉ là tiền đề lý luận, không phải phát kiến của hai ông.", "key_fact": "Sứ mệnh lịch sử GCCN được luận chứng dựa trên duy vật lịch sử và giá trị thặng dư.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-54", "question": "Chủ nghĩa duy vật lịch sử và Học thuyết giá trị thặng dư đã được C. Mác phát triển và trình bày một cách có hệ thống trong tác phẩm nào?", "options": [{"key": "A", "text": "Hệ tư tưởng Đức"}, {"key": "B", "text": "Tình cảnh của giai cấp lao động ở Anh"}, {"key": "C", "text": "Bộ Tư bản"}, {"key": "D", "text": "Những nguyên lý của chủ nghĩa cộng sản"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Bộ 'Tư bản' là nơi Mác trình bày một cách hệ thống và phát triển chủ nghĩa duy vật lịch sử và học thuyết giá trị thặng dư. 'Hệ tư tưởng Đức' chỉ mới đặt nền móng cho quan niệm duy vật lịch sử.", "key_fact": "Bộ 'Tư bản' trình bày có hệ thống duy vật lịch sử và học thuyết giá trị thặng dư.", "topic": "Tác giả và tác phẩm", "note": "", "comment_answer": null}, {"id": "MLN131-bo-55", "question": "V.I. Lênin sinh ngày tháng năm nào?", "options": [{"key": "A", "text": "5.5.1870"}, {"key": "B", "text": "22.4.1870"}, {"key": "C", "text": "18.3.1870"}, {"key": "D", "text": "28.11.1870"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "V.I. Lênin sinh ngày 22/4/1870 tại Ximbiếc, Nga. Phương án A (5/5) là ngày sinh của Mác, D (28/11) là ngày sinh của Ăngghen.", "key_fact": "V.I. Lênin sinh ngày 22/4/1870.", "topic": "Tiểu sử nhà kinh điển", "note": "", "comment_answer": null}, {"id": "MLN131-bo-56", "question": "V.I. Lênin mất ngày tháng năm nào?", "options": [{"key": "A", "text": "22.4.1924"}, {"key": "B", "text": "21.1.1924"}, {"key": "C", "text": "21.1.1922"}, {"key": "D", "text": "28.1.1924"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "V.I. Lênin mất ngày 21/1/1924. Phương án C cùng ngày nhưng sai năm (1922), còn A (22/4) là ngày sinh của ông.", "key_fact": "V.I. Lênin mất ngày 21/1/1924.", "topic": "Tiểu sử nhà kinh điển", "note": "", "comment_answer": null}, {"id": "MLN131-bo-57", "question": "Ai là người đầu tiên đưa chủ nghĩa xã hội từ khoa học thành thực tiễn sinh động.", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "Ph.ănghen"}, {"key": "C", "text": "V.I. Lênin"}, {"key": "D", "text": "Hồ Chí Minh"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "V.I. Lênin lãnh đạo Cách mạng Tháng Mười Nga 1917 thành công, lần đầu tiên biến CNXH từ lý luận khoa học thành thực tiễn. Mác và Ăngghen xây dựng lý luận nhưng chưa có một nhà nước XHCN trên thực tế.", "key_fact": "Lênin là người đầu tiên đưa CNXH từ khoa học thành hiện thực.", "topic": "Phát triển CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-58", "question": "Từ khi ra đời (1848) đến nay, Chủ nghĩa xã hội khoa học phát triển qua mấy giai đoạn chủ yếu?", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giáo trình chia quá trình phát triển của CNXH khoa học thành ba giai đoạn chủ yếu: thời Mác - Ăngghen, thời Lênin, và từ sau khi Lênin mất đến nay. Phương án A (2) bỏ sót giai đoạn sau Lênin.", "key_fact": "CNXHKH phát triển qua 3 giai đoạn: Mác - Ăngghen, Lênin, sau Lênin.", "topic": "Phát triển CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-59", "question": "Nhà nước xã hội chủ nghĩa đầu tiên được thành lập ở đâu?", "options": [{"key": "A", "text": "Công xã Pari"}, {"key": "B", "text": "Nga"}, {"key": "C", "text": "Ba Lan"}, {"key": "D", "text": "Trung Quốc"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nhà nước XHCN đầu tiên ra đời ở Nga sau Cách mạng Tháng Mười năm 1917. Công xã Pari (1871) là nhà nước kiểu mới đầu tiên của giai cấp vô sản nhưng chỉ tồn tại 72 ngày, chưa phải nhà nước XHCN hoàn chỉnh.", "key_fact": "Nhà nước XHCN đầu tiên là nước Nga Xô viết (1917).", "topic": "Nhà nước XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-60", "question": "Khái niệm chuyên chính vô sản được Các Mác dùng lần đầu tiên trong tác phẩm nào?", "options": [{"key": "A", "text": "Đấu tranh giai cấp ở Pháp"}, {"key": "B", "text": "Góp phần phê phán triết học pháp quyền của Hêghen"}, {"key": "C", "text": "Phê phán cương lĩnh Gô-ta"}, {"key": "D", "text": "Tuyên ngôn của Đảng cộng sản."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Thuật ngữ 'chuyên chính vô sản' được C.Mác dùng lần đầu trong 'Đấu tranh giai cấp ở Pháp 1848–1850' (1850). 'Tuyên ngôn' (1848) chỉ nói giai cấp vô sản 'trở thành giai cấp thống trị', giành lấy dân chủ, chứ chưa dùng khái niệm này.", "key_fact": "Khái niệm 'chuyên chính vô sản' xuất hiện lần đầu trong 'Đấu tranh giai cấp ở Pháp 1848–1850' của Mác.", "topic": "Chuyên chính vô sản", "note": "Đáp án gốc trong file ghi D, đã sửa sau khi kiểm tra.", "comment_answer": null}, {"id": "MLN131-bo-61", "question": "Định nghĩa về giai cấp được Lênin trình bày lần đầu tiên trong tác phẩm nào?", "options": [{"key": "A", "text": "Một bước tiến, hai bước lùi."}, {"key": "B", "text": "Làm gì?"}, {"key": "C", "text": "Sáng kiến vĩ đại."}, {"key": "D", "text": "Những nhiệm vụ trước mắt của chính quyền Xô viết"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Định nghĩa kinh điển về giai cấp ('những tập đoàn to lớn gồm những người khác nhau về địa vị trong hệ thống sản xuất xã hội...') được Lênin trình bày trong 'Sáng kiến vĩ đại' (1919). Các tác phẩm còn lại bàn về xây dựng đảng và chính quyền Xô viết.", "key_fact": "Định nghĩa giai cấp của Lênin nằm trong 'Sáng kiến vĩ đại' (1919).", "topic": "Giai cấp và cơ cấu xã hội", "note": "", "comment_answer": null}, {"id": "MLN131-bo-62", "question": "Tìm ra định nghĩa đúng nhất về giai cấp công nhân:", "options": [{"key": "A", "text": "Là giai cấp bị thống trị."}, {"key": "B", "text": "Là giai cấp lao động trong nền sản xuất công nghiệp có trình độ kỹ thuật và công nghệ hiện đại của xã hội."}, {"key": "C", "text": "Là giai cấp đông đảo trong dân cư."}, {"key": "D", "text": "Là giai cấp bị áp bức bóc lột nặng nề nhất"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giai cấp công nhân là giai cấp lao động trong nền sản xuất công nghiệp có trình độ kỹ thuật, công nghệ hiện đại - định nghĩa nhấn mạnh phương thức lao động công nghiệp. Phương án D (bị bóc lột nặng nề nhất) chỉ là đặc điểm dưới CNTB, không phải định nghĩa bản chất.", "key_fact": "GCCN là giai cấp lao động trong nền sản xuất công nghiệp hiện đại.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-63", "question": "Điều kiện để một cuộc cách mạng dân chủ tư sản kiểu mới có thể chuyển biến thành cách mạng vô sản:", "options": [{"key": "A", "text": "Có sự lãnh đạo của Đảng của giai cấp công nhân."}, {"key": "B", "text": "Chính quyền dân chủ nhân dân được củng cố, chuẩn bị nhứng điều kiện thực hiện chuyên chính vô sản."}, {"key": "C", "text": "Liên minh công nông được giữ vững và phát triển"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cách mạng dân chủ tư sản kiểu mới chỉ chuyển lên cách mạng vô sản khi có sự lãnh đạo của Đảng của GCCN, liên minh công nông được giữ vững, và chính quyền dân chủ nhân dân được củng cố để chuẩn bị điều kiện cho chuyên chính vô sản. Cả ba đều cần thiết nên chọn D.", "key_fact": "Điều kiện chuyển cách mạng: Đảng lãnh đạo, liên minh công nông, chính quyền dân chủ nhân dân vững mạnh.", "topic": "Cách mạng XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-64", "question": "Cấu trúc cơ bản của một hình thái kinh tế – xã hội là:", "options": [{"key": "A", "text": "Lực lượng sản xuất và quan hệ sản xuất"}, {"key": "B", "text": "Lực lượng sản xuất, quan hệ sản xuất và kiến trúc thượng tầng."}, {"key": "C", "text": "Cơ sở kinh tế và thể chế nhà nước."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cấu trúc cơ bản của một hình thái KT-XH gồm lực lượng sản xuất, quan hệ sản xuất (cơ sở hạ tầng) và kiến trúc thượng tầng. Phương án A thiếu kiến trúc thượng tầng; C chỉ nói đến nhà nước nên không đầy đủ.", "key_fact": "Hình thái KT-XH = LLSX + QHSX + kiến trúc thượng tầng.", "topic": "Hình thái kinh tế - xã hội", "note": "", "comment_answer": null}, {"id": "MLN131-bo-65", "question": "Cơ cấu xã hội nào có vai trò quan trọng nhất:", "options": [{"key": "A", "text": "Cơ cấu nghề nghiệp"}, {"key": "B", "text": "Cơ cấu dân cư"}, {"key": "C", "text": "Cơ cấu dân tộc"}, {"key": "D", "text": "Cơ cấu giai cấp"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong các loại cơ cấu xã hội, cơ cấu xã hội - giai cấp giữ vị trí quan trọng nhất, vì nó liên quan đến sở hữu tư liệu sản xuất, tổ chức quản lý và địa vị chính trị - xã hội, chi phối các loại cơ cấu khác. Cơ cấu nghề nghiệp, dân cư, dân tộc đều quan trọng nhưng không có vai trò chi phối như vậy.", "key_fact": "Cơ cấu xã hội - giai cấp có vị trí quan trọng hàng đầu.", "topic": "Cơ cấu xã hội - giai cấp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-66", "question": "Khái niệm nào trong sau đây được dùng để chỉ một cộng đồng người ổn định được hình thành trong lịch sử trong một lãnh thổ nhất định, có chung mối liên hệ về kinh tế, ngôn ngữ và một nền văn hoá?", "options": [{"key": "A", "text": "Bộ lạc"}, {"key": "B", "text": "Dân tộc"}, {"key": "C", "text": "Quốc gia"}, {"key": "D", "text": "Bộ tộc"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Dân tộc là cộng đồng người ổn định, hình thành trong lịch sử, có chung lãnh thổ, kinh tế, ngôn ngữ và nền văn hóa. Bộ lạc và bộ tộc là các hình thức cộng đồng tiền dân tộc, chưa có mối liên hệ kinh tế bền vững; 'quốc gia' nhấn mạnh yếu tố nhà nước.", "key_fact": "Dân tộc: cộng đồng ổn định có chung lãnh thổ, kinh tế, ngôn ngữ, văn hóa.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-67", "question": "Vì sao giai cấp nông dân không thể lãnh đạo được cuộc cách mạng xã hội chủ nghĩa? (chọn 1 phương án đúng)", "options": [{"key": "A", "text": "Họ đông nhưng không mạnh."}, {"key": "B", "text": "Họ không có chính đảng."}, {"key": "C", "text": "Họ không đại diện cho phương thức sản xuất tiên tiến"}, {"key": "D", "text": "Cả a và b."}], "answer": ["C"], "multi": false, "confidence": "medium", "source": "key", "explanation": "Theo CNXHKH, giai cấp lãnh đạo cách mạng XHCN phải là giai cấp \"đại diện cho phương thức sản xuất tiên tiến\" (giai cấp công nhân); nông dân gắn với sản xuất nhỏ, phân tán, không có hệ tư tưởng độc lập nên không thể lãnh đạo. 'Đông nhưng không mạnh', 'không có chính đảng' chỉ là hệ quả; đề yêu cầu chọn 1 phương án đúng nên C là lý do căn bản. (Nguồn: https://hoatieu.vn/tai-sao-giai-cap-nong-dan-khong-the-la-giai-cap-lanh-dao-cach-mang-219360 ; https://luatminhkhue.vn/quy-dinh-ve-su-menh-lich-su-cua-giai-cap-cong-nhan.aspx)", "key_fact": "Nông dân không đại diện cho phương thức sản xuất tiên tiến nên không thể lãnh đạo cách mạng XHCN.", "topic": "Sứ mệnh giai cấp công nhân", "note": "Đáp án gốc trong file ghi D, đã sửa sau khi tra cứu.", "comment_answer": null}, {"id": "MLN131-bo-68", "question": "Đặc trưng nào trong số các đặc trưng sau được coi là đặc trưng cơ bản nhất của giai cấp công nhân nói chung?", "options": [{"key": "A", "text": "Không có tư liệu sản xuất, phải bán sức lao động."}, {"key": "B", "text": "Họ lao động trong nền công nghiệp có trình độ công nghệ và kỹ thuật hiện đại."}, {"key": "C", "text": "Bị giai cấp tư sản bóc lột"}, {"key": "D", "text": "Cả ba đều sai"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đặc trưng cơ bản nhất của GCCN là lao động trong nền sản xuất công nghiệp có trình độ kỹ thuật, công nghệ hiện đại - đặc trưng này đúng ở cả dưới CNTB lẫn CNXH. Phương án A và C chỉ đúng với công nhân dưới CNTB, nên không phải đặc trưng chung.", "key_fact": "Đặc trưng cơ bản nhất của GCCN: lao động bằng phương thức công nghiệp hiện đại.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-69", "question": "Ai là tác giả của câu nói: “Chủ nghĩa xã hội hay là chết”", "options": [{"key": "A", "text": "V.I. Lênin"}, {"key": "B", "text": "Phiđen Castrô"}, {"key": "C", "text": "Hồ Chí Minh"}, {"key": "D", "text": "Đặng Tiểu Bình"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Chủ nghĩa xã hội hay là chết' là khẩu hiệu của Phiđen Caxtơrô, thể hiện quyết tâm bảo vệ CNXH ở Cuba sau khi Liên Xô sụp đổ. Không nhầm với Lênin hay Đặng Tiểu Bình.", "key_fact": "'Chủ nghĩa xã hội hay là chết' là câu nói của Phiđen Caxtơrô.", "topic": "Phong trào cộng sản quốc tế", "note": "", "comment_answer": null}, {"id": "MLN131-bo-70", "question": "Câu nói “ Chủ nghĩa đế quốc là sự chuẩn bị vật chất đầy đủ nhất cho cách mạng vô sản” là của:", "options": [{"key": "A", "text": "Các Mác"}, {"key": "B", "text": "Ăngghen"}, {"key": "C", "text": "V.I Lênin"}, {"key": "D", "text": "Hồ Chí Minh"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Lênin khẳng định 'chủ nghĩa đế quốc là sự chuẩn bị vật chất đầy đủ nhất cho chủ nghĩa xã hội' / cách mạng vô sản, vì CNTB độc quyền đã xã hội hóa sản xuất cao độ. Mác và Ăngghen sống ở giai đoạn CNTB tự do cạnh tranh, chưa phân tích chủ nghĩa đế quốc.", "key_fact": "Lênin: chủ nghĩa đế quốc là sự chuẩn bị vật chất đầy đủ nhất cho cách mạng vô sản.", "topic": "Cách mạng XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-71", "question": "Tác phẩm nào được Lênin coi là cuốn bách khoa toàn thư thực sự của chủ nghĩa cộng sản?", "options": [{"key": "A", "text": "Sự khốn cùng của triết học"}, {"key": "B", "text": "Chống Đuy rinh"}, {"key": "C", "text": "Đấu tranh giai cấp ở Pháp"}, {"key": "D", "text": "Tuyên ngôn của Đảng cộng sản"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tác phẩm \"Chống Đuy-rinh\" (1878) của Ph.Ăngghen trình bày một cách hệ thống cả ba bộ phận cấu thành chủ nghĩa Mác: triết học, kinh tế chính trị và chủ nghĩa xã hội khoa học, nên được Lênin đánh giá như cuốn bách khoa toàn thư của chủ nghĩa Mác. \"Tuyên ngôn của Đảng cộng sản\" là cương lĩnh chính trị đầu tiên, đánh dấu sự ra đời của CNXHKH, chứ không phải là tác phẩm trình bày toàn diện như bách khoa thư.", "key_fact": "\"Chống Đuy-rinh\" của Ăngghen trình bày toàn diện ba bộ phận của chủ nghĩa Mác.", "topic": "Lịch sử CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-72", "question": "Phát hiện ra sự phân chia xã hội thành giai cấp và đấu tranh giai cấp là công lao của:", "options": [{"key": "A", "text": "Các Mác"}, {"key": "B", "text": "Ph.Ăng ghen"}, {"key": "C", "text": "V.I. Lênin"}, {"key": "D", "text": "Các nhà sử học tư sản trước Mác"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Chính C.Mác thừa nhận rằng việc phát hiện ra sự tồn tại của các giai cấp và cuộc đấu tranh giữa chúng không phải là công lao của ông, mà các nhà sử học tư sản (như Ti-e-ri, Ghi-đô, Mi-nhê) đã nêu ra trước đó. Công lao của Mác là chứng minh sự tồn tại giai cấp gắn với các giai đoạn phát triển nhất định của sản xuất và đấu tranh giai cấp tất yếu dẫn tới chuyên chính vô sản, nên chọn A là nhầm.", "key_fact": "Các nhà sử học tư sản trước Mác đã phát hiện ra giai cấp và đấu tranh giai cấp.", "topic": "Lịch sử CNXH khoa học", "note": "", "comment_answer": null}, {"id": "MLN131-bo-73", "question": "Câu nói: “Điểm chủ yếu trong học thuyết của Mác là ở chỗ nó làm sáng tỏ vai trò lịch sử của giai cấp vô sản là người xây dựng chủ nghĩa xã hội\" là của ai.", "options": [{"key": "A", "text": "Ph. Ăng ghen."}, {"key": "B", "text": "V.I. Lênin"}, {"key": "C", "text": "Hồ Chí Minh"}, {"key": "D", "text": "Stalin."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đây là nhận định của V.I.Lênin khi khái quát cống hiến của học thuyết Mác: làm sáng tỏ vai trò lịch sử toàn thế giới của giai cấp vô sản là người xây dựng xã hội xã hội chủ nghĩa. Ăngghen là người cùng sáng lập học thuyết, không phải người đưa ra đánh giá này.", "key_fact": "Lênin: điểm chủ yếu của học thuyết Mác là làm sáng tỏ vai trò lịch sử của giai cấp vô sản.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-74", "question": "Cách mạng xã hội chủ nghĩa là quá trình cải biến một cách toàn diện trên tất cả các lĩnh vực của đời sống xã hội từ kinh tế, chính trị, văn hoá, tư tưởng, v.v. để xây dựng thành công chủ nghĩa xã hội và cuối cùng là chủ nghĩa cộng sản.", "options": [{"key": "A", "text": "Đúng"}, {"key": "B", "text": "Chưa hoàn toàn đúng"}, {"key": "C", "text": "Sai"}, {"key": "D", "text": "Có ý sai"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nhận định này đúng với định nghĩa cách mạng XHCN theo nghĩa rộng trong giáo trình: quá trình cải biến toàn diện mọi lĩnh vực đời sống xã hội để xây dựng thành công CNXH và tiến tới CNCS. Nó không sai, chỉ là không bao quát nghĩa hẹp (cuộc cách mạng chính trị giành chính quyền).", "key_fact": "Nghĩa rộng: cách mạng XHCN là quá trình cải biến toàn diện mọi lĩnh vực xã hội.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-75", "question": "Nguyên nhân sâu xa của cách mạng xã hội chủ nghĩa là:", "options": [{"key": "A", "text": "Mâu thuẫn giữa Lực lượng sản xuất và quan hệ sản xuất"}, {"key": "B", "text": "Do sự phát triển của lực lượng sản xuất"}, {"key": "C", "text": "Do sự phát triển của giai cấp công nhân"}, {"key": "D", "text": "Giai cấp tư sản đã trở thành giai cấp phản động"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nguyên nhân sâu xa của cách mạng XHCN là mâu thuẫn giữa lực lượng sản xuất mang tính xã hội hóa ngày càng cao với quan hệ sản xuất dựa trên chế độ chiếm hữu tư nhân TBCN. Sự phát triển của LLSX (B) chỉ là tiền đề, chính mâu thuẫn mới là gốc rễ, còn mâu thuẫn giữa công nhân và tư sản là biểu hiện về mặt xã hội của mâu thuẫn ấy.", "key_fact": "Nguyên nhân sâu xa: mâu thuẫn giữa LLSX xã hội hóa và QHSX tư bản chủ nghĩa.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-76", "question": "Tiến trình của cách mạng xã hội chủ nghĩa có mấy giai đoạn?", "options": [{"key": "A", "text": "Một"}, {"key": "B", "text": "Hai"}, {"key": "C", "text": "Ba"}, {"key": "D", "text": "Bốn"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tiến trình cách mạng XHCN gồm hai giai đoạn: giai đoạn thứ nhất là giành chính quyền, thiết lập nhà nước của giai cấp công nhân và nhân dân lao động; giai đoạn thứ hai là cải tạo xã hội cũ, xây dựng xã hội mới XHCN và CSCN. Không nên nhầm với các giai đoạn phát triển của hình thái kinh tế - xã hội cộng sản chủ nghĩa.", "key_fact": "Cách mạng XHCN có hai giai đoạn: giành chính quyền và cải tạo, xây dựng xã hội mới.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-77", "question": "Điều kiện chủ quan có vai trò quyết định nhất của cuộc cách mạng xã hội chủ nghĩa.", "options": [{"key": "A", "text": "Mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất tư bản chủ nghĩa."}, {"key": "B", "text": "Mâu thuẫn giữa giai cấp công nhân và giai cấp tư sản."}, {"key": "C", "text": "Sự trưởng thành của giai cấp công nhân, đặc biệt khi nó đã có đảng tiên phong lãnh đạo."}, {"key": "D", "text": "Giai cấp công nhân liên minh được với giai cấp công nhân nông dân."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Điều kiện chủ quan quyết định nhất là sự trưởng thành của giai cấp công nhân, đặc biệt khi có đảng cộng sản tiên phong lãnh đạo. Các phương án A, B là điều kiện khách quan (mâu thuẫn kinh tế, xã hội), nên không phải điều kiện chủ quan.", "key_fact": "Điều kiện chủ quan quyết định: giai cấp công nhân trưởng thành, có đảng tiên phong lãnh đạo.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-78", "question": "Công xã Pari ra đời vào ngày tháng năm nào?", "options": [{"key": "A", "text": "22.6.1848"}, {"key": "B", "text": "18.3.1871"}, {"key": "C", "text": "4.9.1870"}, {"key": "D", "text": "28.5.1871"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Công xã Pari ra đời ngày 18/3/1871 sau cuộc khởi nghĩa của công nhân Pari và tồn tại 72 ngày đến 28/5/1871. Ngày 28/5/1871 (D) là ngày Công xã thất bại, còn 4/9/1870 là ngày lập nền Cộng hòa III ở Pháp.", "key_fact": "Công xã Pari: 18/3/1871 - 28/5/1871 (72 ngày).", "topic": "Công xã Pari", "note": "", "comment_answer": null}, {"id": "MLN131-bo-79", "question": "Động lực của cuộc cách mạng xã hội chủ nghĩa", "options": [{"key": "A", "text": "Giai cấp tư sản, giai cấp công nhân, giai cấp nông dân."}, {"key": "B", "text": "Giai cấp công nhân, giai cấp nông dân, tầng lớp trí thức."}, {"key": "C", "text": "Giai cấp nông dân, giai cấp công nhân, tiểu tư sản."}, {"key": "D", "text": "Giai cấp công nhân, tầng lớp trí thức, giai cấp nông dân, tiểu tư sản."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giáo trình xác định động lực của cách mạng XHCN là giai cấp công nhân (động lực chủ yếu), giai cấp nông dân (động lực to lớn) và tầng lớp trí thức, tức liên minh công - nông - trí thức. Giai cấp tư sản (A) là đối tượng của cách mạng nên không thể là động lực.", "key_fact": "Động lực cách mạng XHCN: liên minh công nhân - nông dân - trí thức.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-80", "question": "Ai là người đầu tiên đưa ra khái niệm cách mạng dân chủ tư sản kiểu mới", "options": [{"key": "A", "text": "C. Mác"}, {"key": "B", "text": "Ph.Ăngghen"}, {"key": "C", "text": "C.Mác và Ph.Ăngghen"}, {"key": "D", "text": "V. I. Lênin"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "V.I.Lênin, trong điều kiện chủ nghĩa đế quốc, đã phát triển lý luận và đưa ra khái niệm cách mạng dân chủ tư sản kiểu mới, do giai cấp vô sản lãnh đạo và có khả năng chuyển lên cách mạng XHCN. Mác và Ăngghen mới nêu tư tưởng cách mạng không ngừng chứ chưa đưa ra khái niệm này.", "key_fact": "Lênin là người đầu tiên nêu khái niệm cách mạng dân chủ tư sản kiểu mới.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-81", "question": "Cách mạng dân chủ tư sản kiểu mới do giai cấp, tầng lớp nào lãnh đạo.", "options": [{"key": "A", "text": "Giai cấp tư sản"}, {"key": "B", "text": "Giai cấp công nhân"}, {"key": "C", "text": "Tầng lớp trí thức"}, {"key": "D", "text": "Giai cấp nông dân"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Điểm khác biệt căn bản của cách mạng dân chủ tư sản kiểu mới là do giai cấp công nhân thông qua đảng cộng sản lãnh đạo. Nếu do giai cấp tư sản lãnh đạo (A) thì đó là cách mạng dân chủ tư sản kiểu cũ.", "key_fact": "Cách mạng dân chủ tư sản kiểu mới do giai cấp công nhân lãnh đạo.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-82", "question": "Cách mạng dân chủ tư sản do giai cấp, tầng lớp nào lãnh đạo?", "options": [{"key": "A", "text": "Giai cấp công nhân"}, {"key": "B", "text": "Giai cấp tư sản"}, {"key": "C", "text": "Giai cấp công nhân và giai cấp tư sản"}, {"key": "D", "text": "Giai cấp công nhân và giai cấp nông dân"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cách mạng dân chủ tư sản (kiểu cũ) do giai cấp tư sản lãnh đạo nhằm lật đổ chế độ phong kiến, xác lập chủ nghĩa tư bản, như cách mạng Pháp 1789. Giai cấp công nhân (A) chỉ lãnh đạo cách mạng dân chủ tư sản kiểu mới.", "key_fact": "Cách mạng dân chủ tư sản kiểu cũ do giai cấp tư sản lãnh đạo.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-83", "question": "Điều kiện để thực hiện sự chuyển biến từ cách mạng dân chủ tư sản kiểu mới lên cách mạng xã hội chủ nghĩa là gì?", "options": [{"key": "A", "text": "Đảng cộng sản giữ vững vai trò lãnh đạo"}, {"key": "B", "text": "Liên minh công nông được củng cố và tăng cường"}, {"key": "C", "text": "Chính quyền của công nhân và nông dân được thiết lập chuyển lê làm nhiệm vụ của CCVS."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Để chuyển từ cách mạng dân chủ tư sản kiểu mới lên cách mạng XHCN cần đồng thời: Đảng cộng sản giữ vững vai trò lãnh đạo, liên minh công nông được củng cố, và chính quyền công nông được thiết lập rồi chuyển sang làm nhiệm vụ của chuyên chính vô sản. Thiếu một điều kiện nào cũng không đủ, nên chọn riêng A, B hoặc C là chưa đầy đủ.", "key_fact": "Chuyển lên cách mạng XHCN cần: Đảng lãnh đạo, liên minh công nông, chính quyền công nông làm nhiệm vụ chuyên chính vô sản.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-84", "question": "Cách mạng xã hội chủ nghĩa do giai cấp, tầng lớp nào lãnh đạo?", "options": [{"key": "A", "text": "Giai cấp công nhân, giai cấp nông dân"}, {"key": "B", "text": "Giai cấp công nhân, giai cấp nông dân, tầng lớp trí thức"}, {"key": "C", "text": "Giai cấp công nhân"}, {"key": "D", "text": "Giai cấp công nhân, giai cấp tư sản, giai cấp nông dân"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cách mạng XHCN do giai cấp công nhân thông qua đảng cộng sản lãnh đạo; nông dân và trí thức là lực lượng, động lực cùng tham gia chứ không phải lực lượng lãnh đạo. Vì vậy các phương án gộp nông dân, trí thức vào lực lượng lãnh đạo là sai.", "key_fact": "Giai cấp công nhân (qua đảng cộng sản) lãnh đạo cách mạng XHCN.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-85", "question": "Mục tiêu của giai đoạn thứ nhất của cách mạng xã hội chủ nghĩa là gì?", "options": [{"key": "A", "text": "Giải phóng con người, giải phóng xã hội"}, {"key": "B", "text": "Giành chính quyền về tay giai cấp công nhân và nhân dân lao động"}, {"key": "C", "text": "Xóa bỏ bóc lột đem lại đời sống ấm no cho nhân dân"}, {"key": "D", "text": "Cả ba đều đúng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Mục tiêu giai đoạn thứ nhất của cách mạng XHCN là giành chính quyền về tay giai cấp công nhân và nhân dân lao động. Giải phóng con người, giải phóng xã hội (A) là mục tiêu cuối cùng, còn xóa bỏ bóc lột (C) thuộc giai đoạn cải tạo, xây dựng sau đó.", "key_fact": "Giai đoạn thứ nhất của cách mạng XHCN: giành chính quyền.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-86", "question": "Mục tiêu cuối cùng của giai cấp công nhân, của cuộc cách mạng xã hội chủ nghĩa là?", "options": [{"key": "A", "text": "Giành chính quyền"}, {"key": "B", "text": "Giải phóng con người, giải phóng xã hội"}, {"key": "C", "text": "Đánh đổ chủ nghĩa tư bản"}, {"key": "D", "text": "Cả a, ba và c."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Mục tiêu cuối cùng của giai cấp công nhân và cách mạng XHCN là giải phóng con người, giải phóng xã hội, đem lại cuộc sống tự do, hạnh phúc cho mọi người. Giành chính quyền và đánh đổ chủ nghĩa tư bản chỉ là mục tiêu, bước đi trước đó, nên đáp án gộp D là sai.", "key_fact": "Mục tiêu cuối cùng: giải phóng con người, giải phóng xã hội.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-87", "question": "Mục tiêu cuối cùng của cách mạng xã hội chủ nghĩa là gì?", "options": [{"key": "A", "text": "Xoá bỏ chế độ tư hữu"}, {"key": "B", "text": "Giải phóng con người, giải phóng xã hội"}, {"key": "C", "text": "Giành chính quyền về tay giai cấp công nhân"}, {"key": "D", "text": "Xoá bỏ chế độ tư bản chủ nghĩa"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo giáo trình, mục tiêu cuối cùng của cách mạng XHCN là giải phóng xã hội, giải phóng con người khỏi mọi áp bức, bóc lột. Xóa bỏ chế độ tư hữu (A) hay chế độ TBCN (D) là phương tiện, nhiệm vụ để đạt mục tiêu đó, còn giành chính quyền (C) là mục tiêu giai đoạn đầu.", "key_fact": "Mục tiêu cuối cùng của cách mạng XHCN là giải phóng con người, giải phóng xã hội.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-88", "question": "Cách mạng xã hội chủ nghĩa lần đầu tiên nổ ra và thắng lợi ở đâu?", "options": [{"key": "A", "text": "Pháp"}, {"key": "B", "text": "Việt Nam"}, {"key": "C", "text": "Nga"}, {"key": "D", "text": "Trung Quốc"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cách mạng Tháng Mười Nga năm 1917 là cuộc cách mạng XHCN đầu tiên nổ ra và thắng lợi, mở ra thời đại mới. Pháp có Công xã Pari 1871 nhưng đó chỉ là cuộc cách mạng vô sản đầu tiên và đã thất bại.", "key_fact": "Cách mạng XHCN đầu tiên thắng lợi: Cách mạng Tháng Mười Nga 1917.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-89", "question": "Cách mạng dân chủ tư sản kiểu cũ và cách mạng dân chủ tư sản kiểu mới khác nhau ở điểm nào?", "options": [{"key": "A", "text": "Đối tượng của cách mạng."}, {"key": "B", "text": "Lực lượng tham gia."}, {"key": "C", "text": "Lực lượng lãnh đạo."}, {"key": "D", "text": "Cả a, b, c"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Điểm khác nhau căn bản giữa hai kiểu cách mạng dân chủ tư sản là lực lượng lãnh đạo: kiểu cũ do giai cấp tư sản lãnh đạo, kiểu mới do giai cấp công nhân lãnh đạo. Đối tượng (chế độ phong kiến) về cơ bản tương đồng nên không thể chọn \"cả a, b, c\".", "key_fact": "Khác biệt cốt lõi của cách mạng dân chủ tư sản kiểu cũ và kiểu mới là giai cấp lãnh đạo.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-90", "question": "Động lực cơ bản, chủ yếu của cách mạng xã hội chủ nghĩa là?", "options": [{"key": "A", "text": "Giai cấp nông dân."}, {"key": "B", "text": "Giai cấp công nhân"}, {"key": "C", "text": "Giai cấp tư sản."}, {"key": "D", "text": "Cả a,b,c"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giai cấp công nhân là lực lượng lãnh đạo đồng thời là động lực cơ bản, chủ yếu của cách mạng XHCN. Giai cấp nông dân (A) là động lực to lớn, quan trọng nhưng không phải động lực chủ yếu, còn tư sản là đối tượng của cách mạng.", "key_fact": "Giai cấp công nhân là động lực cơ bản, chủ yếu của cách mạng XHCN.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-91", "question": "Hình thức đầu tiên của chuyên chính vô sản là?", "options": [{"key": "A", "text": "Công xã Pari"}, {"key": "B", "text": "Nhà nước Xô viết"}, {"key": "C", "text": "Nhà nước dân chủ nhân dân"}, {"key": "D", "text": "Nhà nước xã hội chủ nghĩa"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Công xã Pari 1871 là hình thức nhà nước chuyên chính vô sản đầu tiên trong lịch sử, được Mác và Ăngghen tổng kết thành kinh nghiệm lý luận. Nhà nước Xô viết (B) ra đời sau Cách mạng Tháng Mười 1917, là nhà nước XHCN đầu tiên tồn tại lâu dài.", "key_fact": "Công xã Pari là hình thức đầu tiên của chuyên chính vô sản.", "topic": "Công xã Pari", "note": "", "comment_answer": null}, {"id": "MLN131-bo-92", "question": "Giai cấp nào không có hệ tư tưởng riêng.", "options": [{"key": "A", "text": "Giai cấp tư sản."}, {"key": "B", "text": "Giai cấp vô sản"}, {"key": "C", "text": "Giai cấp nông dân"}, {"key": "D", "text": "Giai cấp phong kiến"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giai cấp nông dân không đại diện cho một phương thức sản xuất độc lập, có tính phân tán, nên không có hệ tư tưởng riêng mà chịu ảnh hưởng hệ tư tưởng của giai cấp thống trị hoặc giai cấp lãnh đạo. Giai cấp tư sản, vô sản, phong kiến đều gắn với phương thức sản xuất riêng và có hệ tư tưởng riêng.", "key_fact": "Nông dân không có hệ tư tưởng riêng vì không đại diện cho phương thức sản xuất độc lập.", "topic": "Liên minh giai cấp, tầng lớp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-93", "question": "Trí thức được quan niệm là:", "options": [{"key": "A", "text": "Một giai cấp"}, {"key": "B", "text": "Một tầng lớp"}, {"key": "C", "text": "Cả a,b đều sai"}, {"key": "D", "text": "Cả a, b đều đúng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trí thức là một tầng lớp xã hội đặc biệt, lao động trí óc phức tạp, không có địa vị kinh tế độc lập trong hệ thống sản xuất nên không phải là một giai cấp. Chọn A là nhầm lẫn giữa giai cấp và tầng lớp xã hội.", "key_fact": "Trí thức là một tầng lớp xã hội, không phải giai cấp.", "topic": "Liên minh giai cấp, tầng lớp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-94", "question": "Tôn giáo hình thành là do:", "options": [{"key": "A", "text": "Trình độ nhận thức."}, {"key": "B", "text": "Trong xã hội có áp bức bóc lột."}, {"key": "C", "text": "Do tâm lý, tình cảm."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giáo trình nêu ba nguồn gốc của tôn giáo: nguồn gốc nhận thức (trình độ nhận thức hạn chế), nguồn gốc kinh tế - xã hội (sự bất lực trước tự nhiên, áp bức bóc lột) và nguồn gốc tâm lý (sợ hãi, tình cảm, lòng biết ơn). Chọn riêng một nguồn gốc là chưa đầy đủ.", "key_fact": "Tôn giáo có ba nguồn gốc: kinh tế - xã hội, nhận thức, tâm lý.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-95", "question": "Dùng tiêu chí nào để phân loại các tư tưởng xã hội chủ nghĩa?", "options": [{"key": "A", "text": "Theo lịch đại"}, {"key": "B", "text": "Theo trình độ phát triển tư tưởng"}, {"key": "C", "text": "Kết hợp tính lịch đại với trình độ phát triển"}, {"key": "D", "text": "Cả a, ba và c"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Để phân loại các tư tưởng XHCN, người ta kết hợp tiêu chí lịch đại (thời gian xuất hiện) với trình độ phát triển của tư tưởng (từ không tưởng đến khoa học). Dùng riêng một tiêu chí (A hoặc B) không phản ánh đủ cả tiến trình lịch sử lẫn chất lượng tư tưởng.", "key_fact": "Phân loại tư tưởng XHCN: kết hợp tính lịch đại với trình độ phát triển.", "topic": "Lịch sử tư tưởng XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-96", "question": "Ai đã nhận xét: “ ý nghĩa của chủ nghĩa không tưởng phê phán và của chủ nghĩa cộng sản không tưởng phê phán là tỉ lệ nghịch với thời gian”", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "Ph.Ăng ghen"}, {"key": "C", "text": "C.Mác và Ph.Ăng ghen"}, {"key": "D", "text": "V.I. Lênin"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nhận định này nằm trong \"Tuyên ngôn của Đảng cộng sản\" (1848), tác phẩm chung của C.Mác và Ph.Ăngghen, phần phê phán các trào lưu xã hội chủ nghĩa phi vô sản. Vì là tác phẩm viết chung nên chọn riêng Mác hoặc Ăngghen là chưa chính xác.", "key_fact": "\"Ý nghĩa của CNXH không tưởng phê phán tỷ lệ nghịch với thời gian\" (Tuyên ngôn, Mác - Ăngghen).", "topic": "Lịch sử tư tưởng XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-97", "question": "Khi phân tích về thời kỳ quá độ lên chủ nghĩa xã hội, ai là người đầu đặt vấn đề phải học tập các kinh nghiệm tổ chức, quản lý kinh tế của chủ nghĩa tư bản để cải tạo nền kinh tế tiểu nông lạc hậu?", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "V.I. Lênin"}, {"key": "C", "text": "Stalin"}, {"key": "D", "text": "Hồ Chí Minh"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong Chính sách kinh tế mới (NEP), V.I.Lênin chủ trương học tập kinh nghiệm tổ chức, quản lý của chủ nghĩa tư bản, sử dụng chủ nghĩa tư bản nhà nước để cải tạo nền kinh tế tiểu nông. Mác chưa trực tiếp chỉ đạo xây dựng CNXH nên chưa đặt vấn đề này trong thực tiễn.", "key_fact": "Lênin (NEP) chủ trương học tập kinh nghiệm quản lý của chủ nghĩa tư bản.", "topic": "Thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-98", "question": "Ai là người đưa ra tư tưởng độc lập dân tộc gắn liền với chủ nghĩa xã hội?", "options": [{"key": "A", "text": "V.I. Lênin"}, {"key": "B", "text": "Hồ Chí Minh"}, {"key": "C", "text": "Đặng Tiểu Bình"}, {"key": "D", "text": "Phạm Văn Đồng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Độc lập dân tộc gắn liền với chủ nghĩa xã hội là tư tưởng xuyên suốt của Hồ Chí Minh, xác định con đường cách mạng Việt Nam. Lênin bàn về vấn đề dân tộc, thuộc địa nói chung nhưng tư tưởng cụ thể này là của Hồ Chí Minh.", "key_fact": "Hồ Chí Minh: độc lập dân tộc gắn liền với chủ nghĩa xã hội.", "topic": "Con đường cách mạng Việt Nam", "note": "", "comment_answer": null}, {"id": "MLN131-bo-99", "question": "Câu “Giữa xã hội tư bản chủ nghĩa và xã hội cộng sản chủ nghĩa là một thời kì cải biến cách mạng từ xã hội nọ sang xã hội kia. Thích ứng với thời kỳ ấy là một thời kì quá độ chính trị, và nhà nước của thời kì ấy không thể là cái gì khác hơn là nền chuyên chính cách mạng của giai cấp vô sản” là của ai?", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "Ph.Ăng ghen"}, {"key": "C", "text": "C.Mác và Ph.Ăng ghen"}, {"key": "D", "text": "V.I.Lênin"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đây là luận điểm của C.Mác trong \"Phê phán Cương lĩnh Gô-ta\" (1875), khẳng định tất yếu của thời kỳ quá độ và nhà nước chuyên chính vô sản. Tác phẩm do Mác viết riêng nên không chọn C hay Lênin (Lênin chỉ trích dẫn và phát triển luận điểm này).", "key_fact": "Luận điểm về thời kỳ quá độ chính trị và chuyên chính vô sản là của Mác (Phê phán Cương lĩnh Gô-ta).", "topic": "Thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-100", "question": "Có mấy hình thức quá độ lên chủ nghĩa xã hội?", "options": [{"key": "A", "text": "Hai"}, {"key": "B", "text": "Ba"}, {"key": "C", "text": "Bốn"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Có hai hình thức quá độ lên CNXH: quá độ trực tiếp (từ CNTB phát triển lên CNXH) và quá độ gián tiếp (từ xã hội tiền tư bản, bỏ qua chế độ TBCN, như Việt Nam). Không có ba hay bốn hình thức.", "key_fact": "Hai hình thức quá độ: trực tiếp và gián tiếp.", "topic": "Thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-101", "question": "Quá độ lên chủ nghĩa xã hội bỏ qua chế độ tư bản chủ nghĩa là bỏ qua yếu tố nào của chủ nghĩa tư bản?", "options": [{"key": "A", "text": "Bỏ qua nhà nước của giai cấp tư sản."}, {"key": "B", "text": "Bỏ qua cơ sở kinh tế của chủ nghĩa tư bản."}, {"key": "C", "text": "Bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư tưởng tư bản chủ nghĩa."}, {"key": "D", "text": "Bỏ qua chế độ áp bức bóc lột của giai cấp tư sản"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo Đảng ta, bỏ qua chế độ TBCN là bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng TBCN, nhưng vẫn tiếp thu thành tựu của nhân loại dưới CNTB. Phương án B sai vì không bỏ qua toàn bộ cơ sở kinh tế như kinh tế thị trường, LLSX hiện đại.", "key_fact": "Bỏ qua TBCN là bỏ qua sự thống trị của QHSX và kiến trúc thượng tầng TBCN.", "topic": "Thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-102", "question": "Điền từ thiếu vào ô trống: “bước quá độ từ chủ nghĩa tư bản lên chủ nghĩa xã hội kẻ thù chủ yếu của chúng ta là giai cấp …, những tập quán thói quen của giai cấp ấy” (V.I. Lênin )", "options": [{"key": "A", "text": "Phong kiến"}, {"key": "B", "text": "Nông dân"}, {"key": "C", "text": "Tiểu tư sản"}, {"key": "D", "text": "Tư sản"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Lênin chỉ rõ trong bước quá độ, kẻ thù chủ yếu là giai cấp tiểu tư sản cùng những tập quán, thói quen, tâm lý tự phát của nó, vì lực lượng này rộng lớn và thường xuyên đẻ ra chủ nghĩa tư bản. Tư sản (D) là đối tượng đã bị đánh đổ về chính trị, nên không phải đáp án Lênin nêu ở đây.", "key_fact": "Lênin: kẻ thù chủ yếu trong bước quá độ là giai cấp tiểu tư sản và tập quán của nó.", "topic": "Thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-103", "question": "Hình thái kinh tế - xã hội cộng sản chủ nghĩa bắt đầu và kết thúc khi nào?", "options": [{"key": "A", "text": "Từ khi Đảng cộng sản ra đời và xây dựng xong chủ nghĩa xã hội."}, {"key": "B", "text": "Bắt đầu từ thời kỳ quá độ cho đến khi xây dựng xong giai đoạn cao của xã hội cộng sản."}, {"key": "C", "text": "Bắt đầu từ giai đoạn cao của xã hội cộng sản và kết thúc ở giai đoạn cao của xã hội cộng sản."}, {"key": "D", "text": "Cả ba đều không đúng."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hình thái kinh tế - xã hội cộng sản chủ nghĩa bắt đầu từ thời kỳ quá độ lên CNXH và kéo dài đến khi xây dựng xong giai đoạn cao là xã hội cộng sản. Sự ra đời của đảng cộng sản (A) không phải là điểm khởi đầu của hình thái kinh tế - xã hội.", "key_fact": "Hình thái KT-XH CSCN: từ thời kỳ quá độ đến giai đoạn cao của xã hội cộng sản.", "topic": "Hình thái KT-XH cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-104", "question": "Câu “Tôi coi sự phát triển của những hình thái kinh tế xã hội là một quá trình lịch sử tự nhiên” là của ai?", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "Ph.Ăng ghen"}, {"key": "C", "text": "C.Mác và Ph.Ăng ghen"}, {"key": "D", "text": "V.I.Lênin"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Câu này của C.Mác trong Lời tựa bộ \"Tư bản\", khẳng định sự phát triển của các hình thái kinh tế - xã hội là quá trình lịch sử - tự nhiên. Vì \"Tư bản\" là tác phẩm của riêng Mác nên không chọn C.", "key_fact": "Mác (Tư bản): sự phát triển hình thái KT-XH là quá trình lịch sử - tự nhiên.", "topic": "Hình thái KT-XH cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-105", "question": "Hôn nhân tiến bộ dựa trên cơ sở nào?", "options": [{"key": "A", "text": "Tình yêu"}, {"key": "B", "text": "Tự nguyện"}, {"key": "C", "text": "Hôn nhân 1 vợ một chồng"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hôn nhân tiến bộ là hôn nhân xuất phát từ tình yêu, tự nguyện, một vợ một chồng, vợ chồng bình đẳng và được bảo đảm về pháp lý. Mỗi phương án A, B, C chỉ nêu một khía cạnh nên chưa đầy đủ.", "key_fact": "Hôn nhân tiến bộ: tự nguyện, xuất phát từ tình yêu, một vợ một chồng, bình đẳng.", "topic": "Gia đình", "note": "", "comment_answer": null}, {"id": "MLN131-bo-106", "question": "Hiện nay tôn giáo nào ở Việt Nam có số lượng tín đồ đông nhất?", "options": [{"key": "A", "text": "Phật giáo"}, {"key": "B", "text": "Công giáo"}, {"key": "C", "text": "Tin lành"}, {"key": "D", "text": "Hồi giáo"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo số liệu thống kê tôn giáo, Phật giáo có số tín đồ đông nhất ở Việt Nam, tiếp theo là Công giáo. Công giáo (B) dễ gây nhầm vì có tổ chức chặt chẽ, nhưng số tín đồ ít hơn Phật giáo.", "key_fact": "Phật giáo là tôn giáo có nhiều tín đồ nhất ở Việt Nam.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-107", "question": "Chủ nghĩa xã hội nghiên cứu vấn đề tín ngưỡng, tôn giáo dưới góc độ nào?", "options": [{"key": "A", "text": "Góc độ chính trị-xã hội."}, {"key": "B", "text": "Hình thái ý thức xã hội."}, {"key": "C", "text": "Tâm lý-xã hội."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "CNXHKH nghiên cứu tín ngưỡng, tôn giáo vừa là một hình thái ý thức xã hội, vừa là một thực thể xã hội có tác động chính trị - xã hội, đồng thời gắn với tâm lý - xã hội của quần chúng. Chọn một góc độ riêng lẻ là chưa đầy đủ theo đáp án của đề.", "key_fact": "Tôn giáo được xem xét dưới nhiều góc độ: ý thức xã hội, chính trị - xã hội, tâm lý - xã hội.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-108", "question": "Sự thay đổi căn bản, toàn diện và triệt để một hình thái kinh tế – xã hội này bằng một hình thái kinh tế – xã hội khác là:", "options": [{"key": "A", "text": "Đột biến xã hội."}, {"key": "B", "text": "Cách mạng xã hội"}, {"key": "C", "text": "Cải cách xã hội"}, {"key": "D", "text": "Tiến bộ xã hội"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cách mạng xã hội là sự thay đổi căn bản, toàn diện và triệt để một hình thái kinh tế - xã hội này bằng một hình thái kinh tế - xã hội khác cao hơn. Cải cách xã hội (C) chỉ là thay đổi bộ phận trong khuôn khổ chế độ cũ, không thay đổi bản chất hình thái.", "key_fact": "Cách mạng xã hội là thay thế hình thái KT-XH này bằng hình thái KT-XH khác.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-109", "question": "Thời kỳ quá độ lên chủ nghĩa xã hội ở trên phạm vi cả nước ta bắt đầu từ khi nào?", "options": [{"key": "A", "text": "1945"}, {"key": "B", "text": "1954"}, {"key": "C", "text": "1975"}, {"key": "D", "text": "1930"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sau thắng lợi của cuộc Tổng tiến công mùa Xuân 1975, đất nước thống nhất, cả nước bước vào thời kỳ quá độ lên CNXH. Năm 1954 (B) chỉ là thời điểm miền Bắc bắt đầu quá độ lên CNXH, chưa phải phạm vi cả nước.", "key_fact": "Cả nước quá độ lên CNXH từ năm 1975; miền Bắc từ năm 1954.", "topic": "Thời kỳ quá độ ở Việt Nam", "note": "", "comment_answer": null}, {"id": "MLN131-bo-110", "question": "Xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng có mấy đặc trưng?", "options": [{"key": "A", "text": "5"}, {"key": "B", "text": "6"}, {"key": "C", "text": "7"}, {"key": "D", "text": "8"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cương lĩnh 1991 nêu 6 đặc trưng; Cương lĩnh xây dựng đất nước (bổ sung, phát triển năm 2011) nâng lên 8 đặc trưng của xã hội XHCN mà nhân dân ta xây dựng, và giáo trình CNXHKH 2021 trình bày theo Cương lĩnh 2011. Đáp án 6 chỉ đúng với nội dung cũ. (Nguồn: https://special.nhandan.vn/CNXH-la-che-do-vi-hanh-phuc-nhan-dan/index.html ; https://vov.vn/chinh-tri/tung-buoc-bo-sung-hoan-thien-mo-hinh-xay-dung-xhcn-o-viet-nam-post1175598.vov)", "key_fact": "Cương lĩnh 2011 (giáo trình hiện hành): xã hội XHCN Việt Nam có 8 đặc trưng.", "topic": "Thời kỳ quá độ ở Việt Nam", "note": "Đáp án gốc trong file ghi B, đã sửa sau khi tra cứu.", "comment_answer": null}, {"id": "MLN131-bo-111", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội được Đảng ta nêu ra ở Đại hội nào?", "options": [{"key": "A", "text": "Đại hội IV"}, {"key": "B", "text": "Đại hội VI"}, {"key": "C", "text": "Đại hội VII"}, {"key": "D", "text": "Đại hội VIII"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "\"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội\" được thông qua tại Đại hội VII (1991). Đại hội VI (1986) là đại hội khởi xướng đường lối đổi mới, chưa thông qua Cương lĩnh này.", "key_fact": "Cương lĩnh 1991 được thông qua tại Đại hội VII.", "topic": "Thời kỳ quá độ ở Việt Nam", "note": "", "comment_answer": null}, {"id": "MLN131-bo-112", "question": "Trong Văn kiện Đại hội IX, Đảng ta xác định phải tiếp thu và kế thừa những gì của chủ nghĩa tư bản trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam?", "options": [{"key": "A", "text": "Tiếp thu, kế thừa những thành tựu mà nhân loại đã đạt được dưới chế độ tư bản chủ nghĩa, đặc biệt về khoa học và công nghệ, để phát triển nhanh lực lượng sản xuất, xây dựng nền kinh tế hiện đại."}, {"key": "B", "text": "Tiếp thu, kế thừa mô hình quản lý kinh tế - xã hội và thành tựu khoa học công nghệ."}, {"key": "C", "text": "Tiếp thu, kế thừa những giá trị kinh tế, chính trị, văn hoá - xã hội và pháp luật trong chủ nghĩa tư bản."}, {"key": "D", "text": "Cả ba đều sai"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Văn kiện Đại hội IX xác định quá độ bỏ qua chế độ TBCN nhưng tiếp thu, kế thừa những thành tựu mà nhân loại đạt được dưới CNTB, đặc biệt về khoa học và công nghệ, để phát triển nhanh LLSX, xây dựng nền kinh tế hiện đại. Phương án C sai vì không kế thừa các giá trị chính trị, pháp luật mang bản chất tư sản.", "key_fact": "Đại hội IX: kế thừa thành tựu nhân loại dưới CNTB, đặc biệt khoa học và công nghệ.", "topic": "Thời kỳ quá độ ở Việt Nam", "note": "", "comment_answer": null}, {"id": "MLN131-bo-113", "question": "“Thời kì phát triển mới - đẩy mạnh công nghiệp hoá, hiện đại hoá đất nước” được Đảng ta nêu ra ở Đại hội nào?", "options": [{"key": "A", "text": "Đại hội VI"}, {"key": "B", "text": "Đại hội VII"}, {"key": "C", "text": "Đại hội VIII"}, {"key": "D", "text": "Đại hội IX"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đại hội VIII (1996) nhận định nước ta đã ra khỏi khủng hoảng kinh tế - xã hội và chuyển sang thời kỳ phát triển mới: đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước. Đại hội VII (B) mới đề ra Cương lĩnh, chưa xác định bước chuyển này.", "key_fact": "Đại hội VIII (1996): bước vào thời kỳ đẩy mạnh CNH, HĐH.", "topic": "Thời kỳ quá độ ở Việt Nam", "note": "", "comment_answer": null}, {"id": "MLN131-bo-114", "question": "Tìm ý đúng cho luận điểm sau: “Cùng với sự phát triển của khoa học và công nghệ ngày càng hiện đại, giai cấp công nhân:", "options": [{"key": "A", "text": "Giảm về số lượng và nâng cao về chất lượng."}, {"key": "B", "text": "Tăng về số lượng và nâng cao về chất lượng."}, {"key": "C", "text": "Giảm về số lượng và có trình độ sản xuất ngày càng cao"}, {"key": "D", "text": "Cả a, b và c."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo giáo trình cũ, cùng với sự phát triển của khoa học và công nghệ hiện đại, số công nhân lao động cơ bắp trực tiếp có xu hướng giảm, trong khi trình độ học vấn, tay nghề được nâng lên (xu hướng trí thức hóa). Phương án B dễ nhầm vì giáo trình mới nhấn mạnh giai cấp công nhân Việt Nam đang tăng về số lượng do công nghiệp hóa, nhưng nhận định trong câu nói về tác động chung của KHCN hiện đại.", "key_fact": "KHCN hiện đại làm công nhân lao động trực tiếp giảm về số lượng nhưng nâng cao về chất lượng.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-115", "question": "Xét về phương thức lao động, phương thức sản xuất, giai cấp công nhân mang thuộc tính cơ bản nào.", "options": [{"key": "A", "text": "Có số lượng đông nhất trong dân cư."}, {"key": "B", "text": "Là giai cấp tạo ra của cải vật chất làm giàu cho xã hội"}, {"key": "C", "text": "Là giai cấp trực tiếp vận hành máy móc có tính chất công nghiệp ngày càng hiện đại"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Xét về phương thức lao động, giai cấp công nhân là những người lao động trực tiếp hay gián tiếp vận hành công cụ sản xuất có tính chất công nghiệp ngày càng hiện đại, xã hội hóa cao. Phương án B là vai trò của mọi người lao động sản xuất nói chung, còn A không phải là thuộc tính về phương thức lao động.", "key_fact": "Về phương thức lao động: công nhân vận hành công cụ sản xuất công nghiệp ngày càng hiện đại.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-116", "question": "Xét trong quan hệ sản xuất tư bản chủ nghĩa giai cấp công nhân là:", "options": [{"key": "A", "text": "Giai cấp nghèo khổ nhất"}, {"key": "B", "text": "Giai cấp không có tư liệu sản xuất, đi làm thuê cho nhà tư bản, bị nhà tư bản bóc lột giá trị thặng dư"}, {"key": "C", "text": "Giai cấp có số lượng đông trong dân cư"}, {"key": "D", "text": "Cả a, b và c đều đúng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong quan hệ sản xuất TBCN, giai cấp công nhân không có tư liệu sản xuất, phải bán sức lao động cho nhà tư bản và bị bóc lột giá trị thặng dư. \"Nghèo khổ nhất\" (A) chỉ là hệ quả, không phải đặc trưng về quan hệ sản xuất.", "key_fact": "Trong CNTB, công nhân không có TLSX, làm thuê và bị bóc lột giá trị thặng dư.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-117", "question": "Nội dung sứ mệnh lịch sử của giai cấp công nhân là:", "options": [{"key": "A", "text": "Xoá bỏ chế độ tư bản chủ nghĩa, xoá bỏ chế độ người bóc lột người"}, {"key": "B", "text": "Giải phóng giai cấp công nhân, nhân dân lao động và toàn thể nhân loại khỏi mọi sự áp bức, bóc lột, nghèo nàn lạc hậu."}, {"key": "C", "text": "Xây dựng xã hội cộng sản chủ nghĩa văn minh"}, {"key": "D", "text": "Cả a, b và c đều đúng"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sứ mệnh lịch sử của giai cấp công nhân bao gồm: xóa bỏ chế độ TBCN và chế độ người bóc lột người, giải phóng giai cấp công nhân, nhân dân lao động và toàn nhân loại, xây dựng xã hội cộng sản văn minh. Mỗi phương án A, B, C chỉ là một mặt của sứ mệnh.", "key_fact": "Sứ mệnh GCCN: xóa bỏ CNTB, giải phóng nhân loại, xây dựng xã hội cộng sản.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-118", "question": "Chọn từ thích hợp điền vào ô trống “đối với chúng ta, chủ nghĩa cộng sản không phải là một …. cần phải sáng tạo ra, không phải là một …(2) mà hiện thực phải khuôn theo. Chúng ta gọi chủ nghĩa cộng sản là một phong trào….(3) nó xoá bỏ trạng thái hiện nay” (C.Mác: Hệ tư tưởng Đức).", "options": [{"key": "A", "text": "Lý tưởng(1), trạng thái (2), hiện thực (3)"}, {"key": "B", "text": "Trạng thái(1), lý tưởng (2), hiện thực (3)"}, {"key": "C", "text": "Trạng thái (1), hiện thực (2), lý tưởng (3)"}, {"key": "D", "text": "Hiện thực (1), lý tưởng (2), trạng thái (3)"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nguyên văn trong 'Hệ tư tưởng Đức': chủ nghĩa cộng sản 'không phải là một trạng thái cần phải sáng tạo ra, không phải là một lý tưởng mà hiện thực phải khuôn theo... phong trào hiện thực, nó xóa bỏ trạng thái hiện nay'. Thứ tự đúng là trạng thái – lý tưởng – hiện thực, tức phương án B; key A đảo chỗ (1) và (2).", "key_fact": "Mác: chủ nghĩa cộng sản không phải là trạng thái phải tạo ra, không phải lý tưởng hiện thực phải khuôn theo, mà là phong trào hiện thực.", "topic": "Lịch sử CNXH khoa học", "note": "Đáp án gốc trong file ghi A, đã sửa sau khi kiểm tra.", "comment_answer": null}, {"id": "MLN131-bo-119", "question": "Sứ mệnh lịch sử của giai cấp công nhân do các yếu tố khách quan nào quy định?", "options": [{"key": "A", "text": "Địa vị kinh tế - xã hội và đặc điểm chính trị - xã hội"}, {"key": "B", "text": "Là con đẻ của nền đại công nghiệp"}, {"key": "C", "text": "Do sự phát triển của lực lượng sản xuất hiện đại"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sứ mệnh lịch sử của giai cấp công nhân do những điều kiện khách quan quy định: địa vị kinh tế - xã hội (đại biểu LLSX tiên tiến, không có TLSX) và đặc điểm chính trị - xã hội (tiên phong, triệt để cách mạng, tổ chức kỷ luật, bản chất quốc tế). Phương án B, C chỉ là một phần nội hàm của địa vị kinh tế - xã hội.", "key_fact": "Sứ mệnh GCCN do địa vị kinh tế - xã hội và đặc điểm chính trị - xã hội quy định.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-120", "question": "Giai cấp công nhân là giai cấp triệt để cách mạng bởi vì:", "options": [{"key": "A", "text": "Xoá bỏ chủ nghĩa tư bản và xây dựng chủ nghĩa xã hội"}, {"key": "B", "text": "Là giai cấp không có tư liệu sản xuất"}, {"key": "C", "text": "Là giai cấp cùng khổ nhất trong xã hội"}, {"key": "D", "text": "Là giai cấp thực hiện xoá bỏ mọi chế độ tư hữu"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giai cấp công nhân triệt để cách mạng vì lợi ích của nó thống nhất với lợi ích nhân dân lao động, mục tiêu là xóa bỏ mọi chế độ tư hữu, không thay thế chế độ tư hữu này bằng chế độ tư hữu khác như các cuộc cách mạng trước. Phương án C (cùng khổ nhất) chỉ là biểu hiện, không lý giải tính triệt để.", "key_fact": "GCCN triệt để cách mạng vì xóa bỏ mọi chế độ tư hữu.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-121", "question": "Theo Lênin, quy luật hình thành và phát triển Đảng cộng sản của giai cấp công nhân là:", "options": [{"key": "A", "text": "Chủ nghĩa Mác kết hợp với phong trào công nhân"}, {"key": "B", "text": "Chủ nghĩa Mác – Lênin kết hợp với Phong trào công nhân"}, {"key": "C", "text": "Chủ nghĩa Mác – Lênin kết hợp với phong trào công nhân và Phong trào yêu nước"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo Lênin, đảng cộng sản ra đời là sản phẩm của sự kết hợp chủ nghĩa Mác với phong trào công nhân. Phương án C (thêm phong trào yêu nước) là sự vận dụng sáng tạo của Hồ Chí Minh cho trường hợp Việt Nam, không phải công thức của Lênin.", "key_fact": "Lênin: Đảng cộng sản = chủ nghĩa Mác + phong trào công nhân.", "topic": "Đảng cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-122", "question": "Nước cộng hoà dân chủ nhân dân đầu tiên ra đời ở châu á là nước nào?", "options": [{"key": "A", "text": "Việt Nam"}, {"key": "B", "text": "Trung Quốc"}, {"key": "C", "text": "Triều Tiên"}, {"key": "D", "text": "Mông cổ"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nước Cộng hòa nhân dân Mông Cổ được thành lập năm 1924, là nước cộng hòa dân chủ nhân dân đầu tiên ở châu Á. Việt Nam Dân chủ Cộng hòa ra đời năm 1945, là nhà nước dân chủ nhân dân đầu tiên ở Đông Nam Á, nên dễ gây nhầm.", "key_fact": "Mông Cổ (1924) là nước cộng hòa nhân dân đầu tiên ở châu Á.", "topic": "Lịch sử phong trào cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-123", "question": "Liên bang CH XHCN Xô-viết ( Liên xô) được thành lập năm nào?", "options": [{"key": "A", "text": "1917"}, {"key": "B", "text": "1918"}, {"key": "C", "text": "1922"}, {"key": "D", "text": "1924"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Liên bang Cộng hòa XHCN Xô viết (Liên Xô) được thành lập ngày 30/12/1922. Năm 1917 (A) là năm Cách mạng Tháng Mười thắng lợi, lập ra nước Nga Xô viết, chưa phải Liên Xô.", "key_fact": "Liên Xô thành lập ngày 30/12/1922.", "topic": "Lịch sử phong trào cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-124", "question": "Điền từ còn thiếu vào chỗ trống: Giai cấp công nhân là cơ sở … của Đảng cộng sản, là nguồn bổ sung lực lượng của Đảng cộng sản.", "options": [{"key": "A", "text": "Chính trị - xã hội"}, {"key": "B", "text": "Giai cấp"}, {"key": "C", "text": "Xã hội - giai cấp"}, {"key": "D", "text": "Chính trị"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giáo trình khẳng định giai cấp công nhân là cơ sở xã hội - giai cấp của đảng cộng sản, là nguồn bổ sung lực lượng cho Đảng. Từ \"chính trị - xã hội\" (A) dễ nhầm nhưng không đúng thuật ngữ giáo trình dùng.", "key_fact": "GCCN là cơ sở xã hội - giai cấp của Đảng cộng sản.", "topic": "Đảng cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-125", "question": "Điền từ còn thiếu vào chỗ trống: Đảng cộng sản Việt Nam ra đời là sản phẩm của sự kết hợp chủ nghĩa Mác - Lênin, với phong trào công nhân và … ở nước ta vào những năm cuối thập kỷ của thế kỷ XX.", "options": [{"key": "A", "text": "Chủ nghĩa yêu nước"}, {"key": "B", "text": "Phong trào yêu nước"}, {"key": "C", "text": "Truyền thống yêu nước"}, {"key": "D", "text": "Truyền thống dân tộc"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đảng Cộng sản Việt Nam ra đời là sản phẩm của sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước. Phương án A, C dễ nhầm vì có chữ \"yêu nước\" nhưng thuật ngữ chính xác là \"phong trào yêu nước\" (cùng loại với \"phong trào công nhân\").", "key_fact": "ĐCSVN = chủ nghĩa Mác - Lênin + phong trào công nhân + phong trào yêu nước.", "topic": "Đảng cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-126", "question": "Điền từ còn thiếu vào chỗ trống: Đảng cộng sản là … chiến đấu, là bộ tham mưu của giai cấp công nhân, là biểu hiện tập trung lợi ích, nguyện vọng, phẩm chất, trí tuệ của giai cấp công nhân và của dân tộc.", "options": [{"key": "A", "text": "Đội tiên phong"}, {"key": "B", "text": "Lực lượng"}, {"key": "C", "text": "Cơ sở"}, {"key": "D", "text": "Cơ quan chỉ huy"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đảng cộng sản là đội tiên phong chiến đấu, bộ tham mưu của giai cấp công nhân, đại biểu trung thành lợi ích của giai cấp công nhân và dân tộc. \"Cơ quan chỉ huy\" (D) không phải cách diễn đạt của giáo trình, đã có \"bộ tham mưu\" thể hiện ý này.", "key_fact": "Đảng cộng sản là đội tiên phong chiến đấu, bộ tham mưu của GCCN.", "topic": "Đảng cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-127", "question": "Quy luật hình thành và phát triển của Đảng cộng sản Việt Nam", "options": [{"key": "A", "text": "Chủ nghĩa Mác, tư tưởng Hồ Chí Minh và phong trào công nhân"}, {"key": "B", "text": "Chủ nghĩa Mác – Lênin, tư tưởng Hồ Chí Minh và phong trào công nhân"}, {"key": "C", "text": "Chủ nghĩa Mác - Lênin, phong trào công nhân, phong trào yêu nước"}, {"key": "D", "text": "Chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh, phong trào công nhân và phong trào yêu nước."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Quy luật ra đời của Đảng Cộng sản Việt Nam là sự kết hợp chủ nghĩa Mác - Lênin, phong trào công nhân và phong trào yêu nước, như Hồ Chí Minh đã khái quát. Phương án D sai vì tư tưởng Hồ Chí Minh là nền tảng tư tưởng của Đảng chứ không phải yếu tố trong quy luật ra đời năm 1930.", "key_fact": "Quy luật ra đời của ĐCSVN: Mác - Lênin + phong trào công nhân + phong trào yêu nước.", "topic": "Đảng cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-128", "question": "Cách mạng xã hội chủ nghĩa theo nghĩa rộng là:", "options": [{"key": "A", "text": "Là một cuộc cách mạng chính trị được kết thúc bằng việc giai cấp công nhân cùng với nhân dân lao động giành được chính quyền, thiết lập nhà nước chuyên chính vô sản."}, {"key": "B", "text": "Là một cuộc cách mạng có nội dung chủ yếu về mặt kinh tế dưới sự lãnh đạo của giai cấp công nhân để xây dựng chủ nghĩa xã hội và chủ nghĩa cộng sản."}, {"key": "C", "text": "Là quá trình cải biến một cách toàn diện trên tất cả các lĩnh vực của đời sống xã hội từ kinh tế, chính trị, văn hoá, tư tưởng, v.v. để xây dựng chủ nghĩa xã hội và cuối cùng là chủ nghĩa cộng sản."}, {"key": "D", "text": "Là cuộc cách mạng của giai cấp công nhân cùng với nhân dân lao động đánh đổ sự thống trị của giai cấp tư sản và lật đổ chủ nghĩa tư bản."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo nghĩa rộng, cách mạng XHCN là quá trình cải biến toàn diện trên mọi lĩnh vực kinh tế, chính trị, văn hóa, tư tưởng để xây dựng CNXH và cuối cùng là CNCS. Phương án A là định nghĩa theo nghĩa hẹp (cách mạng chính trị giành chính quyền).", "key_fact": "Nghĩa rộng: cải biến toàn diện; nghĩa hẹp: cách mạng chính trị giành chính quyền.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-129", "question": "Cách mạng xã hội chủ nghĩa theo nghĩa hẹp là gì?", "options": [{"key": "A", "text": "Là một cuộc cách mạng chính trị được kết thúc bằng việc giai cấp công nhân cùng với nhân dân lao động giành được chính quyền, thiết lập nhà nước chuyên chính vô sản."}, {"key": "B", "text": "Là một cuộc cách mạng có nội dung chủ yếu về mặt kinh tế dưới sự lãnh đạo của giai cấp công nhân để xây dựng chủ nghĩa xã hội và chủ nghĩa cộng sản."}, {"key": "C", "text": "Là quá trình cải biến một cách toàn diện trên tất cả các lĩnh vực của đời sống xã hội từ kinh tế, chính trị, văn hoá, tư tưởng, v.v. để xây dựng chủ nghĩa xã hội và cuối cùng là chủ nghĩa cộng sản."}, {"key": "D", "text": "Là cuộc cách mạng của giai cấp công nhân cùng với nhân dân lao động đánh đổ sự thống trị của giai cấp tư sản và lật đổ chủ nghĩa tư bản."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo nghĩa hẹp, cách mạng XHCN là cuộc cách mạng chính trị, kết thúc bằng việc giai cấp công nhân cùng nhân dân lao động giành chính quyền, thiết lập nhà nước chuyên chính vô sản. Phương án C là định nghĩa theo nghĩa rộng nên dễ nhầm.", "key_fact": "Nghĩa hẹp: cách mạng chính trị giành chính quyền, lập chuyên chính vô sản.", "topic": "Cách mạng xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-130", "question": "Chủ tịch Hồ Chí Minh đã nêu ra con đường phát triển của cách mạng Việt Nam trong Chánh cương vắn tắt của Đảng ta là:", "options": [{"key": "A", "text": "“Làm cách mạng dân tộc dân chủ nhân dân để đi thẳng tới chế độ cộng sản chủ nghĩa”."}, {"key": "B", "text": "“Làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản”."}, {"key": "C", "text": "“Làm thổ địa cách mạng và tư sản dân quyền cách mạng để đi tới xã hội cộng sản”."}, {"key": "D", "text": "“Làm tư sản dân quyền và thổ địa cách mạng để đi thẳng tới xã hội xã hội chủ nghĩa và cộng sản chủ nghĩa”."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Chánh cương vắn tắt (1930) xác định: làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản. Phương án C đảo trật tự, D thêm chữ \"đi thẳng tới xã hội XHCN\" không có trong nguyên văn.", "key_fact": "Chánh cương 1930: tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản.", "topic": "Con đường cách mạng Việt Nam", "note": "", "comment_answer": null}, {"id": "MLN131-bo-131", "question": "Tại sao cho rằng con đường cách mạng Việt Nam là quá độ lên chủ nghĩa xã hội bỏ qua chế độ tư bản chủ nghĩa là một tất yếu?", "options": [{"key": "A", "text": "Đảng cộng sản Việt Nam đã có đường lối đúng đắn"}, {"key": "B", "text": "Do sự phát triển của lực lượng sản xuất"}, {"key": "C", "text": "Vì nó phù hợp với đặc điểm của đất nước và xu thế phát triển của thời đại"}, {"key": "D", "text": "Vì nó đáp ứng được nguyện vọng và mong ước của nhân dân ta"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Con đường quá độ lên CNXH bỏ qua chế độ TBCN là tất yếu vì phù hợp với đặc điểm lịch sử, điều kiện của Việt Nam và xu thế phát triển của thời đại. Đường lối của Đảng (A) và nguyện vọng nhân dân (D) là yếu tố chủ quan, không đủ để chứng minh tính tất yếu khách quan.", "key_fact": "Quá độ bỏ qua TBCN là tất yếu vì phù hợp đặc điểm đất nước và xu thế thời đại.", "topic": "Thời kỳ quá độ ở Việt Nam", "note": "", "comment_answer": null}, {"id": "MLN131-bo-132", "question": "Cơ sở để xác định thời đại và phân chia thời đại là gì?", "options": [{"key": "A", "text": "Hình thái kinh tế - xã hội và vị trí của một giai cấp đứng ở vị trí trung tâm"}, {"key": "B", "text": "Vị trí của một giai cấp đứng ở vị trí trung tâm"}, {"key": "C", "text": "Sự phát triển của lực lượng sản xuất và một quan hệ sản xuất phù hợp"}, {"key": "D", "text": "Cách mạng xã hội chủ nghĩa do giai cấp công nhân lãnh đạo thành công"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo quan điểm mácxít, thời đại được xác định dựa trên hình thái kinh tế - xã hội và giai cấp đứng ở vị trí trung tâm của thời đại, quyết định nội dung và xu hướng phát triển. Phương án B chỉ nêu một yếu tố, còn C là cơ sở của phương thức sản xuất chứ không phải để phân chia thời đại.", "key_fact": "Phân chia thời đại dựa vào hình thái KT-XH và giai cấp đứng ở trung tâm thời đại.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-133", "question": "Thời đại ngày nay tồn tại mấy mâu thuẫn cơ bản?", "options": [{"key": "A", "text": "Hai"}, {"key": "B", "text": "Ba"}, {"key": "C", "text": "Bốn"}, {"key": "D", "text": "Năm"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Thời đại ngày nay có bốn mâu thuẫn cơ bản: giữa CNXH và CNTB; giữa tư bản và lao động; giữa các nước tư bản với nhau; giữa các dân tộc thuộc địa, phụ thuộc với chủ nghĩa đế quốc. Đếm thiếu một trong các mâu thuẫn này sẽ dẫn đến chọn sai A hoặc B.", "key_fact": "Thời đại ngày nay có bốn mâu thuẫn cơ bản.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-134", "question": "Mâu thuẫn cơ bản nổi bật của thời đại hiện nay là:", "options": [{"key": "A", "text": "Mâu thuẫn giữa chủ nghĩa xã hội và chủ nghĩa tư bản"}, {"key": "B", "text": "Giai cấp tư sản và giai cấp công nhân"}, {"key": "C", "text": "Các dân tộc thuộc địa và phụ thuộc với Chủ nghĩa đế quốc"}, {"key": "D", "text": "Mâu thuẫn giữa các nước tư bản chủ nghĩa"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong bốn mâu thuẫn cơ bản, mâu thuẫn giữa CNXH và CNTB là mâu thuẫn nổi bật, bao trùm của thời đại quá độ từ CNTB lên CNXH. Mâu thuẫn giữa tư sản và công nhân (B) là cơ bản trong lòng CNTB nhưng không đặc trưng cho cả thời đại.", "key_fact": "Mâu thuẫn nổi bật của thời đại: giữa CNXH và CNTB.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-135", "question": "Theo Lênin, nội dung của thời đại hiện nay là gì?", "options": [{"key": "A", "text": "Xoá bỏ chủ nghĩa tư bản và xây dựng chủ nghĩa xã hội."}, {"key": "B", "text": "Xoá bỏ giai cấp tư sản và chế độ tư bản chủ nghĩa, thiết lập những cơ sở của xã hội mới là xã hội chủ nghĩa và cộng sản chủ nghĩa."}, {"key": "C", "text": "Thiết lập những cơ sở của xã hội mới là xã hội xã hội chủ nghĩa và cộng sản chủ nghĩa."}, {"key": "D", "text": "Xác lập địa vị thống trị của giai cấp công nhân và nhân dân lao động."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo Lênin, nội dung của thời đại là xóa bỏ giai cấp tư sản và chế độ TBCN, thiết lập những cơ sở của xã hội mới - xã hội XHCN và CSCN. Phương án A và C chỉ nêu một vế, chưa đầy đủ nội dung như Lênin xác định.", "key_fact": "Nội dung thời đại (Lênin): xóa bỏ tư sản, CNTB và thiết lập cơ sở xã hội XHCN, CSCN.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-136", "question": "Thời đại hiện nay có mấy giai đoạn chính?", "options": [{"key": "A", "text": "Ba"}, {"key": "B", "text": "Bốn"}, {"key": "C", "text": "Năm"}, {"key": "D", "text": "Sáu"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giáo trình cũ chia thời đại hiện nay thành bốn giai đoạn chính: từ 1917 đến 1945; từ 1945 đến giữa những năm 1970; từ giữa những năm 1970 đến 1991; và từ 1991 đến nay. Số ba (A) dễ nhầm nếu gộp hai giai đoạn sau Chiến tranh thế giới thứ hai.", "key_fact": "Thời đại hiện nay được chia thành bốn giai đoạn chính.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-137", "question": "Ai là người đưa ra lí thuyết “ Ba làn sóng” hay “ Ba nền văn minh”?", "options": [{"key": "A", "text": "Sáclơ - phuriê"}, {"key": "B", "text": "C.Mác"}, {"key": "C", "text": "Alvin - Toffơlơ"}, {"key": "D", "text": "Nich xon"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Thuyết \"Ba làn sóng\" (nông nghiệp, công nghiệp, hậu công nghiệp/thông tin) do nhà tương lai học Mỹ Alvin Toffler đưa ra trong \"Làn sóng thứ ba\". Mác phân chia lịch sử theo các hình thái kinh tế - xã hội, không theo các làn sóng văn minh.", "key_fact": "Thuyết \"Ba làn sóng\" là của Alvin Toffler.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-138", "question": "Tính chất của thời đại ngày nay là:", "options": [{"key": "A", "text": "Thời kỳ quá độ từ chủ nghĩa tư bản lên chủ nghĩa xã hội trên phạm vi toàn thế giới."}, {"key": "B", "text": "Thời kỳ xây dựng những tiền đề kinh tế, chính trị, văn hoá, xã hội cho chủ nghĩa xã hội"}, {"key": "C", "text": "Diễn ra cuộc đấu tranh gay go, quyết liệt giữa chủ nghĩa xã hội và chủ nghĩa tư bản trên phạm vi toàn thế giới."}, {"key": "D", "text": "Giai cấp công nhân và nhân dân lao động tiến hành đấu tranh giành chính quyền đi lên xây dựng chủ nghĩa xã hội."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Giáo trình cũ xác định tính chất của thời đại ngày nay là cuộc đấu tranh gay go, quyết liệt giữa CNXH và CNTB trên phạm vi toàn thế giới. Phương án A (quá độ từ CNTB lên CNXH trên phạm vi toàn thế giới) thường được dùng để nêu nội dung, bản chất của thời đại nên dễ gây nhầm.", "key_fact": "Tính chất thời đại: đấu tranh gay go, quyết liệt giữa CNXH và CNTB.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-139", "question": "Nguyên nhân nào dẫn đến sự sụp đổ của CNXH ở Liên Xô và Đông Âu:", "options": [{"key": "A", "text": "Quan niệm và vận dụng không đúng đắn về CNXH"}, {"key": "B", "text": "Những sai lầm của Đảng và của những người lãnh đạo cấp cao nhất Đảng Cộng sản Liên Xô."}, {"key": "C", "text": "Sự chống phá của chủ nghĩa đế quốc và các thế lực thù địch bằng “Diễn biến hoà bình”"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sự sụp đổ của CNXH ở Liên Xô và Đông Âu do nhiều nguyên nhân: quan niệm và vận dụng không đúng về CNXH (mô hình tập trung quan liêu), sai lầm của lãnh đạo cấp cao trong cải tổ, và sự chống phá của chủ nghĩa đế quốc bằng \"diễn biến hòa bình\". Chọn một nguyên nhân là chưa đầy đủ.", "key_fact": "CNXH ở Liên Xô, Đông Âu sụp đổ do cả nguyên nhân bên trong lẫn bên ngoài.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-140", "question": "Sự sụp đổ của chế độ chủ nghĩa xã hội ở Liên xô và Đông Âu đã làm cho:", "options": [{"key": "A", "text": "Tính chất và nội dung của thời đại hiện nay có thay đổi."}, {"key": "B", "text": "Tính chất và nội dung của thời đại hiện nay không thay đổi."}, {"key": "C", "text": "Tính chất của thời đại hiện nay có thay đổi."}, {"key": "D", "text": "Nội dung của thời đại hiện nay có thay đổi."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sự sụp đổ của CNXH ở Liên Xô và Đông Âu là tổn thất lớn, làm CNXH tạm thời lâm vào thoái trào, nhưng không làm thay đổi tính chất và nội dung của thời đại: loài người vẫn trong thời đại quá độ từ CNTB lên CNXH. Các phương án A, C, D cho rằng thời đại đã thay đổi là sai.", "key_fact": "Sự sụp đổ ở Liên Xô, Đông Âu không làm thay đổi tính chất, nội dung của thời đại.", "topic": "Thời đại ngày nay", "note": "", "comment_answer": null}, {"id": "MLN131-bo-141", "question": "Trong những mâu thuẫn cơ bản của thời đại hiện nay, mâu thuẫn nào là nổi bật, xuyên suốt thời đại mang tính toàn cầu.", "options": [{"key": "A", "text": "Mâu thuẫn giữa chủ nghĩa xã hội và chủ nghĩa tư bản."}, {"key": "B", "text": "Mâu thuẫn giữa tư bản và lao động."}, {"key": "C", "text": "Mâu thuẫn giữa các dân tộc thuộc địa và phụ thuộc với chủ nghĩa đế quốc"}, {"key": "D", "text": "Mâu thuẫn giữa các nước tư bản với nhau."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Mâu thuẫn giữa CNXH và CNTB là mâu thuẫn giữa hai chế độ xã hội đối lập, xuyên suốt cả thời đại quá độ từ CNTB lên CNXH trên phạm vi toàn thế giới. Mâu thuẫn tư bản – lao động (B) là mâu thuẫn cơ bản nhưng chủ yếu nằm trong lòng từng nước tư bản, không bao trùm toàn bộ thời đại như A.", "key_fact": "Mâu thuẫn CNXH – CNTB nổi bật, xuyên suốt thời đại hiện nay mang tính toàn cầu.", "topic": "Thời đại và thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-142", "question": "Công nghiệp hoá là:", "options": [{"key": "A", "text": "Quy luật bắt buộc đối mọi quốc gia quá độ lên CNXH"}, {"key": "B", "text": "Không phải là quy luật bắt buộc đối với mọi quốc gia quá độ lên CNXH."}, {"key": "C", "text": "Quy luật bắt buộc đối với các quốc gia TBCN khi quá độ lên CNXH."}, {"key": "D", "text": "Cả a và c."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Công nghiệp hoá là nhiệm vụ trung tâm, có tính quy luật đối với các nước quá độ lên CNXH từ nền sản xuất nhỏ, lạc hậu; còn nước đã có nền đại công nghiệp TBCN thì không phải tiến hành công nghiệp hoá lại từ đầu. Vì vậy nó không phải quy luật bắt buộc với mọi quốc gia; phương án A sai vì tuyệt đối hoá, C sai vì nước TBCN phát triển đã có công nghiệp.", "key_fact": "CNH là tất yếu với nước quá độ từ sản xuất nhỏ, không bắt buộc với mọi quốc gia.", "topic": "Thời đại và thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-143", "question": "Quan hệ giữa lợi ích dân tộc với lợi ích của giai cấp công nhân dưới chủ nghĩa xã hội:", "options": [{"key": "A", "text": "Là mâu thuẫn"}, {"key": "B", "text": "Là thống nhất"}, {"key": "C", "text": "Là thống nhất về căn bản"}, {"key": "D", "text": "Đồng nhất với nhau"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Dưới CNXH, lợi ích của giai cấp công nhân về cơ bản phù hợp với lợi ích của toàn dân tộc, vì giai cấp công nhân giải phóng mình đồng thời giải phóng dân tộc. Tuy nhiên vẫn có thể có khác biệt cục bộ nên không thể nói 'đồng nhất' (D) hay 'thống nhất' tuyệt đối (B).", "key_fact": "Lợi ích dân tộc và lợi ích giai cấp công nhân dưới CNXH thống nhất về căn bản.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-144", "question": "Chọn một câu trả lời đúng nhất TBCN hiện đại là một giai đoạn phát triển mới của chủ nghĩa tư bản.", "options": [{"key": "A", "text": "TBCN hiện đại là một giai đoạn phát triển mới của chủ nghĩa tư bản"}, {"key": "B", "text": "TBCN hiện đại đã khắc phục được mâu thuẫn cơ bản vốn có của nó"}, {"key": "C", "text": "TBCN hiện đại không khác gì TBCN trước đây"}, {"key": "D", "text": "Cả a, b và c đều sai"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "CNTB hiện đại là giai đoạn phát triển mới của CNTB với nhiều điều chỉnh về sở hữu, quản lý, phân phối nhờ cách mạng khoa học – công nghệ. Nhưng nó chưa khắc phục được mâu thuẫn cơ bản giữa tính xã hội hoá của sản xuất với chế độ chiếm hữu tư nhân TBCN (B sai), và cũng có khác biệt so với CNTB trước đây (C sai).", "key_fact": "CNTB hiện đại là giai đoạn mới nhưng chưa xoá được mâu thuẫn cơ bản của nó.", "topic": "Thời đại và thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-145", "question": "Dân chủ là gì?", "options": [{"key": "A", "text": "Là quyền lực thuộc về nhân dân"}, {"key": "B", "text": "Là quyền của con người"}, {"key": "C", "text": "Là quyền tự do của mỗi người"}, {"key": "D", "text": "Là trật tự xã hội"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo nghĩa gốc (demos – kratos), dân chủ là quyền lực thuộc về nhân dân; giáo trình xác định dân chủ trước hết là quyền lực của nhân dân. Các phương án B, C chỉ là quyền con người, quyền tự do – những biểu hiện, không phải bản chất của khái niệm dân chủ.", "key_fact": "Dân chủ là quyền lực thuộc về nhân dân.", "topic": "Dân chủ XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-146", "question": "Phạm trù dân chủ xuất hiện khi nào?", "options": [{"key": "A", "text": "Ngay từ khi có xã hội loài người."}, {"key": "B", "text": "Khi có nhà nước vô sản."}, {"key": "C", "text": "Khi có nhà nước"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Với tư cách một phạm trù chính trị gắn với một hình thức nhà nước, dân chủ chỉ xuất hiện khi xã hội có giai cấp và nhà nước (nền dân chủ chủ nô). Phương án A dễ nhầm vì trong cộng đồng nguyên thuỷ có hình thức tự quản 'dân chủ nguyên thuỷ', nhưng đó chưa phải dân chủ với nghĩa chế độ nhà nước; B sai vì dân chủ đã có từ trước nhà nước vô sản.", "key_fact": "Dân chủ với tư cách chế độ chính trị xuất hiện cùng nhà nước.", "topic": "Dân chủ XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-147", "question": "Dân chủ được xem xét dưới góc độ nào?", "options": [{"key": "A", "text": "Phạm trù chính trị"}, {"key": "B", "text": "Phạm trù lịch sử"}, {"key": "C", "text": "Phạm trù văn hoá"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Dân chủ là một giá trị xã hội được xem xét trên nhiều góc độ: là phạm trù chính trị (gắn với nhà nước, giai cấp), là phạm trù lịch sử (ra đời, phát triển qua các nền dân chủ) và là giá trị văn hoá, tinh thần của nhân loại. Chọn riêng A hay B là chưa đầy đủ.", "key_fact": "Dân chủ vừa là phạm trù chính trị, phạm trù lịch sử, vừa là giá trị văn hoá.", "topic": "Dân chủ XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-148", "question": "So với các nền dân chủ trước đây, dân chủ xã hội chủ nghĩa có điểm khác biệt cơ bản nào?", "options": [{"key": "A", "text": "Không còn mang tính giai cấp."}, {"key": "B", "text": "Là nền dân chủ phi lịch sử."}, {"key": "C", "text": "Là nền dân chủ thuần tuý."}, {"key": "D", "text": "Là nền dân chủ rộng rãi cho giai cấp công nhân và nhân dân lao động."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Dân chủ XHCN là nền dân chủ rộng rãi cho đại đa số nhân dân lao động, do giai cấp công nhân lãnh đạo. Nó vẫn mang tính giai cấp và tính lịch sử, nên không phải 'phi giai cấp', 'phi lịch sử' hay 'dân chủ thuần tuý' như các phương án A, B, C.", "key_fact": "Dân chủ XHCN là dân chủ cho đại đa số nhân dân lao động, vẫn mang tính giai cấp.", "topic": "Dân chủ XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-149", "question": "Điền từ còn thiếu vào chỗ trống: “Nước ta là nước dân chủ, nghĩa là nước nhà do nhân dân làm chủ. Nhân dân có quyền lợi làm chủ, thì phải có … làm tròn bổn phận công dân” (Hồ Chí Minh)", "options": [{"key": "A", "text": "Trách nhiệm"}, {"key": "B", "text": "Nghĩa vụ"}, {"key": "C", "text": "Trình độ để"}, {"key": "D", "text": "Khả năng để"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hồ Chí Minh viết: nhân dân có quyền lợi làm chủ thì phải có nghĩa vụ làm tròn bổn phận công dân – nhấn mạnh quyền đi đôi với nghĩa vụ. 'Trách nhiệm' (A) gần nghĩa nhưng không phải từ trong nguyên văn.", "key_fact": "Theo Hồ Chí Minh, quyền làm chủ luôn đi đôi với nghĩa vụ công dân.", "topic": "Dân chủ XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-150", "question": "Điền vào ô trống từ còn thiếu: “Quyền không bao giờ có thể ở một mức độ cao hơn chế độ … và sự phát triển văn hoá của xã hội do chế độ … đó quyết định” (Mác: Phê phán Cương lĩnh Gôta)", "options": [{"key": "A", "text": "Chính trị"}, {"key": "B", "text": "Xã hội"}, {"key": "C", "text": "Kinh tế"}, {"key": "D", "text": "Nhà nước"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong 'Phê phán Cương lĩnh Gôta', Mác khẳng định quyền không bao giờ cao hơn chế độ kinh tế và sự phát triển văn hoá do chế độ kinh tế quyết định. Điều này thể hiện quan điểm duy vật: kinh tế là cơ sở quyết định; 'chính trị' (A) là kiến trúc thượng tầng, không phải yếu tố quyết định.", "key_fact": "Quyền không bao giờ cao hơn chế độ kinh tế (Mác).", "topic": "Dân chủ XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-151", "question": "Câu “Thực hành dân chủ là cái chìa khoá vạn năng có thể giải quyết mọi khó khăn” là của ai?", "options": [{"key": "A", "text": "V.I. Lênin"}, {"key": "B", "text": "Mao Trạch Đông"}, {"key": "C", "text": "Hồ Chí Minh"}, {"key": "D", "text": "Lê Duẩn"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Câu 'Thực hành dân chủ là cái chìa khoá vạn năng có thể giải quyết mọi khó khăn' là của Chủ tịch Hồ Chí Minh, thể hiện vai trò của dân chủ như động lực phát triển. Lênin (A) nhấn mạnh dân chủ nhưng không phải tác giả câu này.", "key_fact": "'Thực hành dân chủ là chìa khoá vạn năng' – Hồ Chí Minh.", "topic": "Dân chủ XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-152", "question": "Bản chất chính trị của nền dân chủ xã hội chủ nghĩa thể hiện như thế nào?", "options": [{"key": "A", "text": "Là sự lãnh đạo của giai cấp công nhân thông qua đảng của nó đối với toàn xã hội, để thực hiện quyền lực và lợi ích của toàn thể nhân dân lao động, trong đó có giai cấp công nhân."}, {"key": "B", "text": "Là thực hiện quyền lực của giai cấp công nhân và nhân dân lao động đối với toàn xã hội."}, {"key": "C", "text": "Là sự lãnh đạo của giai cấp công nhân thông qua chính đảng của nó để cải tạo xã hội cũ và xây dựng xã hội mới."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Về chính trị, dân chủ XHCN là sự lãnh đạo của giai cấp công nhân thông qua đảng của nó đối với toàn xã hội, nhằm thực hiện quyền lực và lợi ích của toàn thể nhân dân lao động, trong đó có giai cấp công nhân. Phương án C chỉ nêu mục tiêu cải tạo xã hội, B thiếu vai trò lãnh đạo của Đảng nên không đầy đủ.", "key_fact": "Bản chất chính trị của dân chủ XHCN: GCCN lãnh đạo qua Đảng vì lợi ích toàn thể nhân dân lao động.", "topic": "Dân chủ XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-153", "question": "Khái niệm “Hệ thống chính trị xã hội chủ nghĩa” do tổ chức nào sau đây nêu ra?", "options": [{"key": "A", "text": "Đảng Cộng sản Liên Xô"}, {"key": "B", "text": "Đảng Cộng sản Trung Quốc"}, {"key": "C", "text": "Đảng Cộng sản Việt Nam"}, {"key": "D", "text": "Quốc tế cộng sản (Quốc tế III)"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Khái niệm 'hệ thống chính trị' được Đảng Cộng sản Việt Nam sử dụng chính thức từ Hội nghị Trung ương 6 khoá VI (1989), thay cho 'hệ thống chuyên chính vô sản' trước đó. Các đảng Liên Xô, Trung Quốc hay Quốc tế III không phải nơi đưa ra khái niệm này trong giáo trình.", "key_fact": "Khái niệm 'hệ thống chính trị XHCN' do Đảng Cộng sản Việt Nam nêu ra.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-154", "question": "Theo Đảng ta cấu trúc cơ bản của hệ thống chính trị xã hội chủ nghĩa bao gồm:", "options": [{"key": "A", "text": "Đảng cộng sản, nhà nước xã hội chủ nghĩa"}, {"key": "B", "text": "Đảng cộng sản Việt Nam, nhà nước xã hội chủ nghĩa, các tổ chức xã hội chính trị."}, {"key": "C", "text": "Đảng cộng sản, nhà nước xã hội chủ nghĩa, hệ thống pháp luật"}, {"key": "D", "text": "Cả ba đều đúng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hệ thống chính trị nước ta gồm Đảng Cộng sản Việt Nam (lãnh đạo), Nhà nước CHXHCN Việt Nam (trụ cột) và Mặt trận Tổ quốc cùng các tổ chức chính trị – xã hội. Hệ thống pháp luật (C) là công cụ của nhà nước, không phải một bộ phận cấu thành hệ thống chính trị.", "key_fact": "Hệ thống chính trị = Đảng + Nhà nước + Mặt trận và các đoàn thể chính trị - xã hội.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-155", "question": "Về bản chất “Hệ thống chính trị xã hội chủ nghĩa” và “hệ thống chuyên chính vô sản” là thống nhất?", "options": [{"key": "A", "text": "Đúng"}, {"key": "B", "text": "Sai"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hệ thống chính trị XHCN chính là sự kế thừa, phát triển của hệ thống chuyên chính vô sản; cách gọi thay đổi nhưng bản chất giai cấp công nhân và mục tiêu thực hiện quyền lực nhân dân là thống nhất. Vì vậy khẳng định 'sai' là không đúng.", "key_fact": "Hệ thống chính trị XHCN và hệ thống chuyên chính vô sản thống nhất về bản chất.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-156", "question": "Đổi mới hệ thống chính trị ở nước ta hiện nay là:", "options": [{"key": "A", "text": "Đổi mới mục tiêu, con đường xã hội chủ nghĩa"}, {"key": "B", "text": "Đổi mới nội dung, phương thức hoạt động, tổ chức cán bộ và quan hệ giữa các tổ chức trong hệ thống chính trị"}, {"key": "C", "text": "Thay đổi hệ thống tư duy lý luận"}, {"key": "D", "text": "Đổi mới tư duy"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đổi mới hệ thống chính trị là đổi mới nội dung, phương thức hoạt động, tổ chức, cán bộ và mối quan hệ giữa các tổ chức trong hệ thống, chứ không thay đổi mục tiêu và con đường XHCN (A sai). 'Đổi mới tư duy' (D) là đổi mới về nhận thức, không phải nội dung trực tiếp của đổi mới hệ thống chính trị.", "key_fact": "Đổi mới hệ thống chính trị không đổi mục tiêu XHCN mà đổi tổ chức, phương thức hoạt động.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-157", "question": "Điền từ còn thiếu vào chỗ trống: Nhà nước xã hội chủ nghĩa vừa có bản chất giai cấp công nhân, vừa có tính nhân dân rộng rãi và tính... sâu sắc.", "options": [{"key": "A", "text": "Giai cấp"}, {"key": "B", "text": "Nhân đạo"}, {"key": "C", "text": "Dân tộc"}, {"key": "D", "text": "Cộng đồng"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nhà nước XHCN Việt Nam mang bản chất giai cấp công nhân, đồng thời có tính nhân dân rộng rãi và tính dân tộc sâu sắc, vì gắn liền với truyền thống dựng nước và giữ nước của dân tộc. 'Giai cấp' (A) đã nằm trong vế bản chất giai cấp công nhân nên không phù hợp.", "key_fact": "Nhà nước XHCN: bản chất GCCN, tính nhân dân rộng rãi, tính dân tộc sâu sắc.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-158", "question": "Tổ chức nào đóng vai trò trụ cột trong hệ thống chính trị ở nước ta hiện nay?", "options": [{"key": "A", "text": "Đảng cộng sản Việt Nam"}, {"key": "B", "text": "Nhà nước xã hội chủ nghĩa"}, {"key": "C", "text": "Mặt trận Tổ quốc"}, {"key": "D", "text": "Các đoàn thể nhân dân"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong hệ thống chính trị, Đảng là hạt nhân lãnh đạo, còn Nhà nước là trụ cột – tổ chức thực hiện quyền lực nhân dân và quản lý xã hội bằng pháp luật. Phương án A dễ nhầm, nhưng vai trò của Đảng là 'lãnh đạo', không phải 'trụ cột'.", "key_fact": "Đảng lãnh đạo, Nhà nước là trụ cột của hệ thống chính trị.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-159", "question": "Bản chất của nhà nước xã hội chủ nghĩa là gì?", "options": [{"key": "A", "text": "Mang bản chất của giai cấp công nhân."}, {"key": "B", "text": "Mang bản chất của đa số nhân dân lao động."}, {"key": "C", "text": "Mang bản chất của giai cấp công nhân, tính nhân dân rộng rãi và tính dân tộc sâu sắc."}, {"key": "D", "text": "Vừa mang bản chất của giai cấp công nhân, vừa mang bản chất của nhân dân lao động và tính dân tộc sâu sắc."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nhà nước XHCN mang bản chất giai cấp công nhân, có tính nhân dân rộng rãi và tính dân tộc sâu sắc. Phương án D dễ nhầm vì nói 'bản chất của nhân dân lao động' – thực ra nhà nước chỉ có một bản chất là giai cấp công nhân, còn tính nhân dân là thuộc tính.", "key_fact": "Nhà nước XHCN có một bản chất là GCCN, kèm tính nhân dân và tính dân tộc.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-160", "question": "Nhà nước pháp quyền xã hội chủ nghĩa quản lý mọi mặt của đời sống xã hội chủ yếu bằng gì?", "options": [{"key": "A", "text": "Đường lối, chính sách"}, {"key": "B", "text": "Hiến pháp, pháp luật"}, {"key": "C", "text": "Tuyên truyền, giáo dục."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nhà nước pháp quyền XHCN quản lý xã hội chủ yếu bằng Hiến pháp và pháp luật, bảo đảm tính tối thượng của pháp luật. Đường lối, chính sách (A) là của Đảng; tuyên truyền, giáo dục (C) chỉ là phương pháp bổ trợ.", "key_fact": "Nhà nước pháp quyền quản lý xã hội chủ yếu bằng Hiến pháp và pháp luật.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-161", "question": "Hệ thống chính trị ở Việt Nam hiện nay ra đời từ khi nào?", "options": [{"key": "A", "text": "1930"}, {"key": "B", "text": "1945"}, {"key": "C", "text": "1954"}, {"key": "D", "text": "1975"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hệ thống chính trị dân chủ nhân dân, với đầy đủ Đảng, Nhà nước và các đoàn thể, ra đời từ Cách mạng tháng Tám năm 1945 với sự ra đời của nước Việt Nam Dân chủ Cộng hoà. Năm 1930 (A) chỉ mới thành lập Đảng, chưa có nhà nước nên chưa hình thành hệ thống chính trị hoàn chỉnh.", "key_fact": "Hệ thống chính trị nước ta ra đời từ Cách mạng tháng Tám 1945.", "topic": "Nhà nước và hệ thống chính trị", "note": "", "comment_answer": null}, {"id": "MLN131-bo-162", "question": "Những đặc trưng cơ bản của chủ nghĩa xã hội mà nhân dân ta đang xây dựng hiện nay được thông qua tại:", "options": [{"key": "A", "text": "Đại hội VI"}, {"key": "B", "text": "Đại hội VII"}, {"key": "C", "text": "Đại hội VIII"}, {"key": "D", "text": "Đại hội IX"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên CNXH, thông qua tại Đại hội VII (1991), lần đầu nêu 6 đặc trưng của xã hội XHCN mà nhân dân ta xây dựng. Đại hội VI (A) là đại hội khởi xướng đổi mới nhưng chưa nêu các đặc trưng này.", "key_fact": "Đặc trưng CNXH Việt Nam được nêu trong Cương lĩnh 1991 (Đại hội VII).", "topic": "Thời đại và thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-163", "question": "Câu “Giữ vững và tăng cường bản chất giai cấp công nhân của Đảng. Đây là nhiệm vụ có ý nghĩa quan trọng hàng đầu đối với Đảng ta”. Được ghi ở Văn kiện nào Đại hội nào của Đảng?", "options": [{"key": "A", "text": "Đại hội VI"}, {"key": "B", "text": "Đại hội VII"}, {"key": "C", "text": "Đại hội VIII"}, {"key": "D", "text": "Đại hội IX"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Văn kiện Đại hội VIII (1996) nhấn mạnh giữ vững và tăng cường bản chất giai cấp công nhân của Đảng là nhiệm vụ có ý nghĩa quan trọng hàng đầu trong xây dựng Đảng. Các đại hội VII, IX cũng nói đến bản chất giai cấp của Đảng nhưng câu trích này thuộc Đại hội VIII.", "key_fact": "Đại hội VIII: tăng cường bản chất GCCN của Đảng là nhiệm vụ quan trọng hàng đầu.", "topic": "Đảng Cộng sản", "note": "", "comment_answer": null}, {"id": "MLN131-bo-164", "question": "Khái niệm “Chuyên chính của giai cấp công nhân” được sử dụng lần đầu tiên trong tác phẩm nào?", "options": [{"key": "A", "text": "Hệ tư tưởng Đức"}, {"key": "B", "text": "Những nguyên lý của CNCS"}, {"key": "C", "text": "Tuyên ngôn của Đảng cộng sản"}, {"key": "D", "text": "Nội chiến ở Pháp"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo đáp án giáo trình, tư tưởng giai cấp vô sản giành chính quyền, trở thành giai cấp thống trị được nêu trong 'Tuyên ngôn của Đảng Cộng sản' (1848). Lưu ý: thuật ngữ 'chuyên chính vô sản' xuất hiện rõ trong tác phẩm 'Đấu tranh giai cấp ở Pháp' (1850) của Mác – không có trong các phương án; 'Nội chiến ở Pháp' (D) ra đời muộn hơn (1871).", "key_fact": "Tư tưởng chuyên chính của GCCN được trình bày từ Tuyên ngôn của Đảng Cộng sản.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-165", "question": "Trong xã hội có giai cấp, cơ cấu nào có vị trí quyết định nhất, chi phối các loại hình cơ cấu xã hội khác?", "options": [{"key": "A", "text": "Cơ cấu xã hội - nghề nghiệp"}, {"key": "B", "text": "Cơ cấu xã hội - dân số"}, {"key": "C", "text": "Cơ cấu xã hội - giai cấp"}, {"key": "D", "text": "Cơ cấu xã hội - dân tộc"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong xã hội có giai cấp, cơ cấu xã hội – giai cấp có vị trí quyết định, chi phối các loại cơ cấu xã hội khác vì liên quan đến sở hữu tư liệu sản xuất, tổ chức quản lý và quyền lực chính trị. Cơ cấu xã hội – nghề nghiệp (A) dễ nhầm nhưng chỉ là một loại hình chịu sự chi phối.", "key_fact": "Cơ cấu xã hội – giai cấp là loại hình cơ bản, quyết định nhất.", "topic": "Cơ cấu xã hội - giai cấp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-166", "question": "Sự biến đổi của cơ cấu xã hội – giai cấp gắn liền và được quy định bởi sự biến động của cơ cấu nào?", "options": [{"key": "A", "text": "Cơ cấu xã hội - dân số"}, {"key": "B", "text": "Cơ cấu xã hội - kinh tế"}, {"key": "C", "text": "Cơ cấu xã hội - dân tộc"}, {"key": "D", "text": "Cơ cấu xã hội - dân cư"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Sự biến đổi của cơ cấu xã hội – giai cấp gắn liền và bị quy định bởi sự biến đổi của cơ cấu kinh tế (cơ cấu ngành, thành phần kinh tế). Cơ cấu dân số, dân cư (A, D) chỉ là các yếu tố phụ, không có tính quyết định.", "key_fact": "Cơ cấu kinh tế quy định sự biến đổi của cơ cấu xã hội – giai cấp.", "topic": "Cơ cấu xã hội - giai cấp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-167", "question": "Trong quá trình xây dựng chủ nghĩa xã hội, liên minh giữa giai cấp công nhân, giai cấp nông dân và tầng lớp trí thức dưới góc độ nào giữ vai trò quyết định?", "options": [{"key": "A", "text": "Chính trị"}, {"key": "B", "text": "Kinh tế"}, {"key": "C", "text": "Văn hoá"}, {"key": "D", "text": "Tư tưởng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong thời kỳ xây dựng CNXH, liên minh công – nông – trí thức trên lĩnh vực kinh tế là nội dung cơ bản, giữ vai trò quyết định, vì nó tạo cơ sở vật chất – kỹ thuật cho CNXH. Liên minh chính trị (A) quan trọng nhất trong giai đoạn giành chính quyền, chứ không phải giai đoạn xây dựng.", "key_fact": "Khi xây dựng CNXH, liên minh về kinh tế giữ vai trò quyết định.", "topic": "Cơ cấu xã hội - giai cấp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-168", "question": "Yếu tố nào quyết định sự liên minh giữa giai cấp công nhân, giai cấp nông dân và tầng lớp trí thức?", "options": [{"key": "A", "text": "Do giai cấp công nhân mong muốn"}, {"key": "B", "text": "Do có cùng một kẻ thù là giai cấp tư sản"}, {"key": "C", "text": "Do có những lợi ích cơ bản thống nhất với nhau"}, {"key": "D", "text": "Do mục tiêu về chính trị của giai cấp công nhân"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Liên minh công – nông – trí thức hình thành do các giai cấp, tầng lớp này có những lợi ích cơ bản thống nhất với nhau, đều cần thoát khỏi áp bức và xây dựng xã hội mới. 'Cùng kẻ thù' (B) chỉ đúng trong giai đoạn đấu tranh giành chính quyền, không phải yếu tố quyết định lâu dài.", "key_fact": "Cơ sở quyết định của liên minh là lợi ích cơ bản thống nhất.", "topic": "Cơ cấu xã hội - giai cấp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-169", "question": "Xu hương phát triển cơ cấu xã hội – giai cấp ở Việt Nam trong thời kỳ quá độ mang tính đa dạng và thống nhất chủ yếu do yếu tố nào quyết định?", "options": [{"key": "A", "text": "Do trình độ phát triển không đồng đều"}, {"key": "B", "text": "Do nền kinh tế nhiều thành phần"}, {"key": "C", "text": "Do sự mong muốn của giai cấp công nhân"}, {"key": "D", "text": "Cả ba đều đúng."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Trong thời kỳ quá độ, nền kinh tế nhiều thành phần là yếu tố khách quan quy định cơ cấu xã hội – giai cấp vừa đa dạng (nhiều giai cấp, tầng lớp) vừa thống nhất (cùng hướng tới mục tiêu XHCN). Trình độ phát triển không đồng đều (A) có ảnh hưởng nhưng không phải yếu tố quyết định chủ yếu.", "key_fact": "Kinh tế nhiều thành phần quyết định tính đa dạng – thống nhất của cơ cấu xã hội – giai cấp.", "topic": "Cơ cấu xã hội - giai cấp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-170", "question": "Nội dung nào quan trọng nhất trong các nội dung Liên minh công-nông-trí thức?", "options": [{"key": "A", "text": "Chính trị"}, {"key": "B", "text": "Kinh tế"}, {"key": "C", "text": "Tư tưởng"}, {"key": "D", "text": "Văn hoá- xã hội"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Liên minh công – nông – trí thức có các nội dung chính trị, kinh tế, văn hoá – xã hội; trong đó nội dung kinh tế là quan trọng nhất, quyết định nhất trong thời kỳ quá độ vì nhằm thoả mãn lợi ích kinh tế của các chủ thể. Chính trị (A) là nền tảng giữ định hướng nhưng không phải nội dung quyết định.", "key_fact": "Nội dung kinh tế là quan trọng nhất của liên minh công – nông – trí thức.", "topic": "Cơ cấu xã hội - giai cấp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-171", "question": "Liên minh giữa giai cấp công nhân với giai cấp nông dân và tầng lớp trí thức là do:", "options": [{"key": "A", "text": "Do mong muốn của công nhân."}, {"key": "B", "text": "Yêu cầu của nông dân"}, {"key": "C", "text": "Yêu cầu của trí thức"}, {"key": "D", "text": "Do đòi hỏi khách quan của cả công nhân, nông dân và trí thức."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Liên minh công – nông – trí thức xuất phát từ nhu cầu và lợi ích khách quan của cả ba chủ thể, không phải ý muốn chủ quan của riêng giai cấp nào. Phương án A dễ nhầm vì giai cấp công nhân giữ vai trò lãnh đạo, nhưng liên minh không phải do mong muốn đơn phương của công nhân.", "key_fact": "Liên minh là đòi hỏi khách quan của cả công nhân, nông dân và trí thức.", "topic": "Cơ cấu xã hội - giai cấp", "note": "", "comment_answer": null}, {"id": "MLN131-bo-172", "question": "Câu “Vô sản tất cả các nước và các dân tộc bị áp bức, đoàn kết lại”là của ai?", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "C.Mác & Ph.Ăng ghen"}, {"key": "C", "text": "V.I Lênin"}, {"key": "D", "text": "Hồ Chí Minh"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Lênin đã phát triển khẩu hiệu của Mác – Ăngghen 'Vô sản tất cả các nước, đoàn kết lại' thành 'Vô sản tất cả các nước và các dân tộc bị áp bức, đoàn kết lại', phù hợp thời đại đế quốc chủ nghĩa. Phương án B là tác giả của khẩu hiệu gốc trong Tuyên ngôn, chưa có vế 'dân tộc bị áp bức'.", "key_fact": "Lênin bổ sung khẩu hiệu thành 'Vô sản và các dân tộc bị áp bức, đoàn kết lại'.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-173", "question": "Nội dung cương lĩnh dân tộc của chủ nghĩa Mác - Lênin là:", "options": [{"key": "A", "text": "Các dân tộc hoàn toàn bình đẳng, các dân tộc được quyền tự quyết, liên hiệp công nhân tất cả các dân tộc lại."}, {"key": "B", "text": "Các dân tộc đoàn kết, bình đẳng và liên hiệp công nhân tất cả các dân tộc lại."}, {"key": "C", "text": "Các dân tộc có quyền tự quyết, các dân tộc có quyền bình đẳng, liên hiệp công nhân tất cả các dân tộc lại."}, {"key": "D", "text": "Các dân tộc hoàn toàn bình đẳng, tự quyết và liên hiệp công nhân các nước."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cương lĩnh dân tộc của Lênin gồm: các dân tộc hoàn toàn bình đẳng; các dân tộc được quyền tự quyết; liên hiệp công nhân tất cả các dân tộc lại. Phương án D dễ nhầm vì viết 'liên hiệp công nhân các nước' thay vì 'tất cả các dân tộc'.", "key_fact": "Cương lĩnh dân tộc: bình đẳng, tự quyết, liên hiệp công nhân tất cả các dân tộc.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-174", "question": "Tác phẩm: “Về quyền dân tộc tự quyết” là của ai?", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "C.Mác & Ph.Ăng ghen"}, {"key": "C", "text": "V.I Lênin"}, {"key": "D", "text": "Stalin"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Về quyền dân tộc tự quyết' (1914) là tác phẩm của V.I. Lênin, trình bày cơ sở lý luận cho Cương lĩnh dân tộc. Stalin (D) có viết về vấn đề dân tộc nhưng không phải tác giả tác phẩm này.", "key_fact": "'Về quyền dân tộc tự quyết' là tác phẩm của Lênin.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-175", "question": "Các thế lực thù địch sử dụng chiến lược “diễn biến hoá bình” chống phá sự nghiệp xây dựng Tổ quốc xã hội chủ nghĩa của nhân dân ta trên phương diện nào?", "options": [{"key": "A", "text": "Kinh tế, chính trị - xã hội"}, {"key": "B", "text": "Văn hoá, tư tưởng"}, {"key": "C", "text": "Đạo đức, lối sống..."}, {"key": "D", "text": "Cả a, b và c đều đúng"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Chiến lược 'diễn biến hoà bình' chống phá toàn diện trên mọi lĩnh vực: kinh tế, chính trị – xã hội, văn hoá, tư tưởng, đạo đức, lối sống. Chỉ chọn một mặt như A hay B là chưa đầy đủ.", "key_fact": "'Diễn biến hoà bình' chống phá toàn diện trên mọi lĩnh vực.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-176", "question": "Điền từ còn thiếu vào chỗ trống: Quyền dân tộc tự quyết là quyền làm chủ của mỗi dân tộc đối với vận mệnh dân tộc mình, quyền tự quyết định chế độ chính trị – xã hội và... phát triển của dân tộc mình.", "options": [{"key": "A", "text": "Cách thức"}, {"key": "B", "text": "Con đường"}, {"key": "C", "text": "Mục tiêu"}, {"key": "D", "text": "Hình thức"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Quyền dân tộc tự quyết là quyền làm chủ của mỗi dân tộc đối với vận mệnh của mình, quyền tự quyết định chế độ chính trị – xã hội và con đường phát triển của dân tộc mình. 'Hình thức' hay 'cách thức' (A, D) không phải từ trong định nghĩa.", "key_fact": "Tự quyết dân tộc gồm quyền chọn chế độ chính trị – xã hội và con đường phát triển.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-177", "question": "Điền từ còn thiếu vào chỗ trống: Lênin viết: “Với sự giúp đỡ của giai cấp vô sản các nước tiên tiến, các nước lạc hậu có thể tiến tới chế độ Xô viết, và qua những giai đoạn phát triển nhất định, tiến tới chủ nghĩa cộng sản, không phải trải qua... phát triển tư bản chủ nghĩa”.", "options": [{"key": "A", "text": "Chế độ"}, {"key": "B", "text": "Giai đoạn"}, {"key": "C", "text": "Quá trình"}, {"key": "D", "text": "Hình thức"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Lênin khẳng định các nước lạc hậu, với sự giúp đỡ của giai cấp vô sản các nước tiên tiến, có thể tiến lên chế độ Xô viết và CNCS mà không phải trải qua giai đoạn phát triển TBCN – cơ sở lý luận của con đường quá độ bỏ qua. Từ 'chế độ' (A) dễ nhầm nhưng nguyên văn là 'giai đoạn'.", "key_fact": "Nước lạc hậu có thể quá độ lên CNXH không qua giai đoạn phát triển TBCN.", "topic": "Thời đại và thời kỳ quá độ", "note": "", "comment_answer": null}, {"id": "MLN131-bo-178", "question": "Trong các nội dung của quyền dân tộc tự quyết thì nội dung nào được coi là cơ bản nhất, tiên quyết nhất?", "options": [{"key": "A", "text": "Tự quyết về chính trị"}, {"key": "B", "text": "Tự quyết về kinh tế"}, {"key": "C", "text": "Tự quyết về văn hoá"}, {"key": "D", "text": "Tự quyết về lãnh thổ"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tự quyết về chính trị – quyền độc lập, tự lựa chọn chế độ chính trị, thành lập quốc gia – là nội dung cơ bản, tiên quyết, vì có độc lập chính trị mới tự quyết được kinh tế, văn hoá. Tự quyết kinh tế (B) quan trọng nhưng phụ thuộc vào tự quyết chính trị.", "key_fact": "Tự quyết về chính trị là nội dung cơ bản, tiên quyết nhất.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-179", "question": "Trong một quốc gia đa tộc người thì vấn đề gì cần giải quyết được coi là có ý nghĩa cơ bản nhất để thực hiện quyền bình đẳng giữa các dân tộc?", "options": [{"key": "A", "text": "Ban hành hệ thống hiến pháp và pháp luật về quyền bình đẳng giữa các dân tộc"}, {"key": "B", "text": "Chống tư tưởng phân biệt chủng tộc, kì thị và chia rẽ dân tộc"}, {"key": "C", "text": "Nâng cao trình độ dân trí, văn hoá cho đồng bào"}, {"key": "D", "text": "Xoá bỏ dần sự chênh lệch về mọi mặt giữa các dân tộc do lịch sử để lại"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Bình đẳng dân tộc phải được thực hiện trên thực tế, nên cơ bản nhất là xoá bỏ dần sự chênh lệch về kinh tế, văn hoá, xã hội giữa các dân tộc do lịch sử để lại. Ban hành pháp luật (A) chỉ là bình đẳng về mặt pháp lý, chưa bảo đảm bình đẳng thực tế.", "key_fact": "Cơ bản nhất của bình đẳng dân tộc là xoá dần chênh lệch phát triển giữa các dân tộc.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-180", "question": "Nước ta có bao nhiêu dân tộc cùng nhau chung sống?", "options": [{"key": "A", "text": "49"}, {"key": "B", "text": "52"}, {"key": "C", "text": "54"}, {"key": "D", "text": "56"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Việt Nam là quốc gia thống nhất gồm 54 dân tộc anh em, trong đó dân tộc Kinh là đa số. Các con số 52, 56 dễ nhầm nhưng không đúng.", "key_fact": "Việt Nam có 54 dân tộc.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-181", "question": "Hiện nay các dân tộc thiểu số ở nước ta có dân số chiếm tỉ lệ bao nhiêu phần trăm số dân cả nước:", "options": [{"key": "A", "text": "15%"}, {"key": "B", "text": "13,5%"}, {"key": "C", "text": "13%"}, {"key": "D", "text": "17%"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo số liệu được dùng trong giáo trình, các dân tộc thiểu số chiếm khoảng 13% dân số cả nước (53 dân tộc thiểu số). Lưu ý số liệu tổng điều tra 2019 là khoảng 14,7%, nhưng đáp án theo tài liệu ôn tập là 13%.", "key_fact": "Dân tộc thiểu số chiếm khoảng 13% dân số (theo giáo trình).", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-182", "question": "Đặc trưng nổi bật trong quan hệ giữa các dân tộc ở nước ta là:", "options": [{"key": "A", "text": "Là sự phân bố đan xen nhau, không một dân tộc nào có lãnh thổ riêng."}, {"key": "B", "text": "Là sự cố kết dân tộc, hoà hợp dân tộc trong một cộng đồng thống nhất."}, {"key": "C", "text": "Là có sự chênh lệch về trình độ phát triển kinh tế - xã hội giữa các dân tộc."}, {"key": "D", "text": "Là các dân tộc có bản sắc văn hoá riêng, đa dạng, phong phú."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đặc trưng nổi bật trong quan hệ dân tộc ở nước ta là truyền thống cố kết, hoà hợp dân tộc trong một cộng đồng thống nhất, hình thành từ yêu cầu dựng nước và giữ nước. Các phương án A, C, D đều là đặc điểm của dân tộc Việt Nam nhưng không phải đặc trưng nổi bật trong quan hệ giữa các dân tộc.", "key_fact": "Đặc trưng nổi bật: các dân tộc cố kết, hoà hợp trong cộng đồng thống nhất.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-183", "question": "Nghị quyết “Về phát huy sức mạnh đại đoàn kết dân tộc vì dân giàu nước mạnh, xã hội công bằng, dân chủ, văn minh” được đề cập đến ở Hội nghị Trung ương nào?", "options": [{"key": "A", "text": "Hội nghị Trung ương II khoá VII"}, {"key": "B", "text": "Hội nghị Trung ương V khoá VIII."}, {"key": "C", "text": "Hội nghị Trung ương VI khoá VIII."}, {"key": "D", "text": "Hội nghị Trung ương VII khoá IX."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nghị quyết 23-NQ/TW 'Về phát huy sức mạnh đại đoàn kết dân tộc vì dân giàu, nước mạnh, xã hội công bằng, dân chủ, văn minh' được ban hành tại Hội nghị Trung ương 7 khoá IX (2003). Hội nghị Trung ương 5 khoá VIII (B) bàn về văn hoá, dễ nhầm.", "key_fact": "Nghị quyết đại đoàn kết dân tộc: Hội nghị Trung ương 7 khoá IX (2003).", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-184", "question": "Để tăng cường, củng cố khối đại đoàn kết dân tộc ở nước ta hiện nay thì chính sách cụ thể nào của Đảng và Nhà nước ta được coi là vấn đề cực kỳ quan trọng?", "options": [{"key": "A", "text": "Tôn trọng lợi ích, truyền thống, văn hoá của các dân tộc."}, {"key": "B", "text": "Phát huy truyền thống đoàn kết giữa các dân tộc."}, {"key": "C", "text": "Phát triển kinh tế hàng hoá ở các vùng dân tộc thiểu số."}, {"key": "D", "text": "Tăng cường bồi dưỡng, đào tạo đội ngũ cán bộ là người dân tộc thiểu số."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Đảng xác định phát triển kinh tế hàng hoá ở vùng dân tộc thiểu số là vấn đề cực kỳ quan trọng, vì đó là nền tảng vật chất để xoá dần chênh lệch, nâng cao đời sống và củng cố khối đoàn kết dân tộc. Đào tạo cán bộ người dân tộc thiểu số (D) cũng quan trọng nhưng không phải nội dung được nhấn mạnh là 'cực kỳ quan trọng' trong câu hỏi.", "key_fact": "Phát triển kinh tế hàng hoá ở vùng dân tộc thiểu số là vấn đề cực kỳ quan trọng.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-185", "question": "Hãy tìm ý đúng trong các phương án dưới đây. Trong Văn kiện Đại hội đại biểu toàn quốc lần thứ IX, Đảng Cộng sản Việt Nam đã nêu rõ:", "options": [{"key": "A", "text": "Vấn đề dân tộc có vai trò quan trọng đối với sự nghiệp phát triển kinh tế - xã hội ở nước ta hiện nay."}, {"key": "B", "text": "Vấn đề dân tộc và đoàn kết các dân tộc luôn có vị trí chiến lược trong sự nghiệp cách mạng."}, {"key": "C", "text": "Vấn đề dân tộc và đoàn kết các dân tộc có vị trí quyết định đến sự sống còn của dân tộc ta hiện nay."}, {"key": "D", "text": "Vấn đề dân tộc và tăng cường khối đại đoàn kết toàn dân tộc là vấn đề chiến lược của Việt Nam hiện nay."}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Văn kiện Đại hội IX nêu: vấn đề dân tộc và đoàn kết các dân tộc có vị trí chiến lược lâu dài trong sự nghiệp cách mạng nước ta. Phương án D dễ nhầm vì dùng 'đại đoàn kết toàn dân tộc' và 'hiện nay', không đúng nguyên văn.", "key_fact": "Đại hội IX: vấn đề dân tộc và đoàn kết dân tộc có vị trí chiến lược.", "topic": "Vấn đề dân tộc", "note": "", "comment_answer": null}, {"id": "MLN131-bo-186", "question": "Bản chất của tôn giáo là gì?", "options": [{"key": "A", "text": "Là sự phản ánh hiện thực khách quan và tồn tại xã hội."}, {"key": "B", "text": "Là sự phản ánh thế giới quan của con người đối với xã hội."}, {"key": "C", "text": "Là một hình thái ý thức xã hội nó phản ánh một cách hoang đường hư ảo cái hiện thực khách quan vào đầu óc con người. Tôn giáo thể hiện sự bất lực của con người trước tự nhiên và xã hội"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo Ăngghen, tôn giáo là một hình thái ý thức xã hội, phản ánh một cách hoang đường, hư ảo hiện thực khách quan vào đầu óc con người, thể hiện sự bất lực của con người trước tự nhiên và xã hội. Phương án A quá chung, đúng cho mọi hình thái ý thức xã hội, không nêu được tính hư ảo đặc thù của tôn giáo.", "key_fact": "Tôn giáo phản ánh hoang đường, hư ảo hiện thực khách quan.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-187", "question": "Cơ sở tồn tại của tôn giáo là gì?", "options": [{"key": "A", "text": "Nhận thức của con người đối với thế giới khách quan"}, {"key": "B", "text": "Niềm tin của con người"}, {"key": "C", "text": "Sự tưởng tượng của con người"}, {"key": "D", "text": "Tồn tại xã hội"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo chủ nghĩa duy vật lịch sử, tồn tại xã hội quyết định ý thức xã hội, nên tôn giáo – một hình thái ý thức xã hội – có cơ sở tồn tại là tồn tại xã hội. Niềm tin hay sự tưởng tượng (B, C) là biểu hiện, không phải cơ sở tồn tại.", "key_fact": "Tồn tại xã hội là cơ sở tồn tại của tôn giáo.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-188", "question": "Câu “Tôn giáo là thuốc phiện của nhân dân” là của ai?", "options": [{"key": "A", "text": "Hêghen"}, {"key": "B", "text": "Phoi ơ bắc"}, {"key": "C", "text": "C.Mác"}, {"key": "D", "text": "V.I. Lênin"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Câu 'Tôn giáo là thuốc phiện của nhân dân' là của C.Mác trong 'Góp phần phê phán triết học pháp quyền của Hêghen. Lời nói đầu'. Hêghen (A) là đối tượng phê phán chứ không phải tác giả.", "key_fact": "'Tôn giáo là thuốc phiện của nhân dân' – C.Mác.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-189", "question": "Nguồn gốc kinh tế - xã hội của tôn giáo là:", "options": [{"key": "A", "text": "Trình độ phát triển lực lượng sản xuất"}, {"key": "B", "text": "Do sự bần cùng về kinh tế, áp bức về chính trị của con người"}, {"key": "C", "text": "Do sự thất vọng, bất lực của con người trước những bất công xã hội"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nguồn gốc kinh tế – xã hội của tôn giáo gồm: lực lượng sản xuất thấp kém khiến con người bất lực trước tự nhiên, và sự bần cùng, áp bức, bất công trong xã hội có giai cấp khiến con người tìm đến tôn giáo. Mỗi phương án A, B, C chỉ nêu một mặt nên đáp án đầy đủ là D.", "key_fact": "Nguồn gốc KT-XH: LLSX thấp kém, áp bức bóc lột, bất lực trước bất công.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-190", "question": "Tôn giáo là một phạm trù lịch sử bởi vì:", "options": [{"key": "A", "text": "Là sản phẩm của con người."}, {"key": "B", "text": "Là do điều kiện kinh tế - xã hội sinh ra."}, {"key": "C", "text": "Tôn giáo ra đời, tồn tại và biến đổi trong một giai đoạn lịch sử nhất định của loài người."}, {"key": "D", "text": "Tôn giáo sẽ tồn tại và phát triển cùng với sự phát triển của lịch sử nhân loại."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tôn giáo là phạm trù lịch sử vì nó ra đời, tồn tại và biến đổi trong một giai đoạn lịch sử nhất định và sẽ mất đi khi những điều kiện sinh ra nó không còn. Phương án D sai vì cho rằng tôn giáo tồn tại mãi cùng lịch sử nhân loại.", "key_fact": "Tôn giáo ra đời, tồn tại, biến đổi trong một giai đoạn lịch sử nhất định.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-191", "question": "Khi nào thì tôn giáo mang tính chính trị?", "options": [{"key": "A", "text": "Phản ánh nguyện vọng của nhân dân."}, {"key": "B", "text": "Khi các cuộc chiến tranh tôn giáo nổ ra."}, {"key": "C", "text": "Khi các giai cấp thống trị đã lợi dụng và sử dụng tôn giáo để phục vụ lợi ích của mình."}, {"key": "D", "text": "Cả a, b và c."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tôn giáo mang tính chính trị khi xã hội có giai cấp và giai cấp thống trị lợi dụng, sử dụng tôn giáo phục vụ lợi ích của mình. Chiến tranh tôn giáo (B) chỉ là biểu hiện, không phải điều kiện làm tôn giáo mang tính chính trị.", "key_fact": "Tôn giáo mang tính chính trị khi bị giai cấp thống trị lợi dụng.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-192", "question": "Số lượng tôn giáo lớn và số lượng tín đồ của các tôn giáo đó ở nước ta có khoảng bao nhiêu?", "options": [{"key": "A", "text": "6 tôn giáo với khoảng 30 triệu tín đồ"}, {"key": "B", "text": "6 tôn giáo với khoảng 20 triệu tín đồ"}, {"key": "C", "text": "5 tôn giáo với khoảng 15 triệu tín đồ"}, {"key": "D", "text": "Cả a, b và c đều sai"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo tài liệu giáo trình, nước ta có 6 tôn giáo lớn (Phật giáo, Công giáo, Tin lành, Hồi giáo, Cao Đài, Hoà Hảo) với khoảng 20 triệu tín đồ. Phương án A cùng số tôn giáo nhưng số tín đồ không đúng với số liệu giáo trình.", "key_fact": "Theo giáo trình: 6 tôn giáo lớn, khoảng 20 triệu tín đồ.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-193", "question": "Điền từ còn thiếu vào chỗ trống: Tôn trọng, bảo đảm quyền tự do... và không... của nhân dân.", "options": [{"key": "A", "text": "Tôn giáo"}, {"key": "B", "text": "Tín ngưỡng"}, {"key": "C", "text": "Tín ngưỡng - tôn giáo"}, {"key": "D", "text": "Tôn giáo - tín ngưỡng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nguyên tắc của Đảng và Nhà nước: tôn trọng, bảo đảm quyền tự do tín ngưỡng và không tín ngưỡng của nhân dân. 'Tín ngưỡng' là khái niệm rộng, bao trùm cả niềm tin tôn giáo; điền 'tôn giáo' (A) không đúng với cách diễn đạt chuẩn.", "key_fact": "Tôn trọng quyền tự do tín ngưỡng và không tín ngưỡng của nhân dân.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-194", "question": "Điền từ còn thiếu vào chỗ trống: Tôn giáo là một hình thái ý thức – xã hội phản ánh một cách hoang đường, hư ảo... khách quan. Qua sự phản ánh của tôn giáo, những sức mạnh tự phát trong tự nhiên và xã hội đều trở thành thần bí.", "options": [{"key": "A", "text": "Thực tiễn"}, {"key": "B", "text": "Hiện thực"}, {"key": "C", "text": "Điều kiện"}, {"key": "D", "text": "Cuộc sống"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Định nghĩa của Ăngghen: tôn giáo phản ánh một cách hoang đường, hư ảo hiện thực khách quan, qua đó các sức mạnh tự phát trong tự nhiên và xã hội trở thành thần bí. 'Thực tiễn' (A) là hoạt động của con người, không phải đối tượng phản ánh trong định nghĩa này.", "key_fact": "Tôn giáo phản ánh hư ảo hiện thực khách quan.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-195", "question": "Giữa chủ nghĩa Mác - Lênin và hệ tư tưởng tôn giáo khác nhau ở điểm nào?", "options": [{"key": "A", "text": "Khác nhau về thế giới quan"}, {"key": "B", "text": "Khác nhau về nhân sinh quan"}, {"key": "C", "text": "Khác nhau ở con đường mưu cầu hạnh phúc cho nhân dân"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Chủ nghĩa Mác – Lênin (duy vật, vô thần) khác hệ tư tưởng tôn giáo (duy tâm, hữu thần) về thế giới quan, về nhân sinh quan và về con đường mưu cầu hạnh phúc: Mác – Lênin chủ trương giải phóng con người ngay trên trần thế, tôn giáo hướng hạnh phúc về thế giới bên kia. Chọn riêng A là chưa đầy đủ.", "key_fact": "Mác – Lênin và tôn giáo khác nhau về thế giới quan, nhân sinh quan và con đường mưu cầu hạnh phúc.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-196", "question": "Về phương diện thế giới quan thì thế giới quan duy vật mácxít và thế giới quan tôn giáo là đối lập nhau.", "options": [{"key": "A", "text": "Đúng"}, {"key": "B", "text": "Sai"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Thế giới quan duy vật mácxít khẳng định thế giới là vật chất, còn thế giới quan tôn giáo là duy tâm, thừa nhận lực lượng siêu nhiên, nên hai thế giới quan đối lập nhau. Tuy vậy, sự khác biệt này không ngăn cản đoàn kết giữa người có và không có tôn giáo vì mục tiêu chung.", "key_fact": "Thế giới quan duy vật mácxít đối lập với thế giới quan tôn giáo.", "topic": "Vấn đề tôn giáo", "note": "", "comment_answer": null}, {"id": "MLN131-bo-197", "question": "Quan hệ nào được coi là quan hệ cơ bản nhất trong gia đình?", "options": [{"key": "A", "text": "Quan hệ hôn nhân"}, {"key": "B", "text": "Quan hệ hôn nhân và huyết thống"}, {"key": "C", "text": "Quan hệ quần tụ trong một không gian sinh tồn"}, {"key": "D", "text": "Quan hệ nuôi dưỡng"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Gia đình được hình thành, duy trì trên cơ sở hai mối quan hệ cơ bản là quan hệ hôn nhân (vợ – chồng) và quan hệ huyết thống (cha mẹ – con cái, anh chị em). Chỉ chọn quan hệ hôn nhân (A) là thiếu quan hệ huyết thống.", "key_fact": "Hôn nhân và huyết thống là hai quan hệ cơ bản của gia đình.", "topic": "Gia đình", "note": "", "comment_answer": null}, {"id": "MLN131-bo-198", "question": "Tác phẩm “Nguồn gốc của gia đình, của chế độ tư hữu và của Nhà nước” là của ai?", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "C.Mác & Ph.Ăng ghen"}, {"key": "C", "text": "Ph.Ăng ghen"}, {"key": "D", "text": "V.I. Lênin"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "'Nguồn gốc của gia đình, của chế độ tư hữu và của nhà nước' (1884) là tác phẩm của Ph.Ăngghen, dựa trên ghi chép của Mác về nghiên cứu của Moócgan. Phương án B dễ nhầm vì Mác có đóng góp tư liệu, nhưng tác giả là riêng Ăngghen.", "key_fact": "Tác phẩm 'Nguồn gốc của gia đình...' là của Ph.Ăngghen.", "topic": "Gia đình", "note": "", "comment_answer": null}, {"id": "MLN131-bo-199", "question": "Chức năng nào được coi là chức năng cơ bản và riêng có của gia đình?", "options": [{"key": "A", "text": "Tái sản xuất ra con người"}, {"key": "B", "text": "Tổ chức đời sống gia đình"}, {"key": "C", "text": "Giáo dục gia đình"}, {"key": "D", "text": "Thoả mãn tâm sinh lý."}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tái sản xuất ra con người (duy trì nòi giống, cung cấp sức lao động) là chức năng cơ bản, đặc thù mà không thiết chế xã hội nào thay thế được. Giáo dục gia đình (C) quan trọng nhưng nhà trường, xã hội cũng đảm nhiệm nên không 'riêng có'.", "key_fact": "Tái sản xuất ra con người là chức năng cơ bản, riêng có của gia đình.", "topic": "Gia đình", "note": "", "comment_answer": null}, {"id": "MLN131-bo-200", "question": "Điều kiện và tiền đề kinh tế - xã hội để xây dựng gia đình trong chủ nghĩa xã hội là gì?", "options": [{"key": "A", "text": "Xoá bỏ chế độ tư hữu, xác lập chế độ công hữu về tư liệu sản xuất."}, {"key": "B", "text": "Phát triển kinh tế - xã hội"}, {"key": "C", "text": "Nhà nước xã hội chủ nghĩa ban hành và thực hiện luật Hôn nhân và nâng cao trình độ văn hoá và dân trí cho mọi người dân"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cơ sở xây dựng gia đình trong CNXH gồm: cơ sở kinh tế – xã hội (xoá bỏ tư hữu, xác lập công hữu, phát triển kinh tế), cơ sở chính trị – xã hội (nhà nước XHCN với Luật Hôn nhân và gia đình) và cơ sở văn hoá (nâng cao dân trí). Từng phương án A, B, C chỉ là một mặt nên chọn D.", "key_fact": "Xây dựng gia đình XHCN cần đồng bộ cơ sở kinh tế, chính trị – pháp luật và văn hoá.", "topic": "Gia đình", "note": "", "comment_answer": null}, {"id": "MLN131-bo-201", "question": "Hôn nhân tự nguyện, tiến bộ là hôn nhân được xây dựng chủ yếu dựa trên cơ sở nào?", "options": [{"key": "A", "text": "Quyền tự do kết hôn và lý hôn"}, {"key": "B", "text": "Tình yêu chân chính"}, {"key": "C", "text": "Tình cảm nam – nữ."}, {"key": "D", "text": "Kinh tế - xã hội xã hội chủ nghĩa"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Hôn nhân tự nguyện, tiến bộ được xây dựng chủ yếu trên cơ sở tình yêu chân chính giữa nam và nữ. Quyền tự do kết hôn, ly hôn (A) là hệ quả, biểu hiện của hôn nhân tự nguyện chứ không phải cơ sở chủ yếu.", "key_fact": "Hôn nhân tiến bộ dựa trên tình yêu chân chính.", "topic": "Gia đình", "note": "", "comment_answer": null}, {"id": "MLN131-bo-202", "question": "Nội dung cơ bản và trực tiếp để xây dựng gia đình ở Việt Nam hiện nay là gì?", "options": [{"key": "A", "text": "Phát triển kinh tế - xã hội"}, {"key": "B", "text": "Nâng cao trình độ dân trí cho nhân dân lao động"}, {"key": "C", "text": "Xây dựng gia đình no ấm, bình đẳng, tiến bộ và hạnh phúc"}, {"key": "D", "text": "Giải phóng người phụ nữ"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nội dung cơ bản và trực tiếp của xây dựng gia đình Việt Nam hiện nay là xây dựng gia đình no ấm, bình đẳng, tiến bộ, hạnh phúc. Phát triển kinh tế – xã hội (A) là điều kiện nền tảng, gián tiếp, không phải nội dung trực tiếp.", "key_fact": "Xây dựng gia đình no ấm, bình đẳng, tiến bộ, hạnh phúc.", "topic": "Gia đình", "note": "", "comment_answer": null}, {"id": "MLN131-bo-203", "question": "Chủ nghĩa Mác - Lênin quan niệm về con người như thế nào?", "options": [{"key": "A", "text": "Là thực thể tự nhiên"}, {"key": "B", "text": "Là thực thể xã hội"}, {"key": "C", "text": "Là chủ thể cải tạo hoàn cảnh"}, {"key": "D", "text": "Cả a, b, và c."}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Chủ nghĩa Mác – Lênin xem con người là thực thể thống nhất giữa mặt tự nhiên và mặt xã hội, đồng thời là chủ thể cải tạo hoàn cảnh, sáng tạo lịch sử. Mỗi phương án A, B, C chỉ là một mặt nên đáp án đầy đủ là D.", "key_fact": "Con người vừa là thực thể tự nhiên – xã hội vừa là chủ thể cải tạo hoàn cảnh.", "topic": "Con người XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-204", "question": "Câu “Nhưng bản chất con người không phải là những cái gì trừu tượng, cố hữu của cá nhân riêng biệt, trong tính hiện thực của nó, bản chất con người là tổng hoà những quan hệ xã hội” trong tác phẩm nào?", "options": [{"key": "A", "text": "Gia đình thần thánh"}, {"key": "B", "text": "Hệ tư tưởng Đức"}, {"key": "C", "text": "Luận cương về Phoi ơ bắc"}, {"key": "D", "text": "Tuyên ngôn của Đảng Cộng sản"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Luận điểm 'bản chất con người là tổng hoà những quan hệ xã hội' nằm trong 'Luận cương về Phoiơbắc' (luận cương 6) của Mác (1845). 'Hệ tư tưởng Đức' (B) cùng thời kỳ nên dễ nhầm, nhưng không chứa câu này.", "key_fact": "'Bản chất con người là tổng hoà các quan hệ xã hội' – Luận cương về Phoiơbắc.", "topic": "Con người XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-205", "question": "Con người phát triển và hoàn thiện mình chủ yếu dựa trên yếu tố nào?", "options": [{"key": "A", "text": "Phát triển kinh tế - xã hội"}, {"key": "B", "text": "Lao động sản xuất"}, {"key": "C", "text": "Đấu tranh giai cấp"}, {"key": "D", "text": "Cả ba đều sai"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Theo quan điểm mácxít, lao động sản xuất là hoạt động cơ bản giúp con người tách khỏi giới động vật và không ngừng phát triển, hoàn thiện mình. Phát triển kinh tế – xã hội (A) là kết quả của lao động, không phải yếu tố chủ yếu trực tiếp.", "key_fact": "Lao động sản xuất là yếu tố chủ yếu để con người phát triển, hoàn thiện.", "topic": "Con người XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-206", "question": "Con người xã hội chủ nghĩa bao gồm những con người từ xã hội nào?", "options": [{"key": "A", "text": "Từ xã hội tư bản"}, {"key": "B", "text": "Trong xã hội xã hội chủ nghĩa"}, {"key": "C", "text": "Cả trong xã hội tư bản chủ nghĩa và xã hội xã hội chủ nghĩa"}, {"key": "D", "text": "Từ xã hội cũ để lại và sinh ra trong xã hội mới"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Con người XHCN được hình thành từ cả những người do xã hội cũ để lại (được cải tạo, giáo dục) và những người sinh ra, lớn lên trong xã hội mới. Phương án C dễ nhầm nhưng chỉ nói 'xã hội tư bản', trong khi nhiều nước như Việt Nam quá độ từ xã hội tiền tư bản.", "key_fact": "Con người XHCN gồm người từ xã hội cũ để lại và người sinh ra trong xã hội mới.", "topic": "Con người XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-207", "question": "Khi nói tới nguồn lực con người là nói tới cái gì?", "options": [{"key": "A", "text": "Là chủ thể hoạt động sáng tạo tham gia cải tạo tự nhiên, làm biến đổi xã hội"}, {"key": "B", "text": "Là nói tới số lượng"}, {"key": "C", "text": "Là nói tới chất lượng"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Nguồn lực con người được hiểu là con người với tư cách chủ thể hoạt động sáng tạo, cải tạo tự nhiên và xã hội, xét cả về số lượng và chất lượng. Chọn riêng số lượng (B) hay chất lượng (C) là phiến diện.", "key_fact": "Nguồn lực con người gồm vai trò chủ thể, số lượng và chất lượng.", "topic": "Con người XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-208", "question": "Để phát huy nguồn lực con người ở Việt Nam hiện nay cần phải thực hiện những phương hướng nào?", "options": [{"key": "A", "text": "Đẩy mạnh sự nghiệp công nghiệp hoá, hiện đại hoá, phát triển nền kinh tế đất nước."}, {"key": "B", "text": "Xây dựng và từng bước hoàn chỉnh một hệ thống chính sách xã hội phù hợp."}, {"key": "C", "text": "Từng bước xây dựng và không ngừng hoàn thiện cơ chế quản lý của chế độ xã hội chủ nghĩa."}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Để phát huy nguồn lực con người cần đồng bộ: đẩy mạnh CNH, HĐH và phát triển kinh tế; xây dựng hệ thống chính sách xã hội phù hợp; hoàn thiện cơ chế quản lý của chế độ XHCN. Mỗi phương án A, B, C chỉ là một phương hướng.", "key_fact": "Phát huy nguồn lực con người cần đồng bộ kinh tế, chính sách xã hội và cơ chế quản lý.", "topic": "Con người XHCN", "note": "", "comment_answer": null}, {"id": "MLN131-bo-209", "question": "Điền từ còn thiếu vào chỗ trống: Cách mạng tư tưởng và văn hoá là cần thiết và tất yếu để thay đổi... tinh thần, làm cho... tinh thần của xã hội phù hợp với phương thức sản xuất mới xét về mặt kinh tế đã hình thành.", "options": [{"key": "A", "text": "Đời sống - đời sống"}, {"key": "B", "text": "Phương thức sản xuất – phương thức sản xuất"}, {"key": "C", "text": "Văn hoá - văn hoá"}, {"key": "D", "text": "Đời sống văn hoá - đời sống văn hoá"}], "answer": ["B"], "multi": false, "confidence": "high", "source": "key", "explanation": "Cách mạng tư tưởng và văn hoá là tất yếu để thay đổi phương thức sản xuất tinh thần, làm cho phương thức sản xuất tinh thần phù hợp với phương thức sản xuất vật chất mới đã hình thành. Phương án D 'đời sống văn hoá' gần nghĩa nhưng không đúng thuật ngữ trong giáo trình.", "key_fact": "Cách mạng tư tưởng – văn hoá nhằm thay đổi phương thức sản xuất tinh thần.", "topic": "Cách mạng tư tưởng - văn hoá", "note": "", "comment_answer": null}, {"id": "MLN131-bo-210", "question": "Tính tất yếu của cách mạng xã hội chủ nghĩa trên lĩnh vực tư tưởng và văn hoá là gì?", "options": [{"key": "A", "text": "Xuất phát từ cuộc đấu tranh giai cấp trên lĩnh vực tư tưởng và văn hoá trong thời đại ngày nay."}, {"key": "B", "text": "Xuất phát từ sự đòi hỏi thay đổi phương thức sản xuất tinh thần."}, {"key": "C", "text": "Xuất phát từ yêu cầu: văn hoá là mục tiêu và động lực cuả quá trình xây dựng chủ nghĩa xã hội"}, {"key": "D", "text": "Cả a, b và c"}], "answer": ["D"], "multi": false, "confidence": "high", "source": "key", "explanation": "Tính tất yếu của cách mạng tư tưởng – văn hoá xuất phát từ: đòi hỏi thay đổi phương thức sản xuất tinh thần; cuộc đấu tranh giai cấp trên lĩnh vực tư tưởng, văn hoá; và yêu cầu văn hoá là mục tiêu, động lực của xây dựng CNXH. Từng phương án A, B, C chỉ là một lý do nên chọn D.", "key_fact": "Cách mạng tư tưởng – văn hoá tất yếu do nhiều yêu cầu khách quan cùng lúc.", "topic": "Cách mạng tư tưởng - văn hoá", "note": "", "comment_answer": null}, {"id": "MLN131-bo-211", "question": "Yếu tố nào có tác động trực tiếp để phát huy nguồn lực con người?", "options": [{"key": "A", "text": "Phát triển kinh tế - xã hội"}, {"key": "B", "text": "Giáo dục chủ nghĩa Mác - Lênin"}, {"key": "C", "text": "Giáo dục về đạo đức, lối sống"}, {"key": "D", "text": "Giải quyết việc làm"}], "answer": ["A"], "multi": false, "confidence": "high", "source": "key", "explanation": "Phát triển kinh tế - xã hội tạo ra điều kiện vật chất, việc làm, thu nhập và môi trường để con người phát huy năng lực, nên đây là yếu tố tác động trực tiếp, mang tính nền tảng đối với việc phát huy nguồn lực con người. Giáo dục chủ nghĩa Mác - Lênin hay giáo dục đạo đức, lối sống là những yếu tố quan trọng nhưng chủ yếu tác động đến nhận thức, phẩm chất; còn giải quyết việc làm chỉ là một bộ phận, một biểu hiện cụ thể của phát triển kinh tế - xã hội.", "key_fact": "Phát triển kinh tế - xã hội là yếu tố tác động trực tiếp để phát huy nguồn lực con người.", "topic": "Nguồn lực con người", "note": "", "comment_answer": null}, {"id": "MLN131-bo-212", "question": "Câu “Những tư tưởng thống trị của một thời đại bao giờ cũng chỉ là tư tưởng của giai cấp thống trị”của ai?", "options": [{"key": "A", "text": "C.Mác"}, {"key": "B", "text": "Ph.Ăng ghen"}, {"key": "C", "text": "C.Mác & Ph.Ăng ghen"}, {"key": "D", "text": "V.I Lênin."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Luận điểm về tư tưởng thống trị của một thời đại là tư tưởng của giai cấp thống trị do C.Mác và Ph.Ăngghen cùng nêu ra (trong Hệ tư tưởng Đức và nhắc lại trong Tuyên ngôn của Đảng Cộng sản). Phương án dễ nhầm là chỉ ghi C.Mác, nhưng đây là tác phẩm hai ông viết chung nên phải là 'C.Mác & Ph.Ăngghen'.", "key_fact": "Câu 'Tư tưởng thống trị của một thời đại bao giờ cũng chỉ là tư tưởng của giai cấp thống trị' là của C.Mác và Ph.Ăngghen.", "topic": "Kinh điển Mác - Lênin", "note": "", "comment_answer": null}, {"id": "MLN131-bo-213", "question": "Điền từ vào ô trống: “Lực lượng sản xuất hàng đầu của nhân loại là…, là người lao động” ( V.I.Lênin).", "options": [{"key": "A", "text": "Khoa học kỹ thuật"}, {"key": "B", "text": "Nền đại công nghiệp"}, {"key": "C", "text": "Công nhân"}, {"key": "D", "text": "Trí thức"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "V.I.Lênin khẳng định: 'Lực lượng sản xuất hàng đầu của toàn thể nhân loại là công nhân, là người lao động', nhấn mạnh vai trò của giai cấp công nhân trong lực lượng sản xuất hiện đại. Phương án 'Nền đại công nghiệp' hay 'Khoa học kỹ thuật' dễ gây nhầm nhưng không khớp với vế sau 'là người lao động'.", "key_fact": "Theo Lênin, lực lượng sản xuất hàng đầu của nhân loại là công nhân, là người lao động.", "topic": "Sứ mệnh giai cấp công nhân", "note": "", "comment_answer": null}, {"id": "MLN131-bo-214", "question": "“Muốn xây dựng CNXH, trước hết cần có những con người XHCN” được Bác nói ở đâu?", "options": [{"key": "A", "text": "Đại hội Đại biểu toàn quốc lần thứ 2 của Đảng 1951."}, {"key": "B", "text": "Đại hội Đại biểu toàn quốc lần thứ 3 của Đảng 1960."}, {"key": "C", "text": "Hội nghị bồi dưỡng lãnh đạo các cấp toàn miền Bắc tháng 3.1961."}, {"key": "D", "text": "Bác nói chuyện tại Đại hội công đoàn toàn quốc lần thứ II ngày 9.3.1961."}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Câu 'Muốn xây dựng chủ nghĩa xã hội, trước hết cần có những con người xã hội chủ nghĩa' được Hồ Chí Minh nói tại Hội nghị bồi dưỡng cán bộ lãnh đạo các cấp toàn miền Bắc tháng 3/1961 (Hồ Chí Minh Toàn tập). Phương án dễ nhầm là bài nói tại Đại hội Công đoàn toàn quốc lần II (3/1961) vì cùng thời điểm, nhưng đó không phải nơi phát biểu câu này.", "key_fact": "'Muốn xây dựng CNXH, trước hết cần có những con người XHCN' – Hồ Chí Minh, Hội nghị bồi dưỡng cán bộ lãnh đạo toàn miền Bắc, 3/1961.", "topic": "Con người xã hội chủ nghĩa", "note": "", "comment_answer": null}, {"id": "MLN131-bo-215", "question": "Tìm phuơng án đúng cho câu “Hiền tài là nguyên khí của quốc gia, nguyên khí thịnh thì thế nước mạnh, nguyên khí suy thì thế nước hèn và càng xuống thấp”.", "options": [{"key": "A", "text": "Nguyễn Trãi"}, {"key": "B", "text": "Nguyễn Huệ"}, {"key": "C", "text": "Lời ghi trên bia ở Văn miếu Quốc Tử Giám"}, {"key": "D", "text": "Hồ Chí Minh"}], "answer": ["C"], "multi": false, "confidence": "high", "source": "key", "explanation": "Câu 'Hiền tài là nguyên khí của quốc gia...' được khắc trên bia Tiến sĩ đầu tiên (khoa Nhâm Tuất 1442) dựng năm 1484 tại Văn Miếu - Quốc Tử Giám, do Thân Nhân Trung soạn. Nhiều người nhầm là của Nguyễn Trãi hay Hồ Chí Minh vì đều đề cao nhân tài, nhưng nguồn gốc đúng là văn bia ở Văn Miếu.", "key_fact": "'Hiền tài là nguyên khí của quốc gia' là lời ghi trên bia Tiến sĩ ở Văn Miếu - Quốc Tử Giám (Thân Nhân Trung soạn).", "topic": "Nguồn lực con người", "note": "", "comment_answer": null}]}]}], "note": "Nguồn câu hỏi: thư mục \"file đề đáp án các môn\" trên Google Drive. MLN131 dùng đáp án gốc (đã soát lại); AET, HOD, IPR có đáp án do AI giải và kiểm tra chéo."};
